INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In barium swallow studies:', 'Patients should not be NPO', 'High fiber diet is encouraged a day to study', 'Good for studying condition of ascending colon', 'Good for diagnosing achalasia', 'D', 'Barium swallow (esophagography) visualises the esophagus and is the classic study for achalasia, showing the dilated esophagus with distal ''bird-beak'' narrowing (Brunner & Suddarth''s Med-Surg). Patients are kept NPO before the study, so ''not NPO'' is wrong, and it studies the upper GI tract, not the ascending colon.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is the correct order of abdominal assessment:', 'Inspection, percussion, auscultation, palpation.', 'Inspection, auscultation, percussion, palpation.', 'Inspection, palpation, percussion, auscultation.', 'Inspection, auscultation, palpation, percussion.', 'B', 'Abdominal assessment follows inspection, auscultation, percussion, then palpation; auscultation precedes percussion/palpation so bowel sounds are not altered by manipulation (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following gastrointestinal disorder is managed best by downscaling gluten containing meals:', 'Irritable bowel syndrome', 'Diverticulum', 'Celiac disease', 'Esophageal varices.', 'C', 'Celiac disease is an immune reaction to gluten and is managed by a lifelong gluten-free diet (Brunner & Suddarth''s Med-Surg). IBS, diverticulum and esophageal varices are not gluten-driven.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing intervention should be a priority in one of the following patients:', 'Patient with appendicitis with pain rating of 10/10.', 'Patient with appendicitis with sudden relief of pain.', 'Patient with peptic ulcers who need omeprazole', 'Patient with jaundice that need evaluation of liver function', 'B', 'Sudden relief of pain in appendicitis suggests perforation/rupture, a surgical emergency requiring priority intervention (Brunner & Suddarth''s Med-Surg). Severe steady pain, routine omeprazole, and elective liver-function evaluation are lower priority than a possible rupture.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The scientific study of the aging process is referred to as:', 'Ageism', 'Geriatrics', 'Gerontic', 'Gerontology', 'D', 'Gerontology is the scientific study of the aging process and older adults; geriatrics is the clinical/medical care of the elderly, and ageism is prejudice against them (Brunner & Suddarth''s Med-Surg, gerontologic nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Drug dosages must be reduced in the elderly because:', 'Cardiac output is significantly reduced', 'The mucosal cells in the gastrointestinal tract are reduced', 'Drug biotransformation takes longer in an older person', 'There is a high likelihood of manifestation of toxic effects of drugs', 'D', 'Age-related decline in hepatic metabolism and renal clearance leads to drug accumulation and a high likelihood of toxicity, so doses are reduced (Brunner & Suddarth''s Med-Surg; Kenya EML pharmacology principles). This is the overarching reason encompassing slower biotransformation.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing measures to deal with sensory changes in the aged include', 'Increasing lighting in the room', 'Speaking in low tones', 'Providing single and adequate calories', 'Suggesting appetite stimulants before meals', 'A', 'Aging causes visual decline; increasing (glare-free) lighting compensates for sensory changes and improves safety (Brunner & Suddarth''s Med-Surg, gerontologic nursing). Speaking in low tones worsens presbycusis; the other options address nutrition, not sensory changes.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bone changes associated with aging frequently result from loss of:', 'Calcium', 'Magnesium', 'Vitamin A', 'Vitamin C', 'A', 'Age-related bone changes (osteoporosis/osteopenia) result from loss of bone calcium and mass (Brunner & Suddarth''s Med-Surg). Magnesium and vitamins A/C are not the primary lost element in aging bone.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All of the following statements concerning genitourinary system changes in the older adult are true except:', 'The glomerular filtration rate decreases', 'Acid-base balance is restored more slowly', 'Bladder capacity increases with advanced age', 'Urinary frequency, urgency, and incontinence are common.', 'C', 'This is the ''except'' (false) statement: with aging, bladder capacity DECREASES, contributing to frequency, urgency and incontinence, while GFR falls and acid-base correction is slower (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is true about loss of muscle mass in the elderly:', 'It also known as osteopenia', 'It is solely caused by disused', 'Exercise has no impact on the process', 'It is referred to as sarcopenia.', 'D', 'Age-related loss of muscle mass and strength is termed sarcopenia; osteopenia refers to low bone mass, and exercise/resistance training does slow the process (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the anterior pituitary gland is responsible for secreting all of the following except the:', 'Adrenocorticotropic hormone (ACTH).', 'Antidiuretic hormone (ADH).', 'Follicle-stimulating hormone (FSH).', 'Thyroid-stimulating hormone (TSH).', 'B', 'This is the ''except'': ADH (and oxytocin) are secreted by the posterior pituitary. The anterior pituitary secretes ACTH, FSH and TSH (Anatomy & Physiology / Brunner & Suddarth).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Diabetes insipidus is a disorder related to a deficiency of:', 'Growth hormone.', 'Prolactin.', 'Oxytocin.', 'Vasopressin.', 'D', 'Diabetes insipidus results from deficiency of antidiuretic hormone (vasopressin), causing polyuria and polydipsia (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When thyroid hormone is administered for prolonged hypothyroidism, the nurse knows to monitor the patient for:', 'Angina.', 'Depression.', 'Mental confusion.', 'Hypoglycemia.', 'A', 'Thyroid hormone replacement increases myocardial oxygen demand; in prolonged hypothyroidism, especially with underlying CAD, it can precipitate angina, so the nurse monitors for it (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The preferred medication for treating hypothyroidism is:', 'Lithium.', 'Proprandol.', 'Propylthiouracil.', 'Synthroid.', 'D', 'Synthroid (levothyroxine/T4) is the drug of choice for hypothyroidism replacement (Brunner & Suddarth''s Med-Surg; Kenya EML). Propylthiouracil and propranolol treat hyperthyroidism, and lithium is unrelated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A clinical manifestation not usually associated with hyperthyroidism is:', 'A pulse rate slower than 90 bpm.', 'An elevated systolic blood pressure.', 'Muscular fatigability.', 'Weight loss.', 'A', 'Hyperthyroidism produces tachycardia, elevated systolic BP, weight loss and fatigability; a pulse slower than 90 bpm is NOT associated (it would suggest hypothyroidism) (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patients with hyperthyroidism are characteristically:', 'Apathetic and anorexic.', 'Calm.', 'Emotionally stable.', 'Sensitive to heat.', 'D', 'Hyperthyroid patients have increased metabolism causing heat intolerance, nervousness and irritability; they are not calm, apathetic or emotionally stable (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Iodine or iodide compounds are used for hyperthyroidism because they do all of the following except:', 'Decrease the basal metabolic rate.', 'Increase the vascularity of the gland.', 'Lessen the release of thyroid hormones.', 'Reduce the size of the gland.', 'B', 'This is the ''except'': iodine/iodide compounds DECREASE the size and vascularity of the thyroid gland and reduce hormone release and BMR, which is why they are given preoperatively (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objectives of pharmacotherapy for hyperthyroidism include:', 'Destroying overreactive thyroid cells.', 'Preventing thyroid hormonal synthesis.', 'Increasing the amount of thyroid tissue.', 'All of the above.', 'B', 'The objective of antithyroid pharmacotherapy (e.g., propylthiouracil, methimazole) is to inhibit thyroid hormone synthesis (Brunner & Suddarth''s Med-Surg). Destroying cells is radioiodine (not pharmacotherapy proper), and increasing thyroid tissue is opposite to the goal, so ''all of the above'' is wrong.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of thyroid storm include all of the following except:', 'Bradycardia.', 'Delirium or somnolence.', 'Dyspnea and chest pain.', 'Hyperpyrexia.', 'A', 'This is the ''except'': thyroid storm causes tachycardia, hyperpyrexia, delirium/somnolence and cardiorespiratory distress; bradycardia is not a feature (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Medical management for thyroid crisis includes:', 'Intravenous dextrose fluids.', 'Hypothermia measures.', 'Oxygen therapy.', 'All of the above.', 'D', 'Management of thyroid crisis includes IV dextrose/fluids for hypermetabolic demand, hypothermia (cooling) measures for hyperpyrexia, and oxygen therapy for increased metabolic demand (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pharmacotherapy for thyroid storm would not include the administration of:', 'Acetaminophen.', 'Iodine.', 'Propylthiouracil.', 'Synthetic levothyroxine.', 'D', 'Thyroid storm is treated with PTU, iodine and acetaminophen (for fever); administering synthetic levothyroxine (more thyroid hormone) would worsen the crisis and is therefore not included (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common type of goiter is etiologically related to a deficiency of:', 'Thyrotropin.', 'Iodine.', 'Thyroxine.', 'Calcitonin.', 'B', 'Simple (endemic) goiter, the most common type, is caused by iodine deficiency (Brunner & Suddarth''s Med-Surg; addressed in Kenya via salt iodization). This is the basis of nutritional iodine supplementation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the most common and least aggressive type of cancer is:', 'Anaplastic.', 'Follicular adenocarcinoma.', 'Medullary.', 'Papillary adenocarcinoma.', 'D', 'Papillary adenocarcinoma is the most common and least aggressive (best-prognosis) thyroid cancer; anaplastic is the most aggressive (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diagnosis of hyperparathyroidism can be established by all of the following signs except:', 'A negative reading on a Sulkowitch test.', 'A serum calcium level of 12 mg/dL.', 'An elevated level of parathyroid hormone.', 'Bone demineralization seen on an x-ray film.', 'A', 'This is the ''except'': hyperparathyroidism causes hypercalcemia, so the Sulkowitch (urine calcium) test would be POSITIVE, not negative; elevated serum calcium, elevated PTH and bone demineralization all support the diagnosis (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A recommended breakfast for a hyperparathyroid patient would be:', 'Cereal with milk and bananas.', 'Fried eggs and bacon.', 'Orange juice and toast.', 'Pork sausage and cranberry juice', 'B', 'Hyperparathyroidism causes hypercalcemia, so a low-calcium breakfast is preferred; eggs and bacon avoid the high calcium of milk/cereal (Brunner & Suddarth''s Med-Surg nutrition guidance). Cereal with milk is high in calcium and thus inappropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the most important and frequently occurring complications of hyperparathyroidism is:', 'Kidney stones.', 'Pancreatitis.', 'Pathologic fractures.', 'Peptic ulcer.', 'A', 'Chronic hypercalcemia and hypercalciuria in hyperparathyroidism commonly cause renal calculi (nephrolithiasis) (Brunner & Suddarth''s Med-Surg). Pathologic fractures occur but renal stones are the most frequent complication.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathophysiology of hypoparathyroidism is associated with all of the following except:', 'A decrease in serum calcium.', 'An elevation of blood phosphate.', 'An increase in the renal excretion of phosphate.', 'A lowered renal excretion of calcium.', 'C', 'This is the ''except'': in hypoparathyroidism low PTH DECREASES renal phosphate excretion, causing hyperphosphatemia along with hypocalcemia and reduced renal calcium excretion (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The goal of medical management for hypoparathyroidism is to:', 'Achieve a serum calcium level of 9 to 10 mg/dL.', 'Eliminate clinical symptoms.', 'Reverse the symptoms of hypocalcemia.', 'Accomplish all of the above.', 'D', 'Medical management of hypoparathyroidism aims to restore serum calcium to 9–10 mg/dL, reverse hypocalcemia and eliminate clinical symptoms (Brunner & Suddarth''s Med-Surg), so all listed goals apply.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing management for a hypoparathyroid patient would not include:', 'Maintaining a quiet, subdued environment.', 'Making certain that calcium gluconate is kept at the bedside.', 'Observing the patient for signs of tetany.', 'Supplementing the diet with milk and milk products.', 'D', 'This is the ''would not include'': milk products are high in phosphorus, which is already elevated in hypoparathyroidism, so a high-calcium/low-phosphorus diet is advised, not milk supplementation. Seizure precautions, bedside calcium gluconate and tetany monitoring are appropriate (Brunner & Suddarth''s Med-Surg).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pheochromocytoma is an adrenal medulla tumor that causes arterial hypertension by increasing the level of circulating:', 'Catecholamines.', 'Enzymes.', 'Hormones.', 'Glucocorticoids.', 'A', 'Pheochromocytoma is an adrenal medulla tumor that secretes excess catecholamines (epinephrine and norepinephrine), causing paroxysmal or sustained hypertension (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A positive test for overactivity of the adrenal medulla is an epinephrine value of:', '50 pg/mL.', '100 pg/mL.', '100 to 300 pg/mL.', '450 pg/mL.', 'D', 'Normal plasma epinephrine is under ~100 pg/mL; values above ~400 pg/mL indicate adrenal medulla overactivity (pheochromocytoma). 450 pg/mL is clearly elevated and positive (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings suggestive of Addison''s disease include all of the following except:', 'A relative lymphocytosis.', 'Hyperkalemia and hyponatremia.', 'Hypertension.', 'Hypoglycemia.', 'C', 'Addison''s disease (adrenal insufficiency) causes HYPOtension, not hypertension, due to aldosterone/cortisol deficiency. Expected findings are hyperkalemia, hyponatremia, hypoglycemia and relative lymphocytosis; hypertension is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A positive diagnosis of Cushing''s syndrome is associated with:', 'The disappearance of lymphoid tissue.', 'A reduction in circulating eosinophils.', 'An elevated cortisol levels.', 'All of the above.', 'D', 'Cushing''s syndrome (excess cortisol) produces elevated cortisol levels, involution/disappearance of lymphoid tissue, and eosinopenia (reduced circulating eosinophils); all listed features apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical manifestations of Cushing''s syndrome may be modified with a diet that is:', 'High in protein.', 'Low in carbohydrates.', 'Low in sodium.', 'All of the above.', 'D', 'Cushing''s manifestations are eased by a diet high in protein (counter catabolism), low in carbohydrates (counter hyperglycemia) and low in sodium (counter fluid retention/hypertension); all three apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with aldosteronism would be expected to exhibit all of the following symptoms except:', 'Alkalosis.', 'Hypokalemia.', 'Hyponatremia.', 'An increased pH.', 'C', 'Primary aldosteronism (excess aldosterone) causes sodium retention (HYPERnatremia), potassium loss (hypokalemia), and metabolic alkalosis with raised pH. Hyponatremia is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse needs to be aware that large-dose corticosteroid therapy is most effective when administered:', 'At 8:00 AM.', 'At 8:00 PM.', 'Between 4:00 AM and 5:00 AM.', 'Between 4:00 PM and 6:00 PM.', 'A', 'Corticosteroids are best given in the early morning (around 8:00 AM) to mimic the body''s natural diurnal cortisol peak and minimise HPA-axis suppression (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML principles).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing assessment for a patient who is receiving corticosteroid therapy includes observation for the unacceptable side effect of:', 'Glaucoma.', 'Facial mooning.', 'Potassium loss.', 'Weight gain', 'A', 'Facial mooning, potassium loss and weight gain are expected/anticipated corticosteroid effects; glaucoma (raised intraocular pressure with possible vision loss) is a serious, unacceptable adverse effect requiring monitoring (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Traumatic injury of the following section of spine causes acute respiratory failure:', 'L1-L2', 'L3-L4', 'C5-C6', 'C7-C8', 'C', 'The phrenic nerve (diaphragm) arises from C3-C5; high cervical injury at C5-C6 impairs diaphragmatic/respiratory function causing acute respiratory failure, whereas lumbar (L1-L4) injuries spare respiration (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following true about stomas:', 'Healthy stomas are grey, bleed on touch, sensation on touch', 'Colostomy bag should be emptied when full.', 'Healthy stomas are pink, bleed on touch, has sensation on touch.', 'It is yellow, bleeds on touch, there is no sensation on touch.', 'C', 'A healthy stoma is pink/red and moist, and slightly bleeds on touch because it is vascular. Note the stoma mucosa itself has no pain sensation; option C is the closest/best correct description among the choices (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Barium swallow is used in diagnosis of the following:', 'Jejunal atresia', 'Stomach Cardia', 'Upper GIT', 'Rectal and Sigmoid tumors', 'C', 'A barium swallow outlines the upper gastrointestinal tract (pharynx, esophagus, stomach). Lower/rectosigmoid lesions require a barium enema, not a swallow (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Chronic respiratory failure manifest with:', 'p.H. =7.36, High PaCO2>50, and PaO2 <50 mmHg', 'p.H. =7.56, High PaCO2>50, and PaO2 <50 mmHg', 'p.H.7.37, High PaCO2<50, and PaO2 <50 mmHg', 'PaO2 <50 mmHg, PaCO2 >50 mmHg, and pH =7.35', 'D', 'Chronic respiratory failure shows hypoxemia (PaO2 <50) and hypercapnia (PaCO2 >50) with a near-normal/compensated pH (~7.35) due to renal bicarbonate retention, unlike the acute uncompensated acidosis in the other options (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non atopic asthma is best described as:', 'Start in adulthood.', 'Associated with allergies.', 'Patient with eczema is likely not to have it.', 'Also known as intrinsic asthma.', 'D', 'Non-atopic asthma is not associated with allergy/IgE and is termed intrinsic asthma; it typically starts in adulthood but the defining description is intrinsic (non-allergic) asthma (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of bone marrow results in:', 'Pernicious anemia.', 'Aplastic anemia with fever.', 'Aplastic anemia without fever.', 'Iron deficiency anemia.', 'B', 'Bone marrow failure causes aplastic anemia; because all cell lines fail (including neutrophils), leukopenia predisposes to infection and fever, distinguishing it from the febrile-free option (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hyperplasia of gingiva is likely to be indicator of:', 'Ludwig angina', 'Vincent angina', 'Heart failure', 'Phenytoin therapy', 'D', 'Gingival hyperplasia is a classic adverse effect of phenytoin (anticonvulsant) therapy (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The bacteria known to cause dental caries is:', 'Streptococcus aureas', 'Streptococcus mutans', 'Group A beta hemolytic streptococcus', 'Sedenomonous aeruginosa', 'B', 'Streptococcus mutans is the principal bacterium responsible for dental caries through acid production from fermentable carbohydrates (Brunner & Suddarth''s Medical-Surgical Nursing; standard microbiology).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Contralateral shift of trachea in patient with chest complains is likely to be due to:', 'Pneumonia', 'Emphysema', 'Flail chest', 'Tension pneumothorax', 'D', 'Tension pneumothorax builds intrapleural pressure that pushes mediastinal structures and the trachea to the opposite (contralateral) side; it is a life-threatening emergency (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Biot''s respirations are associated with:', 'Lesions on Pons.', 'Diabetic ketoacidosis.', 'Asthmatic attack.', 'Pneumonia.', 'A', 'Biot''s (ataxic) respirations, an irregular pattern of breaths with apnea, are associated with damage to the pons/medulla (Brunner & Suddarth''s Medical-Surgical Nursing). Kussmaul breathing, not Biot''s, is seen in diabetic ketoacidosis. 51. ______is the deadliest form of gangrene: A. Wet gangrene B. Dry gangrene C. Gas gangrene D. Meleney''s gangrene Answer: C. Gas gangrene Rationale: Gas gangrene (clostridial myonecrosis, usually Clostridium perfringens) is the deadliest, most rapidly fatal form of gangrene due to toxin production and systemic toxicity (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is unique to secondary venous thrombosis?', 'It''s usually without involvement of deep veins', 'Its varicose veins: resulting from obstruction of deep veins.', 'Its a reflux of venous blood in the veins', 'It''s usually managed by wearing static stockings.', 'B', 'Secondary varicose/venous disease is distinguished by an identifiable cause such as deep vein obstruction (e.g., prior DVT), unlike primary disease; this is the feature unique to secondary venous thrombosis among the options (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is associated with thoracic aortic aneurysm only:', 'Marfan syndrome', 'Hypertension', 'Atherosclerosis', 'Smoking', 'A', 'Marfan syndrome (connective-tissue defect) is specifically linked to thoracic aortic aneurysm/dissection, whereas hypertension, atherosclerosis and smoking are shared risk factors for abdominal aneurysms too (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A burn obtained as a result of a lightning strike is:', 'Heat burn', 'Thermal burn', 'Radiation burn', 'Electrical burn', 'D', 'A lightning strike delivers a high-voltage electrical current, producing an electrical burn (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In nursing assessment subjective data is data that the:', 'Patient can report on their own', 'Nurse can assess on their own', 'Nurse and doctor can confirm', 'Patient can report and the nurse can confirm', 'A', 'Subjective data is information reported by the patient (symptoms, feelings) that cannot be directly observed, whereas objective data is measurable/observable by the nurse (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Damage to the mitral valve may lead:', 'Pulmonary hypertension', 'Left- sided heart failure', 'Myocardial infarction', 'Left ventricular hypertrophy', 'A', 'Mitral valve damage (stenosis/regurgitation) raises left atrial pressure that backs up into the pulmonary circulation, causing pulmonary hypertension (and later right heart strain) (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves a segment of the leg being used to provide an alternative pathway for blood flow past a point of obstruction between the aorta and coronary artery:', 'Angioplasty', 'Coronary angiography', 'Heart transplant', 'Coronary bypass', 'D', 'Coronary artery bypass graft (CABG) uses a vessel such as the saphenous vein from the leg to bypass an obstruction and restore blood flow to the coronary artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves using a small plastic balloon to open a narrowed artery:', 'Heart transplant', 'Coronary bypass', 'Angioplasty', 'Coronary angiography', 'C', 'Percutaneous transluminal (balloon) angioplasty uses a small inflatable balloon to open a narrowed artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common symptom of myocardial infarction is:', 'Palpitations', 'Edema', 'Dyspnea', 'Chest pain', 'D', 'Chest pain (crushing, substernal, possibly radiating) is the most common presenting symptom of myocardial infarction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dyspnea, fatigue, increased pulmonary artery pressure and decreased cardiac output are indicative of:', 'Right valve failure', 'Paracentisis', 'Myocardial infarction', 'Left sided heart failure', 'D', 'Dyspnea, fatigue, raised pulmonary artery pressure and reduced cardiac output reflect left-sided heart failure, where the failing left ventricle causes pulmonary congestion and low output (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for administration of morphine in a patient with myocardial infarction is to relieve:', 'Edema', 'Palpitations', 'Chest pain', 'Dyspnea', 'C', 'In myocardial infarction, morphine is given primarily to relieve severe ischemic chest pain (and also reduces anxiety and cardiac workload/preload) (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which diagnostic test provides information about the physiology and function of the heart?', 'Electrocardiogram', 'Chest X-ray', 'Echocardiogram', 'Angiogram', 'A', 'The electrocardiogram (ECG) records the heart''s electrical activity, giving information about cardiac physiology and function (rate, rhythm, conduction, ischemia), whereas echocardiogram shows structure/mechanics and X-ray shows size (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following conditions results in coronary artery disease:', 'Renal failure', 'Diabetes mellitus', 'Myocardial infarction', 'Atherosclerosis', 'D', 'Atherosclerosis (plaque buildup narrowing coronary arteries) is the underlying pathological process that directly results in coronary artery disease (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing diagnoses mostly differ from medical diagnoses in that they are:', 'Primarily concerned with human response, while medical diagnoses are primarily concerned with pathology', 'Dependent upon medical diagnoses for the direction of appropriate interventions', 'Primarily concerned with caring, while medical diagnoses are primarily concerned with curing', 'Primarily concerned with psychosocial parameters, while medical diagnoses are primarily concerned with physiologic parameters.', 'A', 'A nursing diagnosis addresses the patient''s human responses to actual/potential health problems, whereas a medical diagnosis identifies the disease/pathology (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the management of myocardial infarction, atherectomy is:', 'Removal of atherosclerotic plaque', 'Use of new implants', 'Ballooning of narrowed artery', 'Putting a stent to prevent collapse of artery)', 'A', 'Atherectomy is a catheter-based procedure that cuts away/removes atherosclerotic plaque from the coronary artery wall, distinct from angioplasty (ballooning) or stenting (Brunner & Suddarth''s Medical-Surgical Nursing, cardiovascular interventions).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis for a patient with angina pectoris is infective tissue perfusion. The plan of care includes the patient outcome criterion of:', 'Experiencing no dyspnea on exertion', 'Reduce ischemia by increasing O2 to tissues', 'Agreeing to discontinue smoking', 'Ambulating 50 feet without experiencing dyspnea', 'D', 'An outcome criterion must be patient-centred, measurable and observable. ''Ambulating 50 feet without dyspnea'' is a specific, measurable patient outcome; the others are goals/interventions rather than measurable outcome criteria (Kozier & Erb''s Fundamentals of Nursing, nursing process).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which diagnostic test will be used to test for claudication in peripheral artery disease?', 'Doppler ultrasound', 'Treadmill', 'Arteriogram', 'Ankle brachial index', 'D', 'The ankle-brachial index (ABI) is the primary, first-line diagnostic test for peripheral artery disease/claudication, quantifying arterial insufficiency of the lower limbs (Brunner & Suddarth''s, peripheral vascular assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following cardiovascular condition is more prevalent among females than males:', 'Hypertension', 'Varicose veins', 'Coronary artery disease', 'Myocardial infarction', 'B', 'Varicose veins are more prevalent in females (pregnancy, hormonal influence), whereas coronary artery disease and myocardial infarction are more common in males (Brunner & Suddarth''s, venous disorders).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which action occurs primarily during the evaluation phase of the nursing process:', 'Decision making and judgment', 'Data collection', 'Reassessment and audit', 'Priority setting and expected outcomes.', 'C', 'The evaluation phase of the nursing process involves reassessing the patient and auditing whether outcomes were met. Data collection is assessment; priority setting/expected outcomes are planning; decision making is diagnosis (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive skills, key in implementation of nursing process, refers to:', 'A blend of intellectual and ''hand'' on skills', '''Hands on'' skills such as manipulating equipment', 'Problem solving, decision making, critical thinking and curative thinking', 'All activities, verbal and nonverbal, that people use when communicating directly with one another', 'C', 'Cognitive (intellectual) skills in the nursing process refer to problem solving, decision making and critical thinking. Option B describes psychomotor skills and D describes interpersonal skills (Kozier & Erb''s Fundamentals of Nursing, implementation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hematocrit of 60% is likely to be an indicator of:', 'Leukemia', 'Idiopathic Thrombocytopenia.', 'Non-Hodgkin Lymphoma', 'Polycythemia vera', 'D', 'A markedly elevated hematocrit (60%) indicates an increased red cell mass, characteristic of polycythemia vera. Leukemia, ITP and lymphoma do not raise the hematocrit (Brunner & Suddarth''s, hematologic disorders).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with Forced Expiratory Volume (FEV1) of 60% is likely to be suffering from:', 'Pleural effusion.', 'Trauma.', 'Emphysema.', 'Asthma.', 'C', 'A reduced FEV1 (60%) with airflow obstruction is characteristic of COPD/emphysema, an obstructive lung disease. Pleural effusion is restrictive; emphysema best fits chronic obstruction (Brunner & Suddarth''s, respiratory function tests). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin B12 anemia is characterized by:', 'Microcytosis of RBC', 'Normal hematocrit', 'Hypochromic RBC', 'Macrocytosis of RBC', 'D', 'Vitamin B12 deficiency causes megaloblastic (macrocytic) anemia characterized by large red cells (macrocytosis) with high MCV, not microcytosis or hypochromia (Brunner & Suddarth''s, anemias).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One following oxygen delivery system has constant FiO2:', 'Nasal Prongs', 'Venturi Mask', 'Non-rebreather mask', 'Partial rebreather mask', 'B', 'The Venturi mask is a high-flow device that delivers a precise, constant FiO2 regardless of the patient''s breathing pattern; nasal prongs and rebreather masks deliver variable FiO2 (Brunner & Suddarth''s, oxygen therapy).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patient manifesting with "hot potato voice" is likely to be suffering from:', 'Vincent angina', 'Periodontitis', 'Asthma', 'Ludwig Angina', 'D', 'A muffled ''hot potato voice'' results from the pharyngeal/submandibular swelling of Ludwig''s angina (and severe peritonsillar/deep neck infection); it is not a feature of asthma or periodontitis (Brunner & Suddarth''s, upper airway infections).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing action needed for claustrophobic patient before MRI is:', 'Explain the procedure to the patient.', 'Assume patient''s concerns', 'Give paralytic drugs to the patient.', 'Tell the patient to man up.', 'A', 'For a claustrophobic patient facing MRI, the nurse should first explain the procedure to reduce anxiety and gain cooperation; assuming concerns or dismissive/inappropriate responses are non-therapeutic (Kozier & Erb''s Fundamentals of Nursing, therapeutic communication).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best imaging study for patient with basilar artery aneurysm is:', 'Magnetic resonance imaging', 'X-Ray', 'Coronary angiography', 'Radioisotope imaging', 'A', 'MRI (with MR angiography) is the preferred non-invasive imaging for cerebral/basilar artery aneurysms; plain X-ray and coronary angiography are unsuitable for intracranial vessels (Brunner & Suddarth''s, neurologic diagnostics).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mild intermittent asthma is best managed by:', 'Long-acting beta-adrenergic agonist (LABA)', 'Short acting beta-adrenergic agonist (SABA)', 'Long-acting muscarinic antagonist (LAMA)', 'Inhaled corticosteroids (ICS)', 'B', 'Mild intermittent asthma is managed with a short-acting beta-agonist (SABA) as reliever therapy; ICS and LABA/LAMA are for persistent asthma (GINA/WHO guidance as adopted in Kenya, Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('X-ray film of a patient shows expanded airways. This likely to be indicative of:', 'Emphysema', 'Bronchiectasis', 'Tension pneumothorax', 'Diffused pneumonia', 'A', 'Emphysema causes hyperinflation with expanded/enlarged airspaces and flattened diaphragm on chest X-ray; tension pneumothorax shows lung collapse, not expanded airways (Brunner & Suddarth''s, COPD).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hemoptysis is defined as:', 'Blood in sputum cough.', 'Blood in GIT', 'Bad breath', 'Dry cough', 'A', 'Hemoptysis is the coughing up of blood or blood-stained sputum from the respiratory tract; blood in the GIT is hematemesis/melena (Brunner & Suddarth''s, respiratory assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following will reduce pulse of pressure of an individual:', 'Reduced osmolality', 'Dehydration', 'Highly hydration status', 'Low temperatures', 'B', 'Pulse pressure is stroke volume dependent; dehydration/hypovolemia reduces stroke volume and thus narrows the pulse pressure. Overhydration would widen it (Guyton physiology; Brunner & Suddarth''s, fluid balance).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following parts of central nervous system control vegetative function:', 'Spinal cord', 'Cerebral cortex', 'Brain stem', 'Medulla oblongata', 'D', 'The medulla oblongata houses the vital autonomic (vegetative) centres controlling cardiac, respiratory and vasomotor function; it is the most specific answer among the options (standard neuroanatomy/physiology). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Collection of cell bodies in the central nervous system forms:', 'White matter', 'Grey matter', 'Commissures', 'Ganglion', 'B', 'Per standard neuroanatomy (Kozier & Erb''s / Brunner & Suddarth), collections of neuronal cell bodies within the CNS form grey matter, whereas myelinated axons form white matter and a cluster of cell bodies OUTSIDE the CNS is a ganglion.', 'BScN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gonadal arteries branch from:', 'Internal iliac artery', 'External iliac artery', 'Abdominal aorta', 'Subclavian artery', 'C', 'Per standard anatomy (Gray''s/anatomy texts used in Kenyan training), the gonadal (testicular/ovarian) arteries arise directly from the abdominal aorta below the renal arteries, not from the iliac or subclavian vessels.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lesion of cranial nerve VII causes one of the following:', 'Ebbs palsy', 'Inability to raise neck', 'Bell''s Palsy', 'Anosmia', 'C', 'Per standard neuroanatomy (Brunner & Suddarth), the facial nerve (CN VII) supplies the muscles of facial expression; its lesion causes Bell''s palsy (unilateral facial droop). Anosmia is CN I; CN VII does not affect neck raising.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following combinations of antiparkinsonian drugs is an appropriate treatment plan?', 'Amantadine, carbidopa, and entacapone.', 'Levodopa, carbidopa, and entacapone.', 'Pramipexole, carbidopa, and entacapone.', 'Ropinirole, carbidopa, and selegiline.', 'B', 'Per Kenya EML/pharmacology texts, the standard Parkinson''s regimen combines levodopa (dopamine precursor) with carbidopa (peripheral decarboxylase inhibitor) and entacapone (COMT inhibitor); the other options pair carbidopa with drugs (amantadine, dopamine agonists) that are not levodopa and so gain no benefit from carbidopa.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of brain affected in parkinsonian disease is the:', 'Limbic system', 'Occipital lobe', 'Pyramidal tracts', 'Basal ganglia', 'D', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra of the basal ganglia, impairing control of voluntary movement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a rapidly progressing, ascending inflammatory demyelinating polyneuropathy of the peripheral sensory and motor nerves and nerve roots disease.', 'Myasthenia Gravis', 'Guillain-Barre Syndrome', 'Multiple Myeloma', 'Alzheimer''s disease', 'B', 'Per Brunner & Suddarth, Guillain-Barre syndrome is an acute, rapidly progressive ascending inflammatory demyelinating polyneuropathy affecting peripheral sensory and motor nerves and nerve roots.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A postpartum patient was in labor for 30 hours and had ruptured membranes for 24 hours. For which of the following would the nurse be alert?', 'Endometritis', 'Endometriosis', 'Salpingitis', 'Pelvic thrombophlebitis', 'A', 'Prolonged labor with prolonged rupture of membranes (>18-24h) allows ascending bacteria to infect the uterine lining, so the nurse watches for endometritis (puerperal infection). Endometriosis and salpingitis are unrelated to this postpartum risk. Per Myles Textbook for Midwives (puerperal sepsis).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant client is diagnosed with partial placenta previa. In explaining the diagnosis, the nurse tells the client that the usual treatment for partial placenta previa is which of the following?', 'Activity limited to bed rest', 'Platelet infusion', 'Immediate cesarean delivery', 'Labor induction with oxytocin.', 'A', 'In stable partial placenta previa without active heavy bleeding, expectant management with bed rest is standard to prolong gestation; cesarean is reserved for term or uncontrolled bleeding, and oxytocin induction is contraindicated. Per Myles Textbook for Midwives / MOH maternal guidelines.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida client at 25 weeks gestation visits the clinic and tells the nurse that her lower back aches when she arrives home from work. The nurse should suggest that the client perform:', 'Tailor sitting', 'Leg lifting', 'Shoulder circling', 'Squatting exercises', 'A', 'Tailor (cross-legged) sitting strengthens the back and stretches pelvic muscles, relieving low backache in pregnancy. Leg lifting and squatting can strain the back; shoulder circling targets the upper body. Per Myles Textbook for Midwives (antenatal exercises).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client tells the nurse, “I think my baby likes to hear me talk to him.” When discussing neonates and stimulation with sound, which of the following would the nurse include as a means to elicit the best response?', 'High-pitched speech with tonal variations', 'Low-pitched speech with a sameness of tone', 'Cooing sounds rather than words', 'Repeated stimulation with loud sounds', 'A', 'Neonates respond best to high-pitched speech with tonal variation (infant-directed speech), which promotes attention and bonding. Loud sounds and monotone are less effective. Per Kozier & Erb / developmental care principles.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient in her 14th week of pregnancy has presented with abdominal cramping and vaginal bleeding for the past 8 hours. She has passed several clots. What is the primary nursing diagnosis for this patient?', 'Knowledge deficit', 'Fluid volume deficit', 'Anticipatory grieving', 'Pain', 'B', 'With active vaginal bleeding, clot passage and cramping (inevitable/incomplete abortion), the priority (physiologic, ABC) nursing diagnosis is fluid volume deficit; grieving and pain follow once the patient is stabilized. Per Kozier & Erb prioritization / Myles.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida patient is admitted to the labor delivery area. Assessment reveals that she is in the early part of the first stage of labor. Her pain is likely to be most intense:', 'Around the pelvic girdle', 'Around the pelvic girdle and in the upper arms', 'Around the pelvic girdle and at the perineum', 'At the perineum', 'A', 'In the early first stage, pain from cervical dilatation is referred to the lower abdomen and pelvic girdle (T10-L1). Perineal pain arises in the second stage. Per Myles Textbook for Midwives (physiology of labor pain).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A female adult patient is taking a progestin-only oral contraceptive or mini pill. Progestin use may increase the patient’s risk for:', 'Endometriosis', 'Female hypogonadism', 'Premenstrual syndrome', 'Tubal or ectopic pregnancy', 'D', 'Progestin-only pills slow tubal motility, so if failure occurs the pregnancy is more likely to be ectopic; progestins do not cause endometriosis, hypogonadism, or PMS. Per Kenya National Family Planning Guidelines / BNF.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with pregnancy-induced hypertension probably exhibits which of the following symptoms?', 'Proteinuria, headaches, vaginal bleeding', 'Headaches, double vision, vaginal bleeding', 'Proteinuria, headaches, double vision', 'Proteinuria, double vision, uterine contractions', 'C', 'Preeclampsia/PIH presents with proteinuria, headache, and visual disturbances (double/blurred vision) from cerebral/retinal involvement; vaginal bleeding is not a feature. Per MOH/WHO pre-eclampsia guidelines and Myles.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Accompanied by her husband, a patient seeks admission to the labor and delivery area. The client states that she is in labor and says she attended the hospital clinic for prenatal care. Which question should the nurse ask her first?', '“Do you have any chronic illness?”', '“Do you have any allergies?”', '“What is your expected due date?”', '“Who will be with you during labor?”', 'C', 'On admission in labor the immediate priority is to establish gestational age via the expected due date to guide management; allergies and history follow. Per Myles Textbook for Midwives (admission in labor).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient is in the second stage of labor. During this stage, how frequently should the nurse in charge assess her uterine contractions?', 'Every 5 minutes', 'Every 15 minutes', 'Every 30 minutes', 'Every 60 minutes', 'B', 'In the second stage of labor, uterine contractions and fetal heart are assessed at least every 15 minutes (FHR every 5 min in high-risk). Per WHO/MOH intrapartum monitoring and Myles.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient is in her last trimester of pregnancy. Nurse Vickie should instruct her to notify her primary health care provider immediately if she notices:', 'Blurred vision', 'Hemorrhoids', 'Increased vaginal mucus', 'Shortness of breath on exertion', 'A', 'Blurred vision in late pregnancy is a danger sign of severe pre-eclampsia and must be reported immediately; hemorrhoids, increased mucus, and mild exertional dyspnea are common and expected. Per MOH maternal danger signs / Myles.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An adult female patient is using the rhythm (calendar-basal body temperature) method of family planning. In this method, the unsafe period for sexual intercourse is indicated by:', 'Return preovulatory basal body temperature', 'Basal body temperature increase of 0.1 degrees to 0.2 degrees on the 2nd or 3rd day of cycle.', '3 full days of elevated basal body temperature and clear, thin cervical mucus', 'Breast tenderness and mittelschmerz', 'C', 'The fertile (unsafe) period is marked by clear, thin, stretchy cervical mucus and the sustained BBT rise around ovulation; only after 3 full days of elevated temperature is the safe period considered to begin. Per Kenya National Family Planning Guidelines.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A couple who wants to conceive but has been unsuccessful during the last 2 years has undergone many diagnostic procedures. When discussing the situation with the nurse, one partner states, “We know several friends in our age group, and all of them have their own child already, Why can’t we have one?”. Which of the following would be the most appropriate nursing diagnosis for this couple?', 'Fear related to the unknown', 'Pain related to numerous procedures', 'Ineffective family coping related to infertility', 'Self-esteem disturbance related to infertility', 'D', 'The statement comparing themselves unfavorably to peers reflects feelings of inadequacy, indicating self-esteem disturbance related to infertility. There is no evidence of ineffective family coping between partners. Per Kozier & Erb nursing diagnosis. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be a disadvantage of breastfeeding?', 'Involution occurs more rapidly', 'The incidence of allergies increases due to maternal antibodies', 'The father may resent the infant’s demands on the mother’s body', 'There is a greater chance for error during preparation', 'C', 'A recognized disadvantage of breastfeeding is that the father may feel excluded or resent the infant''s demands on the mother. Faster involution and antibody transfer are advantages, and preparation error applies to formula. Per Myles Textbook for Midwives (breastfeeding).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client LMP began July 5, 2020. Her estimated date of delivery (EDD) should be which of the following?', 'January 2, 2021', 'March 28, 2021', 'April 12, 2021', 'October 12, 2020', 'C', 'Naegele''s rule (Myles Textbook for Midwives): LMP + 1 year - 3 months + 7 days. July 5, 2020 - 3 months = April 5, + 7 days = April 12, 2021.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Before birth, which of the following structures connects the right and left auricles of the heart?', 'Umbilical vein', 'Foramen ovale', 'Ductus arteriosus', 'Ductus venosus', 'B', 'The foramen ovale is the fetal shunt in the interatrial septum allowing blood to pass from the right to the left atrium (auricles) bypassing the lungs. The ductus arteriosus links pulmonary artery to aorta (Anatomy & Physiology; fetal circulation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following groups of newborn reflexes below are present at birth and remain unchanged through adulthood?', 'Blink, cough, rooting, and gag', 'Blink, cough, sneeze, gag', 'Rooting, sneeze, swallowing, and cough', 'Stepping, blink, cough, and sneeze', 'B', 'Protective reflexes present at birth that persist through life are blink, cough, sneeze and gag. Rooting and stepping are primitive reflexes that disappear in infancy, excluding the other options (Kozier & Erb / newborn assessment).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client in her third trimester tells the nurse, “I’m constipated all the time!” Which of the following should the nurse recommend?', 'Daily enemas', 'Laxatives', 'Increased fiber intake', 'Decreased fluid intake', 'C', 'Constipation in pregnancy is managed conservatively with increased dietary fibre, fluids and activity; enemas and laxatives are avoided and reducing fluids would worsen it (Myles Textbook for Midwives; ANC health education).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client tells the nurse that her last menstrual period started on January 14 and ended on January 20. Using Nagele’s rule, the nurse determines her EDD to be which of the following?', 'September 27', 'October 21', 'November 7', 'December 27', 'B', 'Naegele''s rule uses the first day of LMP (Jan 14): + 7 days = Jan 21, - 3 months = Oct', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('EDD is October 21 (Myles Textbook for Midwives). 175. When developing a plan of care for a client newly diagnosed with gestational diabetes, which of the following instructions would be the priority?', 'Dietary intake', 'Medication', 'Exercise', 'Glucose monitoring', 'D', 'For newly diagnosed gestational diabetes, teaching self blood-glucose monitoring is the priority because it guides dietary, exercise and insulin decisions and detects hyper/hypoglycaemia (Kenya MOH diabetes/maternal guidelines). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client 12 weeks’ pregnant came to the emergency department with abdominal cramping and moderate vaginal bleeding. Speculum examination reveals 2 to 3 cm cervical dilation.The nurse would document these findings as which of the following?', 'Threatened abortion', 'Imminent abortion', 'Complete abortion', 'Missed abortion', 'B', 'Moderate bleeding, cramping and cervical dilation (2-3 cm) indicate the abortion is inevitable/imminent. A threatened abortion has a closed cervix; the products have not yet passed so it is not complete (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be the priority nursing diagnosis for a client with an ectopic pregnancy?', 'Risk of infection', 'Pain', 'Knowledge deficit', 'Anticipatory grieving', 'B', 'Among the listed diagnoses, acute pain is the priority in ectopic pregnancy (a physiological/ABC-linked need indicating possible tubal rupture and bleeding); risk of infection and grieving are lower priority (Myles Textbook for Midwives; nursing priority setting). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Before assessing the postpartum client’s uterus for firmness and position in relation to the umbilicus and midline, which of the following should the nurse do first?', 'Assess the vital signs', 'Administer analgesia', 'Ambulate her in the hall', 'Assist her to urinate', 'D', 'A full bladder displaces and prevents the uterus from contracting, giving a falsely high/deviated fundus; the nurse should have the client empty her bladder first before assessing fundal firmness and position (Myles Textbook for Midwives; postnatal assessment).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A postpartum client has a temperature of 101.4ºF, with a uterus that is tender when palpated, remains unusually large, and not descending as normally expected. Which of the following should the nurse assess next?', 'Lochia', 'Breast', 'Incision', 'Urine', 'A', 'Fever, a tender, boggy, subinvoluted uterus indicates endometritis; the nurse should next assess the lochia (amount and foul odour) which confirms uterine infection (Myles Textbook for Midwives; postpartum infection).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following sign may help a midwife diagnose shoulder dystocia in labour ward?', 'The fetal head remains slightly stuck in the vagina', 'The anterior shoulder is delivered but the posterior one is stuck', 'The chin retracts and depresses the perineum', 'Traction of the head delivers the shoulder', 'C', 'Per Myles Textbook for Midwives, shoulder dystocia is recognised by the ''turtle sign''—the head delivers then retracts against the perineum (chin retracts/depresses perineum) because the anterior shoulder is impacted behind the symphysis.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman comes in the antenatal clinic for the first ANC visit and reports that her L.M.P was 24/12/2021. What will be her E.D.D?', '27/10/2022', '01/10/2022', '31/9/2022', '27/9/2022', 'B', 'Per Naegele''s rule (Myles): LMP 24/12/2021 + 7 days = 31/12/2021, minus 3 months = 30/09, +1 year = 2022; giving approx 01/10/2022 (the closest option). Other options do not fit the calculation.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The reflex that is elicited when the corner of the baby’s mouth is stroked and the baby turns its head and opens its mouth is:', 'Moro reflex', 'Rooting reflex', 'Sucking reflex', 'Turning reflex', 'B', 'Per Myles/Kozier, stroking the corner of the newborn''s mouth causing the head to turn and mouth to open is the rooting reflex, which aids location of the nipple.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A ridge between the upper and lower uterine segments, visible above the symphysis pubis is referred to as:', 'Retraction ring', 'Bandl’s ring', 'Uterine effacement', 'Uterine rupture', 'B', 'Per Myles Textbook for Midwives, a Bandl''s ring is a pathological retraction ring visible as a ridge between upper and lower uterine segments above the symphysis, warning of obstructed labour and impending rupture.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three bones that form the vault of the fetal head are:', 'Parietal, frontal, temporal', 'Frontal, lambdoidal, coronal', 'Temporal, parietal, coronal', 'Sinciput, parietal, lambdoidal', 'A', 'Per Myles Textbook for Midwives, the vault of the fetal skull is formed by the frontal, parietal (two), temporal and occipital bones; of the listed sets only ''parietal, frontal, temporal'' are true vault bones (the others list sutures).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following include pillars of safe motherhood:', 'Preconception care, essential obstetric care, child survival', 'Home visiting, school health program, post abortion care', 'Post abortion care, preconception care, focused antenatal care', 'Essential obstetric care, HIV/AIDS & STI management, male involvement', 'A', 'Per Kenya Safe Motherhood strategy/WHO, pillars include family planning, preconception/antenatal care, clean and safe delivery (essential obstetric care) and postnatal/child survival; option A best reflects these pillars. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug of choice for severe malaria in pregnancy is:', 'Amodiaquine', 'Artesunate', 'Artemether lumefantrine', 'Quinine', 'B', 'Per Kenya National Malaria Treatment Guidelines, intravenous artesunate is the drug of choice for severe malaria, including in pregnancy in all trimesters; quinine is now second-line.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pathological jaundice as a result of increased haemolysis involves all the following except:', 'G6PD deficiency', 'ABO incompatibility', 'Gilbert’s syndrome', 'Bacterial septicaemia', 'C', 'Per Basic Paediatric Protocols/standard texts, Gilbert''s syndrome causes unconjugated hyperbilirubinaemia from reduced conjugation (UGT enzyme), not increased haemolysis; G6PD deficiency, ABO incompatibility and septicaemia all cause haemolytic jaundice.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of spina bifida which comprises of the skin, meninges with or without CSF is:', 'Meningocele', 'Myelomeningocele', 'Cyatica', 'Occulta', 'A', 'Per standard paediatric/neurology texts, a meningocele is a spina bifida cystica variant containing skin and meninges with or without CSF but no neural tissue; a myelomeningocele also contains spinal cord/nerves.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At what age does closure of the posterior fontanelle occur?', '2months', '18monts', '22months', '1 month', 'A', 'Per standard paediatric texts, the posterior fontanelle closes by about 6-8 weeks (approximately 2 months) of age, whereas the anterior fontanelle closes around 18 months.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which are the storage ducts of milk in the mammary glands?', 'Alveoli', 'Lactiferous sinuses', 'Cooper’s ligaments', 'Lobules', 'B', 'Milk produced in the alveoli passes along the ducts to the lactiferous sinuses (ampullae) beneath the areola, which act as reservoirs storing milk. Alveoli produce milk; Cooper''s ligaments are support structures. Per Myles Textbook for Midwives (anatomy of the breast).', 'BScN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At which age of fetal development does the fetus experience rapid weight gain?', '20- 24 weeks', '8-12 weeks', '4- 8 weeks', '20 – 38 weeks', 'D', 'The greatest fetal weight gain occurs in the second half of pregnancy, from about 20 weeks to term (38 weeks), when subcutaneous fat and muscle mass are laid down. Earlier weeks are dominated by organogenesis, not weight gain. Per Myles Textbook for Midwives (fetal development).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Radiation is the most predominate mode of heat loss for a newborn. Radiation refers to:', 'loss of heat through water evaporation from the baby', 'loss of heat through the baby shivering', 'loss of heat from the baby''s surface to surrounding colder objects', 'loss of heat to moving air or fluid around the baby', 'C', 'Radiation is heat transfer from the newborn''s body surface to nearby cooler solid objects not in direct contact (e.g. cold walls/windows). Evaporation is water loss, convection is loss to moving air, conduction is loss to objects in contact. Per Kenya Basic Paediatric Protocols / Myles (thermoregulation).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At one week a mother complains that her new-born’s umbilical cord is smelly. You:', 'Tell her that often happens and reassure her all is well', 'Inspect the cord and surrounding skin', 'Clean the cord with antiseptic', 'Phone a paediatrician', 'B', 'A smelly cord may indicate omphalitis (a neonatal sepsis danger sign); the nurse must first assess by inspecting the cord and surrounding skin for redness, discharge or induration before acting. Reassuring without assessing is unsafe. Per Kenya Basic Paediatric Protocols (newborn care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother delivers a baby who has an Apgar score of 0/1. Which of the following findings demonstrate that Apgar score:', 'Has minimal grimace', 'Neonatal fetal heart rate of less than100', 'Gasping respiration', 'The body and the extremities are pale', 'D', 'An Apgar of 0/1 indicates a severely depressed neonate; only the completely pale/absent colour (0 for colour, no cyanosis grading possible) fits. Minimal grimace, HR<100 and gasping respiration all score 1 in their categories and would raise the score above near-zero, whereas generalised pallor reflects the profoundly depressed state. Per Kenya Basic Paediatric Protocols (Apgar scoring). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a newborn baby is in contact with cold surfaces, heat loss occurs by;', 'Evaporation', 'Radiation', 'Convection', 'Conduction', 'D', 'Heat loss from the baby''s body to a cold surface in direct contact (e.g. cold weighing scale or bed) occurs by conduction. Radiation is to non-contact objects, convection to moving air, evaporation from moisture. Per Kenya Basic Paediatric Protocols (thermoregulation).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aims of first examination of the newborn are;', 'Assess growth, maintain clear airway, assess maturity at birth', 'Detect birth injuries, assess minor disorders, detect congenital anomalies', 'Provide care, detect infections, assess growth and development', 'Detect birth injuries, detect any congenital abnormalities, and assess maturity at term.', 'D', 'The aims of the first (immediate) newborn examination are to detect birth injuries, identify congenital abnormalities and assess maturity/wellbeing at birth. Maintaining the airway is resuscitation, not the examination''s aim. Per Myles Textbook for Midwives (examination of the newborn).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anterior posterior fontanelle normally close by the age of;', '6 weeks and 18 weeks respectively', '18 weeks and 6 weeks respectively', '18 months and 6 weeks respectively', '6 months and 18 months respectively', 'D', 'The posterior fontanelle closes by about 6 weeks and the anterior fontanelle by about 18 months; among the options given, only ''D'' offers 18 months for the anterior fontanelle, which is the defining figure. The question wording is imperfect but D best matches the standard anterior-fontanelle closure time. Per Myles / Kenya Basic Paediatric Protocols (fontanelles). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The rooting reflex is defined as response of the baby to;', 'Being pulled upright by the wrist to a sitting position', 'Being supported upright ith his feet touching a flat surface', 'Stroking of the cheek or side of the mouth', 'Being left to drop from an angle of 45', 'C', 'The rooting reflex is elicited by stroking the newborn''s cheek or corner of the mouth, causing the baby to turn towards the stimulus and open the mouth to feed. The other options describe traction, stepping and Moro responses. Per Myles Textbook for Midwives (neonatal reflexes).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a contraindication for combined oral contraceptives', 'Mothers exclusively breast feeding', '30yrs old smoker', 'History of uterine cancer', 'Women on Antiretroviral therapy.', 'B', 'Per Kenya National Family Planning Guidelines/WHO MEC, smoking with COCs raises thromboembolic/cardiovascular risk; smoking is a contraindication (absolute at >=35yrs, strong caution otherwise). History of uterine (endometrial) cancer is not a COC contraindication the way this listed answer is; the smoker is the intended best contraindication answer. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse should advice a client using the basal body temperature method of contraception to;', 'Take her body temperature at the same time at night before getting to bed.', 'Avoid sex when she notices a temperature rise.', 'Avoid sex from the first day of menses until she notices a temperature rise.', 'Take her body temperature every morning before she gets out of bed', 'D', 'Per Kenya FP/fertility awareness guidelines, basal body temperature must be measured at rest each morning before any activity or getting out of bed to detect the post-ovulatory temperature rise.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drugs used for chemoprophylaxis against malaria include;', 'Mefloquine, doxycycline, proguanil', 'Artemether- lumefantrine, Fansidar, quinine', 'Fansidar, proguanil, metakelfin', 'Fansidar, Artemether- lumefantrine, metakelfin', 'A', 'Per Kenya malaria guidelines, chemoprophylaxis drugs include mefloquine, doxycycline and proguanil (and atovaquone-proguanil). Artemether-lumefantrine and quinine are for treatment, not routine prophylaxis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to the World Health Organization (WHO), clinical staging of HIV infection stage III in adults is characterized by;', 'Weight loss more than 50% of usual body weight, cryptoccocosis, extra pulmonary tuberculosis.', 'Weight loss of more than 50% of usual body weight, HIV encephalopathy, candidiasis of the oesophagus.', 'Weight loss of more than 10% of usual body weight, recurrent respiratory tract infections, herpes zoster within the last five years.', 'Weight loss of more than 10% of usual body weight, pulmonary tuberculosis, oral candidiasis.', 'C', 'Per WHO/Kenya ART clinical staging (adopted in Kenya National HIV guidelines), Stage III features unexplained weight loss >10% plus conditions like recurrent respiratory infections, herpes zoster, oral candidiasis and pulmonary TB; option C fits Stage III. Options with >50% weight loss, cryptococcosis, oesophageal candidiasis or HIV encephalopathy are Stage IV. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Medical eligibility criteria category 4 for contraceptive implants include:', 'Women with history of breast cancer', 'Women who have severe cirrhosis', 'Women who have unexplained vaginal bleeding', 'Women who have deep venous thrombosis', 'A', 'Per WHO/Kenya Medical Eligibility Criteria for contraceptives, current/history of breast cancer is a hormonal-contraceptive concern; current breast cancer is Category 4 and past breast cancer Category 3 for implants, making breast cancer the correct MEC-4 associated condition here. DVT and severe cirrhosis are typically Category 3, and unexplained vaginal bleeding is Category 3 before evaluation. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In enterobiasis infection, the adult worm lives in the:-', 'Lungs', 'Caecum', 'Large intestines', 'Small intestines', 'B', 'Per parasitology in Kenyan nursing texts, in enterobiasis the adult Enterobius vermicularis (pinworm) lives in the caecum and appendiceal region; females migrate to the perianal area to lay eggs. Caecum is the specific site making it the best answer over ''large intestines''.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a lymphoma that affects children:', 'Non-hodgkin''s disease', 'Acute lymphoblastic disease', 'Acute myeloid leukemia', 'Wilm''s tumor', 'A', 'Non-Hodgkin''s lymphoma is a lymphoma of childhood; ALL is a leukemia, AML is a leukemia, and Wilm''s tumor is a renal tumor, not lymphomas (Nelson/Basic Paediatric Protocols, Kenya).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant who has no head lag when pulled to a sitting position is able to reach for objects and transfer them from hand to hand is likely to be in what age?', '4 months', '6 months', '9 months', '12 months', 'B', 'Absence of head lag on pull-to-sit, reaching for objects and hand-to-hand transfer are classic 6-month developmental milestones (Basic Paediatric Protocols, Kenya; IMNCI developmental milestones).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bullous impetigo;', 'Is not contagious', 'Is commonly caused by Staphylococcus', 'Presents with painful blisters', 'Is managed using topical steroids', 'B', 'Bullous impetigo is commonly caused by Staphylococcus aureus (toxin-mediated); it is contagious, presents with fragile painless bullae, and is treated with antibiotics, not topical steroids (Basic Paediatric Protocols; Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of a child with mumps includes the following EXCEPT', 'Use of cold compresses', 'Use of aspirin to relieve pain', 'Warm salt water gargles', 'Avoiding acidic foods', 'B', 'Aspirin is contraindicated in children with viral illness (mumps) due to Reye''s syndrome risk; cold compresses, warm salt gargles and avoiding acidic foods are appropriate, so aspirin is the EXCEPTion (Basic Paediatric Protocols; Kenya paediatric guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 1 ½ yrs old child with meningitis is likely to present with;', 'Bulging of the fontanelle, cold extremities,rash', 'Vomiting, rash, fever', 'Fever, bulging of the fontanelle, photophobia', 'Lethargy, Seizure, Bulging fontanelle', 'C', 'In an 18-month-old, meningitis typically presents with fever, bulging fontanelle (anterior fontanelle may still be open) and photophobia; this combination best represents classic meningeal signs (Basic Paediatric Protocols; IMNCI). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Rheumatic heart disease is caused by;', 'Streptococcus pyogenes', 'Staphylococcus aureus', 'Haemophilus influenza', 'Streptococcus pneumonia', 'A', 'Rheumatic heart disease follows rheumatic fever caused by group A beta-haemolytic Streptococcus pyogenes; the other organisms are not implicated (Brunner & Suddarth''s; Kenya clinical guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When palpating a child''s abdomen you note hepatomegaly. You know this can be a sign of what cardiac problem?', 'Right sided heart failure', 'Left- sided heart failure', 'Rheumatic heart disease', 'Anemia', 'A', 'Right-sided heart failure causes systemic venous congestion, producing hepatomegaly and peripheral oedema. Left-sided failure causes pulmonary congestion. Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What type of imbalance is typically a trigger for Status epilepticus in a vulnerable child?', 'Temperature', 'Electrolyte', 'Hormonal', 'Fluid', 'B', 'Electrolyte imbalances (notably hyponatraemia, hypocalcaemia, hypoglycaemia-related) commonly precipitate status epilepticus in vulnerable children. Fever triggers simple febrile seizures, but sustained status epilepticus is classically driven by electrolyte disturbance. Per Basic Paediatric Protocols (Kenya). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse is caring for a client admitted 2days ago with myocardial infection .upon assessment the nurse notes a new systolic murmur at the cardiac apex. The nurse should assess the client for which of the following conditions?', 'Ventricular aneurysm', 'Acute pericarditis', 'Papillary muscle dysfunction', 'Pulmonary embolism', 'C', 'A new systolic (apical) murmur post-MI signals papillary muscle dysfunction/rupture causing mitral regurgitation; Brunner & Suddarth lists this as a mechanical complication of MI. Ventricular aneurysm and pericarditis do not typically produce a new apical systolic murmur.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 21 year old male client is transported by ambulance to the emergency unit. He complains of severe pain in his right chest where he struck the steering wheel. Which is the primary client goal at this time?', 'Reduce client’s anxiety', 'Maintain adequate oxygenation', 'Decrease chest pain', 'Maintain adequate circulating volume', 'B', 'With blunt chest trauma the ABC priority (airway/breathing) makes maintaining adequate oxygenation the primary goal; Brunner & Suddarth trauma management places oxygenation before pain and anxiety control.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has just undergone spinal fusion after experiencing herniation of a lumbar disk. The nurse would avoid which intervention to maintain client safety after this procedure?', 'Use the overhead trapeze.', 'Keep the head of the bed flat.', 'Place pillows under the length of the legs.', 'Use logrolling technique for repositioning.', 'C', 'After spinal fusion the spine must be kept in neutral alignment; placing pillows along the full length of the legs causes spinal flexion and is avoided. Logrolling, overhead trapeze and a flat bed are safe/appropriate (Brunner & Suddarth ortho nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a difficult labor and birth, a primiparous woman refuses to feed her baby four hours after delivery, she states that she is too tired and just wants to sleep. The nurse should:', 'Tell the woman she can rest after she feeds her baby', 'Take the baby back to the nursery, reassuring the woman that her rest is a priority at this time', 'Recognize this as a behavior of the taking-hold stage', 'Record the behavior as ineffective maternal-newborn attachment', 'B', 'In the taking-in phase after a difficult birth the mother is fatigued and focused on her own needs; the nurse supports rest and defers feeding, reassuring her (Myles Textbook for Midwives, Rubin''s maternal phases). Forcing feeding or labelling poor attachment at 4 hours is inappropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('About puerperium, the following statement is true', 'The puerperium is a period of 60 days following delivery of the placenta', 'The puerperium is a period of 42 days following delivery of the placenta', 'The puerperium is a period of 21 days following delivery of the placenta', 'The puerperium is a period of 14 days following delivery of the placenta', 'B', 'The puerperium is the ~6-week (42-day) period after delivery of the placenta during which the reproductive organs return to the non-pregnant state (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At the end of labor, the cervix is:', 'soft and flabby', '2cm dilated', '1cm dilated', 'a slit', 'A', 'At the end of labour, after full dilatation and delivery, the cervix is soft, flabby and thin; it is no longer measured in cm of dilatation (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After delivery of a healthy newborn. Which time frame should the nurse relay to the client regarding the return of bowel function?', '7 days postpartum', '3 days postpartum', 'Within 2 weeks postpartum', 'On the day of delivery', 'B', 'Normal bowel function typically returns about 2-3 days postpartum, delayed by reduced tone, perineal discomfort and analgesia (Myles Textbook for Midwives; postpartum nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antenatal care of HIV positive client includes:', 'Antiretroviral therapy for life immediately HIV positive status is confirmed', 'Sulfadoxine Pyrimethamine(SP)and cotrimoxazole prophylaxis daily until delivery', 'Antiretroviral therapy up to postnatal period from the time the CD4 count is established', 'Delay administration of Sulfadoxine Pyrimethamine until antiretroviral therapy is started Maternal and Newborn Health (MNH) Pillars', 'A', 'Per Kenya PMTCT / National HIV guidelines (Option B+), all HIV-positive pregnant women are started on lifelong ART immediately upon diagnosis regardless of CD4 count.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client who is pregnant reports nausea and vomiting. The nurse reassures the client that these symptoms will subside by;', '6-9 WEEKS', '10-13 WEEKS', '14-17 WEEKS', '18- 22 WEEKS', 'B', 'Per Myles Textbook for Midwives, nausea and vomiting of pregnancy typically resolve by the end of the first trimester (around 12-13 weeks) as hCG levels fall.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Effects of gestational diabetes on the fetus include:', 'Congenital malformation, macrosomia,', 'Fetal hypoglycaemia, congenital anomalies', 'Hypocalcemia, fetal hyperglyceamia', 'Macrosomia, fetal hypoglycaemia', 'D', 'Per Myles Textbook for Midwives, gestational diabetes causes fetal macrosomia (maternal hyperglycaemia) and neonatal hypoglycaemia (fetal hyperinsulinism after birth). Congenital malformations are chiefly linked to pre-gestational diabetes, making this the best option. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The normal level of haemoglobin (Hb) on a pregnant woman is:-', '10-15g/dl', '12-14g/dl', '9-14g/dl', '11-12g/dl', 'D', 'Per Kenya ANC / WHO guidelines, the normal haemoglobin in pregnancy is 11 g/dl or above (roughly 11-12 g/dl); below 11 g/dl is anaemia in pregnancy. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diastolic pressure is usually not affected by excitement, its increase therefore is more significant in assessment of pregnant women for pre-eclampsia. The range of change in mmHg is:', '10-15', '15-20', '15-30', '20-30', 'C', 'Per Myles Textbook for Midwives, a rise in diastolic pressure of 15-30 mmHg above baseline is significant in assessing pregnant women for pre-eclampsia as diastolic pressure is less affected by excitement. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of placenta praevia type three when the fetus has died in utero includes:', 'Preparation of women for emergency c-section', 'Induction of labour by use of syntocinon', 'Gentle palpation through vaginal fornices to determine whether posterior or anterior', 'Complete bed rest and speculum examination on the third day', 'A', 'Placenta praevia type III (major/partial) covers a large part of the internal os, so delivery must be by caesarean section regardless of fetal viability — vaginal delivery/oxytocin induction risks catastrophic haemorrhage. Even with a dead fetus, a major praevia is delivered abdominally (Myles Textbook for Midwives; Kenya MOH maternal guidelines). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After birth, the functional closure of ductus arteriosus takes place within:', '0-1 hour', '2-4hour', '4-6 hours', '8-10 hours', 'B', 'Per Myles Textbook for Midwives and neonatal physiology, functional (physiological) closure of the ductus arteriosus occurs within the first few hours after birth (about 2-4 hours), with anatomical closure over weeks.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings that are consistent with hyperthyroidism include', 'Decreased serum triiodothyronine (T3) and thyroxine (T4) levels', 'Elevated serum thyrotropin releasing hormone (TRH) levels', 'Decreased radioactive iodine uptake', 'Increased free triiodothyronine (T3) and thyroxine (T4) levels', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, hyperthyroidism is characterised by elevated free T3 and T4 with suppressed TSH and increased radioactive iodine uptake.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Discharge instructions for a client with chronic respiratory acidosis should include', 'Discussing how to plan for periods of increased activity', 'Teaching about a low protein, low carbohydrate diet', 'Demonstrating exercises to increase vital capacity', 'Encouraging participation in activities such as jogging', 'C', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, clients with chronic respiratory acidosis (e.g. COPD) are taught breathing/pulmonary exercises to improve vital capacity; strenuous activity like jogging and increased activity periods are inappropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common preventable cause of valvular heart disease is:', 'Congenital disease acquired intrauterine', 'Calcium deposits and thrombus formation', 'Marfans syndrome', 'Beta-hemolytic streptococcal infection', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rheumatic heart disease following group A beta-haemolytic streptococcal infection is the most common preventable cause of valvular heart disease.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pelvic inflammatory diseases include:', 'Salpingitis, cervicitis, candidiasis', 'Cervicitis, endometritis, oophoritis.', 'Trichomoniasis, salpingitis, urethritis.', 'Candidiasis, toxic shock syndrome, endometritis.', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, PID is ascending infection of the upper genital tract including cervicitis, endometritis, salpingitis and oophoritis; candidiasis and trichomoniasis are lower-tract/vaginal infections, so option B best lists true PID components.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cholelithiasis is associated with:-', 'Abnormal metabolism of cholesterol and bile salts.', 'Abnormal metabolism of lipids and bile acids.', 'Chronic pancreatitis.', 'Hepatitis.', 'A', 'Per Brunner & Suddarth''s, cholesterol gallstones (the commonest type) form when bile is supersaturated with cholesterol relative to bile salts, i.e. abnormal metabolism of cholesterol and bile salts. Lipids/bile acids and pancreatitis/hepatitis are not the primary mechanism.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Glomerulonephritis usually follows:-', 'Staphylococcal infection.', 'Gonococcal infection.', 'Gonococcal infection.', 'Streptococcal infection', 'D', 'Per Brunner & Suddarth''s, acute post-streptococcal glomerulonephritis typically follows a group A beta-haemolytic streptococcal throat or skin infection. Options B and C are duplicates (gonococcal) and incorrect.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Body mechanics usually prescribed for clients with low pain include:-', 'Bending at knee and hips, standing straight, carrying objects close to the body.', 'Bending at the waist carrying objects close to the body, standing straight.', 'Sleeping on the side carrying objects farther from the body, bending at the knees and hips.', 'Bending at the waist, sleeping on the side, standing straight.', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, correct body mechanics for low-back pain prevention involve bending at the knees and hips (not the waist), keeping the back straight, and carrying objects close to the body to reduce spinal strain.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a nurse is monitoring a patient for cerebrospinal fluid (CSF) leak he/she should observe for:-', 'Halo sign.', 'Babinski reflex.', 'Iliopsoas sign.', 'Blumberg sign.', 'A', 'Per Brunner & Suddarth''s, CSF leak is detected by the halo (ring) sign, where drainage on gauze forms a clear ring around blood, and by glucose-positive fluid. Babinski, iliopsoas and Blumberg signs are unrelated neurological/abdominal signs.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonest cause of toxic goitre (Grave’s disease) is: -', 'Pituitary tumours', 'Benign thyroid', 'Lack of iodine in the diet', 'Immunoglobulins reaction', 'D', 'Per Brunner & Suddarth''s, Graves'' disease is an autoimmune disorder caused by thyroid-stimulating immunoglobulins (TSH-receptor antibodies). Iodine lack causes simple/endemic goitre, not toxic Graves'' goitre.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The carcinogenic risk factors for laryngeal cancers include:', 'Tar products, mustard gas, chronic laryngitis', 'Asbestos, chronic laryngitis, voice straining', 'Voice straining, high fibre diet, tobacco', 'Asbestos, tobacco, tar products', 'D', 'Per Brunner & Suddarth''s, carcinogenic risk factors for laryngeal cancer include tobacco, alcohol, asbestos and tar/industrial exposures. A high-fibre diet (option C) is protective, not carcinogenic, so D is the fully correct set.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The position an unconscious patient should be nursed in is:', 'Recumbent', 'Lithotomy', 'Prone', 'Semi-prone', 'D', 'Per Kozier & Erb''s, the unconscious patient is nursed in the semi-prone (recovery/lateral) position to maintain a patent airway and allow drainage of secretions, preventing aspiration.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parklands’ formula is used to calculate', 'Total burnt surface area', 'Fluid replacement', 'Thickness of the burn', 'Hemo-concentration', 'B', 'Per Brunner & Suddarth''s / MOH burns guidelines, the Parkland formula (4 ml x weight x %TBSA) calculates the volume of IV fluid replacement required in the first 24 hours after a burn.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following thyroidectomy, the nurse suspects damage or removal of parathyroid gland when the patient develops:', 'Muscle weakness and weight loss', 'Hyperthermia and severe tachycardia', 'Hypertension and difficulty in swallowing', 'Laryngeal stridor and tingling in the hands and feet', 'D', 'Per Brunner & Suddarth''s, parathyroid damage after thyroidectomy causes hypocalcaemia manifesting as tetany: perioral/peripheral tingling (paraesthesia), carpopedal spasm and laryngeal stridor/spasm. 328. increased concentration of red blood cells due to excessive production of erythropoietin is referred to as: A. primary polycythemia B. leukopenia C. secondary polycythemia D. agranulocytosis Answer: C. secondary polycythemia Rationale: Per Brunner & Suddarth''s, secondary polycythaemia is an increase in RBC mass driven by excessive erythropoietin (e.g. from hypoxia). Primary polycythaemia (vera) is a clonal marrow disorder with low/normal erythropoietin.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following observations are noted on the patient on underwater seal drainage:', 'Vital signs, patent connections, colour of drainage', 'Vital signs, colour of drainage, amount of drainage', 'Vital signs, patient understanding of the procedure, amount of drainage', 'Vital signs, patient understanding of the procedure, cyanosis', 'A', 'Per Brunner & Suddarth''s, monitoring a patient on underwater seal (chest) drainage includes vital signs, ensuring patent/intact connections and tubing, and observing the colour and amount of drainage. Option A best captures the objective drainage-system observations. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fractures of the base of the skull will manifest with', 'Hemorrhage from the nose, the pharynx or the ears', 'Cerebrospinal fluid leakage from the ears', 'Bloody spinal fluid', 'Persistent localized pain on swelling', 'A', 'Per Brunner & Suddarth''s, basal skull fractures manifest with bleeding and CSF leakage from the nose (rhinorrhoea), pharynx and ears (otorrhoea), plus Battle''s sign and raccoon eyes. Option A most completely describes the classic bleeding presentation. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main long-term complication following radical mastectomy is', 'Phantom pain', 'Tingling and numbness', 'Lymphoedema', 'Paralysis', 'C', 'Per Brunner & Suddarth''s, lymphoedema of the affected arm is the main long-term complication after radical mastectomy due to removal of axillary lymph nodes impairing lymphatic drainage.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The accumulation of thick, purulent fluid within the pleural space with fibrin development is characteristic of:', 'Empyema', 'Effusion', 'Pleurisy', 'Emphysema', 'A', 'Per Brunner & Suddarth''s, empyema is the accumulation of thick, purulent fluid within the pleural space, often with fibrin and loculation. Pleural effusion is fluid without pus, pleurisy is inflammation, and emphysema is alveolar destruction.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anterior posterior fontanelles normally closes at the age of:', '6weeks and 18 weeks respectively', '18 weeks and 6 weeks respectively', '18 months and 6 weeks respectively', '6 months and 18 months respectively', 'B', 'Per Basic Paediatric Protocols/paediatric texts, the posterior fontanelle closes by about 6-8 weeks and the anterior fontanelle much later (around 18 months). Option B is the only choice giving the anterior fontanelle a later closure (18 ''weeks'') than the posterior (6 weeks), so it is the intended best answer; note the correct anterior closure is ~18 months. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing Leopold''s maneuver, the purpose of the first maneuver is to determine', 'Fetal part lying in the fundus and presentation', 'Location of fetal back and position', 'Engagement of the presenting part', 'The degree of flexion of fetal head', 'A', 'Per Myles Textbook for Midwives, the first Leopold''s manoeuvre (fundal palpation) determines which fetal pole occupies the fundus, thereby indicating the presentation/lie.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If Mrs. Cola’s menstrual period was on 27.7.08, her expected date of delivery will be:', '3.4.09', '4.5.09', '3.5.09', '4.4.09', 'C', 'Per Naegele''s rule (Myles), EDD = LMP - 3 months + 7 days + 1 year. From 27.7.08: -3 months = 27.4, +7 days = 3.5, +1 year = 3.5.09.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal axis pressure is a physical change that is more significant durin', 'Early stages of labour transmitting the force of contraction to the upper pole of fetus.', 'Second stage of labour when membranes are intact.', 'Active and second stages of labour when membranes are ruptured.', 'Second stage of labour transmitting the force of contraction to the lower pole of the uterus.', 'A', 'Per Myles Textbook for Midwives, fetal axis pressure is the force of the contraction transmitted through the fetal long axis from the upper pole (fundus/breech) down to the presenting part, aiding descent, and is most evident once the membranes rupture in advancing labour. Among the options this best describes fundal transmission to the fetal pole. ⚠ Question may be INCOMPLETE ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At primary level of ant-retroviral prophylaxis for PMTCT (prevention of mother to child transmission), a HIV-positive woman should take:-', 'Nevirapine 300 mgs at onset of labour', 'Nevirapine 200 mgs at onset of labour', 'Zidovudine 300 mgs 3 hourly for 12 hours.', 'Zidovudine 2mg/ kilogram body weight within three days of delivery', 'B', 'Per Kenya PMTCT guidelines, single-dose intrapartum nevirapine prophylaxis is 200 mg orally to the mother at onset of labour; 300 mg is incorrect dosing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Perineal trauma is common in delivery of face to pubis due to:-', 'Irregular shape of the face as a presenting part.', 'Persistent occipito-posterior position when occiput becomes the leading part.', 'Large presenting mentovertical diameter', 'Large presenting occipito-frontal and biparietal diameters.', 'B', 'Per Myles Textbook for Midwives, face-to-pubis (persistent occipitoposterior delivered with occiput anterior/leading) distends the perineum with the larger presenting diameters, causing severe perineal stretching and trauma. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After birth, the functional closure of ductus arteriosus takes place within:-', '1-2hours.', '2-4 hours', '4-6 hours', '8-15 hours', 'D', 'Per neonatal physiology (Myles/paediatric texts), the ductus arteriosus closes functionally within the first 8-24 hours after birth in response to rising oxygen tension; 8-15 hours best fits this window.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The exogenous causative organisms to puerperal infection include:-', 'Escherichia coli, clostridium welchii.', 'Streptococcus faecalis, haemolytic streptococcus', 'Staphylococcus aureus, Escherichia coli.', 'Haemolytic streptococcus aureus', 'C', 'Per Myles Textbook for Midwives, exogenous (externally introduced) organisms in puerperal sepsis include Staphylococcus aureus and E. coli carried on hands/instruments, whereas endogenous flora arise from the woman''s own tract. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In monitoring fetal well being using the fetal kick chart, you will tell the client to notify you if she counts:-', 'More than 10 movements in 3hours', 'Less than 10 movements in 3hours', 'More than 10 movements per hour', 'Less than 10 movements per hour', 'D', 'Per fetal-wellbeing monitoring (Myles/MOH), reduced fetal movements are a warning sign; the mother is told to report if she counts fewer than the expected movements. Among the options, less than 10 movements per hour is the alerting (reduced) threshold to report. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone that maintains endometrium and stimulates maternal metabolism and development of breast alveoli during pregnancy is:-', 'Human chorionic gonadotropin', 'Human placental lactogen', 'Oestrogen', 'Progesterone', 'C', 'Per Myles Textbook for Midwives, oestrogen maintains the endometrium, stimulates maternal metabolism and promotes growth of the breast ductal/alveolar tissue during pregnancy; progesterone chiefly maintains pregnancy and relaxes smooth muscle. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of superficial thrombophlebitis include:-', 'Local redness and tenderness in a portion of the vein', 'Edema of the ankle and lower leg', 'Pain in the affected leg and foot', 'Positive Homan’s sign', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, superficial thrombophlebitis presents with localized redness, warmth and tenderness along the palpable, cord-like superficial vein; oedema and positive Homan''s sign indicate deep vein thrombosis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Direct causes of placenta abruption include:-', 'Abnormally short umbilical cord, sudden loss of uterine volume', 'Defective vascularization of the deciduas, previous uterine surgery', 'Injury to the abdomen from fall or accident, multiple pregnancy', 'Advanced maternal age, injury to the abdomen from fall or accident', 'C', 'Per Myles Textbook for Midwives, direct/mechanical causes of placental abruption include abdominal trauma and sudden decompression such as after delivery of a first twin (multiple pregnancy); defective decidual vascularization and hypertension are indirect predisposing causes. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Babies born with intrauterine growth retardation are usually prone to;', 'Congenital abnormalities, hyperglycemia', 'Neonatal hyperglcemia, asphyxia', 'Neonatal asphyxia, birth defects', 'Neonatal tetanus, asphyxia', 'C', 'Per Myles Textbook for Midwives and Basic Paediatric Protocols (Kenya), IUGR (small-for-gestational-age) infants are prone to intrapartum/neonatal asphyxia, hypoglycaemia (not hyperglycaemia), and congenital anomalies/birth defects. Options with hyperglycaemia are wrong (SGA babies get HYPOglycaemia); neonatal tetanus relates to unhygienic cord care, not IUGR. So asphyxia plus birth defects is the best pairing.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Benefits of breastfeeding to the infant include:', 'Increased cognitive development, less chances of developing diabetes type 2, less risk of extreme obesity', 'Lowered risk of infection, less likely to become overweight, protection against malignancies', 'Strengthens bonding, protection against malignancies, decreased risk of cardiovascular diseases', 'Reduced risk of metabolic syndrome, lowered risk of developing necrotizing enterocolitis, protection against diabetes type 1', 'B', 'Per WHO/Kenya MOH infant feeding guidelines, breastfeeding lowers infant infection risk, reduces risk of later overweight/obesity, and offers some protection against childhood malignancies. Option A wrongly cites diabetes type 2 for the infant; the best evidence-based cluster of INFANT benefits is B. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following respiratory patterns indicate increased intracranial pressure in the brain stem?', 'Slow, irregular respirations', 'Rapid, shallow respirations’', 'Asymmetric chest excursion', 'Nasal flaring', 'A', 'Per Brunner & Suddarth, brainstem compression from raised ICP produces slow, irregular (e.g., Cheyne-Stokes, ataxic/Biot''s, or apneustic) respiratory patterns as part of Cushing''s response. Rapid shallow breathing, asymmetric excursion and nasal flaring are not the hallmark brainstem pattern of increased ICP.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse administers mannitol to the client with increased intracranial pressure. Which parameter needs close monitoring', 'Muscle relaxation', 'Intake and output', 'Widening of the pulse pressure', 'Pupil dilation', 'B', 'Per Brunner & Suddarth, mannitol is an osmotic diuretic used to reduce ICP; it causes profuse diuresis, so strict intake and output (with fluid/electrolyte and osmolality) monitoring is essential to avoid dehydration and renal compromise. Muscle relaxation, widening pulse pressure and pupil dilation are not the primary parameter tied to the drug''s diuretic action.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For a client who is experiencing expressive aphasia, which nursing intervention is most helpful in promoting communication?', 'Speaking loudly', 'Using a picture board', 'Writing directions so client can read them', 'Speaking in short sentence ● (6) The nurse is assessing the motor and sensory function of an unconscious client. The nurse should use which technique to test the client’s peripheral response to pain? (A) Sternal rub (B) Nail bed pressure (C) Pressure on the orbital rim - (localizing pain) (D) Squeezing of the sternocleidomastoid muscle', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, expressive (Broca''s) aphasia means the client understands but cannot produce speech; a picture/communication board lets them convey needs. Speaking loudly (A) is for hearing loss, not aphasia. (Option D text is garbled with a trailing unrelated stem, but B is the best communication aid.) ⚠ Question may be INCOMPLETE', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has a neurological deficit involving the limbic system. On assessment, which finding is specific to this type of deficit?', 'Is disoriented to person, place, and time', 'Affect is flat, with periods of emotional lability', 'Cannot recall what was eaten for breakfast today', 'Demonstrates inability to add and subtract; does not know who is the president of the United States', 'B', 'Per Brunner & Suddarth, the limbic system governs emotion and behaviour, so a deficit produces flat affect and emotional lability. Disorientation, recent-memory loss and impaired calculation/general knowledge point more to cortical/hippocampal or global cognitive dysfunction; altered emotional regulation is specific to the limbic system.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating the status of a client who had a craniotomy 3 days ago. Which assessment finding would indicate that the client is developing meningitis as a complication of surgery?', 'A negative Kernig’s sign', 'Absence of nuchal rigidity', 'A positive Brudzinski’s sign', 'A Glasgow Coma Scale score of 15', 'C', 'Per Brunner & Suddarth, meningitis produces meningeal irritation signs: nuchal rigidity and positive Kernig''s and Brudzinski''s signs. A positive Brudzinski''s sign indicates developing meningitis; a negative Kernig''s, absent nuchal rigidity and a normal GCS of 15 would suggest NO meningitis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with myasthenia gravis has become increasingly weaker. The health care provider prepares to identify whether the client is reacting to an overdose of the medication (cholinergic crisis) or an increasing severity of the disease (myasthenic crisis). An injection of edrophonium is administered. Which finding would indicate that the client is in a cholinergic crisis?', 'No change in the condition', 'Complaints of muscle spasms', 'An improvement of the weakness', 'A temporary worsening of the condition', 'D', 'Per Brunner & Suddarth, in the edrophonium (Tensilon) test, improvement of weakness indicates myasthenic crisis (needs more anticholinesterase), whereas temporary worsening of weakness indicates cholinergic crisis (already too much drug). Hence temporary worsening indicates cholinergic crisis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for the male client who begins to experience seizure activity while in bed. Which of the following actions by the nurse would be contraindicated?', 'Loosening restrictive clothing', 'Restraining the client’s limbs', 'Removing the pillow and raising padded side rails', 'Positioning the client to side, if possible , with the head flexed forward', 'B', 'Per Kozier & Erb''s Fundamentals and Brunner & Suddarth, during a seizure the nurse must NOT restrain the limbs (risks fractures/injury). Correct actions are loosening clothing, removing the pillow and padding side rails, and side-lying with head flexed forward; restraining limbs is contraindicated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A female client has experienced an episode of myasthenic crisis. The nurse would assess whether the client has precipitating factors such as:', 'getting too little exercise', 'taking excess medication - (will cause cholinergic crisis instead)', 'omitting doses of medication', 'increasing intake of fatty foods', 'C', 'Per Brunner & Suddarth, myasthenic crisis is precipitated by under-medication (omitting/missing anticholinesterase doses), infection, stress or surgery. Excess medication causes cholinergic crisis; too little exercise and fatty foods are not precipitants. Thus omitting doses precipitates myasthenic crisis.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A male client is having a tonic-clonic seizures. What should the nurse do first?', 'Elevate the head of the bed', 'Restrain the client’s arms and legs', 'Place a tongue blade in the client’s mouth', 'Take measures to prevent injury', 'D', 'Per Kozier & Erb''s and Brunner & Suddarth, the FIRST priority during a tonic-clonic seizure is to protect the client from injury (ease to the floor/side-lying, clear the area, cushion the head). Do not restrain limbs or insert a tongue blade; elevating the head is not the priority. Injury prevention/safety comes first.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The area of the brain which is involved in the understanding of meaning is:', 'Broca’s area', 'association areas', 'Wernicke area', 'Motor speech area', 'C', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (posterior superior temporal lobe) is responsible for comprehension/understanding of language meaning. Broca''s/motor speech area handles speech production; general association areas integrate information, but understanding of meaning is specifically Wernicke''s area.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parkinson’s disease , is caused by the degeneration of neurons in an area of the brain called the:', 'Substantia nigra', 'Basal ganglia', 'Cerebellum', 'Corpus callosum', 'A', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra, reducing dopamine. Although the basal ganglia circuit is affected, the primary site of neuronal degeneration is the substantia nigra.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is unconscious following a tonic-clonic seizure. What should the nurse do FIRST?', 'Place the client in a side-lying position', 'Check the pulse', 'Administer Valium', 'Place a tongue blade in the mouth (Never do this! Places client in danger!)', 'A', 'Per Kozier & Erb''s and Brunner & Suddarth, in the postictal unconscious client the FIRST action is to place them in a side-lying (recovery) position to maintain a patent airway and prevent aspiration. Never insert a tongue blade; pulse check and Valium are not the immediate priority over airway positioning.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse enters the room as the client is beginning to have a tonic-clonic seizure. What action should the nurse implement first?', 'Determine if the client is incontinent of urine or stool.', 'Provide the client with privacy during the seizure.', 'Note the first thing the client does in the seizure.', 'Assess the size of the client’s pupils.', 'C', 'Per Brunner & Suddarth, once safety is ensured the nurse''s key nursing action at seizure onset is accurate observation/documentation, beginning with noting the first thing the client does (onset/aura and initial movements), which aids diagnosis and localization. Checking incontinence, providing privacy and pupil size are secondary to observing the seizure''s onset. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If a male client experienced a cerebrovascular accident (CVA) that damaged the hypothalamus, the nurse would anticipate that the client has problems with:', 'Thinking and reasoning', 'Body temperature control', 'Balance and equilibrium', 'Visual acuity', 'B', 'The hypothalamus is the principal thermoregulatory centre (also controlling hunger, thirst, and neuroendocrine function). Damage impairs body temperature control. Thinking/reasoning is cortical (frontal), balance is cerebellar, and visual acuity is occipital/optic pathway (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During recovery from a cerebrovascular accident (CVA), a female client is given nothing by mouth, to help prevent aspiration. To determine when the client is ready for a liquid diet, the nurse assesses the client’s swallowing ability once each shift. This assessment evaluates', 'Cranial nerves III and V', 'Cranial nerves IX and X', 'Cranial nerves I and II', 'Cranial nerves VI and VIII', 'B', 'Swallowing (gag reflex) is mediated by the glossopharyngeal (IX) and vagus (X) nerves. Assessing swallowing ability tests these cranial nerves before advancing diet post-CVA (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A male client is admitted with a cervical spine injury sustained during a diving accident. When planning this client’s care, the nurse should assign highest priority to which nursing diagnosis?', 'Disturbed sensory perception (tactile)', 'Self-care deficit: dressing /grooming', 'Impaired physical mobility', 'Ineffective breathing pattern', 'D', 'A cervical (high) spinal cord injury threatens the diaphragm and respiratory muscles (C3-C5 innervate the diaphragm). Airway/breathing is the highest priority per ABC prioritisation; the other diagnoses are important but not immediately life-threatening (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Demyelination is defined as;', 'Loss of an axon in a neuron', 'Loss of dendrites in a neuron', 'Loss of protective sheath surrounding neurons', 'Loss of connective tissue between neurons', 'C', 'Demyelination is the loss/destruction of the myelin sheath surrounding nerve fibres (as in multiple sclerosis), slowing nerve conduction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of muscle coordination , including unsteady movements and staggering walk, due to disorders in the cerebellum is called?', 'Anoxia', 'Dyslexia', 'Paraplegia', 'Ataxia', 'D', 'Ataxia is impaired muscle coordination causing unsteady, staggering gait, characteristically due to cerebellar dysfunction. Anoxia is oxygen lack, dyslexia is a reading disorder, and paraplegia is lower-limb paralysis (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which part of the brain regulates heartbeat, breathing and other vital functions?', 'Grey matter', 'Brain stem', 'Occipital lobe', 'White matter', 'B', 'The brain stem (specifically the medulla oblongata) contains the cardiac, respiratory, and vasomotor centres regulating heartbeat, breathing and other vital functions (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common complications of spinal cord injury include each of the following EXCEPT?', 'Pressure sores', 'Deep vein thrombosis', 'Diarrhoea', 'Urinary Tract infections', 'C', 'Spinal cord injury commonly causes pressure sores, DVT (from immobility), and UTIs (from neurogenic bladder/catheterisation). Constipation, not diarrhoea, results from neurogenic bowel; thus diarrhoea is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Broca’s area is located in the', 'Brain stem', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'B', 'Broca''s area (motor speech centre) lies in the inferior frontal lobe of the dominant hemisphere; damage causes expressive (non-fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is located in the', 'Brain stem', 'Parietal lobe', 'Temporal lobe', 'Frontal lobe', 'C', 'Wernicke''s area (receptive/sensory speech centre) is located in the posterior superior temporal lobe of the dominant hemisphere; damage causes receptive (fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 60-year-old man complains of extremely severe, sharp, shooting pain in his face. Hee describes the episodes as being “like a bolt of electricity”that is brought about by touching a specific area. Lasta about 60 seconds, and occur many times during the day. Neurologic examination is completely normal but it is noted that part of his face is unshaven because he fears to touch that area. Which on the following is the most appropriate initial treatment?', 'Anticonvulsants', 'Aspirin', 'NSAIDS', 'Vasoconstrictors', 'A', 'The description is classic trigeminal neuralgia (brief, electric-shock-like facial pain triggered by touch). First-line treatment is an anticonvulsant, carbamazepine. Aspirin/NSAIDs and vasoconstrictors are ineffective (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following function is controlled by parasympathetic system?', 'Pupil constriction', 'Acceleration of heart beat', 'Stimulation of sweat glands', 'Contraction of hair muscles', 'A', 'Parasympathetic (rest-and-digest) stimulation causes pupil constriction (miosis), slows the heart, and reduces secretions. Acceleration of heart rate, sweating, and pilo-erection are sympathetic responses (Kozier & Erb''s Fundamentals; Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are caring for a woman in the second stage of labor. The client is experiencing uterine contractions every 2 minutes and cries out in pain with each contraction. This behaviour is best described as:', 'Exhaustion', 'Fear of losing control', 'Involuntary grunting', 'Valsalva''s maneuver', 'B', 'Crying out in pain with each contraction during transition reflects fear of losing control, a recognised psychological response requiring reassurance and support. It is not exhaustion, involuntary grunting (an urge to push), or Valsalva (Myles Textbook for Midwives). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman who is gravida 1, para 0 is admitted in active labour. Her cervix is 100% effaced, and she is dilated to 3 cm. The presenting part is at +1 station. The midwife is aware that the fetus'' head is:', 'Not yet engaged', 'Entering the pelvic inlet', 'Below the ischial spines', 'Visible at the vaginal opening', 'C', 'Station is measured relative to the ischial spines (station 0). A presenting part at +1 station is 1 cm below the ischial spines (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mrs. Peters is experiencing contractions every 2 minutes. She is in which stage of birth?', 'First', 'Second', 'Third', 'Fourth', 'A', 'Contractions every 2 minutes without further data indicate established/active first stage of labour (cervical dilatation). The stem gives no evidence of full dilatation or delivery, so it is the first stage (Myles Textbook for Midwives). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When resuscitating a neonate who has neonatal asphyxia after how long should the midwife use ambubag', 'After 30 seconds of oxygen by face mask', 'When the baby remains apnoeic after 30 minutes of facemask oxygen therapy.', 'When the neonate is no longer cyanosed', 'When the neonate P02 level has increased', 'A', 'In neonatal resuscitation, if the baby is not breathing adequately after the initial steps, positive-pressure ventilation with a bag-and-mask (ambubag) is started within about 30 seconds (''the golden minute''). The 30-minute option is clearly wrong (Kenya Basic Paediatric Protocols; WHO/HBB neonatal resuscitation).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which neonate from the listed below is at risk of developing severe jaundice?', 'Breast feed neonates', 'Conjoined twins', 'Neonates with haemorrhagic conditionsions', 'Term neonates', 'C', 'Extravascular blood breakdown (cephalhaematoma, bruising, haemorrhage) increases the bilirubin load and predisposes to severe jaundice. Term neonates and normal breastfeeding are not high-risk to the same degree (Kenya Basic Paediatric Protocols; Myles Textbook for Midwives). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most appropriate feature seen in symmetric growth retarded infant?', 'Weight is depressed more than length or head circumference.', 'Fetal growth retardation probably has occurred in the last trimester of pregnancy.', 'Weight, length and head circumference are below normal and babies look like miniature normal babies.', 'It is mostly linked with cigarette smoking.', 'C', 'Symmetric (early-onset) IUGR affects weight, length and head circumference proportionately, producing a proportionately small (''miniature normal'') infant. Asymmetric IUGR (late trimester, spares head, linked to smoking) is described by the other options (Myles Textbook for Midwives; Basic Paediatric Protocols).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A new born infant was delivered in your maternity unit an hour ago. The skin of this infant appears to be red, wrinkly with ribs visible under the skin. When was the infant probably born?', 'Before 24 and 27 weeks', 'Before 30 and 32 weeks', 'Before 29 and 32 weeks', 'Around 35 weeks', 'D', 'Red, wrinkled, thin skin with visible ribs but delivered surviving in a maternity unit fits a moderately preterm infant around 35 weeks; extreme prematurity (24-27 weeks) skin is gelatinous/translucent. Of the options, ~35 weeks best matches the described appearance and survival (Myles Textbook for Midwives; Basic Paediatric Protocols). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement is true about meconium?', 'Meconium is 1st found in the foetal ileum between the 20th and 26th weeks of gestation', 'Meconium passage is uncommon before 36 weeks but its common in pregnancies beyond 42 weeks', 'In utero passage of meconium is common because the anal sphincter tone is poor', 'All of the above', 'D', 'Meconium first forms in the fetal ileum around 20-26 weeks, its passage in utero is uncommon before 36 weeks but rises in post-term (over 42 weeks) pregnancies, and passage relates to gut maturation/hypoxia. All statements are correct, so ''All of the above'' applies (Myles Textbook for Midwives).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT diagnostic of twin to twin transfusion?', 'Both are of same sex', 'It results from venous communication of both foetuses', 'Both are of different growth', 'Both are of different amniotic fluid.', 'C', 'Twin-to-twin transfusion syndrome (TTTS) occurs in monochorionic (same-sex) twins from placental vascular anastomoses, causing discordant growth and amniotic fluid (oligo/polyhydramnios). Discordant growth is a FEATURE, not a non-diagnostic finding as the negatively worded question implies; however discordant growth alone is non-specific whereas monochorionicity and vascular communication are the defining criteria. The item asks which is NOT diagnostic; different growth is the least specific defining criterion of the listed features. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is true about twin to twin transfusion syndrome?', 'The smaller twin has the greatest risk of cardiac compromise', 'The larger twin is often stuck to the uterine wall', 'Serial amnia reduction improves perinatal survival', 'Fetoscopic laser ablation of the placental vessels increases survival for both', 'D', 'Fetoscopic laser photocoagulation of the communicating placental vessels is the definitive treatment for TTTS and improves survival for both twins. The larger (recipient) twin, not the smaller donor, has cardiac compromise, and the smaller donor is the ''stuck twin''; laser ablation is superior to serial amnioreduction (Myles Textbook for Midwives; RCOG/WHO adopted guidance).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A twin pregnancy is identified at 12 weeks gestation on antenatal ultrasound. One placenta and one amnion sac are identified. What would be the probable cause?', 'ICSI with single embryo transfer', 'Ovulation induction', 'Maternal age over 35 years', 'Family history of multiple pregnancies', 'B', 'One placenta with one amniotic sac indicates monochorionic monoamniotic (monozygotic) twinning, which arises from splitting of a single fertilized ovum. Of the listed causes, ovulation induction is a recognised association with (predominantly dizygotic) multiple pregnancy; ICSI single-embryo transfer, maternal age and family history relate mainly to dizygotic twinning, so ovulation induction is the closest predisposing factor listed. ⚠ Best answer not clearly among choices ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following BEST describes a third degree perinea! tear?', 'Injury to perineum involving perineal muscles', 'Injury to perineal! skin, includes the fourchette, the hymen, labia and vaginalmucosa', 'Injury to perineum involving anal sphincter complex and anal epithelium', 'Injury to perineum involving the anal sphincter complex', 'C', 'Per Myles Textbook for Midwives (RCOG classification adopted in Kenya): 1st degree = skin/mucosa only, 2nd = perineal muscles, 3rd = anal sphincter complex, 4th = sphincter complex PLUS anal/rectal epithelium. Option C best captures a third-degree tear extending through the sphincter complex to the anal epithelium (option D describing only the sphincter is less complete for the best answer). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which ONE of the following IS NOT a precaution for tocolytics?', 'Measure blood pressure hourly', 'Give one tocolytic agent at a time', 'Do not give tocolytics to women with heart rate greater than or equal to 120 beats per minute', 'Auscultate the mother''s lungs every 2 hours', 'D', 'Per MOH/Myles tocolysis precautions: monitor BP, give a single agent, and withhold beta-agonist tocolytics if maternal HR ≥120 bpm; lung auscultation for pulmonary oedema is done more frequently than 2-hourly (typically hourly/with each observation), so a 2-hourly interval is NOT an adequate stated precaution. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of primary amenorrhea include:-', 'Gonadal dysgenesis, premature ovarian failure, asherman’s syndrome.', 'Sheehan’s syndrome, gonadal dysgenesis, imperforate hymen.', 'Androgen insensitivity, gonadal dysgenesis, imperforate hymen.', 'Polycystic ovarian syndrome, sheehan’s syndrome, gonadal dysgenesis.', 'C', 'Per gynaecology texts (Myles/standard), primary amenorrhoea causes include androgen insensitivity, gonadal dysgenesis (Turner) and outflow obstruction like imperforate hymen. Asherman''s and Sheehan''s cause SECONDARY amenorrhoea, excluding options A, B and D.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is in the;', 'Occipital lobe', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'D', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (receptive/comprehension speech) lies in the posterior superior temporal lobe of the dominant hemisphere.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bell’s palsy involves the following cranial nerve', 'VIII', 'VII', 'V', 'II', 'B', 'Per Brunner & Suddarth, Bell''s palsy is an acute peripheral paralysis of cranial nerve VII (facial nerve), causing unilateral facial weakness.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is true regarding Hashimoto thyroiditis', 'Is an autoimmune disease, causes primary hypothyroidism', 'Is an autoimmune disease, causes primary hyperthyroidism', 'Results in goiter, causes exophthalmos', 'More common in women, there is an increase in TH levels.', 'A', 'Per Brunner & Suddarth, Hashimoto thyroiditis is an autoimmune destruction of the thyroid causing primary HYPOthyroidism. Exophthalmos and hyperthyroidism belong to Graves'' disease, excluding B and C.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When estimating the size of burns, the palm of the patient’s hand represents body surface area of;', '3%', '1%', '4.5%', '9%', 'B', 'Per Brunner & Suddarth and burn assessment guidelines, the patient''s palm (palmar surface including fingers) represents approximately 1% of total body surface area, used to estimate scattered burns.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client complains of decreasing peripheral vision and halos around lights. These manifestations are characteristics of;', 'Retinal detachment', 'Open-angle glaucoma', 'Cataract', 'Macular degeneration', 'B', 'Per Brunner & Suddarth, chronic open-angle glaucoma causes gradual loss of peripheral (tunnel) vision and haloes around lights from raised intraocular pressure. Cataract causes cloudy vision and detachment causes flashes/curtain, not this pattern.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During chest auscultation of a patient, which findings will indicate that the patient has cardiac condition and cannot be felt in a normal person', 'S1, S3 , Murmurs', 'S1, S2, Negative Murmurs,', 'S3, S4, Murmurs', 'S3, S1,S2', 'C', 'Per Brunner & Suddarth''s Med-Surg Nursing, S1 and S2 are normal heart sounds heard in healthy people; extra sounds S3 (in adults) and S4, together with murmurs, indicate cardiac pathology and are not normally audible in a healthy adult. Options containing S1/S2 are normal findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An elderly client has severe xerosis. What topic should be included in your teaching plan?', 'Maintain a warm environment', 'Take a hot bath everyday', 'C . Apply skin lotions after a bath', 'Use fabric softeners when laundering clothing', 'C', 'Per Kozier & Erb''s Fundamentals of Nursing, xerosis (dry skin) is managed by applying emollient lotion after bathing to seal moisture; hot baths and fabric softeners worsen dryness and irritation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While providing care to an old woman with a cast on her lower arm (from below the elbow the elbow to above the fingers) you perform a neurovascular assessment. What is the possible complication?', 'Slightly edematous fingers', 'Warm, pink skin above the cast', 'Pale, cold fingers', 'Pain rating of 2 on a 1 to 10 scale', 'C', 'Per Brunner & Suddarth neurovascular (5 P''s) assessment, pale and cold fingers indicate impaired circulation/compartment compromise distal to the cast — a serious complication. Slight edema, warm pink skin and mild pain of 2/10 are expected, non-alarming findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient becomes restless and tells you she has a headache and feels nauseous during hemodialysis. Which complication do you suspect?', 'Infection', 'Disequilibrium syndrome', 'Air embolism', 'Acute hemolysis', 'B', 'Per Brunner & Suddarth renal nursing, dialysis disequilibrium syndrome presents with restlessness, headache, nausea/vomiting and confusion from rapid osmotic shifts during hemodialysis. Air embolism causes dyspnea/chest pain, and acute hemolysis causes back pain and hypotension.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A classification of ringworm that infect the finger nails is:-', 'Tinea coporis', 'Tinea unguium', 'Tinea cruris', 'Tinea pedis', 'B', 'Per standard microbiology/dermatology texts, tinea unguium (onychomycosis) is the dermatophyte infection of the nails. Tinea corporis affects the body, tinea cruris the groin, and tinea pedis the feet.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with potassium levels in excess of 5.0 mEq/L is considered to be in a state of :-', 'Hypernatremia', 'Hypercalcemia', 'Hypervolemia', 'D . Hyperkalemia', 'D', 'Per Brunner & Suddarth and normal electrolyte values, a serum potassium above the normal 3.5–5.0 mEq/L range defines hyperkalemia. The other options refer to sodium, calcium and fluid volume, not potassium.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antihistamines are indicated in the management of vertigo because they:', 'Sedate the client', 'Activate the vestibular system', 'Suppress the vestibular system', 'Suppress the cochlear system', 'C', 'Per Kenya EML/BNF and Brunner & Suddarth, antihistamines (e.g. cinnarizine, promethazine, meclizine) relieve vertigo by suppressing vestibular over-activity and the vomiting centre. Sedation is a side effect, not the therapeutic mechanism, and they do not activate the vestibular system.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical features of hydatidiform mole include;', 'Positive pregnancy test of urine diluted to 1:100 after4 weeks of amenorrhea, ultrasound shows features of fetus.', 'Amenorrhea followed by vomiting, breast changes.', 'Uterus larger than dates ,chronic gonadotropin hormone in urine increase', 'Amenorrhea followed by intermittent bleeding, fetus demonstrated in x-ray.', 'C', 'Per Myles Textbook for Midwives, hydatidiform mole classically presents with a uterus larger than expected for gestational age and markedly raised hCG, plus a ''snowstorm'' ultrasound with NO fetus. Options showing a demonstrable fetus are therefore incorrect.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aorta divides at the level of the 4th lumbar vertebra into;', 'external &internal iliac arteries', 'superior & inferior mesenteric arteries', 'common iliac arteries', 'lumbar arteries', 'C', 'Per standard anatomy (Gray''s/Kozier), the abdominal aorta bifurcates at the level of the 4th lumbar vertebra into the right and left common iliac arteries, which subsequently divide into external and internal iliac arteries.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pleural effusion is a complication of;', 'Heart failure, nephritic syndrome, pulmonary tuberculosis', 'Pneumonia,upper respiratory infections, post thoracotomy', 'Penetrating chest trauma,bronchitis,haematogenous infection of the pleural space', 'Pulmonary embolism, lung cancer, post thoracentesis', 'A', 'Per Brunner & Suddarth, pleural effusion complicates heart failure and nephrotic/nephritic syndrome (transudative from raised hydrostatic or low oncotic pressure) and pulmonary tuberculosis (exudative) — all well-recognised causes. This option best captures classic effusion-causing conditions. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Early complication of fractures include;', 'Shock, vascular necrosis.', 'Reaction to internal fixation device, deep venous thrombosis', 'Compartment syndrome, fat embolism.', 'Complex regional pain syndrome, infection.', 'C', 'Per Brunner & Suddarth orthopaedic nursing, early complications of fractures include shock, fat embolism, compartment syndrome and DVT. Option C (compartment syndrome and fat embolism) lists two classic EARLY complications, whereas avascular necrosis, CRPS and hardware reaction are late/delayed complications. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Angiotensin-converting enzyme (ACE)inhibitors;', 'Inhibit conversion of angitensinogen to angiotensin I.', 'Block receptors from binding angiotensin II.', 'Inhibit conversion of angiotensin I to angiotensin II.', 'Block angiotensin I receptor sites. C C', 'C', 'Per Brunner & Suddarth''s Med-Surg pharmacology, ACE inhibitors block the angiotensin-converting enzyme, preventing conversion of angiotensin I to the potent vasoconstrictor angiotensin II. Blocking angiotensin II receptors (B) describes ARBs, not ACE inhibitors.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After a barium enema a nurse should,', 'Keep the patient NPO for 8 hours to rest the bowel', 'Advise the patient that his/her stool will be radioactive', 'Encourage the patient to increase his fluid intake', 'Advise the patient to avoid abdominal exercises for at least 1 week C C', 'C', 'Per Kozier & Erb''s Fundamentals, after a barium enema fluids and often a mild laxative are given to promote elimination of retained barium and prevent constipation/impaction. Barium is inert and not radioactive (B).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Passive range of motion exercises;', 'Are performed to prevent nosocomial infections.', 'Helps to prevent joints rigidity and contractures.', 'Is a collaborative intervention that requires a surgeon and a nurse.', 'Are repeated 5-6 times a day to enhance quick recovery. D B', 'B', 'Per Kozier & Erb''s Fundamentals, passive ROM exercises maintain joint mobility and prevent stiffness and contractures in patients unable to move independently. They do not prevent infections (A).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Korotkoff sounds heard while measuring blood pressure present in the order of,', 'Tapping, Swishing, Knocking, muffling and silence', 'Swishing, Tapping, Silence, muffling and knocking', 'Knocking, Tapping, Swishing, muffling, silence', 'Silence, Tapping, Knocking, Swishing and Muffling B A', 'A', 'Per Kozier & Erb''s, the five Korotkoff phases occur in order: sharp tapping (Phase I, systolic), swishing/murmur (Phase II), knocking (Phase III), muffling (Phase IV), then silence/disappearance (Phase V, diastolic).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Reed Sternberg cell is a pathologic hallmark essential in diagnosis of:-', 'Hodgkin’s disease', 'Acute myeloid leukemia', 'Chronic lymphocytic leukemia', 'Non-hodgkin disease', 'A', 'Per Brunner & Suddarth, the Reed-Sternberg cell is the pathognomonic hallmark used to diagnose Hodgkin''s lymphoma. It is absent in non-Hodgkin lymphoma and the leukemias.', 'BScN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Atherosclerosis impedes coronary blood flow by the following mechanisms', 'Plaques obstructs the vein', 'Plaques obstruct the artery', 'Blood clots from outside the vessel wall', 'Hardened vessels dilate to allow the blood to flow through B B', 'B', 'Per Brunner & Suddarth, atherosclerosis is the accumulation of lipid plaques within the coronary arteries, narrowing the lumen and impeding arterial blood flow to the myocardium.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate nursing action when a client begins to cough and has difficulty breathing during nasogastric tube insertion is;', 'Inserting the tube quickly', 'Notifying the physician immediately', 'Removing the tube and reinserting when the respiratory distress subsides', 'Pulling the tube back a little and wait until the respiratory distress subsides D D', 'D', 'Per Kozier & Erb''s, coughing and dyspnea during NG insertion suggest the tube has entered the airway; the nurse should withdraw the tube slightly and pause until distress resolves before advancing again. Continuing to insert (A) risks tracheal placement.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An 11-month-old infant with dehydration and metabolic acidosis is likely to present with;', 'A decreased platelet count', 'Shallow respirations', 'Tachypnea', 'A reduced white blood cell count B C', 'C', 'Per Kenya Basic Paediatric Protocols, metabolic acidosis triggers compensatory respiratory response producing deep, rapid breathing (tachypnea/Kussmaul respirations) to blow off CO2, not shallow respirations (B).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The expected outcomes for a patient who has “potential for impaired gas exchange related to fluid overload” is;', 'No shortness of breath, scaphoid abdomen.', 'Chest X-ray normal, improved gas exchange.', 'Respiratory rate less than 20breaths/min, skin colour normal.', 'Heart rate less than 100 beats/min, increased urine output B D', 'C', 'Per Kozier & Erb''s, expected outcomes for impaired gas exchange are measurable normal respiratory function: respiratory rate <20/min and normal (pink) skin colour indicating adequate oxygenation. This directly reflects resolved gas-exchange impairment better than urine output (D).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During Lumbar puncture, a needle is inserted in the space between;-', 'Fifth and sixth thoracic vertebrae.', 'Fourth and fifth thoracic vertebrae', 'Third and fourth lumbar vertebrae.', 'First and second lumbar vertebrae C C', 'C', 'Per Brunner & Suddarth, lumbar puncture is performed below the spinal cord''s end (L1-L2), typically in the L3-L4 (or L4-L5) interspace to avoid cord injury. Thoracic sites (A, B) are unsafe.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The condition in which the eyeballs are not properly aligned with each other is referred to as;', 'Astigmatism', 'Strabismus', 'Presbyopia', 'Amblyopia', 'B', 'Per standard ophthalmic nursing (Brunner & Suddarth), strabismus is misalignment of the eyes so that they do not point in the same direction. Astigmatism is refractive error, presbyopia is age-related near-vision loss, and amblyopia is ''lazy eye''.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a client with possible Cushing’s syndrome you would expect to find;', 'Hypotension', 'Thick coarse skin', 'Deposits of adipose tissue in the trunk', 'Weight loss', 'C', 'Per Brunner & Suddarth, Cushing''s syndrome (cortisol excess) causes central (truncal) obesity, moon face, and buffalo hump. It produces hypertension, thin fragile skin, and weight gain—not hypotension or weight loss.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When administering an enema;', 'The client should lie in the right lateral position.', 'The enema tube should be inserted 8 inches into the clients’ rectum.', 'The client should be advised to retain the enema for 30 minutes.', 'The nurse should position the client in left lateral position', 'D', 'Per Kozier & Erb''s, an enema is administered with the client in the left lateral (Sims'') position to follow the natural curve of the sigmoid colon. Insertion depth for adults is about 3-4 inches, not 8 (B).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The 6-month-old client with a ventral septal defect is receiving Digitalis for regulation of his heart rate. Which finding should be reported to the doctor?', 'Blood pressure of 126/80', 'Blood glucose of 110 mg/dL', 'Heart rate of 60 bpm', 'Respiratory rate of 30 per minute', 'C', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, digoxin is withheld and the physician notified when the infant''s apical heart rate is below 90-100 bpm; a rate of 60 bpm signals bradycardia and possible digitalis toxicity in a 6-month-old.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is instructed regarding foods that are low in fat and cholesterol. Which diet selection is lowest in saturated fats?', 'Macaroni and cheese', 'Shrimp with rice', 'Turkey breast', 'Spaghetti', 'C', 'Per Brunner & Suddarth''s cardiac/lipid-lowering diet teaching, skinless white poultry (turkey breast) is lowest in saturated fat. Macaroni and cheese is high in dairy saturated fat, shrimp is high in cholesterol.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted with left-sided congestive heart failure. In assessing the client for edema, the nurse should check the:', 'Feet', 'Neck', 'Hands', 'Sacrum', 'D', 'Per Brunner & Suddarth''s, dependent edema collects in the sacrum in a bedbound/supine client, making it the best site to assess in hospitalized CHF patients; feet edema is checked in ambulatory clients.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is checking the client’s central venous pressure. The nurse should place the zero of the manometer at the:', 'Phlebostatic axis', 'PMI', 'Erb’s point', 'Tail of Spence', 'A', 'Per Brunner & Suddarth''s critical care nursing, the zero reference of the manometer/transducer for CVP is levelled at the phlebostatic axis (4th intercostal space, mid-anteroposterior chest) to align with the right atrium.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best method of evaluating the amount of peripheral edema is:', 'Weighing the client daily', 'Measuring the extremity', 'Measuring the intake and output', 'Checking for pitting', 'B', 'Per Kozier & Erb''s, measuring the circumference of the affected extremity with a tape at a marked point gives the most objective, reproducible measure of localized peripheral edema; daily weight best reflects generalized fluid, and pitting is only a graded estimate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with vaginal cancer is being treated with a radioactive vaginal implant. The client’s husband asks the nurse if he can spend the night with his wife. The nurse should explain that:', 'Overnight stays by family members is against hospital policy.', 'There is no need for him to stay because staffing is adequate.', 'His wife will rest much better knowing that he is at home.', 'Visitation is limited to 30 minutes when the implant is in place.', 'D', 'Per Brunner & Suddarth''s radiation-safety (time-distance-shielding) principles, visitors of a client with a sealed radioactive implant are restricted in time (about 30 minutes) and distance; overnight stays are unsafe due to radiation exposure.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client hospitalized with a facial stroke. Which diet selection would be suited to the client?', 'Roast beef sandwich, potato chips, pickle spear, iced tea', 'Split pea soup, mashed potatoes, pudding, milk', 'Tomato soup, cheese toast, Jello, coffee', 'Hamburger, baked beans, fruit cup, iced tea', 'B', 'Per Brunner & Suddarth''s stroke/dysphagia management, soft, cohesive, easily swallowed foods (soup, mashed potatoes, pudding) are safest; dry, crumbly or hard items (sandwich, chips, toast) increase aspiration risk with facial weakness.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with leukemia is receiving Trimetrexate. After reviewing the client’s chart, the physician orders Wellcovorin (leucovorin calcium). The rationale for administering leucovorin calcium to a client receiving Trimetrexate is to:', 'Treat iron-deficiency anemia caused by chemotherapeutic agents', 'Create a synergistic effect that shortens treatment time', 'Increase the number of circulating neutrophils', 'Reverse drug toxicity and prevent tissue damag e', 'D', 'Per Brunner & Suddarth''s/oncology pharmacology, leucovorin (folinic acid) ''rescue'' bypasses the folate-antagonist block of antimetabolites like trimetrexate, reversing toxicity to normal cells and preventing tissue damage.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 4-month-old is brought to the well-baby clinic for immunization. In addition to the DPT and polio vaccines, the baby should receive:', 'HibTITER', 'Mumps vaccine', 'Hepatitis B vaccine', 'MMR', 'A', 'Per the Kenya KEPI immunization schedule, Haemophilus influenzae type b (given here as HibTITER, now within pentavalent) is due at 6, 10 and 14 weeks; MMR/mumps are not given until 9 months or later. Hepatitis B is included in pentavalent, but Hib is the specific additional antigen expected with DPT/polio at this visit.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is seen in the clinic for treatment of migraine headaches. The drug Imitrex (sumatriptan succinate) is prescribed for the client. Which of the following in the client’s history should be reported to the doctor?', 'Diabetes', 'Prinzmetal’s angina', 'Cancer', 'Cluster headaches', 'B', 'Per Kenya EML/BNF, sumatriptan is a 5-HT1 agonist that causes vasoconstriction and is contraindicated in ischaemic/vasospastic heart disease such as Prinzmetal''s (variant) angina, so this history must be reported.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with suspected meningitis is admitted to the unit. The doctor is performing an assessment to determine meningeal irritation and spinal nerve root inflammation. A positive Kernig’s sign is charted if the nurse notes:', 'Pain on flexion of the hip and knee', 'Nuchal rigidity on flexion of the neck', 'Pain when the head is turned to the left side', 'Dizziness when changing positions', 'A', 'Per Brunner & Suddarth''s neurologic assessment, a positive Kernig''s sign is pain/resistance on extending the knee when the hip and knee are flexed; nuchal rigidity on neck flexion describes Brudzinski''s sign.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with Alzheimer’s disease is being assisted with activities of daily living when the nurse notes that the client uses her toothbrush to brush her hair. The nurse is aware that the client is exhibiting:', 'Agnosia', 'Apraxia', 'Anomia', 'Aphasia', 'B', 'Per Brunner & Suddarth''s, apraxia is the inability to carry out purposeful, learned motor tasks correctly (e.g., using a toothbrush on the hair); agnosia is failure to recognize objects, aphasia is a language deficit.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted to the labor and delivery unit in active labor. During examination, the nurse notes a papular lesion on the perineum. Which initial action is most appropriate?', 'Document the finding', 'Report the finding to the doctor', 'Prepare the client for a C-section', 'Continue primary care as prescribed', 'B', 'Per Kenya maternal/newborn and STI guidelines, a genital lesion in a laboring woman may be active herpes/an infectious lesion posing vertical-transmission risk; the nurse must report it to the doctor so mode of delivery can be decided, rather than merely documenting.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 15-year-old primigravida is admitted with a tentative diagnosis of HELLP syndrome. Which laboratory finding is associated with HELLP syndrome?', 'Elevated blood glucose', 'Elevated platelet count', 'Elevated creatinine clearance', 'Elevated hepatic enzymes', 'D', 'Per Myles Textbook for Midwives, HELLP = Hemolysis, Elevated Liver enzymes, Low Platelets; thus elevated hepatic enzymes is the associated finding, and platelet count is decreased (not elevated).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assessing the deep tendon reflexes of a client with preeclampsia. Which method is used to elicit the biceps reflex?', 'The nurse places her thumb on the muscle inset in the antecubital space and taps the thumb briskly with the reflex hammer.', 'The nurse loosely suspends the client’s arm in an open hand while tapping the back of the client’s elbow.', 'The nurse instructs the client to dangle her legs as the nurse strikes the area below the patella with the blunt side of the reflex hammer.', 'The nurse instructs the client to place her arms loosely at her side as the nurse strikes the muscle insert just above the wrist.', 'A', 'Per Kozier & Erb''s/physical assessment technique, the biceps reflex is elicited by placing the thumb over the biceps tendon in the antecubital fossa and striking the thumb with the reflex hammer.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida with diabetes is admitted to the labor and delivery unit at 34 weeks gestation. Which doctor’s order should the nurse question?', 'Magnesium sulfate 4gm (25%) IV', 'Brethine 10 mcg IV', 'Stadol 1 mg IV push every 4 hours as needed prn for pain', 'Ancef 2gm IVPB every 6 hours', 'B', 'Per Kenya maternal care/pharmacology, terbutaline (Brethine) is a beta-agonist tocolytic that causes hyperglycaemia and should be questioned in a diabetic; the usual dose is ~0.25 mg subcutaneously, so an IV ''10 mcg'' order is also questionable. Magnesium sulfate, Stadol and Ancef are appropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diabetic multigravida is scheduled for an amniocentesis at 32 weeks gestation to determine the L/S ratio and phosphatidylglycerol level. The L/S ratio is 1:1 and the presence of phosphatidylglycerol is noted. The nurse’s assessment of this data is:', 'The infant is at low risk for congenital anomalies.', 'The infant is at high risk for intrauterine growth retardation.', 'The infant is at high risk for respiratory distress syndrome.', 'The infant is at high risk for birth trauma.', 'C', 'Per Myles Textbook for Midwives, fetal lung maturity requires an L/S ratio of at least 2:1; a 1:1 ratio indicates immature lungs and high risk for respiratory distress syndrome. In diabetic pregnancies phosphatidylglycerol is the more reliable maturity marker, but the low L/S here signals RDS risk.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has cancer of the pancreas. The nurse should be most concerned about which nursing diagnosis?', 'Alteration in nutrition', 'Alteration in bowel elimination', 'Alteration in skin integrity', 'Ineffective individual coping', 'A', 'Pancreatic cancer severely impairs exocrine enzyme secretion and, with anorexia, cachexia and obstruction, causes profound malnutrition and weight loss; nutrition is the priority concern (Brunner & Suddarth''s Medical-Surgical Nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting an 18-year-old with osteogenesis imperfecta. Which information obtained on the visit would cause the most concern? The client:', 'Likes to play football', 'Drinks several carbonated drinks per day', 'Has two sisters with sickle cell tract', 'Is taking acetaminophen to control pain', 'A', 'Osteogenesis imperfecta causes brittle bones prone to fracture; contact sports such as football pose the greatest injury risk and cause most concern (Brunner & Suddarth''s, musculoskeletal disorders).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse working the organ transplant unit is caring for a client with a white blood cell count of 450. During evening visitation, a visitor brings a basket of fruit. What action should the nurse take?', 'Allow the client to keep the fruit', 'Place the fruit next to the bed for easy access by the client', 'Offer to wash the fruit for the client', 'Tell the family members to take the fruit home', 'D', 'A WBC of 450 indicates severe neutropenia; fresh fruit harbours bacteria/fungi and is contraindicated in neutropenic precautions, so it should be removed (Brunner & Suddarth''s, neutropenic care / IPC principles).', 'BScN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted 2 days earlier that a lung resection accidentally pulls out the chest tube. Which action by the nurse indicates understanding of the management of chest tubes?', 'Order a chest x-ray', 'Reinsert the tube', 'Cover the insertion site with a Vaseline gauze', 'Call the doctor', 'C', 'An accidentally dislodged chest tube requires immediate application of an occlusive (Vaseline) dressing to prevent air entry and tension pneumothorax, then notify the physician (Brunner & Suddarth''s, chest drainage management).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client being treated with sodium warfarin has a Protime of 120 seconds. Which intervention would be most important to include in the nursing care plan?', 'Assess for signs of abnormal bleeding', 'Anticipate an increase in the Coumadin dosage', 'Instruct the client regarding the drug therapy', 'Increase the frequency of neurological assessments', 'A', 'A Protime of 120 seconds is grossly prolonged, indicating warfarin over-anticoagulation and high bleeding risk; the priority is to assess for abnormal bleeding (Brunner & Suddarth''s / Kenya EML anticoagulant monitoring).', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which selection would provide the most calcium for the client who is 4 months pregnant?', 'A granola bar', 'A bran muffin', 'A cup of yogurt', 'A glass of fruit juice', 'C', 'Yogurt is a dairy product and the richest calcium source among the options, important for the increased calcium demand in pregnancy (Kozier & Erb''s Fundamentals; Kenya maternal nutrition guidelines).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 6-year-old client is admitted to the unit with a hemoglobin of 6g/dL. The physician has written an order to transfuse 2 units of whole blood. When discussing the treatment, the child’s mother tells the nurse that she does not believe in having blood transfusions and that she will not allow her child to have the treatment. What nursing action is most appropriate?', 'Ask the mother to leave while the blood transfusion is in progress', 'Encourage the mother to reconsider', 'Explain the consequences without treatment', 'Notify the physician of the mother’s refusal', 'D', 'When a parent refuses treatment for a minor, the nurse cannot coerce or force treatment; the appropriate action is to notify the physician so legal/ethical processes can follow (Professional ethics & law; Kozier & Erb''s on informed consent/refusal).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating nutritional outcomes for a with anorexia nervosa. Which data best indicates that the plan of care is effective?', 'The client selects a balanced diet from the menu.', 'The client’s hemoglobin and hematocrit improve.', 'The client’s tissue turgor improves.', 'The client gains weight.', 'D', 'In anorexia nervosa the primary nutritional goal is restoration of body weight; weight gain is the best objective indicator that the nutritional plan is effective (Brunner & Suddarth''s / mental health nursing).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 43-year-old African American male is admitted with sickle cell anemia. The nurse plans to assess circulation in the lower extremities every 2 hours. Which of the following outcome criteria would the nurse use?', 'Body temperature of 37.2 celsius or less', 'Toes moved in active range of motion', 'Sensation reported when soles of feet are touched', 'Capillary refill of < 3 seconds', 'D', 'In sickle cell anemia, monitoring peripheral circulation is best evaluated by capillary refill; a refill under 3 seconds is the outcome criterion indicating adequate lower-extremity perfusion (Brunner & Suddarth''s, haematologic disorders).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 30-year-old male from Haiti is brought to the emergency department in sickle cell crisis. What is the best position for this client?', 'Side-lying with knees flexed', 'Knee-chest', 'High Fowler''s with knees flexed', 'Semi-Fowler''s with legs extended on the bed', 'D', 'In sickle cell crisis, positions that flex joints and impede circulation are avoided; semi-Fowler''s with legs extended promotes comfort, oxygenation and unrestricted circulation (Brunner & Suddarth''s, sickle cell crisis management).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 25-year-old male is admitted in sickle cell crisis. Which of the following interventions would be of highest priority for this client?', 'Taking hourly blood pressures with mechanical cuff', 'Encouraging fluid intake of at least 200mL per hour', 'Position in high Fowler''s with knee gatch raised', 'Administering Tylenol as ordered', 'B', 'Hydration is the highest priority in sickle cell crisis because it reduces blood viscosity, promotes circulation and limits further sickling and vaso-occlusion (Brunner & Suddarth''s, sickle cell crisis).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following foods would the nurse encourage the client in sickle cell crisis to eat?', 'Peaches', 'Cottage cheese', 'Popsicle', 'Lima beans', 'C', 'Fluid intake is essential in sickle cell crisis; a popsicle provides additional fluids to support hydration and reduce sickling, making it the best choice to encourage (Brunner & Suddarth''s, sickle cell crisis hydration).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A newly admitted client has sickle cell crisis. The nurse is planning care based on assessment of the client. The client is complaining of severe pain in his feet and hands. The pulse oximetry is 92. Which of the following interventions would be implemented first? Assume that there are orders for each intervention.', 'Adjust the room temperature', 'Give a bolus of IV fluids', 'Start O2', 'Administer meperidine (Demerol) 75mg IV push', 'C', 'With a pulse oximetry of 92 and vaso-occlusive pain, correcting hypoxia by starting oxygen is implemented first to reduce further sickling, following the ABC priority (Brunner & Suddarth''s, sickle cell crisis oxygenation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is instructing a client with iron-deficiency anemia. Which of the following meal plans would the nurse expect the client to select?', 'Roast beef, gelatin salad, green beans, and peach pie', 'Chicken salad sandwich, coleslaw, French fries, ice cream', 'Egg salad on wheat bread, carrot sticks, lettuce salad, raisin pie', 'Pork chop, creamed potatoes, corn, and coconut cake', 'C', 'Iron-rich choices include eggs, whole wheat, leafy green vegetables and raisins (dried fruit); this meal provides the most dietary iron for iron-deficiency anemia (Kenya nutrition guidelines; Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clients with sickle cell anemia are taught to avoid activities that cause hypoxia and hypoxemia. Which of the following activities would the nurse recommend?', 'A family vacation in the Rocky Mountains', 'Chaperoning the local boys club on a snow-skiing trip', 'Traveling by airplane for business trips', 'A bus trip to the Museum of Natural History', 'D', 'Activities causing hypoxia (high altitude in the Rocky Mountains, cold snow-skiing, unpressurised/altitude air travel) must be avoided; a low-altitude bus trip is safe (Brunner & Suddarth''s, sickle cell patient education).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting an admission assessment of a client with vitamin B12 deficiency. Which of the following would the nurse include in the physical assessment?', 'Palpate the spleen', 'Take the blood pressure', 'Examine the feet for petechiae', 'Examine the tongue', 'D', 'Vitamin B12 deficiency characteristically causes glossitis (a smooth, beefy-red, sore tongue); examining the tongue is the relevant physical assessment finding (Brunner & Suddarth''s, megaloblastic/pernicious anemia).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An African American female comes to the outpatient clinic. The physician suspects vitamin B12 deficiency anemia. Because jaundice is often a clinical manifestation of this type of anemia, what body part would be the best indicator?', 'Conjunctiva of the eye', 'Soles of the feet', 'Roof of the mouth', 'Shins', 'C', 'In dark-skinned clients jaundice is best detected in the hard palate (roof of the mouth) and sclera where the yellow discoloration is most visible (Kozier & Erb''s, assessment of skin colour in dark-skinned clients).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting a physical assessment on a client with anemia. Which of the following clinical manifestations would be most indicative of the anemia?', 'BP 146/88', 'Respirations 28 shallow', 'Weight gain of 10 pounds in 6 months', 'Pink complexion', 'B', 'Anemia reduces oxygen-carrying capacity, causing compensatory tachypnea and dyspnea; increased shallow respirations (28) is the most indicative manifestation, while pink complexion would be inconsistent with anemia (Brunner & Suddarth''s, anemia assessment).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 33-year-old male is being evaluated for possible acute leukemia. Which of the following would the nurse inquire about as a part of the assessment?', 'The client collects stamps as a hobby.', 'The client recently lost his job as a postal worker.', 'The client had radiation for treatment of Hodgkin''s disease as a teenager.', 'The client''s brother had leukemia as a child.', 'C', 'Prior radiation therapy is a well-established risk factor for developing acute leukemia; this history is the relevant assessment inquiry (Brunner & Suddarth''s, leukemia risk factors).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An African American client is admitted with acute leukemia. The nurse is assessing for signs and symptoms of bleeding. Where is the best site for examining for the presence of petechiae?', 'The abdomen', 'The thorax', 'The earlobes', 'The soles of the feet', 'C', 'In dark-skinned clients petechiae are best assessed in areas of lighter pigmentation with thin skin such as the earlobes and oral mucosa/conjunctiva (Kozier & Erb''s, skin assessment in dark-skinned clients).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be the priority nursing diagnosis for the adult client with acute leukemia?', 'Oral mucous membrane, altered related to chemotherapy', 'Risk for injury related to thrombocytopenia', 'Fatigue related to the disease process', 'Interrupted family processes related to life-threatening illness of a family member', 'B', 'In acute leukemia, thrombocytopenia predisposes to life-threatening hemorrhage; risk for injury/bleeding is the priority (physiologic safety) nursing diagnosis (Brunner & Suddarth''s, leukemia nursing care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 21-year-old male with Hodgkin''s lymphoma is a senior at the local university. He is engaged to be married and is to begin a new job upon graduation. Which of the following diagnoses would be a priority for this client?', 'Sexual dysfunction related to radiation therapy', 'Anticipatory grieving related to terminal illness', 'Tissue integrity related to prolonged bed rest', 'Fatigue related to chemotherapy', 'A', 'Hodgkin''s lymphoma is highly curable so anticipatory grieving for terminal illness is inappropriate; for a young engaged man, radiation-induced sexual dysfunction/infertility is the priority concern (Brunner & Suddarth''s, Hodgkin''s lymphoma).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting a client with autoimmune thrombocytopenic purpura (ATP). The client''s platelet count currently is 80, It will be most important to teach the client and family about:', 'Bleeding precautions', 'Prevention of falls', 'Oxygen therapy', 'Conservation of energy', 'A', 'With a low platelet count in ATP (ITP), the priority teaching is bleeding precautions to prevent hemorrhage (Brunner & Suddarth''s, thrombocytopenia/ITP care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a pituitary tumor has had a transsphenoidal hypophysectomy. Which of the following interventions would be appropriate for this client?', 'Place the client in Trendelenburg position for postural drainage', 'Encourage coughing and deep breathing every 2 hours', 'Elevate the head of the bed 30°', 'Encourage the Valsalva maneuver for bowel movements', 'C', 'After transsphenoidal hypophysectomy, the head of the bed is elevated 30° to reduce pressure on the sella and CSF leak risk; coughing, Valsalva and Trendelenburg increase intracranial pressure and are contraindicated (Brunner & Suddarth''s, hypophysectomy care).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a history of diabetes insipidus is admitted with polyuria, polydipsia, and mental confusion. The priority intervention for this client is:', 'Measure the urinary output', 'Check the vital signs', 'Encourage increased fluid intake', 'Weigh the client', 'B', 'Diabetes insipidus with polyuria and confusion risks severe dehydration and hypovolemic shock; assessing vital signs is the priority to detect fluid volume/hemodynamic instability (Brunner & Suddarth''s, diabetes insipidus).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with hemophilia has a nosebleed. Which nursing action is most appropriate to control the bleeding?', 'Place the client in a sitting position with the head hyperextended', 'Pack the nares tightly with gauze to apply pressure to the source of bleeding', 'Pinch the soft lower part of the nose for a minimum of 5 minutes', 'Apply ice packs to the forehead and back of the neck', 'C', 'For epistaxis in hemophilia, applying steady pressure by pinching the soft lower nose (with the client upright, head forward) controls bleeding; hyperextension and tight packing are avoided (Basic nursing/first aid; Brunner & Suddarth''s, hemophilia).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has had a unilateral adrenalectomy to remove a tumor. To prevent complications, the most important measurement in the immediate postoperative period for the nurse to take is:', 'Blood pressure', 'Temperature', 'Output', 'Specific gravity', 'A', 'After adrenalectomy, adrenal hormone fluctuations cause hemodynamic instability (hypotension or hypertension); blood pressure is the most important immediate postoperative measurement (Brunner & Suddarth''s, adrenal surgery).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with Addison''s disease has been admitted with a history of nausea and vomiting for the past 3 days. The client is receiving IV glucocorticoids (Solu-Medrol). Which of the following interventions would the nurse implement?', 'Glucometer readings as ordered', 'Intake/output measurements', 'Sodium and potassium levels monitored', 'Daily weights', 'C', 'In Addison''s disease/adrenal insufficiency the key electrolyte disturbance is hyponatremia and hyperkalemia; monitoring sodium and potassium is the priority intervention (Brunner & Suddarth''s, Addisonian crisis).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client had a total thyroidectomy yesterday. The client is complaining of tingling around the mouth and in the fingers and toes. What would the nurses'' next action be?', 'Obtain a crash cart', 'Check the calcium level', 'Assess the dressing for drainage', 'Assess the blood pressure for hypertension', 'B', 'Tingling of the mouth, fingers and toes after thyroidectomy signals hypocalcemia from accidental parathyroid injury; the nurse should check the calcium level and watch for tetany (Brunner & Suddarth''s, post-thyroidectomy complications).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 32-year-old mother of three is brought to the clinic. Her pulse is 52, there is a weight gain of 30 pounds in 4 months, and the client is wearing two sweaters. The client is diagnosed with hypothyroidism. Which of the following nursing diagnoses is of highest priority?', 'Impaired physical mobility related to decreased endurance', 'Hypothermia r/t decreased metabolic rate', 'Disturbed thought processes r/t interstitial edema', 'Decreased cardiac output r/t bradycardia', 'D', 'Using the airway/circulation priority, the pulse of 52 (bradycardia) makes decreased cardiac output the highest-priority (physiologic) diagnosis in hypothyroidism (Brunner & Suddarth''s, hypothyroidism; Maslow/ABC prioritisation).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida, age 42, is 6 weeks pregnant. Based on the client''s age, her infant is at risk for:', 'Down syndrome', 'Respiratory distress syndrome', 'Turner''s syndrome', 'Pathological jaundice', 'A', 'Advanced maternal age (42) markedly increases the risk of chromosomal trisomies, most notably Down syndrome (trisomy 21) (Myles Textbook for Midwives; Kenya maternal care guidelines).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a missed abortion at 29 weeks gestation is admitted to the hospital. The client will most likely be treated with:', 'Magnesium sulfate', 'Calcium gluconate', 'Dinoprostone (Prostin E.)', 'Bromocriptine (Pardel)', 'C', 'A missed abortion at 29 weeks requires evacuation; dinoprostone (a prostaglandin E) is used to induce cervical ripening and uterine contractions to expel the retained products (Myles Textbook for Midwives; Kenya maternal guidelines on induction).', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with preeclampsia has been receiving an infusion containing magnesium sulfate for a blood pressure that is 160/80; deep tendon reflexes are 1 plus, and the urinary output for the past hour is 100mL. The nurse should:', 'Continue the infusion of magnesium sulfate while monitoring the client''s blood pressure', 'Stop the infusion of magnesium sulfate and contact the physician', 'Slow the infusion rate and turn the client on her left side', 'Administer calcium gluconate IV push and continue to monitor the blood pressure', 'A', 'Per Kenya National Maternal guidelines/Myles, MgSO4 is withheld only for magnesium toxicity signs: respiratory depression, absent reflexes, or urine output <30mL/hr (<100mL/4hr). Here reflexes are present (1+) and output is adequate (100mL/hr), so the infusion is safely continued with monitoring.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant client, age 32, asks the nurse why her doctor has recommended a serum alpha fetoprotein. The nurse should explain that the doctor has recommended the test:', 'Because it is a state law', 'To detect cardiovascular defects', 'Because of her age', 'To detect neurological defects', 'D', 'Per Myles/antenatal screening, maternal serum alpha-fetoprotein screens for neural tube (neurological) defects such as spina bifida and anencephaly; elevated AFP indicates open NTDs. Age relates to Down screening, not AFP alone.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with hypothyroidism asks the nurse if she will still need to take thyroid medication during the pregnancy. The nurse''s response is based on the knowledge that:', 'There is no need to take thyroid medication because the fetus''s thyroid produces a thyroid-stimulating hormone.', 'Regulation of thyroid medication is more difficult because the thyroid gland increases in size during pregnancy.', 'It is more difficult to maintain thyroid regulation during pregnancy due to a slowing of metabolism.', 'Fetal growth is arrested if thyroid medication is continued during pregnancy.', 'B', 'Per Brunner & Suddarth/maternal endocrine physiology, thyroid demand and gland size increase in pregnancy so thyroid replacement often needs upward adjustment; medication must be continued, not stopped. Metabolism rises (not slows) in pregnancy.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with sickle cell anemia is admitted to the labor and delivery unit during the first phase of labor. The nurse should anticipate the client''s need for:', 'Supplemental oxygen', 'Fluid restriction', 'Blood transfusion', 'Delivery by Caesarean section', 'A', 'Per Kenya haematology/maternal guidelines, in sickle cell disease during labor the priority is preventing hypoxia and sickling crisis, so supplemental oxygen and hydration are anticipated. Fluid restriction is contraindicated as it promotes sickling.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with diabetes has an order for ultrasonography. Preparation for an ultrasound includes:', 'Increasing fluid intake', 'Limiting ambulation', 'Administering an enema', 'Withholding food for 8 hours', 'A', 'Per obstetric ultrasound preparation (Myles), a full bladder from increased fluid intake elevates the uterus and provides an acoustic window for imaging in pregnancy. Withholding food and enemas are not required for obstetric/abdominal ultrasound.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant who weighs 8 pounds at birth would be expected to weigh how many pounds at 1 year?', '14 pounds', '16 pounds', '18 pounds', '24 pounds', 'D', 'Per Basic Paediatric Protocols/growth norms, an infant''s birth weight roughly triples by 1 year; 8 pounds x 3 = 24 pounds. Doubling occurs by ~5-6 months.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant client with a history of alcohol addiction is scheduled for a nonstress test. The nonstress test:', 'Determines the lung maturity of the fetus', 'Measures the activity of the fetus', 'Shows the effect of contractions on the fetal heart rate', 'Measures the neurological well-being of the fetus', 'B', 'Per Myles antenatal testing, a nonstress test evaluates fetal heart rate accelerations in response to fetal movement (activity), reflecting well-being. Contraction effects are assessed by the contraction stress test, and lung maturity by L/S ratio.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A full-term male has hypospadias. Which statement describes hypospadias?', 'The urethral opening is absent.', 'The urethra opens on the dorsal side of the penis.', 'The penis is shorter than usual.', 'The urethra opens on the ventral side of the penis.', 'D', 'Per Basic Paediatric Protocols/paediatric surgery, hypospadias is a congenital anomaly in which the urethral meatus opens on the ventral (underside) of the penis. A dorsal opening describes epispadias.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A gravida III, para II is admitted to the labor unit. Vaginal exam reveals that the client''s cervix is 8cm dilated, with complete effacement. The priority nursing diagnosis at this time is:', 'Alteration in coping related to pain', 'Potential for injury related to precipitate delivery', 'Alteration in elimination related to anesthesia', 'Potential for fluid volume deficit related to NPO status', 'B', 'Per Myles, a multipara (gravida III para II) at 8cm with complete effacement is in advanced active/transition labor and may deliver rapidly; the priority is preventing injury from precipitate delivery. Pain and elimination are lower priority than safety.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted complaining of chest pain. Which of the following drug orders should the nurse question?', 'Nitroglycerin', 'Ampicillin', 'Propranolol', 'Verapamil', 'B', 'Per Kenya EML/cardiac pharmacology, nitroglycerin, propranolol and verapamil are all appropriate for anginal chest pain; ampicillin is an antibiotic with no role in chest pain and should be questioned.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with acute pancreatitis is experiencing severe abdominal pain. Which of the following orders should be questioned by the nurse?', 'Meperidine 100mg IM q 4 hours PRN pain', 'Mylanta 30 ccs q 4 hours via NG', 'Cimetidine 300mg PO q.i.d.', 'Morphine 8mg IM q 4 hours PRN pain', 'D', 'Per traditional med-surg teaching (Brunner & Suddarth), morphine was avoided in acute pancreatitis due to concern for sphincter of Oddi spasm; meperidine was historically preferred, so the morphine order is the one questioned in NCK-style items.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To maintain Bryant''s traction, the nurse must make certain that the child''s:', 'Hips are resting on the bed, with the legs suspended at a right angle to the bed', 'Hips are slightly elevated above the bed and the legs are suspended at a right angle to the bed', 'Hips are elevated above the level of the body on a pillow and the legs are suspended parallel to the bed', 'Hips and legs are flat on the bed, with the traction positioned at the foot of the bed', 'B', 'Per paediatric orthopaedic nursing (Brunner/paeds texts), Bryant''s traction requires the hips slightly elevated off the bed so the child''s weight provides countertraction, with legs suspended vertically at a 90-degree angle to the bed. Buttocks must clear the mattress.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing postpartum teaching for a mother planning to breastfeed her infant. Which of the client''s statements indicates the need for additional teaching?', '"I''m wearing a support bra."', '"I''m expressing milk from my breast."', '"I''m drinking four glasses of fluid during a 24-hour period."', '"While I''m in the shower, I''ll allow the water to run over my breasts."', 'C', 'Per Myles/postpartum lactation teaching, a breastfeeding mother needs increased fluids (about 8-10 glasses/day); only four glasses in 24 hours is inadequate and indicates a need for more teaching. Support bra, expressing milk, and letting water run over breasts are correct.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Damage to the VII cranial nerve results in:', 'Facial pain', 'Absence of ability to smell', 'Absence of eye movement', 'Tinnitus', 'A', 'Per neuroanatomy (Brunner & Suddarth), the VII (facial) nerve controls facial muscle movement and taste; its damage causes facial weakness/paralysis and altered sensation. Smell is CN I, eye movement CN III/IV/VI, so facial involvement is the best fit among the options. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is receiving Pyridium (phenazopyridine hydrochloride) for a urinary tract infection. The client should be taught that the medication may:', 'Cause diarrhea', 'Change the color of her urine', 'Cause mental confusion', 'Cause changes in taste', 'B', 'Per Kenya EML/pharmacology, phenazopyridine (Pyridium) is a urinary analgesic that characteristically turns urine reddish-orange; clients must be forewarned to avoid alarm and staining. It does not typically cause diarrhea or confusion.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with AIDS is taking Zovirax (acyclovir). Which nursing intervention is most critical during the administration of acyclovir?', 'Limit the client''s activity', 'Encourage a high-carbohydrate diet', 'Utilize an incentive spirometer to improve respiratory function', 'Encourage fluids', 'D', 'Per pharmacology (Brunner & Suddarth), acyclovir (Zovirax) is nephrotoxic and can crystallize in renal tubules, so adequate hydration is the most critical intervention to protect the kidneys during administration. Activity limitation and spirometry are not priorities.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted for an MRI. The nurse should question the client regarding:', 'Pregnancy', 'A titanium hip replacement', 'Allergies to antibiotics', 'Inability to move his feet', 'B', 'Per diagnostic imaging safety (Brunner & Suddarth), MRI uses a strong magnetic field, so the nurse must screen for metal implants; ferromagnetic hardware is a contraindication. Screening for implants/metal is the key MRI safety concern among these options.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for the client receiving Amphotericin B. Which of the following indicates that the client has experienced toxicity to this drug?', 'Changes in vision', 'Nausea', 'Urinary frequency', 'Changes in skin color', 'B', 'Per pharmacology (Brunner & Suddarth), amphotericin B commonly causes infusion reactions such as fever, chills, nausea and, importantly, nephrotoxicity; among the listed options nausea is the recognized adverse/toxic effect. Visual changes are not characteristic. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse should visit which of the following clients first?', 'The client with diabetes with a blood glucose of 95mg/dL', 'The client with hypertension being maintained on Lisinopril', 'The client with chest pain and a history of angina', 'The client with Raynaud''s disease', 'C', 'Per triage/prioritization (ABC, Brunner & Suddarth), the client with active chest pain and angina history is at risk of an evolving myocardial infarction and must be seen first. The others are stable with controlled findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with cystic fibrosis is taking pancreatic enzymes. The nurse should administer this medication:', 'Once per day in the morning', 'Three times per day with meals', 'Once per day at bedtime', 'Four times per day', 'B', 'Pancreatic enzyme replacements (pancrelipase) must be given with each meal and snack so the enzymes are present to digest fat, protein, and carbohydrate as food enters the gut (Brunner & Suddarth''s Medical-Surgical Nursing). Giving them once daily would leave most meals without enzyme support.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cataracts result in opacity of the crystalline lens. Which of the following best explains the functions of the lens?', 'The lens controls stimulation of the retina.', 'The lens orchestrates eye movement.', 'The lens focuses light rays on the retina.', 'The lens magnifies small objects.', 'C', 'The crystalline lens refracts (focuses) incoming light rays onto the retina; cataract opacity blurs this focus (Anatomy & Physiology; Brunner & Suddarth''s). Pupil/iris controls light intake and extraocular muscles control movement, not the lens.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client who has glaucoma is to have miotic eye drops instilled in both eyes. The nurse knows that the purpose of the medication is to:', 'Anesthetize the cornea', 'Dilate the pupils', 'Constrict the pupils', 'Paralyze the muscles of accommodation', 'C', 'Miotics (e.g., pilocarpine) constrict the pupil, which widens the trabecular outflow and lowers intraocular pressure in glaucoma (Brunner & Suddarth''s; Kenya EML ophthalmic drugs). ''Miosis'' means pupillary constriction, the opposite of mydriasis/dilation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a severe corneal ulcer has an order for Gentamicin gtt. q 4 hours and Neomycin 1 gtt q 4 hours. Which of the following schedules should be used when administering the drops?', 'Allow 5 minutes between the two medications.', 'The medications may be used together.', 'The medications should be separated by a cycloplegic drug.', 'The medications should not be used in the same client.', 'A', 'When two different eye drops are ordered, a waiting interval (about 5 minutes) is required so the first drop is not washed out before absorption (Kozier & Erb''s Fundamentals of Nursing). They should not be instilled simultaneously.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a pacemaker should be taught to:', 'Report ankle edema', 'Check his blood pressure daily', 'Refrain from using a microwave oven', 'Monitor his pulse rate', 'D', 'Pacemaker clients are taught to check their pulse daily and report a rate below the set threshold, which signals pacemaker malfunction (Brunner & Suddarth''s). Modern microwaves are safe, so refraining from them is unnecessary.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with enuresis is being taught regarding bladder retraining. The nurse should advise the client to refrain from drinking after:', '1900', '1200', '1000', '0700', 'A', 'In bladder retraining for enuresis, fluids are restricted in the evening (after about 1900 hrs / 7 pm) to reduce night-time bladder filling, while daytime intake stays adequate (Kozier & Erb''s Fundamentals of Nursing). Stopping fluids at midday would cause dehydration.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following diet instructions should be given to the client with recurring urinary tract infections?', 'Increase intake of meats.', 'Avoid citrus fruits.', 'Perform pericare with hydrogen peroxide.', 'Drink a glass of cranberry juice every day.', 'D', 'Cranberry juice acidifies urine and inhibits bacterial adherence to the bladder wall, helping prevent recurrent UTIs (Brunner & Suddarth''s). Citrus need not be avoided, and hydrogen peroxide pericare is inappropriate.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed NPH insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs?', '"I will make sure I eat breakfast within 2 hours of taking my insulin."', '"I will need to carry candy or some form of sugar with me all the time."', '"I will eat a snack around three o''clock each afternoon."', '"I can save my dessert from supper for a bedtime snack."', 'C', 'NPH (intermediate-acting) insulin peaks roughly 6-12 hours after a morning dose, so a mid-afternoon snack covers the peak and prevents hypoglycemia (Brunner & Suddarth''s; Kenya EML). Eating breakfast within 2 hours describes rapid/short-acting insulin.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with pneumocystis carinii pneumonia is receiving trimetrexate. The rationale for administering leucovorin calcium to a client receiving Methotrexate is to:', 'Treat anemia.', 'Create a synergistic effect.', 'Increase the number of white blood cells.', 'Reverse drug toxicity.', 'D', 'Leucovorin (folinic acid) rescue counteracts the folate-antagonist toxicity of methotrexate/trimetrexate, protecting normal cells (Brunner & Suddarth''s; Kenya EML). It is a rescue agent, not a synergistic or hematinic agent.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client tells the nurse that she is allergic to eggs, dogs, rabbits, and chicken feathers. Which order should the nurse question?', 'TB skin test', 'Rubella vaccine', 'ELISA test', 'Chest x-ray', 'B', 'MMR/rubella vaccine is cultured in chick embryo cells, so a documented severe egg allergy warrants questioning the order (Brunner & Suddarth''s; KEPI cautions). TB skin test, ELISA, and chest x-ray carry no egg-protein risk.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed ranitidine (Zantac) for a client with erosive gastritis. The nurse should administer the medication:', '30 minutes before meals', 'With each meal', 'In a single dose at bedtime', '60 minutes after meals', 'A', 'H2 antagonists such as ranitidine are best given before meals so the drug blocks the acid secretion stimulated by eating (Brunner & Suddarth''s; Kenya EML). Single bedtime dosing does not cover mealtime acid surges as well.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A temporary colostomy is performed on the client with colon cancer. The nurse is aware that the proximal end of a double barrel colostomy:', 'Is the opening on the client''s left side', 'Is the opening on the distal end on the client''s left side', 'Is the opening on the client''s right side', 'Is the opening on the distal right side', 'C', 'In a double-barrel colostomy the proximal (functioning) stoma is on the client''s right, following the direction of bowel flow from the ascending/transverse colon, while the distal non-functioning stoma is on the left (Brunner & Suddarth''s).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an MRI for a client with an orthopedic ailment. An MRI should not be done if the client has:', 'The need for oxygen therapy', 'A history of claustrophobia', 'A permanent pacemaker', 'Sensory deafness', 'C', 'MRI is contraindicated with most permanent pacemakers because the strong magnetic field can disrupt or damage the device (Brunner & Suddarth''s). Claustrophobia and deafness can be accommodated and are not absolute contraindications.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 6-month-old client is placed on strict bed rest following a hernia repair. Which toy is best suited to the client?', 'Colorful crib mobile', 'Hand-held electronic games', 'Cars in a plastic container', '30-piece jigsaw puzzle', 'A', 'A colorful crib mobile suits a 6-month-old''s developmental level (visual tracking) and is appropriate for strict bed rest (Basic Paediatric Protocols; growth & development principles). Electronic games and jigsaw puzzles are for older children.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to discharge a client with a long history of polio. The nurse should tell the client that:', 'Taking a hot bath will decrease stiffness and spasticity.', 'A schedule of strenuous exercise will improve muscle strength.', 'Rest periods should be scheduled throughout the day.', 'Visual disturbances can be corrected with prescription glasses.', 'C', 'Clients with polio/post-polio syndrome fatigue easily, so scheduled rest periods conserve energy and protect weakened muscles (Brunner & Suddarth''s). Strenuous exercise can worsen muscle weakness and is contraindicated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client on the postpartum unit has a proctoepisiotomy. The nurse should anticipate administering which medication?', 'Dulcolax suppository', 'Docusate sodium (Colace)', 'Methyergonovine maleate (Methergine)', 'Bromocriptine sulfate (Parlodel)', 'B', 'After a proctoepisiotomy (extending into the rectum), a stool softener such as docusate sodium prevents straining and protects the repair (Myles Textbook for Midwives). A stimulant Dulcolax suppository is avoided as it can traumatize the suture line.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with pancreatic cancer has an infusion of TPN (Total Parenteral Nutrition). The doctor has ordered for sliding-scale insulin. The most likely explanation for this order is:', 'Total Parenteral Nutrition leads to negative nitrogen balance and elevated glucose levels.', 'Total Parenteral Nutrition cannot be managed with oral hypoglycemics.', 'Total Parenteral Nutrition is a high-glucose solution that often elevates the blood glucose levels.', 'Total Parenteral Nutrition leads to further pancreatic disease.', 'C', 'TPN is a hypertonic high-dextrose solution that commonly causes hyperglycemia, requiring sliding-scale insulin coverage (Brunner & Suddarth''s). TPN actually promotes positive nitrogen balance, so option A is incorrect.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An adolescent primigravida who is 10 weeks pregnant attends the antepartal clinic for a first check-up. To develop a teaching plan, the nurse should initially assess:', 'The client''s knowledge of the signs of preterm labor', 'The client''s feelings about the pregnancy', 'Whether the client was using a method of birth control', 'The client''s thought about future children', 'B', 'For an adolescent primigravida, the nurse must first assess her feelings/acceptance of the pregnancy, as this shapes her receptiveness to any teaching plan (Myles Textbook for Midwives; Kenya focused antenatal care). Preterm-labor signs are taught later in pregnancy.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An obstetric client is admitted with dehydration. Which IV fluid would be most appropriate for the client?', '0.45 normal saline', 'Dextrose 1% in water', 'Lactated Ringer''s', 'Dextrose 5% in 0.45 normal saline', 'C', 'Lactated Ringer''s is an isotonic, balanced crystalloid ideal for restoring intravascular volume in dehydration (Kenya MOH fluid guidelines; Brunner & Suddarth''s). ''Dextrose 1% in water'' is not a standard preparation, and 0.45 NS is hypotonic.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a thyroid scan to confirm the diagnosis. Before the procedure, the nurse should:', 'Assess the client for allergies', 'Bolus the client with IV fluid', 'Tell the client he will be asleep', 'Insert a urinary catheter', 'A', 'A thyroid scan uses radioactive iodine tracer, so the nurse must assess for iodine/shellfish allergy before the procedure (Brunner & Suddarth''s). Sedation, IV bolus, and catheterization are not routinely required.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an injection of RhoGam for a client with blood type A negative. The nurse understands that RhoGam is given to:', 'Provide immunity against Rh isoenzymes', 'Prevent the formation of Rh antibodies', 'Eliminate circulating Rh antibodies', 'Convert the Rh factor from negative to positive', 'B', 'RhoGam (anti-D immunoglobulin) provides passive immunity that suppresses the Rh-negative mother''s active production of anti-Rh antibodies, protecting future pregnancies (Myles Textbook for Midwives; Kenya MNH guidelines). It does not convert the Rh factor or eliminate existing antibodies.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted to the emergency room after a fall. X-rays reveal that the client has several fractured bones in the foot. Which treatment should the nurse anticipate for the fractured foot?', 'Application of a short inclusive spica cast', 'Stabilization with a plaster-of-Paris cast', 'Surgery with Kirschner wire implantation', 'A gauze dressing only', 'B', 'Simple closed fractures of the foot are typically immobilized with a plaster-of-Paris cast to allow bone healing (Brunner & Suddarth''s; Kenya orthopaedic practice). A spica cast is for hip/thigh, and Kirschner wires are reserved for unstable/displaced fractures.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with bladder cancer is being treated with iridium seed implants. The nurse''s discharge teaching should include telling the client to:', 'Strain his urine', 'Increase his fluid intake', 'Report urinary frequency', 'Avoid prolonged sitting', 'B', 'After bladder iridium seed implants, increased fluid intake dilutes urine, reduces bladder irritation, and flushes the urinary tract (Brunner & Suddarth''s oncology nursing). Straining urine is not indicated for internal implants.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a heart transplant, a client is started on medication to prevent organ rejection. Which category of medication prevents the formation of antibodies against the new organ?', 'Antivirals', 'Antibiotics', 'Immunosuppressants', 'Analgesics', 'C', 'Immunosuppressant drugs (e.g., cyclosporine, tacrolimus) suppress the immune response and prevent antibody-mediated rejection of the transplanted heart (Brunner & Suddarth''s; Kenya EML). Antivirals and antibiotics treat infection, not rejection.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing a client for cataract surgery. The nurse is aware that the procedure will use:', 'Mydriatics to facilitate removal', 'Miotic medications such as Timoptic', 'A laser to smooth and reshape the lens', 'Silicone oil injections into the eyeball', 'A', 'Before cataract extraction, mydriatic (dilating) drops are instilled to widen the pupil and allow access to and removal of the lens (Brunner & Suddarth''s; Kenya EML ophthalmic). Miotics constrict the pupil and would hinder surgery.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with Alzheimer''s disease is awaiting placement in a skilled nursing facility. Which long-term plans would be most therapeutic for the client?', 'Placing mirrors in several locations in the home', 'Placing a picture of herself in her bedroom', 'Placing simple signs to indicate the location of the bedroom, bathroom, and so on', 'Alternating healthcare workers to prevent boredom', 'C', 'Simple orienting signs help the Alzheimer''s client navigate and maintain independence and safety (Brunner & Suddarth''s; mental health nursing). Mirrors can increase confusion/agitation and rotating caregivers reduces consistency.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with an abdominal cholecystectomy returns from surgery with a Jackson-Pratt drain. The chief purpose of the Jackson-Pratt drain is to:', 'Prevent the need for dressing changes', 'Reduce edema at the incision', 'Provide for wound drainage', 'Keep the common bile duct open', 'C', 'A Jackson-Pratt is a closed-suction drain whose main purpose is to remove serosanguineous fluid from the surgical wound bed, reducing collection and promoting healing (Kozier & Erb''s; Brunner & Suddarth''s). It does not keep the bile duct patent.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted with multiple trauma. Fractures include the pelvis, femur, and ulna. Which finding should be reported to the physician immediately?', 'Hematuria', 'Muscle spasms', 'Dizziness', 'Nausea', 'A', 'With a pelvic fracture, hematuria signals possible bladder or urethral injury and must be reported immediately (Brunner & Suddarth''s; Kenya trauma care). Muscle spasms and nausea are expected and less urgent findings.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant''s Apgar score is 9 at 5 minutes. The nurse is aware that the most likely cause for the deduction of one point is:', 'The baby is cold.', 'The baby is experiencing bradycardia.', 'The baby''s hands and feet are blue.', 'The baby is lethargic.', 'C', 'Per Myles Textbook for Midwives, acrocyanosis (blue hands and feet) is the commonest reason a healthy newborn loses one Apgar point on colour, giving a score of 9; heart rate, tone and reflex are usually normal.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for rapid continuous rewarming of the area affected by frostbite is to:', 'Lessen the amount of cellular damage', 'Prevent the formation of blisters', 'Promote movement', 'Prevent pain and discomfort', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rapid continuous rewarming of frostbite in a warm water bath limits the extent of tissue and cellular destruction; the other options are secondary.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client recently started on hemodialysis wants to know how the dialysis will take the place of his kidneys. The nurse''s response is based on the knowledge that hemodialysis works by:', 'Passing water through a dialyzing membrane', 'Eliminating plasma proteins from the blood', 'Lowering the pH by removing nonvolatile acids', 'Filtering waste through a dialyzing membrane', 'D', 'Per Brunner & Suddarth''s, hemodialysis removes nitrogenous waste and excess solutes by diffusion across a semipermeable dialyzing membrane; it does not remove plasma proteins and its purpose is waste filtration, not simply passing water.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During a home visit, a client with AIDS tells the nurse that he has been exposed to measles. Which action by the nurse is most appropriate?', 'Administer an antibiotic', 'Contact the physician for an order for immune globulin', 'Administer an antiviral', 'Tell the client that he should remain in isolation for 2 weeks', 'B', 'Per Kenya HIV/AIDS and immunocompromised care guidelines and Brunner & Suddarth''s, an immunosuppressed AIDS client exposed to measles should receive immune (immunoglobulin) prophylaxis; antibiotics and antivirals are not indicated for measles post-exposure protection.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client who is admitted with an above-the-knee amputation tells the nurse that his foot hurts and itches. Which response by the nurse indicates understanding of phantom limb pain?', '"The pain will go away in a few days."', '"The pain is due to peripheral nervous system interruptions. I will get you some pain medication."', '"The pain is psychological because your foot is no longer there."', '"The pain and itching are due to the infection you had before the surgery."', 'B', 'Per Brunner & Suddarth''s, phantom limb pain is a real physiologic phenomenon arising from severed peripheral nerve pathways and CNS reorganization, not psychological; it should be acknowledged and treated with analgesia.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with cancer of the pancreas has undergone a Whipple procedure. The nurse is aware that during the Whipple procedure, the doctor will remove the:', 'Head of the pancreas', 'Proximal third section of the small intestines', 'Stomach and duodenum', 'Esophagus and jejunum', 'A', 'Per Brunner & Suddarth''s, the Whipple (pancreaticoduodenectomy) removes the head of the pancreas along with the duodenum, distal stomach, gallbladder and distal common bile duct; among the options, the head of the pancreas is the defining structure removed.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a minimal-bacteria diet for a client with neutropenia. The client should be taught to avoid eating:', 'Fruits', 'Salt', 'Pepper', 'Ketchup', 'A', 'Per oncology nursing guidance in Brunner & Suddarth''s, a neutropenic (low-bacteria) diet avoids raw/fresh fruits and vegetables which carry surface bacteria; seasonings like salt, pepper and ketchup are not the primary hazard.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assisting the physician with removal of a central venous catheter. To facilitate removal, the nurse should instruct the client to:', 'Perform the Valsalva maneuver as the catheter is advanced', 'Turn his head to the left side and hyperextend the neck', 'Take slow, deep breaths as the catheter is removed', 'Turn his head to the right while maintaining a sniffing position', 'A', 'Per Brunner & Suddarth''s, during central venous catheter removal the client performs the Valsalva maneuver (bear down/hold breath) to raise intrathoracic pressure and prevent air embolism as the catheter is withdrawn; the stem''s wording ''advanced'' reflects the removal procedure and the Valsalva timing is the key safety action.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has an order for streptokinase. Before administering the medication, the nurse should assess the client for:', 'Allergies to pineapples and bananas', 'A history of streptococcal infections', 'Prior therapy with phenytoin', 'A history of alcohol abuse', 'B', 'Per Kenya EML/BNF pharmacology, streptokinase is derived from streptococci; recent streptococcal infection produces antibodies that reduce efficacy and increase allergic risk, so the nurse assesses for prior streptococcal infection.', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing discharge teaching for the client with leukemia. The client should be told to avoid:', 'Using oil- or cream-based soaps', 'Flossing between the teeth', 'The intake of salt', 'Using an electric razor', 'B', 'Per Brunner & Suddarth''s, leukemia clients are thrombocytopenic and neutropenic; flossing can cause gum bleeding and introduce infection, so it should be avoided. An electric razor is actually recommended to prevent cuts.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is changing the ties of the client with a tracheotomy. The safest method of changing the tracheostomy ties is to:', 'Apply the new tie before removing the old one.', 'Have a helper present.', 'Hold the tracheotomy with the nondominant hand while removing the old tie.', 'Ask the doctor to suture the tracheostomy in place.', 'A', 'Per Kozier & Erb''s Fundamentals, the safest method when changing tracheostomy ties is to secure the new tie before removing the old one to prevent accidental decannulation.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is monitoring a client following a lung resection. The hourly output from the chest tube was 300mL. The nurse should give priority to:', 'Turning the client to the left side', 'Milking the tube to ensure patency', 'Slowing the intravenous infusion', 'Notifying the physician', 'D', 'Per Brunner & Suddarth''s, chest tube drainage exceeding 100 mL/hr (here 300 mL) suggests active hemorrhage and is a priority to report to the physician immediately; milking the tube is contraindicated.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with clotting disorder has an order to continue Lovenox (enoxaparin) injections after discharge. The nurse should teach the client that Lovenox injections should:', 'Be injected into the deltoid muscle', 'Be injected into the abdomen', 'Aspirate after the injection', 'Clear the air from the syringe before injections', 'B', 'Per Kenya EML/BNF, enoxaparin (Lovenox) is given subcutaneously into the abdominal fat (''love handles''); the air bubble is not expelled and the site is not aspirated or massaged to avoid bruising.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has recently returned from having a thyroidectomy. The nurse should keep which of the following at the bedside?', 'A tracheotomy set', 'A padded tongue blade', 'An endotracheal tube', 'An airway', 'A', 'Per Brunner & Suddarth''s, after thyroidectomy a tracheotomy set is kept at the bedside because laryngeal nerve damage, tracheal compression or tetany-related laryngospasm can cause airway obstruction requiring emergency tracheotomy. Source: NCK Paper 1 & 2 Combined Practice Sets (Type 1-4)', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which blood gas analyses are most indicative of respiratory acidosis?', 'pH = 7.22, PC02 = 55 mm Hg, HC03 = 30 mEq/L.', 'pH = 7.28, PC02 = 45 mm Hg, HC03 = 15 mEq/L.', 'pH = 7.34, PC02 = 35 mm Hg, HC03 = 25 mEq/L.', 'pH = 7.40, PC02 = 25 mm Hg, HC03 = 30 mEq/L.', 'A', 'Respiratory acidosis = low pH with elevated PCO2. Option A shows pH 7.22 (acidotic) with PCO2 55 (elevated, the primary cause) and compensatory HCO3 rise. The other options are metabolic acidosis (B), normal (C), or respiratory alkalosis (D). Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Expansion of the intravascular volume and increased intravascular pressure are the main causes of edema in', 'lymphatic obstruction', 'heart failure', 'protein-losing enteropathy', 'nephrotic syndrome', 'B', 'In heart failure, increased intravascular (venous/hydrostatic) volume and pressure drive fluid into interstitium causing oedema; per Brunner & Suddarth''s Medical-Surgical Nursing. Lymphatic obstruction, protein-losing enteropathy and nephrotic syndrome cause oedema mainly via reduced oncotic pressure or lymphatic blockage, not raised intravascular volume/pressure.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common respiratory tract manifestations of neonatal bacterial infections is', 'ethmoiditis', 'empyema', 'otitis media', 'mastoiditis', 'C', 'Otitis media is a common upper respiratory tract manifestation of neonatal bacterial infection; per Basic Paediatric Protocols/neonatal texts. Ethmoiditis, empyema and mastoiditis are uncommon in neonates as presenting infections. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antiretroviral agents, such as AZT are used in the management of AIDS. Which of the following is not an action expected of these drugs?', 'They prolong the life of the client with AIDS', '. They reduce the risk of opportunistic infections', '. They shorten the period of communicability of the disease', 'They are able to bring about a cure of the disease condition Your Answer :', 'D', 'Per Kenya National ARV Guidelines, ART suppresses viral replication, prolongs life, reduces opportunistic infections and lowers communicability, but does NOT cure HIV. The question asks which is NOT an expected action, so the correct answer is that ARVs cure the disease.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 1 1/2 year old child was classified as having 3rd degree of protein energy malnutrition, kwashjorkor. Which of the following signs will be most apparent in this child?', 'voracious appetite', 'wasting', 'apathy', 'edema', 'D', 'Per Kenya Basic Paediatric Protocols and IMNCI, kwashiorkor (protein malnutrition) is characterised chiefly by bilateral pitting oedema, along with apathy and hair/skin changes; oedema is the defining/most apparent sign distinguishing it from marasmus (wasting). Wasting is the hallmark of marasmus, not kwashiorkor. 679. abnrmally low set ears could be indicative of A. otogenous tetanus B. congenital heart defect C. tracheoesophageal fistula D. renal anomalies Answer: D. renal anomalies Rationale: Per paediatric/neonatal assessment (Basic Paediatric Protocols; standard paediatric texts), low-set ears are a well-recognised marker associated with congenital renal anomalies (and chromosomal syndromes) because the ears and kidneys develop concurrently. This is the classic newborn examination association. 680. in type three trachea-esophageal fistula A. upper segment of esophagus open into trachea B. lower segment of esophagus open into trachea C. normal trachea and esophagus are connected by a fistula D. proximal and distal segments of esophagus are blind Answer: C. normal trachea and esophagus are connected by a fistula Rationale: Per paediatric surgery classification (Gross type C, the most common tracheo-esophageal fistula), Type III/C is a proximal esophageal atresia with a distal esophageal segment communicating with the trachea via a fistula — i.e. trachea and esophagus connected by a fistula. This is the commonest variant taught in paediatric nursing. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother brought her daughter, 4 years old, to the RHU because of cough and colds. Following the IMCI assessment guide, which of the following is a danger sign that indicates the need for urgent referral to a hospital?', 'Inability to drink', 'High grade fever', 'Signs of severe dehydration', 'Cough for more than 30 days', 'A', 'Per Kenya IMNCI guidelines, the general danger signs requiring urgent referral are: inability to drink or breastfeed, vomiting everything, convulsions, and lethargy/unconsciousness. Inability to drink is a listed IMNCI danger sign; high fever and cough duration are not general danger signs.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother brought her 10 month old infant for consultation because of fever which started 4 days prior to consultation. To determine malaria risk, what will you do?', 'Do a tourniquet test', 'Ask where the family resides', 'Get a specimen for blood smear', 'Ask if the fever is present everyday', 'C', 'Per Kenya Malaria Guidelines and IMNCI, any child with fever in a malaria-endemic area must have a parasitological test (blood smear or RDT) to confirm malaria before treatment. A confirmed blood smear determines actual malaria, whereas residence/pattern questions only assess exposure risk. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathognomonic sign of measles is Koplik’s spot. You may see Koplik’s spot by inspecting the:', 'Nasal Mucosa', 'Buccal mucosa', 'Skin on the abdomen', 'Skin on the antecubital surface', 'B', 'Per standard paediatric/communicable disease texts, Koplik''s spots (pathognomonic of measles) are small white spots seen on the buccal mucosa opposite the molars, appearing before the rash. They are not found on the nasal mucosa or skin.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a mother’s class, you discuss proper breastfeeding technique. Which of these is a sign that the baby has “lactated on” the breast property?', 'The baby takes shallow, rapid sucks', '. The mother does not feel nipple pain', 'The baby’s mouth is only partly open', 'Only the mother’s nipple is inside the baby’s mouth', 'B', 'Per Kenya MOH/WHO breastfeeding guidance, good attachment (latch) signs include the baby''s mouth wide open, more areola visible above than below, chin touching breast, slow deep sucks, and painless feeding for the mother. Shallow rapid sucks, partly-open mouth and nipple-only in mouth indicate poor attachment.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following medications might be prescribed for someone with OCD: -', 'Anxiolytic', 'Antipsychotic', 'Hypnotic', 'Mood stabilizers', 'A', 'Per Kenya EML and psychiatric nursing references, OCD is treated with SSRIs and adjunctive anxiolytics to control anxiety; of the listed drug classes an anxiolytic is the appropriate choice, as OCD is an anxiety-spectrum disorder rather than a psychotic or mood disorder. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When developing a plan of care for a male adolescent, the nurse considers the child’s psychosocial needs. During adolescence, psychosocial development focuses on:', 'Becoming industrious', 'Establishing an identity', 'Achieving intimacy', 'Developing initiative', 'B', 'Per Erikson''s developmental theory (Kozier & Erb''s), the psychosocial task of adolescence is identity vs. role confusion, i.e. establishing an identity. Industry is school age, intimacy is young adulthood, initiative is preschool.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a child less than 3 years, the diagnosis of failure to thrive (FTT)is considered if', 'weight is below the 3rdpercentile', 'BMI less than the 25thpercentile', 'weight drops down more than 2 major percentile', 'BMI less than the 25thpercentile', 'C', 'Failure to thrive in a child under 3 is defined by weight below the 3rd/5th percentile OR crossing downward more than 2 major percentile lines on the growth chart (Nelson; Basic Paediatric Protocols). The best single discriminating dynamic criterion is a fall of more than 2 major percentiles; BMI percentiles are not used in this age group. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Approaching to a child with failure to thrive based on signs and symptoms.Of the following, the MOST common cause behind a child has spitting, vomiting, and food refusal is', 'gastroesophageal reflux', 'chronic tonsillitis', 'food allergies', 'inflammatory bowel disease', 'A', 'In an infant/young child with spitting, vomiting and food refusal contributing to FTT, gastroesophageal reflux is the most common underlying cause (Nelson Textbook of Pediatrics). Tonsillitis, food allergy and IBD are far less common causes of this triad.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All the following are an absolute indications for endotracheal intubation EXCEPT', 'inability to protect the airway against aspiration', 'failing to maintain adequate oxygenation', 'complete airway obstruction', 'failing to control blood carbon dioxide levels', 'D', 'Absolute indications for intubation are inability to protect the airway, failure to oxygenate, and complete airway obstruction (Brunner & Suddarth; ATLS). Isolated CO2 (ventilation) derangement is a relative indication and can often be managed non-invasively, making it the EXCEPT.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A child growing within normal developmental milestones will be able to have good head control at the age of:', '3-6 months', '6-9 months', '12-18 months', '20-24 months', 'A', 'Per Basic Paediatric Protocols / IMNCI developmental milestones, good head control is achieved by about 3-4 months (within the 3-6 month range), well before sitting and standing milestones. 710. the characteristics of a classical syphilitic ulcer include A. painful, flat lesion with edema of the surrounding area B. painful, extensive lesions, fluid filled vesicle like blister C. painless, flat lesion with smooth regular firm edge D. painless, flat lesion with irregular edges and flat dirty base Answer: C. painless, flat lesion with smooth regular firm edge Rationale: The primary syphilitic chancre is a painless, indurated ulcer with a smooth, clean base and firm, regular raised edges; painful ragged/dirty ulcers suggest chancroid (Kenya STI guidelines, Brunner & Suddarth). 711. the commonest causative organism of urinary tract infection is A. proteus B. streptococcus aureus C. Escherichia coli D. Klebsiela Answer: C. Escherichia coli Rationale: Escherichia coli is the commonest causative organism of urinary tract infection, accounting for the majority of uncomplicated UTIs (Brunner & Suddarth, Kenya clinical guidelines).', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are clinical features of marasmus except', 'Hepatomegaly', 'Old man’s’ face', 'edema', 'Decrease in 60% of required weight', 'C', 'Oedema is the hallmark of kwashiorkor, not marasmus; marasmus features severe wasting, old man''s face and weight far below expected. Thus oedema is the exception (Kenya IMNCI / Basic Paediatric Protocols). ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following falls under “DELAY” in the medical eligibility criteria?', 'Age of 18 years', 'Local skin infection', 'Depressive disorders', 'Diabetes Mellitus', 'B', 'In WHO/Kenya Medical Eligibility Criteria, the classifications are Accept, Caution, Delay and Refer; a local infection at the insertion site is a ''Delay'' condition for methods like implants/IUCDs until it resolves, whereas the others are accept/caution categories.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lactation amenorrhea method of family planning is suitable for a woman who', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of more than six months', 'Breastfeeds exclusively,has history of delayed menstruation, wants highly effective method in the first six months', 'Breastfeeds exclusively, has not resumed menstruation, has a baby of less than six months', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of less than six months A. what disease is indicative of thiamine deficiency A. Beriberi B. Pellagra C. Scurvy D. Kwashiokor', 'C', 'LAM requires all three criteria: exclusive breastfeeding, amenorrhoea (menses not resumed), and infant under 6 months. Per Kenya National Family Planning Guidelines. Option D''s stray text (Beriberi item) is disregarded.', 'BScN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 60-year-old homeless man is brought to the emergency department by ambulance. He has a history of alcohol dependence syndrome. He is confused and agitated. He complains of double vision and he needs support while walking because of a disturbed gait. The most appropriate treatment is:-', 'Intravenous diazepam', 'Intravenous thiamine', 'Intravenous ascorbic acid', 'Intravenous glucose', 'B', 'Confusion, ophthalmoplegia (double vision) and ataxic gait in an alcohol-dependent patient is the classic triad of Wernicke''s encephalopathy; IV thiamine must be given before glucose to prevent precipitating/worsening the encephalopathy (Brunner & Suddarth; MOH guidelines).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following parts of the brain is associated with multiple feelings and behaviors and is sometimes referred to as the “emotional brain”: -', 'Frontal lobe', 'Thalamus', 'Hypothalamus', 'Limbic system', 'D', 'The limbic system is termed the ''emotional brain'', governing multiple emotions and behaviours; the frontal lobe handles executive function and the thalamus is a sensory relay (neuroanatomy texts).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Benzodiazepines primarily act on:-', 'GABA-A receptors', '5HT receptors', 'Dopamine receptors', 'Mu receptors', 'A', 'Benzodiazepines act by enhancing GABA at GABA-A receptors, increasing chloride conductance and CNS inhibition (pharmacology). Serotonin, dopamine and mu (opioid) receptors are unrelated to their primary action.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A child has been recovering from an operation of the cleft lip. What is your priority nursing care?', 'Bleeding tendency', 'Wound care', 'Airway patency', 'Risk for Infection', 'C', 'Following cleft-lip repair, maintaining airway patency is the priority per ABC prioritisation, as oedema, secretions and altered anatomy risk obstruction (Basic Paediatric Protocols / paediatric surgical nursing). Bleeding, wound care and infection are important but subordinate to airway.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother would like to know the reason why there is asthma in her child. How would you explain it?', 'An asthma attack is a response to release of inflammatory mediators to epithelial cells. The autonomic neural control to airway is affected.', 'An asthma attack can happen when the child is exposed to certain allergens that would trigger an allergic reaction to the bronchioles causing constriction of the bronchial tree. This is either acquired or being hereditary', 'An asthma attack is an inborn problem of a child that involves abnormal growth of the bronchial tree causing restriction.', 'All of these', 'B', 'Asthma is a chronic inflammatory airway disease in which allergen exposure triggers bronchoconstriction, with both genetic (hereditary) and acquired/environmental components (WHO/GINA, paediatric nursing). This best matches option B in accessible parent-education terms.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to Erikson stage, what is the stage of a toddler going through?', 'Trust versus mistrust', 'Initiative versus Guilt', 'Autonomy versus Shame', 'Identity versus Role Confusion', 'C', 'In Erikson''s stages the toddler (approximately 1-3 years) is in the autonomy versus shame and doubt stage (growth & development). Trust vs mistrust is infancy, initiative vs guilt is preschool, and identity vs role confusion is adolescence.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the earliest time that a child can be diagnosed to have autism?', '2 years old', '2 months old', '6 years old', '6 months old', 'D', 'Early signs of autism (impaired social engagement, lack of eye contact/social smile) can be detected as early as 6 months of age, the earliest of the options offered (child development). The other options are later than the earliest detectable point. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse leads an adolescent health information group, which often expands into other areas of discussion. She knows that these youths are trying to find out “who they are,” and discussion often focuses on which directions they want to take in school and life, as well as peer relationships. According to Erikson, this stage is known as:', 'identity vs. role confusion', 'adolescent rebellion.', 'career experimentation.', 'relationship testing', 'A', 'Adolescents seeking to discover ''who they are'' are in Erikson''s identity versus role confusion stage (growth & development). The other options are not Erikson stages.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A baby will be able to hold its head by?', '11 months', '1 month', '3 months', '9months :', 'C', 'Head control (holding the head steady) is achieved by about 3 months of age per developmental milestones (Basic Paediatric Protocols / growth & development). One month is too early and 9-11 months is too late for this milestone.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Erikson’s developmental theories differ from Freud’s in that Erikson placed greater emphasis on', 'Cultural factors in development', 'Instinctual drive', 'Interpersonal relations', 'Psychosexual development', 'A', 'Erikson''s psychosocial theory emphasised cultural and social influences across the lifespan, differing from Freud''s focus on instinctual drives and psychosexual development (growth & development). While Erikson also valued relationships, cultural/psychosocial emphasis is the defining contrast with Freud. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While assessing a newborn with cleft lip, the nurse would be alert that which of the following will most likely be compromised?', 'Sucking ability', 'Respiratory status', 'Locomotion', 'GI function', 'A', 'A cleft lip disrupts the infant''s ability to form a seal, so sucking ability is most likely compromised, creating feeding difficulty (paediatric/neonatal nursing). Respiratory status, locomotion and GI function are not primarily affected by an isolated cleft lip.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A treatment plan for child with sickle cell anemia will include:', 'IV fluids to adequately hydrate', 'Narcotic pain management when pain is severe', 'Transfusion of RBCs to correct anemia', 'All of these', 'D', 'Management of a sickle cell crisis includes adequate hydration with IV fluids, analgesia including opioids for severe pain, and RBC transfusion for significant anaemia (Kenya sickle cell guidelines / paediatric nursing). Therefore all listed measures apply.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 9-year old is admitted with suspected rheumatic fever. Which finding is suggested of polymigratory arthritis?', 'Irregular movements of the extremities and facial grimacing', 'Painless swelling over the extensor surfaces of the joints', 'Faint areas of red demarcation over the back and abdomen', 'Swelling, inflammation and effusion of the joints', 'D', 'Polymigratory arthritis of rheumatic fever presents as swelling, inflammation and effusion migrating between large joints (Jones criteria / paediatric nursing). Irregular movements/grimacing indicate chorea, painless swellings indicate nodules, and red demarcation indicates erythema marginatum.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which nursing action is a priority as the plan of care is developed for a 7year-old child hospitalized for acute glomerulo-nephritis?', 'Assess for generalized edema', 'Monitor for increased urinary output', 'Encourage rest during hyperactive periods', 'Note patterns of increased blood pressure', 'D', 'In acute glomerulonephritis, hypertension from fluid overload is a key life-threatening complication, so monitoring blood pressure patterns is the priority (paediatric renal nursing). Edema assessment matters but hypertension surveillance is the priority; oliguria (not increased output) is expected. ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a 12 year old child with Wilm''s tumor, the nurse should keep in mind that it most important to avoid which of the following?', 'Measuring the child''s chest circumference', 'Palpating the child''s abdomen', 'Placing the child in an upright position', 'Measuring the child''s occipitofrontal circumference', 'B', 'In Wilms'' tumour, palpating the abdomen must be avoided because it may dislodge tumour cells and cause metastatic spread (paediatric oncology nursing). The other measures pose no such risk.', 'BScN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Respiratory Distress Syndrome is a disease of preterm infant which caused due to all of the following except:', 'Atelectasis of alveoli.', 'Immaturity of the respiratory center.', 'Formation of surfactant substances.', 'Hypoxia.', 'C', 'RDS of the preterm is caused by DEFICIENCY (not formation) of surfactant, leading to alveolar atelectasis, hypoxia and immature respiratory control. Since ''formation of surfactant substances'' would prevent RDS, it is the exception. Per Basic Paediatric Protocols (Kenya).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sudden stimulus causes the arms to fly up and out is:', 'Moro', 'Gag', 'Rooting', 'Tonic neck', 'A', 'The Moro (startle) reflex is elicited by a sudden stimulus causing symmetrical abduction/extension of the arms followed by flexion. Rooting and gag involve the mouth; tonic neck is the fencing posture. Standard neonatal assessment (Kozier & Erb''s, Basic Paediatric Protocols).', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse is administering blood to a child who has a low hemoglobin count. He asks how long to RBC’s last in my body? The correct response is:', 'The life span of RBC is 45 days', 'The life span of RBC is 60 days', 'The life span of RBC is 90 days', 'The life span of RBC is 120 days', 'D', 'Normal erythrocyte lifespan is approximately 120 days before splenic removal. Anatomy & Physiology / Brunner & Suddarth''s haematology.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clinical assessments would most likely be demonstrated in severe dehydration?', 'Pale skin turgor', 'Normal skin turgor', 'Marked oliguria', 'Normal blood pressure', 'C', 'Severe dehydration produces marked oliguria/anuria from reduced renal perfusion, along with hypotension and poor (not normal) skin turgor. Per Kenya IMNCI classification of severe dehydration; ''normal'' BP and turgor are inconsistent with severe loss.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Shock is characterized by the following signs except', 'Tachypnea', 'Pallor', 'Cool skin', 'Delayed capillary refill', 'A', 'The question asks the sign that is NOT typical; however pallor, cool skin and delayed capillary refill are hallmark shock signs while tachypnea is also expected. Re-reading, tachypnea IS present in shock, but among the four the intended ''except'' is tachypnea being the least specific compensatory finding. Per Basic Paediatric Protocols, all four occur in shock, so this item lists no true exception; tachypnea is the best ''except'' choice as the others are the classic peripheral perfusion signs. ⚠ Best answer not clearly among choices ⚠ More than one defensible answer', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant has had frequent episodes of green, mucus-containing stools. The nursing assessment reveals that the infant has dry mucus membranes, poor skin turgor, and an absence of tearing. Based on these data, what is the most appropriate nursing diagnosis?', 'Impaired skin integrity related to irritation caused by frequent, loose stools', 'Deficient fluid volume related to frequent, loose stools', 'Pain related to abdominal cramping and diarrhea', 'Imbalanced nutrition: less than body requirements related to diarrhea', 'B', 'Dry mucous membranes, poor skin turgor and absent tearing are signs of dehydration, making deficient fluid volume the priority (ABC/physiologic) diagnosis. Per Kenya IMNCI and Kozier & Erb''s; skin integrity and nutrition are lower priority than fluid loss.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnosis would the nurse identify as a priority for the infant with tracheoesophageal fistula (TEF)?', 'impaired parenting related to newborn''s illness', 'risk of injury related to increased potential for aspiration', 'ineffective nutrition: less than body requirements, related to poor sucking ability', 'ineffective breathing pattern related to a weak diaphragm', 'B', 'In TEF the priority is preventing aspiration of secretions/feeds into the lungs (airway protection), making risk of injury/aspiration the priority. Per airway-first (ABC) prioritisation; parenting and nutrition are lower priority.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In bacterial meningitis all the following may be observed during CSF analysis results except: a. b. c. d.', 'high cells count', 'high glucose', 'high protein', 'turbidity', 'B', 'In bacterial meningitis CSF shows high WBC (neutrophils), high protein, low (not high) glucose, and turbidity. Thus ''high glucose'' is the exception. Per Basic Paediatric Protocols / Brunner & Suddarth''s.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Kerning''s sign is manifestation for:', 'Wiliam''s tumor .', 'Acute Rheumatic Fever.', 'Encephalitis', 'Meningiti s', 'D', 'Kernig''s sign (resistance/pain on knee extension with hip flexed) is a sign of meningeal irritation seen in meningitis. Brunner & Suddarth''s / Basic Paediatric Protocols.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An appropriate nursing assessment of an infant with spina bifida includes all of the following, except: a. b c. d.', 'head circumference.', 'checking reflexes.', 'palpating fontanels.', 'abdominal girth.', 'D', 'Assessment of an infant with spina bifida focuses on neurologic status: head circumference, reflexes, and fontanels (for hydrocephalus). Abdominal girth is not a routine part of this assessment, making it the exception. Standard neuro-paediatric nursing.', 'BScN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A Child clinic recorded a total of 300 cases of pneumonia in the month of May. This is referred to as;', 'Prevalence', 'Incidence', 'Disease burden', 'Morbidity', 'B', 'Per epidemiology (KMTC/AMREF community health), the number of NEW cases occurring in a defined population over a specified period (300 pneumonia cases in one month) is incidence. Prevalence would be all existing cases at a point in time.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to KEPI schedule of immunization, the correct dose for vitamin A at six months is;', '50,000 i.u', '100,000 i.u', '200,000 i.u', '500,000 i.u', 'B', 'Per KEPI/Kenya vitamin A supplementation schedule, infants 6-11 months receive 100,000 IU; children 12-59 months receive 200,000 IU every 6 months. At exactly six months the dose is 100,000 IU.', 'BScN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gametes of plasmodium develop in the;', 'Human liver', 'Human blood', 'Stomach of the mosquito', 'Salivary glands of the mosquito', 'B', 'The sexual forms (gametocytes/gametes) of Plasmodium develop in HUMAN BLOOD, within red blood cells, and circulate to be taken up in a mosquito blood meal. Only after ingestion do the gametes fuse to form a zygote/ookinete and oocysts in the mosquito stomach. As the item asks where the gametes develop (in the human host), human blood is the best answer. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Malaria', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bancroftian filariasis can be prevented by', 'Clearing bushes along rivers to increase the water flow rate.', 'Screening of house windows', 'Not settling near forests', 'Wearing shoes when working in swampy areas.', 'B', 'Per community health references, Bancroftian filariasis is transmitted by Culex mosquitoes; vector control including screening of house windows/doors and mosquito control prevents transmission. Shoes prevent hookworm, not filariasis.', 'BScN', 'Paper II', 'Community Health Nursing', 'Communicable Diseases', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nursing officer in-charge of a health facility used the facility''s outreach vehicle to attend her brother''s fundraising function and therefore the outreach services were not offered that day. Which principle of management did she break?', 'Unity of direction', 'Discipline', 'Unity of command', 'Subordination of Individual Interest', 'D', 'Per Fayol''s principles of management, using the facility vehicle for a personal (brother''s) function placed her individual interest above the organisation''s, violating ''subordination of individual interest to the general interest''.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse should advice a care taker for a home Based Care (HBC) patient with mouth sores;', 'Not to give cold food and drinks to the patient', 'Rinse the mouth of the patient with salty water.', 'Use a spoon instead of straws when giving fluids to the patient', 'Not to give citrus fruits like lemon to the patient', 'D', 'Per Kenya Home-Based Care guidelines for HIV/AIDS patients with mouth sores, acidic/citrus foods (lemon, oranges) and spicy/salty foods irritate ulcers and should be avoided; soft, non-irritating foods are recommended. Salt-water rinses are actually helpful, so option B is not the advice given here. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('School health committees are composed of the following EXCEPT;', 'Teachers, students, community health nurse', 'Teachers, community informal leaders, Parents', 'Community health nurse, Teachers, school''s supportive staff', 'Parents, teachers, community formal leaders', 'A', 'Per school health programme guidelines, the school health committee comprises teachers, parents, community leaders, health workers and supportive staff; students/pupils are not formal committee members, so this option is the EXCEPT.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A community health nurse should advice the community to ensure the distance between food shelves and the ground is at least;', '30cm', '10cm', '0.5 metres', '1 metre', 'A', 'Per environmental/food hygiene standards taught in Kenyan community health, food storage shelves should be at least 30 cm (about 1 foot) above the ground/floor to prevent contamination and allow cleaning and pest control.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A country with population pyramid that is broad at the bottom should have more health programs focusing on ;', 'Promoting women health', 'Prevention of chronic diseases', 'Youth health', 'Prevention of sexually transmitted diseases', 'C', 'Per demography, a population pyramid broad at the base indicates a young, rapidly growing population with a high proportion of children/youth, so health programs should focus on child and youth health (and MCH). Chronic disease prevention fits an ageing population.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Active immunity;', 'Is acquired after several doses of a vaccine.', 'Is acquired after vaccination with a live vaccine.', 'Is only acquired only when organisms invade the body.', 'Is life long', 'A', 'Per immunology/KEPI, active immunity develops when the body produces its own antibodies, typically requiring several doses of a vaccine (or natural infection) to build adequate protection. It is not always lifelong and not only from live vaccines or only from natural invasion.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A child who is seen for the first time at 9months should be given the following vaccines;', 'BCG, Polio, Penta valent, measles', 'Polio, penta valent, measles', 'Measles only', 'BCG, Penta valent, measles', 'B', 'Per KEPI catch-up guidance, a child first seen at 9 months no longer needs BCG (given at birth, and scar may already be present/window passed for benefit weighing) but requires catch-up OPV, pentavalent and the measles dose due at 9 months. Option B best fits the routine antigens still indicated. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Autocratic leaders are likely to use the following theory;', 'Abraham Maslow', 'Theory X', 'Theory Y', 'Fredrick Herzberg''s', 'B', 'Per McGregor''s management theory, autocratic leaders adopt Theory X assumptions (workers dislike work and need control/coercion), whereas participative leaders align with Theory Y.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of an effective team include:-', 'The management relationship in the organization is directive, information flows mainly downwards', 'Every member understands the objective and goals, communication is open during meetings', 'Criticism is frank and constructive, each individual strives to meet individual tasks', 'Decision making is by consensus, conflicts never arise due to the harmony', 'B', 'Per nursing management/leadership theory, effective teams share understood goals, open communication and consensus decision-making. Option B reflects these; directive downward-only flow and the claim that conflicts ''never arise'' are incorrect characteristics.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Active immunity:-', 'Is the immunity developed by own production of antibodies', 'Develops when a high proportion of the community have been immunized', 'Is when one is protected temporarily by use of borrowed antibodies', 'Is when one''s immunity is reinforced by use of vaccines', 'A', 'Per Kenya immunization/KEPI principles, active immunity is protection from the body''s own antibody production (via infection or vaccination). Borrowed antibodies give passive immunity, and high community coverage describes herd immunity.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Physical therapy in home based care helps in:-', 'Reducing loneliness, relaxation, improving circulation', 'Improving circulation, preventing muscle wasting, improving digestion', 'Reducing loneliness, preventing chest infection, improving digestion', 'Prevention of contractures, prevention of boredom, improving digestion', 'B', 'Per Kenya home-based care guidelines, physical therapy/exercise improves circulation, prevents muscle wasting and contractures, and aids digestion/bowel function. Option B best lists physical (rather than purely psychosocial) benefits. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A family in which the spouses have divorced but they both remain responsible for upkeep of the children is referred to as:-', 'Blended family', 'Binuclear family', 'Single family', 'Foster family', 'B', 'Per family sociology in community health nursing, a binuclear family is one where divorced parents both remain responsible for raising the children across two households. A blended family involves remarriage combining children, which is different.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of increasing the communities ability to handle a disaster is referred to as:-', 'Preparedness', 'Response', 'Mitigation', 'Prevention', 'A', 'Per Kenya disaster management guidelines, preparedness is the process of building the community''s capacity and readiness to handle a disaster before it occurs. Mitigation reduces impact/hazard severity, while response is action taken during the event.', 'BScN', 'Paper II', 'Community Health Nursing', 'Disaster Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nutrient requirements of children are NOT influenced by:', 'Growth rate', 'Body composition', 'Composition of new growth', 'Sex of the child', 'D', 'Growth rate, body composition and composition of new growth all directly influence a child''s nutrient requirements; sex has minimal influence in early childhood and is the least relevant factor (Kenya nutrition/paediatric guidelines).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a disorder in the stream of thought', 'Flight of ideas', 'Perseveration', 'Neologism', 'Thought blocking', 'A', 'Flight of ideas is a disorder of the stream/form of thought; neologism is a disorder of speech/content and thought blocking and perseveration, while form-related, flight of ideas is the classic stream-of-thought answer (Standard psychiatric nursing text). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An abnormal grief reaction would be:', 'Social withdrawal within six months of the grieving period', 'Lack of emotional response a few days after death has taken place', 'Overwhelming waves of grief one month after death has occurred', 'Incomplete acceptance that death has taken place two months after death has occurred', 'B', 'Absent/inhibited grief (no emotional response) is an abnormal (delayed/inhibited) grief reaction; social withdrawal, waves of grief and incomplete acceptance within a few months are normal features of the grieving process (standard psychiatric nursing text).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Factors to consider when selecting an instructional method do NOT include.', 'Time', 'Students characteristics', 'Teacher''s skill', 'Common practice', 'D', 'Time, student characteristics and teacher''s skill are legitimate factors in selecting an instructional method; ''common practice'' is not a valid selection criterion (Nurse education/teaching methodology).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a behaviorist theory of learning', 'Assimilation', 'Cognitive', 'Insight learning', 'Discovery learning', 'A', 'Cognitive, insight and discovery learning are cognitive/constructivist theories; among these options assimilation is the one classed under behaviorist-associative learning (learning theory). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During involuntary admission:-', 'Relatives fill MOH 613 form and the doctor fills MOH 615 form in duplicate', 'Relatives fill MOH 613 form and the doctor fills MOH 637 form in duplicate', 'Relatives fill MOH 614 form and the doctor fills MOH 615 form in duplicate', 'The doctor fills MOH 614 form and relatives fill MOH 615 form in duplicate', 'A', 'Under Kenya''s Mental Health Act procedures for involuntary admission, relatives complete the MOH 613 application and the medical officer completes the MOH 615 (medical recommendation) in duplicate (Kenya Mental Health Act/MOH forms).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A disorder where an individual displays numerous periods of hypomanic and depressive symptoms that do not meet the criteria for a major depressive episode is called:-', 'Dysthymia', 'Cyclothymia', 'Bipolar I', 'Bipolar II', 'B', 'Cyclothymia is characterised by numerous periods of hypomanic and depressive symptoms that do not meet criteria for a major depressive or manic episode; dysthymia is persistent mild depression only (DSM/standard psychiatric text).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are abnormalities of the sexual object', 'Voyeurism, sexual sadism and Transvestism', 'Sexual Masochism, bestiality and Paedophilia', 'Fetishism, Transvestism and Paedophilia', 'Fetishism, Sexual sadism and Voyeurism', 'C', 'Abnormalities of the sexual object (choice of object) include fetishism, transvestism/transvestic and paedophilia; voyeurism, sadism and masochism are abnormalities of the sexual aim (standard psychiatric text). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While teaching a group of patients a nurse used the term ''note carefully''. This is an example of;', 'Reinforcement', 'Set induction', 'Topic closure', 'Stimulus variation', 'D', 'Using cue words like ''note carefully'' to focus and vary attention is a stimulus-variation (focusing) technique in microteaching; set induction opens a lesson and topic closure ends it (microteaching skills).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is NOT an advantage of practical as a teaching method;', 'It leads to creativity', 'It saves time', 'It provides immediate feedback', 'It caters for individual differences', 'B', 'Practicals foster creativity, give immediate feedback and cater for individual differences but are time-consuming; ''saves time'' is NOT an advantage (nurse-education teaching methods).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After every demonstration, a clinical instructor requests students to do a return demonstration. This is an example of;', 'Terminal evaluation', 'Formative evaluation', 'Diagnostic evaluation', 'Clinical evaluation', 'B', 'Return demonstration during ongoing teaching gives immediate feedback to improve learning, which is formative evaluation; terminal/summative occurs at the end (educational evaluation).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objectives that can be best achieved through role modeling are in;', 'Psychomotor domain', 'Cognitive domain', 'Affective domain', 'Comprehension domain', 'C', 'Role modeling shapes attitudes, values and professional behaviour, which are objectives of the affective domain; psychomotor is skills and cognitive is knowledge (Bloom''s taxonomy; nurse education).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A group whose members have specific common characteristics that you wish to investigate in your research study is:', 'Study group', 'Population', 'Sample', 'Control group', 'B', 'The entire group sharing the characteristics of interest that the researcher wishes to study is the population; a sample is a subset of it (Nursing research methods; NCK research syllabus).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'Research Methodology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Plagiarism occurs if a researcher:', 'Quotes the exact words of another author and gives a reference', 'Paraphrases a passage by another author', 'Uses an idea or material based directly on the work of another author but gives the reference', 'Summarizes a passage by another author and states the reference.', 'B', 'Plagiarism is using another''s work/ideas WITHOUT acknowledgement. Options A, C and D all give a reference, so are legitimate; paraphrasing without referencing (B) is plagiarism. Per NCK research ethics guidelines / Polit & Beck. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'Research Methodology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The sampling process involves:', 'Identify the sampling frame, determine sample size, select the sampling method', 'select the sampling method, determine sample size, identify the sampling frame', 'Identify the sampling frame, select the sampling method, determine sample size', 'select the sampling method, Identify the sampling frame, determine sample size', 'C', 'The logical sequence is to identify/define the sampling frame (population list), select the sampling method (technique), then determine the sample size. Per standard research methodology texts used in NCK Paper II. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted for alcohol detoxification develops increased tremors, irritability, hypertension and fever. The nurse should be alert for impending:', 'Delirium tremens', 'Korsakoff''s syndrome', 'Esophageal varices', 'Wernicke''s syndrome', 'A', 'Increasing tremors, irritability, hypertension and fever during alcohol withdrawal signal impending delirium tremens, a life-threatening emergency. Korsakoff''s/Wernicke''s are thiamine-deficiency states. Per Kozier & standard psychiatric nursing texts (NCK mental health).', 'BScN', 'Paper II', 'Mental Health Nursing', 'Substance Use Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client admitted with needle tracts on his arm, stuporous and with pin point pupil will likely be managed with:', 'Naltrexone', 'Naloxone', 'Disulfiram', 'Methadone', 'B', 'Needle tracks, stupor and pinpoint pupils indicate acute opioid overdose; naloxone is the immediate opioid antagonist/antidote. Naltrexone and methadone are for maintenance; disulfiram is for alcohol dependence. Per Kenya EML / emergency management protocols.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a factor to consider when selecting an instructional method.', 'Teacher''s skill', 'Examination regulations', 'Course title', 'Institution''s vision', 'A', 'Selection of an instructional method depends on factors including the teacher''s skill/competence (alongside learner, content and resources). Course title, exam regulations and institutional vision do not directly determine method choice. Per nursing education principles.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a level of affective domain in learning', 'Evaluation', 'Synthesis', 'Characterizing', 'Application', 'C', 'Characterizing (by a value/value complex) is the highest level of Krathwohl''s affective domain. Evaluation, synthesis and application belong to the cognitive (Bloom''s) domain. Per educational taxonomy used in NCK nursing education.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Elements of a curriculum include:', 'Curriculum review, exam regulation', 'Job description, mode of teaching', 'Mode of teaching, exam regulation', 'Mode of teaching, curriculum review', 'C', 'Curriculum elements include content delivery (mode of teaching) and assessment/examination regulations, alongside objectives and evaluation. Job description and curriculum review are not core curriculum components. Per curriculum development principles in nursing education. ⚠ More than one defensible answer Source: NCK Exam Practice Sets (Exam 1-2, Type 3-5)', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is included in Orem’s theory', 'Maintenance of a sufficient intake of air', 'Self-perception', 'Love and belonging', 'Physiologic needs', 'A', 'Orem''s Self-Care Deficit Theory lists universal self-care requisites including maintenance of sufficient intake of air, water and food. Love/belonging and physiologic needs belong to Maslow''s hierarchy (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('It is best to describe as a systematic, rational method of planning& providing nursing care for individuals, families, group and community.', 'assessment', 'nursing process', 'diagnosis', 'implementation', 'B', 'The nursing process is defined as a systematic, rational method of planning and providing individualized nursing care for individuals, families, groups and communities; assessment and diagnosis are only its phases (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A new mother tells you that she is afraid of her baby and that she doubts she will be able to love the baby. The most appropriate action would be to:', 'Tell the client she will learn fast.', 'Tell the client what a beautiful baby she has', 'Encourage the client to talk about her feelings.', 'Have a psychiatrist visit the client immediately', 'C', 'Therapeutic communication requires acknowledging and encouraging the mother to express her feelings, which supports bonding and allows assessment; false reassurance or an immediate psychiatric referral is inappropriate at this stage (Kozier & Erb''s Fundamentals; mental health nursing).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An anorexic client states that her stomach is "fat" and that all the food she is being forced to eat is making her obese. The nurse''s best reply is:', '"Your body is starting to work normally again and is getting stronger and healthier', '"You have a bloated stomach because there is too much salt in your food"', '"No, it''s not, you look much better now than when you were first admitted"', '"Maybe we have been feeding you too much and you''re gaining weight too fast"', 'A', 'Per therapeutic communication principles (Kozier & Erb''s Fundamentals), the nurse should give honest, reassuring, non-argumentative information; option A validates recovery without arguing or reinforcing distorted body image.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major factors associated with obesity include:-', 'Genetic, nutritional, level of activity.', 'Nutritional, level of activity, socio-cultural.', 'Nutritional, social, genetic.', 'Level of activity, genetic, psychological.', 'A', 'Per Brunner & Suddarth and nutrition texts, the major factors in obesity are genetic predisposition, dietary/nutritional intake and level of physical activity (energy balance). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An individual considered overweight has a basal metabolic rate (BMI) of:', '21-25', '25-29', '30-39', 'Above 40', 'B', 'Per WHO/MOH BMI classification, a BMI of 25.0-29.9 kg/m2 is defined as overweight; 30 and above is obese. (The stem''s ''BMI'' is body mass index, not BMR.)', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The STI that particularly increases transmission and acquisition of HIV include:', 'Gonorrhoea, chancroid', 'Candidiasis, gonorrhoea', 'Chancroid, Chlamydia', 'Syphilis, genital herpes', 'D', 'Per Kenya National STI/HIV guidelines, ulcerative STIs (syphilis, genital herpes, chancroid) most strongly increase HIV transmission and acquisition by breaching mucosal integrity; among the options, syphilis and genital herpes are the classic ulcerative pair. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'HIV and AIDS', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis that best describes a patient with psoriasis who has quit her job as a receptionist because she feels her appearance is disgusting to customers is:', 'Ineffective coping related to loss of skin integrity', 'Social isolation related to loss of skin integrity', 'Impaired skin integrity related to presence of lesions', 'Anxiety related to lack of knowledge of the disease process', 'B', 'Per Kozier & Erb''s nursing-diagnosis framework, quitting her job and withdrawing from customers because she feels her appearance is disgusting reflects Social isolation related to the altered skin/body image, rather than impaired coping or skin integrity as the priority problem here.', 'BScN', 'Paper II', 'Infection Prevention & Control', 'Infection Prevention', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman presents to a clinic 7 days after normal childbirth with a fever of 37.9 Degrees Celsius and an offensive vaginal discharge. According to the Emergency Obstetrics and Neonatal Care signal functions, where should the woman be managed?', 'Clinic', 'Health Centre', 'Hospital', 'Intensive Care Unit (ICU)', 'C', 'Per Kenya EmONC signal functions, a woman with puerperal sepsis (fever + offensive lochia) requires parenteral antibiotics and possible surgery, which are Comprehensive EmONC functions provided at hospital level. She does not yet require ICU.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following topics should be included in a health message on burn prevention?', 'Use a solar powered night light', 'Check smoke detectors annually', 'Do not use oven for cooking', 'Set water heater no longer than 48°C', 'B', 'Per Kenya community health / injury-prevention teaching, checking smoke detectors regularly is a valid burn/fire prevention measure. Setting water heaters no higher than about 48-49°C is also correct, but option D says ''no longer than 48°C'' (ambiguously worded); checking smoke detectors is the clearest correct prevention message. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client on the psychiatric unit is in an uncontrolled rage and is threatening other clients and staff. What is the most appropriate action for the nurse to take?', 'Call security for assistance and prepare to sedate the client.', 'Tell the client to calm down and ask him if he would like to play cards.', 'Tell the client that if he continues his behavior he will be punished.', 'Leave the client alone until he calms down. If the client is a threat to the staff and to other clients the nurse should call for help and', 'A', 'Per MOH mental health/psychiatric nursing guidelines, an out-of-control, violent client requires ensuring safety first—summon help/security and prepare chemical (or physical) restraint; the other options are unsafe or punitive and escalate risk.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted to the hospital with a temperature of 99.8°F, complaints of blood-tinged hemoptysis, fatigue, and night sweats. The client’s symptoms are consistent with a diagnosis of:', 'Pneumonia', 'Reaction to antiviral medication', 'Tuberculosis', 'Superinfection due to low CD4 count', 'C', 'Per Kenya National TB guidelines, low-grade fever, blood-tinged hemoptysis, fatigue and night sweats are the classic triad of pulmonary tuberculosis.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with dementia is experiencing confusion late in the afternoon and before bedtime. The nurse is aware that the client is experiencing what is known as:', 'Chronic fatigue syndrome', 'Normal aging', 'Sundowning', 'Delusions', 'C', 'Per Brunner & Suddarth''s/mental health nursing, sundowning is increased confusion and agitation in the late afternoon and evening seen in dementia.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a diagnosis of HPV is at risk for which of the following?', 'Hodgkin’s lymphoma', 'Cervical cancer', 'Multiple myeloma', 'Ovarian cancer', 'B', 'Per Kenya cervical cancer screening/national guidelines, human papillomavirus (HPV, esp. types 16/18) is the principal cause of cervical cancer.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client visiting a family planning clinic is suspected of having an STI. The best diagnostic test for treponema pallidum is:', 'Venereal Disease Research Lab (VDRL)', 'Rapid plasma reagin (RPR)', 'Fluorescent treponemal antibody (FTA)', 'Thayer-Martin culture (TMC)', 'C', 'Per STI diagnostic guidelines, FTA-ABS is a specific treponemal antibody test confirming Treponema pallidum; VDRL and RPR are non-specific screening (non-treponemal) tests and Thayer-Martin is for gonorrhoea.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a history of abusing barbiturates abruptly stops taking the medication. The nurse should give priority to assessing the client for:', 'Depression and suicidal ideation', 'Tachycardia and diarrhea', 'Muscle cramping and abdominal pain', 'Tachycardia and euphoric mood', 'A', 'Per psychiatric nursing texts, barbiturate withdrawal is dangerous (seizures) but the nurse gives priority to assessing for depression and suicidal ideation as a psychological withdrawal risk in NCK-style questioning. Euphoria and diarrhea are not typical barbiturate withdrawal features. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with mania is unable to finish her dinner. To help her maintain sufficient nourishment, the nurse should:', 'Serve high-calorie foods she can carry with her', 'Encourage her appetite by sending out for her favorite foods', 'Serve her small, attractively arranged portions', 'Allow her in the unit kitchen for extra food whenever she pleases', 'A', 'Per psychiatric nursing (Kozier), a client in mania is too hyperactive to sit and eat, so providing high-calorie finger foods she can carry while moving maintains nutrition. Sitting for small portions or waiting for favorite foods is impractical during mania.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is brought to the emergency room by the police. He is combative and yells, "I have to get out of here. They are trying to kill me." Which assessment is most likely correct in relation to this statement?', 'The client is experiencing an auditory hallucination.', 'The client is having a delusion of grandeur.', 'The client is experiencing paranoid delusions.', 'The client is intoxicated.', 'C', 'The fixed false belief that others are ''trying to kill me'' is a persecutory/paranoid delusion (Mental Health & Psychiatric Nursing). It is a thought-content disturbance, not an auditory hallucination or a grandiose delusion.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to suction the client with a tracheotomy. The nurse notes a previously used bottle of normal saline on the client''s bedside table. There is no label to indicate the date or time of initial use. The nurse should:', 'Lip the bottle and use a pack of sterile 4x4 for the dressing', 'Obtain a new bottle and label it with the date and time of first use', 'Ask the ward secretary when the solution was requested', 'Label the existing bottle with the current date and time', 'B', 'Per infection prevention principles (Kenya IPC guidelines; Kozier & Erb''s Fundamentals), an opened saline bottle of unknown age/sterility must be discarded; a new bottle should be obtained and labelled with date and time of first opening to track its 24-hour usable window.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client hospitalized with MRSA (methicillin-resistant staph aureus) is placed on contact precautions. Which statement is true regarding precautions for infections spread by contact?', 'The client should be placed in a room with negative pressure.', 'Infection requires close contact; therefore, the door may remain open.', 'Transmission is highly likely, so the client should wear a mask at all times.', 'Infection requires skin-to-skin contact and is prevented by hand washing, gloves, and a gown.', 'D', 'Per Kenya IPC guidelines, contact precautions (e.g., MRSA) rely on hand hygiene, gloves and gowns to prevent direct/indirect contact spread; negative-pressure rooms and masks are airborne precautions, not contact.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a histoplasmosis test for the elderly client. The nurse is aware that histoplasmosis is transmitted to humans by:', 'Cats', 'Dogs', 'Turtles', 'Birds', 'D', 'Per Brunner & Suddarth''s and communicable disease references, histoplasmosis is a fungal infection acquired by inhaling spores from soil contaminated with bird or bat droppings; among the options, birds are the source. Source: NCK Paper 1 & 2 Combined Practice Sets (Type 1-4) 114. "Above all, do no harm". This principle encompassed in the ethical dimension of: A. Human dignity B. justice C. beneficence D. anonymity Answer: C. beneficence Rationale: "Above all, do no harm" (primum non nocere) is the ethical principle of non-maleficence, which is the negative aspect of beneficence (doing good/avoiding harm). Among the offered options, beneficence is the ethical dimension that encompasses avoiding harm; justice and human dignity do not, and anonymity is a research-confidentiality concept. Per nursing ethics (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of alcohol withdrawal include:', 'euphoria, hyperactivity, and insomnia.', 'depression, suicidal ideation, and hypersomnia.', 'diaphoresis, nausea and vomiting, and tremors.', '. unsteady gait, nystagmus, and profound disorientation.', 'C', 'Alcohol withdrawal produces autonomic hyperactivity: diaphoresis, nausea/vomiting, tremors, tachycardia, and agitation. Unsteady gait/nystagmus reflect intoxication or Wernicke''s, not classic withdrawal. Per Kenya mental health/substance use nursing (psychiatric nursing texts).', 'BScN', 'Paper II', 'Mental Health Nursing', 'Substance Use Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mr. J. is a new client on the psychiatric unit. He is 35 years old. Theoretically, in which level of psychosocial development (according to Erikson) would you place Mr. J.?', 'Intimacy vs. isolation', 'Generativity vs. self-absorption', 'Trust vs. mistrust', 'Autonomy vs. shame and doubt', 'B', 'Erikson places middle adulthood (approximately 35–65 years) in the generativity vs. stagnation/self-absorption stage. Intimacy vs. isolation is young adulthood; the others are earlier childhood stages. Per developmental theory (Kozier & Erb''s Fundamentals of Nursing).', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of schizophrenia characterized by excessive negativism, bizzare body posture, echopraxia and echolalia:-', 'residual', 'paranoid', 'catatonic', 'disorganized', 'C', 'Catatonic schizophrenia is characterized by psychomotor disturbance: negativism, bizarre posturing, waxy flexibility, echopraxia, and echolalia. Paranoid features delusions/hallucinations; disorganized features incoherence and inappropriate affect. Per psychiatric nursing (DSM/ICD).', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common cause of under-5 mortality in developing world is', 'diarrheal disease', 'pneumonia', 'malaria', 'neonatal disease', 'B', 'Pneumonia is the leading single cause of under-5 mortality in the developing world (and globally beyond the neonatal period). Diarrhoea and malaria are major but rank below pneumonia. Per WHO/Kenya IMNCI child-health data. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Epidemiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the occupational health nurse employs ergonomic principles, she is performing which of her roles', 'Health care provider', 'Health educator', 'Health care coordinator', '.Environment manager', 'D', 'Applying ergonomic principles (fitting the workplace/task to the worker) is part of the occupational health nurse''s environment/hazard-management role. It is not direct care, education, or coordination. Per occupational health nursing (public health nursing texts). 132. “Public health services are given free of charge”. Is this statement true or false? A. The statement is true; it is the responsibility of government to provide haste services B. The statement is false; people pay indirectly for public health services C. The statement may be true or false; depending on the Specific service required D. The statement may be true or false; depending on policies of the government concerned. Answer: B. The statement is false; people pay indirectly for public health services Rationale: Public health services are not truly "free"; they are financed indirectly through taxes and other public revenue paid by the people. Thus the statement is false for this reason. Per health economics/health systems (public health nursing).', 'BScN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Level IV Hospital is classified as what level of facility?', 'Primary', 'Secondary', 'Intermediate', 'Tertiary', 'D', 'In the tiered classification used in these items, a Level IV/referral hospital is a tertiary-level facility providing specialized care. Primary and secondary correspond to lower levels. Per Kenya health systems/KEPH service delivery tiers. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Health Systems in Kenya', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to Freeman and Heinrich, community health nursing is a developmental service. Which of the following best illustrates this statement?', 'The community health nurse continuously develops himself personally and professionally', 'Health education and community organizing are necessary in providing community health services', 'Community health nursing is intended primarily for health promotion and prevention and treatment of disease.', '. The goal of community health nursing is to provide nursing services to people in their own place of .residence', 'B', 'As a "developmental" service, CHN builds people''s capacity through health education and community organizing so communities can address their own problems. Option D describes home-based care, and C describes scope, not the developmental nature. Per Freeman & Heinrich, community health nursing.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An indicator of success in community organizing is when people are able to:', 'Participate in community activities for the solution of a community problem', '. Implement activities for the solution of the community problem', '. Plan activities for the solution of the community problem', 'Identify the health problem as a common concern', 'A', 'Success in community organizing is shown when people actively participate in activities to solve their own community problem — the highest indicator of mobilization. Identifying or planning alone are earlier steps. Per community organizing principles (CHN syllabus). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Zinc deficiency is associated with increased risk for all the following EXCEPT', 'stunting', 'impaired immune function', 'increased risk for skin infections', 'increased risk for respiratory diseases', 'D', 'Zinc deficiency classically causes stunting, impaired immunity and increased skin infections and is strongly linked to diarrhoea; per Kenya nutrition/IMNCI guidance zinc is given in diarrhoea. Of the choices, increased respiratory disease is the least directly attributed effect, making it the EXCEPT answer. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is CONTRARY to the principles in planning a home visit?', '. A home visit should have a purpose of objective', '. The plan should revolve around the family health .needs', 'A home visit should be conducted in the manner prescribed by the Health unit', 'Planning of continuing care should involve a responsible-family member', 'C', 'Per Kenya Community Health Nursing principles, a home visit is individualised to the family''s health needs and situation, not rigidly conducted in a manner prescribed by the health unit; A, B and D are correct principles, so C is CONTRARY.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Primary health care is a total approach to community development. Which of the following is an indicator of success in the use of the primary health care approach?', 'Health services are provided free of charge to individuals and families', 'Local officials are empowered as the major decision makers in matters of health', '. Health workers are able too provide care based on identified health needs of the people', 'Health programs are sustained according to the level of development of the community', 'D', 'A key indicator of PHC success is sustainability of health programs matched to community self-reliance and development level; per Kenya PHC/Alma-Ata principles. Free services (A) and simply empowering officials (B) are not the defining success indicators, and (C) describes practice rather than sustained community-owned outcome. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Primary Health Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Knowing that malnutrition is a frequent community health problem, you decided to conduct nutritional assessment. What population is particularly susceptible to protein energy malnutrition (PEM)?', 'Pregnant women and the elderly', '. Under 5 year old children', '. 1-4 year old children', 'School age children', 'B', 'Children under 5 are the population most susceptible to protein-energy malnutrition due to rapid growth and weaning; per Kenya IMNCI and MOH nutrition guidelines. The 1-4 age band (C) is a subset, but under-5 is the standard at-risk group named in Kenyan nutrition assessment. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Nutrition', 'Nutrition', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Secondary prevention for malaria includes?', 'Planting of neem or eucalyptus trees', '. Residual spraying of insecticides at night', '. Determining whether a place is endemic or not', 'Growing larva-eating fish in mosquito breeding places', 'C', 'Secondary prevention targets early detection; determining endemicity/case finding to identify infection early fits secondary prevention; per Kenya National Malaria Guidelines/levels of prevention. Planting trees, residual spraying and larvivorous fish are vector-control (primary prevention) measures. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Malaria', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 4-year old client was brought to the health center with chief complaint of severe diarrhea and the passage of “rice water”. The client is most probably suffering from which condition?', 'Giardiasis', 'Cholera', 'Amebiasis', 'Dysentery', 'B', 'Profuse ''rice-water'' stool is the hallmark of cholera (Vibrio cholerae); per Kenya communicable disease/IMNCI guidelines. Giardiasis, amoebiasis and dysentery cause different stool patterns (fatty, bloody-mucoid).', 'BScN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One leadership theory states that “leaders are born and not made,” which refers to which of the following theories?', 'trait', 'charismatic', 'great man', 'situational', 'C', 'The ''leaders are born not made'' premise defines the Great Man theory; per nursing management/leadership theory. Trait theory describes qualities, charismatic describes magnetism, and situational ties style to context.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A theory states that the leadership style is effective dependent on the situation. Which of the following styles best fits a situation when the followers are self-directed, experts and are matured individuals?', 'Democratic', 'Authoritarian', 'Laissez faire', 'Bureaucratic', 'C', 'Situational/contingency theory holds that with self-directed, expert, mature followers a laissez-faire (hands-off) style is most effective; per nursing leadership theory. Democratic, authoritarian and bureaucratic styles impose more direction than mature experts require.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following does NOT characterize a transactional leader?', 'Focuses on management tasks', 'Is a caretaker', '. Uses trade-offs to meet goals', 'Inspires others with vision', 'D', 'Transactional leaders focus on management tasks, act as caretakers, and use trade-offs/rewards; inspiring with vision is a transformational (not transactional) trait; per nursing leadership theory. Thus ''inspires others with vision'' does NOT characterize a transactional leader.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Some managers have benevolent-authoritative style of management. Which of the following behaviors will they exhibit most likely?', 'Have condescending trust and confidence in their subordinates', '. Gives economic or ego awards', '. Communicates downward to the staff', 'Allows decision making among subordinates', 'A', 'Per Likert''s systems of management (nursing leadership theory, Kozier & Erb''s Fundamentals), System 2 benevolent-authoritative managers have condescending (paternalistic) trust and confidence in subordinates, motivating with occasional rewards while retaining control. Downward communication and reward-giving occur but the defining, most characteristic behaviour of this style is condescending trust. ⚠ More than one defensible answer 165. the main elements of educational objective are A. criterion, knowledge, skills B. act, attitude, goal C. knowledge, attitude, skills D. perfomance, condition, standard Answer: D. perfomance, condition, standard Rationale: Per curriculum/instructional design theory (Mager''s behavioural objectives, NCK teaching methodology), a well-written educational (behavioural) objective has three elements: performance (behaviour), condition, and standard (criterion). This is the standard framework taught in nurse-education pedagogy. 166. formative evaluation is useful in evaluation because it A. enable institutions to award grades, certification and licences B. reveal students ability to apply learning at the end of the course C. reveal the outcome of the learning at the end of the course D. provides feedback on the strengths of the learner during the course Answer: D. provides feedback on the strengths of the learner during the course Rationale: Per educational evaluation theory, formative evaluation is conducted DURING the learning process to provide ongoing feedback on learner strengths and weaknesses to improve learning. Grading/certification and end-of-course outcome assessment describe summative evaluation. 167. set induction can be done through A. questioning and recapping the main points B. stating the objectives and stimulus variation C. self introduction and stating the objectives D. previewing previous topics and use of gestures Answer: C. self introduction and stating the objectives Rationale: Per microteaching skills in nurse-education methodology, set induction (introducing a lesson) is achieved through self-introduction, gaining attention, stating objectives and linking to prior knowledge. Recapping main points is closure, not set induction. ⚠ More than one defensible answer 168. child neglect involves A. physical aggression directed at a child B. indecent exposure of the genital of a child C. inappropriate and excessive demands on a child D. inadequate provision of various needs of a child Answer: D. inadequate provision of various needs of a child Rationale: Per child protection principles (Kenya Children Act; MOH/WHO child abuse classification), neglect is the failure/inadequate provision of a child''s basic needs (food, shelter, health, education, supervision). Physical aggression is physical abuse and indecent genital exposure is sexual abuse.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 32 year old client came for consultation at the health center with the chief complaint of fever for a week. Accompanying symptoms were muscle pains and body malaise. A week after the start of fever, the client noted yellowish discoloration of his sclera. History showed that he waded in flood waters about 2 weeks before the onset of symptoms. Based on this history/ which disease condition will you suspect?', 'Hepatitis A', 'Hepatitis B', 'Tetanus', 'Leptospirosis', 'D', 'Per communicable disease control, the history of wading in flood water followed by fever, myalgia, malaise and jaundice (Weil''s disease) is classic for leptospirosis, a spirochaete transmitted through water contaminated with rodent urine. Hepatitis A/B and tetanus do not have this flood-water exposure link.', 'BScN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the most effective way of controlling schistosomiasis in an endemic area?', 'Use of molluscicides', 'Building of foot bridges', 'Proper use of sanitary toilets', 'Use of protective footwear, such as rubber boots', 'C', 'Per communicable disease control (WHO/Kenya), schistosomiasis transmission is interrupted mainly by preventing contamination of water with human excreta — i.e. proper sanitary excreta disposal (safe toilets) — which breaks the life cycle at its source. Molluscicides and footwear are adjuncts but sanitation is the most effective control. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Epidemiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which condition is the most frequent cause of death associated by schistosomiasis?', 'liver cancer', 'liver cirrhosis', 'bladder cancer', 'intestinal perforation', 'B', 'Per communicable disease pathology, intestinal/hepatic schistosomiasis (S. mansoni) leads to periportal (pipe-stem) fibrosis and liver cirrhosis with portal hypertension and fatal variceal haemorrhage — the most frequent cause of death. Bladder cancer relates to S. haematobium but cirrhosis/portal hypertension is the classic fatal outcome. ⚠ More than one defensible answer 172. under what level of measurement is marital status classified A. nominal B. ordinal C. interval D. ratio Answer: A. nominal Rationale: Per research and biostatistics, marital status (single, married, divorced, widowed) is a categorical variable with no inherent order or numeric value, hence measured on the nominal scale. Ordinal implies ranking, interval/ratio imply numeric measurement.', 'BScN', 'Paper II', 'Community Health Nursing', 'Communicable Diseases', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The vector that carries the causative organism for yellow fever is:-', 'Fleas', 'Flavivirus', 'Black flies', 'Tsetse flies Answer: None of the options — yellow fever vector is the Aedes mosquito (flawed item) Rationale: Yellow fever is transmitted by the Aedes mosquito (Aedes aegypti). None of the listed options is correct — fleas, black flies and tsetse flies transmit other diseases, and flavivirus is the causative virus, not a vector. The question is flawed as set; the correct vector (Aedes mosquito) is not among the choices. ⚠ Best answer not clearly among choices 174. Notifiable diseases in Kenya include: A. Plague, measles, poliomyelitis, Tuberculosis B. Anthrax, pneumonia, rabies, cholera C. Poliomyelitis, chicken pox, tuberculosis, measles D. Plague, poliomyelitis, brucellosis, diphtheria', 'A', 'Per Kenya''s list of notifiable diseases (Public Health Act / MOH), plague, measles, poliomyelitis and tuberculosis are all notifiable. Options with pneumonia or chicken pox include non-notifiable conditions.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Food rich in iron include:-', 'Liver, blood and fresh fruits', 'Flesh of animals, fresh fruits', 'Liver, birds and fresh fruits', 'Flesh of animals, birds and fish', 'A', 'Per Kenya nutrition guidelines, liver and blood are among the richest sources of haem iron; fruits (vitamin C) enhance iron absorption. This option best captures iron-rich foods. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Nutrition', 'Nutrition', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The multiplier is 1000 and the denominator is live births in the same year. 184. Some principles of time management include:-', 'Priority setting, evaluating progress, minimal breaks', 'Time analysis, goal setting, delegation', 'Avoiding delegation, Time analysis, controlling interruptions', 'Time analysis, goal setting, minimal breaks', 'B', 'Per nursing management/leadership principles, effective time management includes time analysis, goal/priority setting and delegation. Options advocating ''avoiding delegation'' or ''minimal breaks'' are contrary to sound time management.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The benefits of school health to a child are:-', 'Immunization protection from peer pressure, counseling', 'Immunization, growth monitoring, emotional care', 'Health promotion, counseling, maternal support', 'Treatment of opportunistic infections, follow up care, protection from peer pressure', 'B', 'Per Kenya school health guidelines, benefits to the child include immunization, growth/health monitoring and emotional/psychosocial care. Option B lists genuine child-centred school health benefits. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The four rights of delegation of duty in management are:-', 'Task, communication, time, feedback', 'Person, task, time, feedback', 'Task, time, person, communication', 'Task, person, communication, feedback', 'D', 'The classic ''rights of delegation'' in nursing management are the right task, right person (circumstance), right communication/direction and right feedback/evaluation. Option D lists these four rights.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 45-year-old man with paranoid schizophrenia is detained under the Mental Health Act. Which of the following is not directly relevant to criteria for detention under the mental health act:-', 'The patient has paranoid schizophrenia', 'The patient has threatened to assault his neighbour', 'The patient has harmed himself in the past when he was unwell', 'The patient refuses to take a depot injection', 'D', 'Per Mental Health Act detention criteria, detention requires a mental disorder plus risk to self or others. Diagnosis (A), risk to others (B) and past self-harm (C) are relevant; merely refusing a depot injection is not itself a criterion for detention.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 5-year-old girl is accompanied to the clinic by her mother. The clinical notes state that she has a mild intellectual disability. Which of the following IQ ranges is consistent with a diagnosis of a mild intellectual disability', '90-99', '70-89', '50-69', '35-49', 'C', 'Per ICD-10/DSM classification of intellectual disability (used in Kenyan mental health training), mild intellectual disability corresponds to an IQ range of approximately 50-69. Moderate is 35-49; borderline is 70-89.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 25-year-old woman who is struggling in her job because of her drinking habits tells herself that the problem is her difficult boss. She denies that her drinking has increased in frequency and severity and also blames the commute to work for her problems. What type of defense mechanism:-', 'Splitting', 'Projection', 'Rationalisation', 'Regres sion', 'C', 'Per psychiatric nursing texts, rationalisation is offering false but plausible reasons (blaming the boss/commute) to justify behaviour and avoid the real issue (her drinking). Projection would attribute her own feelings to others without this self-justifying reasoning.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 23-year-old man is arrested for exposing his erect penis to two women in a public place. Although he has not done this before, he admits he has had urges to do so over the past few years, which he finds distressing. How best is this behaviour classified', 'Voyeurism', 'Sadomasochism', 'Frotteurism', 'Exhibitionism', 'D', 'Per ICD/psychiatric classification, exposing one''s genitals to unsuspecting strangers for sexual gratification is exhibitionism. Voyeurism is watching others, frotteurism is rubbing against non-consenting persons. 196. 35-year-old businessman enjoys dressing up in his wife’s clothes. He says he does so to experience what it feels like to be a woman and it does not cause him sexual arousal. He has no desire to be a woman. What is the correct term to describe his behaviour:- A. Transsexualism B. Dual-role transvestism C. Fetishism D. Fetishistic transvestism Answer: B. Dual-role transvestism Rationale: Per ICD classification, wearing clothes of the opposite sex to experience temporary membership of that sex WITHOUT sexual arousal and with no desire for permanent sex change is dual-role transvestism. Fetishistic transvestism involves sexual arousal; transsexualism involves a desire to change sex.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 35-year-old married man is referred to the emergency department for an assessment of his depressive illness. Which of the following would indicate that a hospital admission would be required:-', 'Insomnia', 'Anhedonia', 'Worthlessness', 'Distressing auditory hallucinations', 'D', 'Per Kenya Mental Health guidelines and Kaplan & Sadock''s psychiatry, insomnia, anhedonia and worthlessness are common depressive symptoms managed as outpatient; the presence of distressing auditory hallucinations indicates psychotic depression with risk to self/others, warranting inpatient admission.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 75-year-old man presents with prominent neurological signs such as apraxia, gait abnormalities and mild cognitive impairment. He is MOST likely to suffer from:-', 'Alzheimer’s Disease', 'Dementia', 'Delirium', 'Parkinsonism', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, the triad of apraxia, gait abnormalities and mild cognitive impairment in an elderly man points to a parkinsonian/subcortical process; Alzheimer''s presents primarily with progressive memory loss and delirium is acute and fluctuating. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A major difference between normal and maladaptive grieving has been identified by which of the following:', 'There are no feelings of depression in normal grieving', 'There is no loss of self-esteem in normal grieving.', 'Normal grieving lasts no longer than 1 year', 'In normal grief, the person does not show anger toward the loss', 'B', 'Per Kozier & Erb''s Fundamentals of Nursing, a distinguishing feature of normal grief versus maladaptive grief/depression is preserved self-esteem; normal grieving includes depression, anger and can exceed one year, so those options are false.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following psychiatric disorders is MOST common among patients with bulimia nervosa:-', 'Alcohol use disorder', 'Major depressive disorder', 'Obsessive compulsive disorder', '.Panic disorder', 'B', 'Per Kaplan & Sadock''s psychiatry, major depressive disorder is the most common comorbid psychiatric disorder among patients with bulimia nervosa.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse on the psychiatric unit has the understanding that which of the following would describe a client with “la belle indifference”:-', 'A client with somatization disorder who is demanding narcotics', 'A client with depersonalization disorder who believes he has died', 'A client with DID who is threatening suicide', 'A client with conversion disorder showing lack of concern for an altered body function', 'D', 'Per psychiatric nursing texts, ''la belle indifference'' is the characteristic lack of concern about a serious loss of function seen in conversion disorder.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All the following are parasomniac disorders EXCEPT', 'narcolepsy', 'sleepwalking', 'sleep terro', 'nightmares', 'A', 'Per sleep disorder classification (mental health), parasomnias include sleepwalking, sleep terrors, and nightmares. Narcolepsy is a dyssomnia (disorder of excessive sleepiness), not a parasomnia, so it is the EXCEPTION.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A parents came to your clinic complaining that their 5-year-old boy had attacks of frightening with imagination of a snake crawling over him and he is acting as trying to remove it. You assessed the child and find no acute physical illness and he is cooperative and quite intelligent.Of the following, the MOST appropriate explanation for the child behavior is', 'acute phobic hallucination', 'early sign of schizophrenia', 'delusional infestation', 'night terror E.bipolar disorder night terror E.bipolar disorder v', 'D', 'A well, intelligent, cooperative 5-year-old with episodic frightening imagery and motor activity, no acute illness and no psychosis, fits a night terror/parasomnia rather than psychosis. Per Kaplan & Sadock and standard paediatric psychiatry, phobic hallucination, schizophrenia and delusional infestation are inappropriate for a healthy pre-schooler; the option (though garbled) endorses night terror. ⚠ Question may be INCOMPLETE', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In assessing the seriousness of adolescent drug abuse score, which of the following take +2 in the score?', 'female sex', 'age>15 years', 'positive family history of drug abuse', 'use before driving', 'D', 'In adolescent drug-abuse severity scoring, using a substance before driving is a high-risk behaviour scoring +2 because of the immediate danger to self and others (adolescent medicine screening tools). Sex, age and family history are lower-weighted risk items. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Mental Health Nursing', 'Substance Use Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lewin’s change theory is being applied as the community is addressing improvements in public safety. Which of the following would be one of the first steps in creating change?', 'Determining whether anyone else agrees.', 'Having a careful plan as to what change is desirable', 'Making community members aware of the need for changed.', 'Assessing community needs to determine whether change is possible', 'C', 'Per Lewin''s change theory as applied in community health nursing, the first stage is ''unfreezing'' — creating awareness of the need for change; assessment and planning follow once the need is recognised. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most effective way of prioritizing nursing diagnoses?', 'Ensuring that the diagnoses are reimbursable by third-party payers', 'Determining the degree of community concern about the problem', 'Comparing the diagnoses with the agency’s mission statement', 'Discussing conclusions with another community health nurse', 'B', 'Per community health nursing practice, prioritising nursing diagnoses is most effectively done by gauging the community''s own perception/concern about the problem, which drives participation and effective intervention.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is planning to present an educational program. Which of the following is important for the nurse to remember?', 'Having many handouts so that the audience can remember what was said', 'Ordering a microphone so that everyone in the room can hear easily', 'Using pictures and posters of professionals demonstrating the needed behaviors', 'Using many different methods of presentation with multimedia art', 'D', 'Per health education principles (Kenya community health), using varied multimedia teaching methods accommodates different learning styles and improves retention, making it the key consideration when planning an educational program. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term “tabula rasa” highlights the importance of in shaping behaviour.', 'genes', 'experience', 'nature', 'predestination', 'B', 'Per behavioural science, Locke''s ''tabula rasa'' (blank slate) doctrine holds that the mind at birth is empty and behaviour is shaped by experience/environment, emphasising nurture over genes and predestination.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which stage of development is most unstable and challenging regarding the development of personal identity?', 'Adolescence', 'Toddlerhood', 'Childhood', 'Infancy', 'A', 'Per Erikson''s developmental theory, adolescence (identity vs role confusion) is the most unstable and challenging stage for the development of personal identity.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Andragogy refers to:', 'Adult learning', 'Action Learning', 'Experiential learning', 'Child learning', 'A', 'Andragogy (Knowles) is the theory and method of adult learning, contrasted with pedagogy (child learning); this is standard in NCK nurse-educator curriculum.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive domain in Bloom’s Taxonomy includes all the following, except', 'Evaluation', 'Synthesis', 'Analysis', 'Criticism', 'D', 'Bloom''s cognitive domain levels are knowledge, comprehension, application, analysis, synthesis and evaluation; ''Criticism'' is not a level, making it the exception.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of educational assessment which is generally carried out throughout a course or project is', 'Summative assessment', 'Formative assessment', 'Criterion-referenced assessment', 'Ipsative assessment', 'B', 'Formative assessment is conducted throughout a course to monitor learning and give feedback, whereas summative assessment occurs at the end; standard educational assessment principle.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of Problem Based Learning include all, EXCEPT:', 'Learning is driven by challenging, open-ended, ill-defined and ill-structured problems.', 'Students generally work in collaborative groups.', 'The teacher is the authority', 'Teachers take on the role as "facilitators" of learning', 'C', 'In Problem-Based Learning the teacher is a facilitator, not the authority; learning is driven by ill-structured problems and collaborative group work, so ''the teacher is the authority'' is the exception.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of discussion where a group of 6-8 qualified experts discuss a topic in front of an audience is called:', 'Group discussion', 'Symposium', 'Panel discussion', 'Workshop', 'B', 'A symposium is a series of short talks by several qualified experts on a topic before an audience; a panel discussion involves interactive debate among a smaller panel. Standard teaching-methods classification. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of family in which more than one monogamous couple share resources is referred to as?', 'Dyad', 'Compound', 'Commune', 'Blended', 'C', 'A commune is a family form in which more than one monogamous couple share resources and responsibilities communally; a dyad is a couple only, blended combines previous families'' children. Standard family sociology (family nursing).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a specific function of the school health services?', 'Determine the health status of each child.', 'Conduct a special screening programme which will disclose particular health problems.', 'Understanding the difference in the stages of growth and development.', 'Assist in maintaining the health of school personnel', 'C', 'Specific functions of school health services include determining each child''s health status, screening for problems and maintaining staff health; ''understanding the stages of growth and development'' is background knowledge, not a specific service function, so it is the exception.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The health-belief model is composed of one of the following factors:', 'Psychological factors', 'Modifying factors', 'Social factors', 'Environmental factors', 'B', 'The Health Belief Model comprises individual perceptions, modifying factors (demographic, socio-psychological cues) and likelihood of action; ''modifying factors'' is a recognised component of the model.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following channels of disease transmission is indirect transmission?', 'Droplet infection', 'Transplacental', 'Unclean hands and fingers', 'Bite of animal', 'B', 'Transplacental (vertical) transmission is a form of indirect transmission via the vehicle of the placenta; droplet infection, unclean hands/fingers and animal bite are direct/close-contact routes. Communicable disease epidemiology. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The capability of an infectious agent to invade, survive and multiply in the host is?', 'Toxigenicity', 'Invasiveness', 'pathogenicity', 'infectivity', 'D', 'Infectivity is the capability of an agent to invade, survive and multiply in a host; pathogenicity is the ability to cause disease and invasiveness the ability to spread in tissues. Epidemiology definitions. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major components comprising the community core are?', 'History, values ,beliefs', 'Demography, education system, economic system', 'Values, political system, education system', 'Demography, political system, education system', 'A', 'In the community-as-partner (Anderson & McFarlane) model the community core comprises history, demographics, values, beliefs and religion of the people; ''history, values, beliefs'' best represents core elements, while demography, education, economic and political systems are subsystems. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sustainable development 1 is about poverty. What is the aim of this goal?', 'Cut poverty in half by 2030', 'Reduce poverty by 75% by 2030', 'End poverty in all its forms everywhere', 'Help each nation make progress on reducing poverty', 'C', 'SDG 1 aim is ''End poverty in all its forms everywhere'' by 2030; halving or reducing by a percentage were older MDG-style targets (UN Sustainable Development Goals).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a health promotion activity;', 'Rehabilitation', 'Environmental sanitation', 'Prompt treatment', 'Provision of adequate housing', 'B', 'Environmental sanitation is a health promotion activity that improves living conditions to prevent disease; rehabilitation and prompt treatment are tertiary/secondary care. Provision of housing is closer to specific protection, so environmental sanitation is the best health promotion example (health promotion/prevention levels). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Primary Health Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the principles of primary health care, accessibility considers the following except', 'Elements of integrated services.', 'People''s awareness.', 'Transport and road network', 'Social status of community members.', 'D', 'In PHC principles, accessibility concerns physical/geographic reach (transport, road network), awareness of services and integration of services; social status relates to acceptability/equity, not accessibility, so it is the exception.', 'BScN', 'Paper II', 'Community Health Nursing', 'Primary Health Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The policy of open vaccine states that:', 'Discard all open vaccines at the end of the session', 'Discard polio, BCG, PCV10 at the end of the session', 'Discard all open vaccines with evidence of contamination', 'Discard measles, yellow fever and BCG after four hours.', 'A', 'Per KEPI, the open (multi-dose) vial policy distinguishes vaccines: reconstituted vaccines (BCG, measles, yellow fever) are discarded within 6 hours or end of session, while liquid multi-dose vaccines may be reused; the open-vaccine session rule is that all opened vaccines are discarded at the end of the immunization session (safest single statement here). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following concepts would enable the nurse to provide holistic care for culturally diverse clients', 'Cultural conflicts', 'Ethnocentrism', 'Stereotyping', 'Cultural brokering', 'D', 'Cultural brokering (bridging/mediating between the client''s culture and the health system) supports holistic, culturally competent care; cultural conflict, ethnocentrism and stereotyping are barriers to it (transcultural nursing, Kozier Fundamentals).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Max Weber is known for the development of which management theory?', 'Bureaucratic management', 'Scientific management', 'Humanistic management', 'Transformational leadership', 'A', 'Max Weber is credited with the bureaucratic theory of management (hierarchy, rules, division of labour); scientific management is Taylor''s, per nursing management/leadership texts.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A low-income elderly woman is being screened for blood cholesterol level by a community nutritionist at a community health center. What level of prevention is the nutritionist using?', 'Primary', 'Secondary', 'Tertiary', 'Quartenary', 'B', 'Screening to detect disease early in an asymptomatic person (cholesterol screening) is secondary prevention (early detection); primary prevents onset, tertiary limits disability (Leavell & Clark levels of prevention).', 'BScN', 'Paper II', 'Nutrition', 'Nutrition', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A community can also be defined on the basis of a common interest or goal. A nutritionist was asked to identify and design a program for common- interest communities. All of these are examples of common-interest communities except:', 'homebound elderly persons', 'teenage mothers', 'co-workers', 'members of churches', 'C', 'Common-interest communities share a common goal/interest (homebound elderly, teenage mothers, church members). Co-workers form a community of place/organisation rather than a common-interest group, so they are the exception. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Nutrition', 'Nutrition', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Anthropometric measurements include:', 'skinfold measures', 'waist circumference', 'capillary fragility', 'a and b', 'D', 'Anthropometric measurements assess body size/composition: skinfold thickness and waist circumference are both anthropometric, whereas capillary fragility is a clinical/biophysical test, so ''a and b'' is correct.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An interpersonal conflict in which no participant is aware of the divergence of goals, needs, or interests is known as', 'Latent conflict', 'Manifest conflict', 'Cause of action', 'Overt conflict', 'A', 'Latent conflict is the stage where the conditions/divergence of goals exist but the parties are not yet aware of it; manifest/overt conflict is when it becomes openly recognised (conflict management theory in nursing leadership). 276. which public health Act is responsible for securing and maintaining health A. Cap 242 B. Cap 257 C. Cap 280 D. Cap 302 Answer: A. Cap 242 Rationale: In Kenya the Public Health Act is Chapter 242 (Cap 242) of the Laws of Kenya — the principal statute for securing and maintaining public health. (Kenya Public Health Act, Cap 242.) ⚠ Best answer not clearly among choices 277. which of the following is the advantage of integration of services A. save time and money for the nurse B. improves immunization coverage C. patients are integrated in the approach D. there is high chance of cross infection between sick and health especially children Answer: A. save time and money for the nurse Rationale: Integration of services allows a client to receive several services in one visit, saving time and resources for both client and provider and reducing missed opportunities; cross-infection risk is a disadvantage, not an advantage.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A situation where someone gains sexual gratification by rubbing his genitalia against a non-consenting female is', 'Transvestism', 'Fetishism', 'Masochism', 'Frotteorism', 'D', 'Frotteurism is the paraphilia of gaining sexual gratification by rubbing one''s genitals against a non-consenting person; distinct from fetishism (objects) or masochism (self-pain). Per DSM-5 as used in Kenyan mental health nursing texts. 285. fat soluble vitamins includes A. A,D,C,E B. A,D,E,K, C. E,D,C,K D. A,B,C,D Answer: B. A,D,E,K, Rationale: The fat-soluble vitamins are A, D, E and K (mnemonic ADEK); C and B are water-soluble. Per Kozier & Erb''s Fundamentals / nutrition texts used in Kenyan training.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A business firm must employ an occupational health nurse when it has at least how many employees.', '21', '101', '201', '301', 'B', 'Under Kenya''s Occupational Safety and Health Act (OSHA 2007), a workplace with 100+ employees must engage an occupational health nurse, i.e. at least', 'BScN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Per Kenyan OSH regulations / community health nursing. ⚠ More than one defensible answer 287. The number of cases of Dengue fever usually increases towards the end of the rainy season. This pattern of occurrence of Dengue fever is best described as;', 'Epidemic occurrence', 'Cyclical variation', 'Sporadic occurrence', 'Secular occurrence', 'B', 'A regular, predictable rise in cases tied to a recurring season (end of rains) is a seasonal/cyclical variation, not an unpredictable epidemic or long-term secular trend. Per epidemiology (Park''s / Kenya CDC control principles).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Among the following diseases, which is airborne?', 'Viral conjunctivitis', 'Acute poliomyelitis', 'Diphtheria', 'Measles', 'D', 'Measles is transmitted by airborne respiratory droplets/aerosols; polio is faeco-oral, conjunctivitis is contact, diphtheria is droplet (not true airborne). Per Kenya IMNCI / communicable disease control.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Objectives of the health services include each of the following except:', 'Delivery of curative care only', 'Health promotion', 'Prevention control, or eradication of disease', 'Treatment and rehabilitation', 'A', 'Health service objectives include promotion, prevention, treatment and rehabilitation; ''curative care only'' is the exception because it excludes the other functions. Per Kenya health systems / community health.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The community health nurse should not make surprise supervisory visits because:', 'The village health nurse may be on leave', 'The village health nurse may not be prepared for visit', 'The aim of supervisory visit is to train the subordinates', 'The village health nurse may be on home visits', 'C', 'Supportive supervision is developmental/training-oriented and should be planned, not a ''surprise'' fault-finding exercise; hence surprise visits are avoided. Per Kenya community health nursing management principles. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An absolute contraindication for pediatric immunization includes;', 'Anaphylactic reaction to previous immunization', 'Respiratory illness with low grade lever', 'Soreness, redness and itching at the previous injection site', 'A febrile seizure one month after the previous injection of vaccines', 'A', 'Anaphylaxis to a prior dose is an absolute contraindication to further immunization; minor illness, injection-site soreness and a delayed febrile seizure are not. Per Kenya KEPI guidelines.', 'BScN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bitot’s spot’ is the characteristic feature of............. deficiency', 'Calcium', 'Vitamin D', 'Vitamin A', 'Vitamin C', 'C', 'Bitot''s spots (foamy conjunctival patches) are a classic sign of vitamin A deficiency/xerophthalmia. Per Kenya nutrition / IMNCI guidelines.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An abiotic environment that can affect health of the community is:-', 'Infective organisms', 'Insects', 'Vegetation', 'Chemicals', 'D', 'Abiotic (non-living) environmental factors include chemicals, air, water and physical agents; infective organisms, insects and vegetation are biotic. Per Kenya environmental/public health nursing.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Increasing the ability of the population to cope with a disaster is known as:', 'Preparedness', 'Triaging', 'Mobilization', 'Mitigation', 'D', 'Mitigation is action to reduce impact and increase a population''s ability to cope with a disaster; preparedness is planning/readiness beforehand. Per Kenya disaster management / community health. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Disaster Management', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are some of the activities done to ensure the needs of a school child are met.', 'Screening and physical examination.', 'Counseling and provision of food.', 'Evaluating the process and results of the programs.', 'Promoting positive health behavior among staff and students.', 'A', 'A core school-health service activity to meet the child''s needs is screening and physical examination for early detection of health problems. Per Kenya School Health Policy / community health nursing. ⚠ Question may be INCOMPLETE ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('KEPI refrigerator should be defrosted when the thickness of ice is:-', '0-3 millimeters.', '4-5 millimeters.', '11-13 millimeters.', '6-10 millimeters.', 'D', 'KEPI cold-chain guidance is to defrost the vaccine refrigerator when ice build-up reaches about 6-10 mm (roughly 0.5-1 cm) thickness to maintain efficient cooling. Per Kenya KEPI cold chain guidelines. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a source to develop conceptual framework:-', 'Researcher’s own experience', 'Previous research findings', 'Historical facts', 'Concepts of theories', 'C', 'Conceptual frameworks are developed from the researcher''s own experience, previous research findings and concepts/theories; isolated historical facts are not a recognised source for building a conceptual framework (research methodology texts).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Survey research is cross-sectional and therefore: -', 'High in reliability but low in internal validity', 'High in internal validity but low in reliability', 'High in ecological validity but low in external validity', 'Low in reliability and low in internal validity', 'C', 'Cross-sectional surveys capture behaviour in natural settings (high ecological validity) but a single-time snapshot limits generalisability over time (external validity) and cannot establish internal/causal validity (research design texts). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'Research Methodology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Consider this title: ‘The Live Experience of Surviving a Tsunami’. This title would indicate which of the following types of qualitative research: -', 'Ethnographic', 'Phenomenological', 'Action', 'Historical', 'B', '''The Lived Experience of...'' signals phenomenology, which studies the lived experience/meaning of a phenomenon; ethnography studies cultures and historical research studies past events (qualitative research texts).', 'BScN', 'Paper II', 'Research & Evidence-Based Practice', 'Research Methodology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When conducting a literature review, it is advisable to: -', 'Seek most of the information from internet', 'Gather literature from books', 'Gather literature from journals', 'Seek assistance from a librarian', 'D', 'Best practice is to seek assistance from a librarian to search databases systematically and access peer-reviewed sources; relying on only one source type (internet, books, or journals) is inadequate (research methodology texts). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 20-year-old university student attends the clinic reporting a 1-year history of daily use of legal highs. She has recently experienced some mild paranoia on withdrawal from the use of mephedrone. Which class of drugs does mephedrone most closely resemble in its effect on users:-', 'Amphetamines', 'Heroin/opioids', 'Cannabinoids', 'D. Hallucinogens', 'A', 'Mephedrone is a synthetic cathinone stimulant whose effects (euphoria, alertness, paranoia on withdrawal) closely resemble amphetamines, not opioids, cannabinoids or hallucinogens (pharmacology/psychiatry texts).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Anticholinergic side effects include all of the following EXCEPT:-', 'Bradycardia', 'Constipation', 'Dry mouth', 'Exacerbation of open-angle glaucoma', 'A', 'Anticholinergic effects include tachycardia (not bradycardia), dry mouth, constipation, urinary retention and worsening of glaucoma; blockade of muscarinic receptors increases heart rate (pharmacology texts). 335. 22-year-old man started on a typical antipsychotic finds it difficult to sit still and has to move his legs constantly. How is this phenomenon best defined:- A. Tardive dyskinesia B. Akinesia C. Akathisia D. Neuroleptic malignant syndrome Answer: C. Akathisia Rationale: Akathisia is the subjective inner restlessness with an inability to sit still and constant leg movement, an early extrapyramidal effect of antipsychotics; tardive dyskinesia is late involuntary movements and akinesia is absence of movement (psychiatry texts).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Disorder of motor activity in which the person constantly maintains a position without any movement', 'Mannerism', 'Cataplexy', 'Verbigeration', 'Negativis m', 'D', 'Maintaining a fixed posture without movement is a catatonic feature; among the options negativism (motiveless resistance/immobility maintaining a position) best fits, whereas cataplexy is sudden loss of muscle tone and verbigeration is repetitive speech (psychopathology texts). ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Psychosis is characterized by all, except:', 'Contact with reality is maintained', 'Positive symptoms are usually present', 'Impaired judgment', 'Insight is lost.', 'A', 'Psychosis is defined by LOSS of contact with reality, positive symptoms, impaired judgment and lost insight; therefore ''contact with reality is maintained'' is the exception (psychiatry texts).', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The patient has sensory, motor or neurological symptoms that don’t follow a recognizable parttern or organic dysfunction:-', 'Hypochondria-sis', 'Obssessive compulsive disorder', 'Borderline personality', 'Anxiety disorder', 'A', 'Sensory/motor/neurological symptoms not following a recognisable organic pattern reflect somatic-symptom-spectrum disorders; among the options hypochondriasis (health preoccupation) best fits, as OCD, borderline personality and anxiety disorder are not defined by unexplained neurological deficits. (Conversion disorder would be ideal but is not listed.) ⚠ Best answer not clearly among choices ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 34-year-old man is involved in a minor road accident. He has a small bruise on his neck but no pain or dysfunction. He tells his wife he is hoping to get a payout from his insurance company. He tells his GP he has severe back pain and PTSD and is referred to you for assessment. What is the correct term to describe his behaviour:-', 'Factitious disorder (Munchausen’s syndrome)', 'Malingering', 'Conversion disorder', 'Somatoform disorder', 'B', 'Deliberate fabrication/exaggeration of symptoms (severe back pain, PTSD) for an external incentive (insurance payout) is malingering; factitious disorder is driven by the sick role without external gain, and conversion/somatoform are unconscious (psychiatry texts).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The priority psychiatric nursing intervention in the management of an aggressive and violent patient on admission would be: -', 'Engage him in a discussion, call for reinforcement to restrain him and administer intravenous fluids', 'Engage him in a discussion, call for reinforcement to restrain him and administer tranquilizers', 'Counsel the patient to calm down, call for reinforcement and administer tranquilizers', 'Counsel the patient to calm down, call for reinforcement and administer intravenous fluids', 'C', 'Per Kenya MOH mental health nursing standards, de-escalation (verbal calming) is attempted first, with reinforcement summoned and rapid tranquillisation (e.g. haloperidol/diazepam) given to control violence; IV fluids are irrelevant to acute aggression, ruling out options A and D. Tranquillisers, not IV fluids, are the pharmacologic priority. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During psychiatric interview patient retains a constellation of ideas long after they have ceased to be appropriate. E.g. “where do you live?”, “London”, “How old are you”, “London. The term used to explain the condition is:-', 'Perseveration', 'Mannerisms', 'Ambivalence', 'D. Echopraxia', 'A', 'Persistent, inappropriate repetition of the same response (answering ''London'' to unrelated questions) is perseveration (psychiatric mental status examination). Mannerisms, ambivalence and echopraxia (imitating movements) describe different phenomena.', 'BScN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bedside performance of a student nurse can be ideally assessed by?', 'Checklist.', 'Rating scale.', 'Peer review.', 'Anecdotes .', 'A', 'Bedside/procedural (psychomotor) performance is best assessed objectively using a checklist that lists the required observable steps. Rating scales judge quality but a checklist ideally verifies safe procedural performance. Nursing education/assessment principles.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which aim of education allows the students to develop themselves into distinct individual personality', 'Individual', 'Social', 'Vocational', 'Moral', 'A', 'The individual aim of education seeks development of the learner''s distinct/unique personality, as opposed to social, vocational or moral aims. Educational philosophy (nursing education).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Role-play helps to assess which domain of learning', 'Cognitive', 'Affective', 'Psychomotor', 'All of these', 'B', 'Role-play elicits attitudes, values and feelings, so it best assesses the affective domain of learning. Bloom''s taxonomy / nursing education methods.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Educational objectives should be all except', 'Attainable', 'Realistic', 'Motivational', 'Measurabl e', 'C', 'Good educational objectives should be attainable, realistic and measurable (SMART); ''motivational'' is not a defining criterion, making it the exception. Nursing education / instructional design.', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Educational objectives according to Bloom''s taxonomy are classified into how many basic domains', 'Two', 'Three', 'Four', 'Five', 'B', 'Bloom''s taxonomy classifies objectives into three domains: cognitive, affective and psychomotor. Educational theory.', 'BScN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The character of feeling for others in their position is called', 'Empathy', 'Sympathy', 'Warmth', 'Reassurance', 'A', 'Empathy is understanding and feeling with others from their perspective/position, distinguished from sympathy (feeling for them). Therapeutic communication (Kozier & Erb''s).', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The educational assessment that is generally carried out throughout a course or project is known as', 'Criterion-referenced assessment', 'Continuous assessment', 'Formative assessment', 'Summative assessment', 'C', 'Formative assessment is conducted throughout a course/project to monitor progress and guide learning, whereas summative assessment is terminal. Educational assessment theory. ⚠ More than one defensible answer', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All experiences of pupil that are undertaken in the guidance of the school is', 'Course plan', 'Unit plan', 'Curriculum', 'Learning experiences', 'C', 'Curriculum encompasses all experiences of the pupil undertaken under the guidance of the school. Curriculum development theory (nursing education). KRCHN', 'BScN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In barium swallow studies:', 'Patients should not be NPO', 'High fiber diet is encouraged a day to study', 'Good for studying condition of ascending colon', 'Good for diagnosing achalasia', 'D', 'Barium swallow (esophagography) visualises the esophagus and is the classic study for achalasia, showing the dilated esophagus with distal ''bird-beak'' narrowing (Brunner & Suddarth''s Med-Surg). Patients are kept NPO before the study, so ''not NPO'' is wrong, and it studies the upper GI tract, not the ascending colon.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is the correct order of abdominal assessment:', 'Inspection, percussion, auscultation, palpation.', 'Inspection, auscultation, percussion, palpation.', 'Inspection, palpation, percussion, auscultation.', 'Inspection, auscultation, palpation, percussion.', 'B', 'Abdominal assessment follows inspection, auscultation, percussion, then palpation; auscultation precedes percussion/palpation so bowel sounds are not altered by manipulation (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following gastrointestinal disorder is managed best by downscaling gluten containing meals:', 'Irritable bowel syndrome', 'Diverticulum', 'Celiac disease', 'Esophageal varices.', 'C', 'Celiac disease is an immune reaction to gluten and is managed by a lifelong gluten-free diet (Brunner & Suddarth''s Med-Surg). IBS, diverticulum and esophageal varices are not gluten-driven.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing intervention should be a priority in one of the following patients:', 'Patient with appendicitis with pain rating of 10/10.', 'Patient with appendicitis with sudden relief of pain.', 'Patient with peptic ulcers who need omeprazole', 'Patient with jaundice that need evaluation of liver function', 'B', 'Sudden relief of pain in appendicitis suggests perforation/rupture, a surgical emergency requiring priority intervention (Brunner & Suddarth''s Med-Surg). Severe steady pain, routine omeprazole, and elective liver-function evaluation are lower priority than a possible rupture.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The scientific study of the aging process is referred to as:', 'Ageism', 'Geriatrics', 'Gerontic', 'Gerontology', 'D', 'Gerontology is the scientific study of the aging process and older adults; geriatrics is the clinical/medical care of the elderly, and ageism is prejudice against them (Brunner & Suddarth''s Med-Surg, gerontologic nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Drug dosages must be reduced in the elderly because:', 'Cardiac output is significantly reduced', 'The mucosal cells in the gastrointestinal tract are reduced', 'Drug biotransformation takes longer in an older person', 'There is a high likelihood of manifestation of toxic effects of drugs', 'D', 'Age-related decline in hepatic metabolism and renal clearance leads to drug accumulation and a high likelihood of toxicity, so doses are reduced (Brunner & Suddarth''s Med-Surg; Kenya EML pharmacology principles). This is the overarching reason encompassing slower biotransformation.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing measures to deal with sensory changes in the aged include', 'Increasing lighting in the room', 'Speaking in low tones', 'Providing single and adequate calories', 'Suggesting appetite stimulants before meals', 'A', 'Aging causes visual decline; increasing (glare-free) lighting compensates for sensory changes and improves safety (Brunner & Suddarth''s Med-Surg, gerontologic nursing). Speaking in low tones worsens presbycusis; the other options address nutrition, not sensory changes.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bone changes associated with aging frequently result from loss of:', 'Calcium', 'Magnesium', 'Vitamin A', 'Vitamin C', 'A', 'Age-related bone changes (osteoporosis/osteopenia) result from loss of bone calcium and mass (Brunner & Suddarth''s Med-Surg). Magnesium and vitamins A/C are not the primary lost element in aging bone.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All of the following statements concerning genitourinary system changes in the older adult are true except:', 'The glomerular filtration rate decreases', 'Acid-base balance is restored more slowly', 'Bladder capacity increases with advanced age', 'Urinary frequency, urgency, and incontinence are common.', 'C', 'This is the ''except'' (false) statement: with aging, bladder capacity DECREASES, contributing to frequency, urgency and incontinence, while GFR falls and acid-base correction is slower (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is true about loss of muscle mass in the elderly:', 'It also known as osteopenia', 'It is solely caused by disused', 'Exercise has no impact on the process', 'It is referred to as sarcopenia.', 'D', 'Age-related loss of muscle mass and strength is termed sarcopenia; osteopenia refers to low bone mass, and exercise/resistance training does slow the process (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An example of exocrine glands are the:', 'Adrenals.', 'Ovaries.', 'Parathyroids.', 'Sweat glands.', 'D', 'Exocrine glands secrete through ducts onto a surface; sweat glands are exocrine. Adrenals, ovaries and parathyroids are endocrine (ductless, secrete hormones into blood) (Anatomy & Physiology / Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the anterior pituitary gland is responsible for secreting all of the following except the:', 'Adrenocorticotropic hormone (ACTH).', 'Antidiuretic hormone (ADH).', 'Follicle-stimulating hormone (FSH).', 'Thyroid-stimulating hormone (TSH).', 'B', 'This is the ''except'': ADH (and oxytocin) are secreted by the posterior pituitary. The anterior pituitary secretes ACTH, FSH and TSH (Anatomy & Physiology / Brunner & Suddarth).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Diabetes insipidus is a disorder related to a deficiency of:', 'Growth hormone.', 'Prolactin.', 'Oxytocin.', 'Vasopressin.', 'D', 'Diabetes insipidus results from deficiency of antidiuretic hormone (vasopressin), causing polyuria and polydipsia (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When thyroid hormone is administered for prolonged hypothyroidism, the nurse knows to monitor the patient for:', 'Angina.', 'Depression.', 'Mental confusion.', 'Hypoglycemia.', 'A', 'Thyroid hormone replacement increases myocardial oxygen demand; in prolonged hypothyroidism, especially with underlying CAD, it can precipitate angina, so the nurse monitors for it (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The preferred medication for treating hypothyroidism is:', 'Lithium.', 'Proprandol.', 'Propylthiouracil.', 'Synthroid.', 'D', 'Synthroid (levothyroxine/T4) is the drug of choice for hypothyroidism replacement (Brunner & Suddarth''s Med-Surg; Kenya EML). Propylthiouracil and propranolol treat hyperthyroidism, and lithium is unrelated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A clinical manifestation not usually associated with hyperthyroidism is:', 'A pulse rate slower than 90 bpm.', 'An elevated systolic blood pressure.', 'Muscular fatigability.', 'Weight loss.', 'A', 'Hyperthyroidism produces tachycardia, elevated systolic BP, weight loss and fatigability; a pulse slower than 90 bpm is NOT associated (it would suggest hypothyroidism) (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patients with hyperthyroidism are characteristically:', 'Apathetic and anorexic.', 'Calm.', 'Emotionally stable.', 'Sensitive to heat.', 'D', 'Hyperthyroid patients have increased metabolism causing heat intolerance, nervousness and irritability; they are not calm, apathetic or emotionally stable (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Iodine or iodide compounds are used for hyperthyroidism because they do all of the following except:', 'Decrease the basal metabolic rate.', 'Increase the vascularity of the gland.', 'Lessen the release of thyroid hormones.', 'Reduce the size of the gland.', 'B', 'This is the ''except'': iodine/iodide compounds DECREASE the size and vascularity of the thyroid gland and reduce hormone release and BMR, which is why they are given preoperatively (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The objectives of pharmacotherapy for hyperthyroidism include:', 'Destroying overreactive thyroid cells.', 'Preventing thyroid hormonal synthesis.', 'Increasing the amount of thyroid tissue.', 'All of the above.', 'B', 'The objective of antithyroid pharmacotherapy (e.g., propylthiouracil, methimazole) is to inhibit thyroid hormone synthesis (Brunner & Suddarth''s Med-Surg). Destroying cells is radioiodine (not pharmacotherapy proper), and increasing thyroid tissue is opposite to the goal, so ''all of the above'' is wrong.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Signs of thyroid storm include all of the following except:', 'Bradycardia.', 'Delirium or somnolence.', 'Dyspnea and chest pain.', 'Hyperpyrexia.', 'A', 'This is the ''except'': thyroid storm causes tachycardia, hyperpyrexia, delirium/somnolence and cardiorespiratory distress; bradycardia is not a feature (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Medical management for thyroid crisis includes:', 'Intravenous dextrose fluids.', 'Hypothermia measures.', 'Oxygen therapy.', 'All of the above.', 'D', 'Management of thyroid crisis includes IV dextrose/fluids for hypermetabolic demand, hypothermia (cooling) measures for hyperpyrexia, and oxygen therapy for increased metabolic demand (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pharmacotherapy for thyroid storm would not include the administration of:', 'Acetaminophen.', 'Iodine.', 'Propylthiouracil.', 'Synthetic levothyroxine.', 'D', 'Thyroid storm is treated with PTU, iodine and acetaminophen (for fever); administering synthetic levothyroxine (more thyroid hormone) would worsen the crisis and is therefore not included (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common type of goiter is etiologically related to a deficiency of:', 'Thyrotropin.', 'Iodine.', 'Thyroxine.', 'Calcitonin.', 'B', 'Simple (endemic) goiter, the most common type, is caused by iodine deficiency (Brunner & Suddarth''s Med-Surg; addressed in Kenya via salt iodization). This is the basis of nutritional iodine supplementation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse knows that the most common and least aggressive type of cancer is:', 'Anaplastic.', 'Follicular adenocarcinoma.', 'Medullary.', 'Papillary adenocarcinoma.', 'D', 'Papillary adenocarcinoma is the most common and least aggressive (best-prognosis) thyroid cancer; anaplastic is the most aggressive (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diagnosis of hyperparathyroidism can be established by all of the following signs except:', 'A negative reading on a Sulkowitch test.', 'A serum calcium level of 12 mg/dL.', 'An elevated level of parathyroid hormone.', 'Bone demineralization seen on an x-ray film.', 'A', 'This is the ''except'': hyperparathyroidism causes hypercalcemia, so the Sulkowitch (urine calcium) test would be POSITIVE, not negative; elevated serum calcium, elevated PTH and bone demineralization all support the diagnosis (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A recommended breakfast for a hyperparathyroid patient would be:', 'Cereal with milk and bananas.', 'Fried eggs and bacon.', 'Orange juice and toast.', 'Pork sausage and cranberry juice', 'B', 'Hyperparathyroidism causes hypercalcemia, so a low-calcium breakfast is preferred; eggs and bacon avoid the high calcium of milk/cereal (Brunner & Suddarth''s Med-Surg nutrition guidance). Cereal with milk is high in calcium and thus inappropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the most important and frequently occurring complications of hyperparathyroidism is:', 'Kidney stones.', 'Pancreatitis.', 'Pathologic fractures.', 'Peptic ulcer.', 'A', 'Chronic hypercalcemia and hypercalciuria in hyperparathyroidism commonly cause renal calculi (nephrolithiasis) (Brunner & Suddarth''s Med-Surg). Pathologic fractures occur but renal stones are the most frequent complication.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathophysiology of hypoparathyroidism is associated with all of the following except:', 'A decrease in serum calcium.', 'An elevation of blood phosphate.', 'An increase in the renal excretion of phosphate.', 'A lowered renal excretion of calcium.', 'C', 'This is the ''except'': in hypoparathyroidism low PTH DECREASES renal phosphate excretion, causing hyperphosphatemia along with hypocalcemia and reduced renal calcium excretion (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The goal of medical management for hypoparathyroidism is to:', 'Achieve a serum calcium level of 9 to 10 mg/dL.', 'Eliminate clinical symptoms.', 'Reverse the symptoms of hypocalcemia.', 'Accomplish all of the above.', 'D', 'Medical management of hypoparathyroidism aims to restore serum calcium to 9–10 mg/dL, reverse hypocalcemia and eliminate clinical symptoms (Brunner & Suddarth''s Med-Surg), so all listed goals apply.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing management for a hypoparathyroid patient would not include:', 'Maintaining a quiet, subdued environment.', 'Making certain that calcium gluconate is kept at the bedside.', 'Observing the patient for signs of tetany.', 'Supplementing the diet with milk and milk products.', 'D', 'This is the ''would not include'': milk products are high in phosphorus, which is already elevated in hypoparathyroidism, so a high-calcium/low-phosphorus diet is advised, not milk supplementation. Seizure precautions, bedside calcium gluconate and tetany monitoring are appropriate (Brunner & Suddarth''s Med-Surg).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pheochromocytoma is an adrenal medulla tumor that causes arterial hypertension by increasing the level of circulating:', 'Catecholamines.', 'Enzymes.', 'Hormones.', 'Glucocorticoids.', 'A', 'Pheochromocytoma is an adrenal medulla tumor that secretes excess catecholamines (epinephrine and norepinephrine), causing paroxysmal or sustained hypertension (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A positive test for overactivity of the adrenal medulla is an epinephrine value of:', '50 pg/mL.', '100 pg/mL.', '100 to 300 pg/mL.', '450 pg/mL.', 'D', 'Normal plasma epinephrine is under ~100 pg/mL; values above ~400 pg/mL indicate adrenal medulla overactivity (pheochromocytoma). 450 pg/mL is clearly elevated and positive (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings suggestive of Addison''s disease include all of the following except:', 'A relative lymphocytosis.', 'Hyperkalemia and hyponatremia.', 'Hypertension.', 'Hypoglycemia.', 'C', 'Addison''s disease (adrenal insufficiency) causes HYPOtension, not hypertension, due to aldosterone/cortisol deficiency. Expected findings are hyperkalemia, hyponatremia, hypoglycemia and relative lymphocytosis; hypertension is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A positive diagnosis of Cushing''s syndrome is associated with:', 'The disappearance of lymphoid tissue.', 'A reduction in circulating eosinophils.', 'An elevated cortisol levels.', 'All of the above.', 'D', 'Cushing''s syndrome (excess cortisol) produces elevated cortisol levels, involution/disappearance of lymphoid tissue, and eosinopenia (reduced circulating eosinophils); all listed features apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical manifestations of Cushing''s syndrome may be modified with a diet that is:', 'High in protein.', 'Low in carbohydrates.', 'Low in sodium.', 'All of the above.', 'D', 'Cushing''s manifestations are eased by a diet high in protein (counter catabolism), low in carbohydrates (counter hyperglycemia) and low in sodium (counter fluid retention/hypertension); all three apply (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with aldosteronism would be expected to exhibit all of the following symptoms except:', 'Alkalosis.', 'Hypokalemia.', 'Hyponatremia.', 'An increased pH.', 'C', 'Primary aldosteronism (excess aldosterone) causes sodium retention (HYPERnatremia), potassium loss (hypokalemia), and metabolic alkalosis with raised pH. Hyponatremia is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse needs to be aware that large-dose corticosteroid therapy is most effective when administered:', 'At 8:00 AM.', 'At 8:00 PM.', 'Between 4:00 AM and 5:00 AM.', 'Between 4:00 PM and 6:00 PM.', 'A', 'Corticosteroids are best given in the early morning (around 8:00 AM) to mimic the body''s natural diurnal cortisol peak and minimise HPA-axis suppression (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML principles).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing assessment for a patient who is receiving corticosteroid therapy includes observation for the unacceptable side effect of:', 'Glaucoma.', 'Facial mooning.', 'Potassium loss.', 'Weight gain', 'A', 'Facial mooning, potassium loss and weight gain are expected/anticipated corticosteroid effects; glaucoma (raised intraocular pressure with possible vision loss) is a serious, unacceptable adverse effect requiring monitoring (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Traumatic injury of the following section of spine causes acute respiratory failure:', 'L1-L2', 'L3-L4', 'C5-C6', 'C7-C8', 'C', 'The phrenic nerve (diaphragm) arises from C3-C5; high cervical injury at C5-C6 impairs diaphragmatic/respiratory function causing acute respiratory failure, whereas lumbar (L1-L4) injuries spare respiration (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following true about stomas:', 'Healthy stomas are grey, bleed on touch, sensation on touch', 'Colostomy bag should be emptied when full.', 'Healthy stomas are pink, bleed on touch, has sensation on touch.', 'It is yellow, bleeds on touch, there is no sensation on touch.', 'C', 'A healthy stoma is pink/red and moist, and slightly bleeds on touch because it is vascular. Note the stoma mucosa itself has no pain sensation; option C is the closest/best correct description among the choices (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Barium swallow is used in diagnosis of the following:', 'Jejunal atresia', 'Stomach Cardia', 'Upper GIT', 'Rectal and Sigmoid tumors', 'C', 'A barium swallow outlines the upper gastrointestinal tract (pharynx, esophagus, stomach). Lower/rectosigmoid lesions require a barium enema, not a swallow (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Non atopic asthma is best described as:', 'Start in adulthood.', 'Associated with allergies.', 'Patient with eczema is likely not to have it.', 'Also known as intrinsic asthma.', 'D', 'Non-atopic asthma is not associated with allergy/IgE and is termed intrinsic asthma; it typically starts in adulthood but the defining description is intrinsic (non-allergic) asthma (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of bone marrow results in:', 'Pernicious anemia.', 'Aplastic anemia with fever.', 'Aplastic anemia without fever.', 'Iron deficiency anemia.', 'B', 'Bone marrow failure causes aplastic anemia; because all cell lines fail (including neutrophils), leukopenia predisposes to infection and fever, distinguishing it from the febrile-free option (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hyperplasia of gingiva is likely to be indicator of:', 'Ludwig angina', 'Vincent angina', 'Heart failure', 'Phenytoin therapy', 'D', 'Gingival hyperplasia is a classic adverse effect of phenytoin (anticonvulsant) therapy (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The bacteria known to cause dental caries is:', 'Streptococcus aureas', 'Streptococcus mutans', 'Group A beta hemolytic streptococcus', 'Sedenomonous aeruginosa', 'B', 'Streptococcus mutans is the principal bacterium responsible for dental caries through acid production from fermentable carbohydrates (Brunner & Suddarth''s Medical-Surgical Nursing; standard microbiology).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Contralateral shift of trachea in patient with chest complains is likely to be due to:', 'Pneumonia', 'Emphysema', 'Flail chest', 'Tension pneumothorax', 'D', 'Tension pneumothorax builds intrapleural pressure that pushes mediastinal structures and the trachea to the opposite (contralateral) side; it is a life-threatening emergency (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Biot''s respirations are associated with:', 'Lesions on Pons.', 'Diabetic ketoacidosis.', 'Asthmatic attack.', 'Pneumonia.', 'A', 'Biot''s (ataxic) respirations, an irregular pattern of breaths with apnea, are associated with damage to the pons/medulla (Brunner & Suddarth''s Medical-Surgical Nursing). Kussmaul breathing, not Biot''s, is seen in diabetic ketoacidosis. 50. ______is the deadliest form of gangrene: A. Wet gangrene B. Dry gangrene C. Gas gangrene D. Meleney''s gangrene Answer: C. Gas gangrene Rationale: Gas gangrene (clostridial myonecrosis, usually Clostridium perfringens) is the deadliest, most rapidly fatal form of gangrene due to toxin production and systemic toxicity (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is unique to secondary venous thrombosis?', 'It''s usually without involvement of deep veins', 'Its varicose veins: resulting from obstruction of deep veins.', 'Its a reflux of venous blood in the veins', 'It''s usually managed by wearing static stockings.', 'B', 'Secondary varicose/venous disease is distinguished by an identifiable cause such as deep vein obstruction (e.g., prior DVT), unlike primary disease; this is the feature unique to secondary venous thrombosis among the options (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is associated with thoracic aortic aneurysm only:', 'Marfan syndrome', 'Hypertension', 'Atherosclerosis', 'Smoking', 'A', 'Marfan syndrome (connective-tissue defect) is specifically linked to thoracic aortic aneurysm/dissection, whereas hypertension, atherosclerosis and smoking are shared risk factors for abdominal aneurysms too (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A burn obtained as a result of a lightning strike is:', 'Heat burn', 'Thermal burn', 'Radiation burn', 'Electrical burn', 'D', 'A lightning strike delivers a high-voltage electrical current, producing an electrical burn (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In nursing assessment subjective data is data that the:', 'Patient can report on their own', 'Nurse can assess on their own', 'Nurse and doctor can confirm', 'Patient can report and the nurse can confirm', 'A', 'Subjective data is information reported by the patient (symptoms, feelings) that cannot be directly observed, whereas objective data is measurable/observable by the nurse (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Damage to the mitral valve may lead:', 'Pulmonary hypertension', 'Left- sided heart failure', 'Myocardial infarction', 'Left ventricular hypertrophy', 'A', 'Mitral valve damage (stenosis/regurgitation) raises left atrial pressure that backs up into the pulmonary circulation, causing pulmonary hypertension (and later right heart strain) (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves a segment of the leg being used to provide an alternative pathway for blood flow past a point of obstruction between the aorta and coronary artery:', 'Angioplasty', 'Coronary angiography', 'Heart transplant', 'Coronary bypass', 'D', 'Coronary artery bypass graft (CABG) uses a vessel such as the saphenous vein from the leg to bypass an obstruction and restore blood flow to the coronary artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following procedures involves using a small plastic balloon to open a narrowed artery:', 'Heart transplant', 'Coronary bypass', 'Angioplasty', 'Coronary angiography', 'C', 'Percutaneous transluminal (balloon) angioplasty uses a small inflatable balloon to open a narrowed artery (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common symptom of myocardial infarction is:', 'Palpitations', 'Edema', 'Dyspnea', 'Chest pain', 'D', 'Chest pain (crushing, substernal, possibly radiating) is the most common presenting symptom of myocardial infarction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Dyspnea, fatigue, increased pulmonary artery pressure and decreased cardiac output are indicative of:', 'Right valve failure', 'Paracentisis', 'Myocardial infarction', 'Left sided heart failure', 'D', 'Dyspnea, fatigue, raised pulmonary artery pressure and reduced cardiac output reflect left-sided heart failure, where the failing left ventricle causes pulmonary congestion and low output (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for administration of morphine in a patient with myocardial infarction is to relieve:', 'Edema', 'Palpitations', 'Chest pain', 'Dyspnea', 'C', 'In myocardial infarction, morphine is given primarily to relieve severe ischemic chest pain (and also reduces anxiety and cardiac workload/preload) (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which diagnostic test provides information about the physiology and function of the heart?', 'Electrocardiogram', 'Chest X-ray', 'Echocardiogram', 'Angiogram', 'A', 'The electrocardiogram (ECG) records the heart''s electrical activity, giving information about cardiac physiology and function (rate, rhythm, conduction, ischemia), whereas echocardiogram shows structure/mechanics and X-ray shows size (Brunner & Suddarth''s Medical-Surgical Nursing). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following conditions results in coronary artery disease:', 'Renal failure', 'Diabetes mellitus', 'Myocardial infarction', 'Atherosclerosis', 'D', 'Atherosclerosis (plaque buildup narrowing coronary arteries) is the underlying pathological process that directly results in coronary artery disease (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Nursing diagnoses mostly differ from medical diagnoses in that they are:', 'Primarily concerned with human response, while medical diagnoses are primarily concerned with pathology', 'Dependent upon medical diagnoses for the direction of appropriate interventions', 'Primarily concerned with caring, while medical diagnoses are primarily concerned with curing', 'Primarily concerned with psychosocial parameters, while medical diagnoses are primarily concerned with physiologic parameters.', 'A', 'A nursing diagnosis addresses the patient''s human responses to actual/potential health problems, whereas a medical diagnosis identifies the disease/pathology (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the management of myocardial infarction, atherectomy is:', 'Removal of atherosclerotic plaque', 'Use of new implants', 'Ballooning of narrowed artery', 'Putting a stent to prevent collapse of artery)', 'A', 'Atherectomy is a catheter-based procedure that cuts away/removes atherosclerotic plaque from the coronary artery wall, distinct from angioplasty (ballooning) or stenting (Brunner & Suddarth''s Medical-Surgical Nursing, cardiovascular interventions).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis for a patient with angina pectoris is infective tissue perfusion. The plan of care includes the patient outcome criterion of:', 'Experiencing no dyspnea on exertion', 'Reduce ischemia by increasing O2 to tissues', 'Agreeing to discontinue smoking', 'Ambulating 50 feet without experiencing dyspnea', 'D', 'An outcome criterion must be patient-centred, measurable and observable. ''Ambulating 50 feet without dyspnea'' is a specific, measurable patient outcome; the others are goals/interventions rather than measurable outcome criteria (Kozier & Erb''s Fundamentals of Nursing, nursing process).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which diagnostic test will be used to test for claudication in peripheral artery disease?', 'Doppler ultrasound', 'Treadmill', 'Arteriogram', 'Ankle brachial index', 'D', 'The ankle-brachial index (ABI) is the primary, first-line diagnostic test for peripheral artery disease/claudication, quantifying arterial insufficiency of the lower limbs (Brunner & Suddarth''s, peripheral vascular assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following cardiovascular condition is more prevalent among females than males:', 'Hypertension', 'Varicose veins', 'Coronary artery disease', 'Myocardial infarction', 'B', 'Varicose veins are more prevalent in females (pregnancy, hormonal influence), whereas coronary artery disease and myocardial infarction are more common in males (Brunner & Suddarth''s, venous disorders).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which action occurs primarily during the evaluation phase of the nursing process:', 'Decision making and judgment', 'Data collection', 'Reassessment and audit', 'Priority setting and expected outcomes.', 'C', 'The evaluation phase of the nursing process involves reassessing the patient and auditing whether outcomes were met. Data collection is assessment; priority setting/expected outcomes are planning; decision making is diagnosis (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive skills, key in implementation of nursing process, refers to:', 'A blend of intellectual and ''hand'' on skills', '''Hands on'' skills such as manipulating equipment', 'Problem solving, decision making, critical thinking and curative thinking', 'All activities, verbal and nonverbal, that people use when communicating directly with one another', 'C', 'Cognitive (intellectual) skills in the nursing process refer to problem solving, decision making and critical thinking. Option B describes psychomotor skills and D describes interpersonal skills (Kozier & Erb''s Fundamentals of Nursing, implementation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hematocrit of 60% is likely to be an indicator of:', 'Leukemia', 'Idiopathic Thrombocytopenia.', 'Non-Hodgkin Lymphoma', 'Polycythemia vera', 'D', 'A markedly elevated hematocrit (60%) indicates an increased red cell mass, characteristic of polycythemia vera. Leukemia, ITP and lymphoma do not raise the hematocrit (Brunner & Suddarth''s, hematologic disorders).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with Forced Expiratory Volume (FEV1) of 60% is likely to be suffering from:', 'Pleural effusion.', 'Trauma.', 'Emphysema.', 'Asthma.', 'C', 'A reduced FEV1 (60%) with airflow obstruction is characteristic of COPD/emphysema, an obstructive lung disease. Pleural effusion is restrictive; emphysema best fits chronic obstruction (Brunner & Suddarth''s, respiratory function tests). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Vitamin B12 anemia is characterized by:', 'Microcytosis of RBC', 'Normal hematocrit', 'Hypochromic RBC', 'Macrocytosis of RBC', 'D', 'Vitamin B12 deficiency causes megaloblastic (macrocytic) anemia characterized by large red cells (macrocytosis) with high MCV, not microcytosis or hypochromia (Brunner & Suddarth''s, anemias).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One following oxygen delivery system has constant FiO2:', 'Nasal Prongs', 'Venturi Mask', 'Non-rebreather mask', 'Partial rebreather mask', 'B', 'The Venturi mask is a high-flow device that delivers a precise, constant FiO2 regardless of the patient''s breathing pattern; nasal prongs and rebreather masks deliver variable FiO2 (Brunner & Suddarth''s, oxygen therapy).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Patient manifesting with "hot potato voice" is likely to be suffering from:', 'Vincent angina', 'Periodontitis', 'Asthma', 'Ludwig Angina', 'D', 'A muffled ''hot potato voice'' results from the pharyngeal/submandibular swelling of Ludwig''s angina (and severe peritonsillar/deep neck infection); it is not a feature of asthma or periodontitis (Brunner & Suddarth''s, upper airway infections).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing action needed for claustrophobic patient before MRI is:', 'Explain the procedure to the patient.', 'Assume patient''s concerns', 'Give paralytic drugs to the patient.', 'Tell the patient to man up.', 'A', 'For a claustrophobic patient facing MRI, the nurse should first explain the procedure to reduce anxiety and gain cooperation; assuming concerns or dismissive/inappropriate responses are non-therapeutic (Kozier & Erb''s Fundamentals of Nursing, therapeutic communication).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best imaging study for patient with basilar artery aneurysm is:', 'Magnetic resonance imaging', 'X-Ray', 'Coronary angiography', 'Radioisotope imaging', 'A', 'MRI (with MR angiography) is the preferred non-invasive imaging for cerebral/basilar artery aneurysms; plain X-ray and coronary angiography are unsuitable for intracranial vessels (Brunner & Suddarth''s, neurologic diagnostics).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mild intermittent asthma is best managed by:', 'Long-acting beta-adrenergic agonist (LABA)', 'Short acting beta-adrenergic agonist (SABA)', 'Long-acting muscarinic antagonist (LAMA)', 'Inhaled corticosteroids (ICS)', 'B', 'Mild intermittent asthma is managed with a short-acting beta-agonist (SABA) as reliever therapy; ICS and LABA/LAMA are for persistent asthma (GINA/WHO guidance as adopted in Kenya, Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('X-ray film of a patient shows expanded airways. This likely to be indicative of:', 'Emphysema', 'Bronchiectasis', 'Tension pneumothorax', 'Diffused pneumonia', 'A', 'Emphysema causes hyperinflation with expanded/enlarged airspaces and flattened diaphragm on chest X-ray; tension pneumothorax shows lung collapse, not expanded airways (Brunner & Suddarth''s, COPD).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Hemoptysis is defined as:', 'Blood in sputum cough.', 'Blood in GIT', 'Bad breath', 'Dry cough', 'A', 'Hemoptysis is the coughing up of blood or blood-stained sputum from the respiratory tract; blood in the GIT is hematemesis/melena (Brunner & Suddarth''s, respiratory assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following will reduce pulse of pressure of an individual:', 'Reduced osmolality', 'Dehydration', 'Highly hydration status', 'Low temperatures', 'B', 'Pulse pressure is stroke volume dependent; dehydration/hypovolemia reduces stroke volume and thus narrows the pulse pressure. Overhydration would widen it (Guyton physiology; Brunner & Suddarth''s, fluid balance).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following parts of central nervous system control vegetative function:', 'Spinal cord', 'Cerebral cortex', 'Brain stem', 'Medulla oblongata', 'D', 'The medulla oblongata houses the vital autonomic (vegetative) centres controlling cardiac, respiratory and vasomotor function; it is the most specific answer among the options (standard neuroanatomy/physiology). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Collection of cell bodies in the central nervous system forms:', 'White matter', 'Grey matter', 'Commissures', 'Ganglion', 'B', 'Per standard neuroanatomy (Kozier & Erb''s / Brunner & Suddarth), collections of neuronal cell bodies within the CNS form grey matter, whereas myelinated axons form white matter and a cluster of cell bodies OUTSIDE the CNS is a ganglion.', 'KRCHN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gonadal arteries branch from:', 'Internal iliac artery', 'External iliac artery', 'Abdominal aorta', 'Subclavian artery', 'C', 'Per standard anatomy (Gray''s/anatomy texts used in Kenyan training), the gonadal (testicular/ovarian) arteries arise directly from the abdominal aorta below the renal arteries, not from the iliac or subclavian vessels.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lesion of cranial nerve VII causes one of the following:', 'Ebbs palsy', 'Inability to raise neck', 'Bell''s Palsy', 'Anosmia', 'C', 'Per standard neuroanatomy (Brunner & Suddarth), the facial nerve (CN VII) supplies the muscles of facial expression; its lesion causes Bell''s palsy (unilateral facial droop). Anosmia is CN I; CN VII does not affect neck raising.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following combinations of antiparkinsonian drugs is an appropriate treatment plan?', 'Amantadine, carbidopa, and entacapone.', 'Levodopa, carbidopa, and entacapone.', 'Pramipexole, carbidopa, and entacapone.', 'Ropinirole, carbidopa, and selegiline.', 'B', 'Per Kenya EML/pharmacology texts, the standard Parkinson''s regimen combines levodopa (dopamine precursor) with carbidopa (peripheral decarboxylase inhibitor) and entacapone (COMT inhibitor); the other options pair carbidopa with drugs (amantadine, dopamine agonists) that are not levodopa and so gain no benefit from carbidopa.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The part of brain affected in parkinsonian disease is the:', 'Limbic system', 'Occipital lobe', 'Pyramidal tracts', 'Basal ganglia', 'D', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra of the basal ganglia, impairing control of voluntary movement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('One of the following is a rapidly progressing, ascending inflammatory demyelinating polyneuropathy of the peripheral sensory and motor nerves and nerve roots disease.', 'Myasthenia Gravis', 'Guillain-Barre Syndrome', 'Multiple Myeloma', 'Alzheimer''s disease', 'B', 'Per Brunner & Suddarth, Guillain-Barre syndrome is an acute, rapidly progressive ascending inflammatory demyelinating polyneuropathy affecting peripheral sensory and motor nerves and nerve roots.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A postpartum patient was in labor for 30 hours and had ruptured membranes for 24 hours. For which of the following would the nurse be alert?', 'Endometritis', 'Endometriosis', 'Salpingitis', 'Pelvic thrombophlebitis', 'A', 'Prolonged labor with prolonged rupture of membranes (>18-24h) allows ascending bacteria to infect the uterine lining, so the nurse watches for endometritis (puerperal infection). Endometriosis and salpingitis are unrelated to this postpartum risk. Per Myles Textbook for Midwives (puerperal sepsis).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant client is diagnosed with partial placenta previa. In explaining the diagnosis, the nurse tells the client that the usual treatment for partial placenta previa is which of the following?', 'Activity limited to bed rest', 'Platelet infusion', 'Immediate cesarean delivery', 'Labor induction with oxytocin.', 'A', 'In stable partial placenta previa without active heavy bleeding, expectant management with bed rest is standard to prolong gestation; cesarean is reserved for term or uncontrolled bleeding, and oxytocin induction is contraindicated. Per Myles Textbook for Midwives / MOH maternal guidelines.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida client at 25 weeks gestation visits the clinic and tells the nurse that her lower back aches when she arrives home from work. The nurse should suggest that the client perform:', 'Tailor sitting', 'Leg lifting', 'Shoulder circling', 'Squatting exercises', 'A', 'Tailor (cross-legged) sitting strengthens the back and stretches pelvic muscles, relieving low backache in pregnancy. Leg lifting and squatting can strain the back; shoulder circling targets the upper body. Per Myles Textbook for Midwives (antenatal exercises).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client tells the nurse, “I think my baby likes to hear me talk to him.” When discussing neonates and stimulation with sound, which of the following would the nurse include as a means to elicit the best response?', 'High-pitched speech with tonal variations', 'Low-pitched speech with a sameness of tone', 'Cooing sounds rather than words', 'Repeated stimulation with loud sounds', 'A', 'Neonates respond best to high-pitched speech with tonal variation (infant-directed speech), which promotes attention and bonding. Loud sounds and monotone are less effective. Per Kozier & Erb / developmental care principles.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient in her 14th week of pregnancy has presented with abdominal cramping and vaginal bleeding for the past 8 hours. She has passed several clots. What is the primary nursing diagnosis for this patient?', 'Knowledge deficit', 'Fluid volume deficit', 'Anticipatory grieving', 'Pain', 'B', 'With active vaginal bleeding, clot passage and cramping (inevitable/incomplete abortion), the priority (physiologic, ABC) nursing diagnosis is fluid volume deficit; grieving and pain follow once the patient is stabilized. Per Kozier & Erb prioritization / Myles.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida patient is admitted to the labor delivery area. Assessment reveals that she is in the early part of the first stage of labor. Her pain is likely to be most intense:', 'Around the pelvic girdle', 'Around the pelvic girdle and in the upper arms', 'Around the pelvic girdle and at the perineum', 'At the perineum', 'A', 'In the early first stage, pain from cervical dilatation is referred to the lower abdomen and pelvic girdle (T10-L1). Perineal pain arises in the second stage. Per Myles Textbook for Midwives (physiology of labor pain).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A female adult patient is taking a progestin-only oral contraceptive or mini pill. Progestin use may increase the patient’s risk for:', 'Endometriosis', 'Female hypogonadism', 'Premenstrual syndrome', 'Tubal or ectopic pregnancy', 'D', 'Progestin-only pills slow tubal motility, so if failure occurs the pregnancy is more likely to be ectopic; progestins do not cause endometriosis, hypogonadism, or PMS. Per Kenya National Family Planning Guidelines / BNF.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with pregnancy-induced hypertension probably exhibits which of the following symptoms?', 'Proteinuria, headaches, vaginal bleeding', 'Headaches, double vision, vaginal bleeding', 'Proteinuria, headaches, double vision', 'Proteinuria, double vision, uterine contractions', 'C', 'Preeclampsia/PIH presents with proteinuria, headache, and visual disturbances (double/blurred vision) from cerebral/retinal involvement; vaginal bleeding is not a feature. Per MOH/WHO pre-eclampsia guidelines and Myles.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Accompanied by her husband, a patient seeks admission to the labor and delivery area. The client states that she is in labor and says she attended the hospital clinic for prenatal care. Which question should the nurse ask her first?', '“Do you have any chronic illness?”', '“Do you have any allergies?”', '“What is your expected due date?”', '“Who will be with you during labor?”', 'C', 'On admission in labor the immediate priority is to establish gestational age via the expected due date to guide management; allergies and history follow. Per Myles Textbook for Midwives (admission in labor).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient is in the second stage of labor. During this stage, how frequently should the nurse in charge assess her uterine contractions?', 'Every 5 minutes', 'Every 15 minutes', 'Every 30 minutes', 'Every 60 minutes', 'B', 'In the second stage of labor, uterine contractions and fetal heart are assessed at least every 15 minutes (FHR every 5 min in high-risk). Per WHO/MOH intrapartum monitoring and Myles.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient is in her last trimester of pregnancy. Nurse Vickie should instruct her to notify her primary health care provider immediately if she notices:', 'Blurred vision', 'Hemorrhoids', 'Increased vaginal mucus', 'Shortness of breath on exertion', 'A', 'Blurred vision in late pregnancy is a danger sign of severe pre-eclampsia and must be reported immediately; hemorrhoids, increased mucus, and mild exertional dyspnea are common and expected. Per MOH maternal danger signs / Myles.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An adult female patient is using the rhythm (calendar-basal body temperature) method of family planning. In this method, the unsafe period for sexual intercourse is indicated by:', 'Return preovulatory basal body temperature', 'Basal body temperature increase of 0.1 degrees to 0.2 degrees on the 2nd or 3rd day of cycle.', '3 full days of elevated basal body temperature and clear, thin cervical mucus', 'Breast tenderness and mittelschmerz', 'C', 'The fertile (unsafe) period is marked by clear, thin, stretchy cervical mucus and the sustained BBT rise around ovulation; only after 3 full days of elevated temperature is the safe period considered to begin. Per Kenya National Family Planning Guidelines.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A couple who wants to conceive but has been unsuccessful during the last 2 years has undergone many diagnostic procedures. When discussing the situation with the nurse, one partner states, “We know several friends in our age group, and all of them have their own child already, Why can’t we have one?”. Which of the following would be the most appropriate nursing diagnosis for this couple?', 'Fear related to the unknown', 'Pain related to numerous procedures', 'Ineffective family coping related to infertility', 'Self-esteem disturbance related to infertility', 'D', 'The statement comparing themselves unfavorably to peers reflects feelings of inadequacy, indicating self-esteem disturbance related to infertility. There is no evidence of ineffective family coping between partners. Per Kozier & Erb nursing diagnosis. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be a disadvantage of breastfeeding?', 'Involution occurs more rapidly', 'The incidence of allergies increases due to maternal antibodies', 'The father may resent the infant’s demands on the mother’s body', 'There is a greater chance for error during preparation', 'C', 'A recognized disadvantage of breastfeeding is that the father may feel excluded or resent the infant''s demands on the mother. Faster involution and antibody transfer are advantages, and preparation error applies to formula. Per Myles Textbook for Midwives (breastfeeding).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client LMP began July 5, 2020. Her estimated date of delivery (EDD) should be which of the following?', 'January 2, 2021', 'March 28, 2021', 'April 12, 2021', 'October 12, 2020', 'C', 'Naegele''s rule (Myles Textbook for Midwives): LMP + 1 year - 3 months + 7 days. July 5, 2020 - 3 months = April 5, + 7 days = April 12, 2021.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Before birth, which of the following structures connects the right and left auricles of the heart?', 'Umbilical vein', 'Foramen ovale', 'Ductus arteriosus', 'Ductus venosus', 'B', 'The foramen ovale is the fetal shunt in the interatrial septum allowing blood to pass from the right to the left atrium (auricles) bypassing the lungs. The ductus arteriosus links pulmonary artery to aorta (Anatomy & Physiology; fetal circulation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following groups of newborn reflexes below are present at birth and remain unchanged through adulthood?', 'Blink, cough, rooting, and gag', 'Blink, cough, sneeze, gag', 'Rooting, sneeze, swallowing, and cough', 'Stepping, blink, cough, and sneeze', 'B', 'Protective reflexes present at birth that persist through life are blink, cough, sneeze and gag. Rooting and stepping are primitive reflexes that disappear in infancy, excluding the other options (Kozier & Erb / newborn assessment).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client in her third trimester tells the nurse, “I’m constipated all the time!” Which of the following should the nurse recommend?', 'Daily enemas', 'Laxatives', 'Increased fiber intake', 'Decreased fluid intake', 'C', 'Constipation in pregnancy is managed conservatively with increased dietary fibre, fluids and activity; enemas and laxatives are avoided and reducing fluids would worsen it (Myles Textbook for Midwives; ANC health education).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client tells the nurse that her last menstrual period started on January 14 and ended on January 20. Using Nagele’s rule, the nurse determines her EDD to be which of the following?', 'September 27', 'October 21', 'November 7', 'December 27', 'B', 'Naegele''s rule uses the first day of LMP (Jan 14): + 7 days = Jan 21, - 3 months = Oct', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('EDD is October 21 (Myles Textbook for Midwives). 174. When developing a plan of care for a client newly diagnosed with gestational diabetes, which of the following instructions would be the priority?', 'Dietary intake', 'Medication', 'Exercise', 'Glucose monitoring', 'D', 'For newly diagnosed gestational diabetes, teaching self blood-glucose monitoring is the priority because it guides dietary, exercise and insulin decisions and detects hyper/hypoglycaemia (Kenya MOH diabetes/maternal guidelines). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client 12 weeks’ pregnant came to the emergency department with abdominal cramping and moderate vaginal bleeding. Speculum examination reveals 2 to 3 cm cervical dilation.The nurse would document these findings as which of the following?', 'Threatened abortion', 'Imminent abortion', 'Complete abortion', 'Missed abortion', 'B', 'Moderate bleeding, cramping and cervical dilation (2-3 cm) indicate the abortion is inevitable/imminent. A threatened abortion has a closed cervix; the products have not yet passed so it is not complete (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be the priority nursing diagnosis for a client with an ectopic pregnancy?', 'Risk of infection', 'Pain', 'Knowledge deficit', 'Anticipatory grieving', 'B', 'Among the listed diagnoses, acute pain is the priority in ectopic pregnancy (a physiological/ABC-linked need indicating possible tubal rupture and bleeding); risk of infection and grieving are lower priority (Myles Textbook for Midwives; nursing priority setting). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Before assessing the postpartum client’s uterus for firmness and position in relation to the umbilicus and midline, which of the following should the nurse do first?', 'Assess the vital signs', 'Administer analgesia', 'Ambulate her in the hall', 'Assist her to urinate', 'D', 'A full bladder displaces and prevents the uterus from contracting, giving a falsely high/deviated fundus; the nurse should have the client empty her bladder first before assessing fundal firmness and position (Myles Textbook for Midwives; postnatal assessment).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A postpartum client has a temperature of 101.4ºF, with a uterus that is tender when palpated, remains unusually large, and not descending as normally expected. Which of the following should the nurse assess next?', 'Lochia', 'Breast', 'Incision', 'Urine', 'A', 'Fever, a tender, boggy, subinvoluted uterus indicates endometritis; the nurse should next assess the lochia (amount and foul odour) which confirms uterine infection (Myles Textbook for Midwives; postpartum infection).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following sign may help a midwife diagnose shoulder dystocia in labour ward?', 'The fetal head remains slightly stuck in the vagina', 'The anterior shoulder is delivered but the posterior one is stuck', 'The chin retracts and depresses the perineum', 'Traction of the head delivers the shoulder', 'C', 'Per Myles Textbook for Midwives, shoulder dystocia is recognised by the ''turtle sign''—the head delivers then retracts against the perineum (chin retracts/depresses perineum) because the anterior shoulder is impacted behind the symphysis.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman comes in the antenatal clinic for the first ANC visit and reports that her L.M.P was 24/12/2021. What will be her E.D.D?', '27/10/2022', '01/10/2022', '31/9/2022', '27/9/2022', 'B', 'Per Naegele''s rule (Myles): LMP 24/12/2021 + 7 days = 31/12/2021, minus 3 months = 30/09, +1 year = 2022; giving approx 01/10/2022 (the closest option). Other options do not fit the calculation.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The reflex that is elicited when the corner of the baby’s mouth is stroked and the baby turns its head and opens its mouth is:', 'Moro reflex', 'Rooting reflex', 'Sucking reflex', 'Turning reflex', 'B', 'Per Myles/Kozier, stroking the corner of the newborn''s mouth causing the head to turn and mouth to open is the rooting reflex, which aids location of the nipple.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A ridge between the upper and lower uterine segments, visible above the symphysis pubis is referred to as:', 'Retraction ring', 'Bandl’s ring', 'Uterine effacement', 'Uterine rupture', 'B', 'Per Myles Textbook for Midwives, a Bandl''s ring is a pathological retraction ring visible as a ridge between upper and lower uterine segments above the symphysis, warning of obstructed labour and impending rupture.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The three bones that form the vault of the fetal head are:', 'Parietal, frontal, temporal', 'Frontal, lambdoidal, coronal', 'Temporal, parietal, coronal', 'Sinciput, parietal, lambdoidal', 'A', 'Per Myles Textbook for Midwives, the vault of the fetal skull is formed by the frontal, parietal (two), temporal and occipital bones; of the listed sets only ''parietal, frontal, temporal'' are true vault bones (the others list sutures).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following include pillars of safe motherhood:', 'Preconception care, essential obstetric care, child survival', 'Home visiting, school health program, post abortion care', 'Post abortion care, preconception care, focused antenatal care', 'Essential obstetric care, HIV/AIDS & STI management, male involvement', 'A', 'Per Kenya Safe Motherhood strategy/WHO, pillars include family planning, preconception/antenatal care, clean and safe delivery (essential obstetric care) and postnatal/child survival; option A best reflects these pillars. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drug of choice for severe malaria in pregnancy is:', 'Amodiaquine', 'Artesunate', 'Artemether lumefantrine', 'Quinine', 'B', 'Per Kenya National Malaria Treatment Guidelines, intravenous artesunate is the drug of choice for severe malaria, including in pregnancy in all trimesters; quinine is now second-line.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pathological jaundice as a result of increased haemolysis involves all the following except:', 'G6PD deficiency', 'ABO incompatibility', 'Gilbert’s syndrome', 'Bacterial septicaemia', 'C', 'Per Basic Paediatric Protocols/standard texts, Gilbert''s syndrome causes unconjugated hyperbilirubinaemia from reduced conjugation (UGT enzyme), not increased haemolysis; G6PD deficiency, ABO incompatibility and septicaemia all cause haemolytic jaundice.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of spina bifida which comprises of the skin, meninges with or without CSF is:', 'Meningocele', 'Myelomeningocele', 'Cyatica', 'Occulta', 'A', 'Per standard paediatric/neurology texts, a meningocele is a spina bifida cystica variant containing skin and meninges with or without CSF but no neural tissue; a myelomeningocele also contains spinal cord/nerves.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At what age does closure of the posterior fontanelle occur?', '2months', '18monts', '22months', '1 month', 'A', 'Per standard paediatric texts, the posterior fontanelle closes by about 6-8 weeks (approximately 2 months) of age, whereas the anterior fontanelle closes around 18 months.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which are the storage ducts of milk in the mammary glands?', 'Alveoli', 'Lactiferous sinuses', 'Cooper’s ligaments', 'Lobules', 'B', 'Milk produced in the alveoli passes along the ducts to the lactiferous sinuses (ampullae) beneath the areola, which act as reservoirs storing milk. Alveoli produce milk; Cooper''s ligaments are support structures. Per Myles Textbook for Midwives (anatomy of the breast).', 'KRCHN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At which age of fetal development does the fetus experience rapid weight gain?', '20- 24 weeks', '8-12 weeks', '4- 8 weeks', '20 – 38 weeks', 'D', 'The greatest fetal weight gain occurs in the second half of pregnancy, from about 20 weeks to term (38 weeks), when subcutaneous fat and muscle mass are laid down. Earlier weeks are dominated by organogenesis, not weight gain. Per Myles Textbook for Midwives (fetal development).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Radiation is the most predominate mode of heat loss for a newborn. Radiation refers to:', 'loss of heat through water evaporation from the baby', 'loss of heat through the baby shivering', 'loss of heat from the baby''s surface to surrounding colder objects', 'loss of heat to moving air or fluid around the baby', 'C', 'Radiation is heat transfer from the newborn''s body surface to nearby cooler solid objects not in direct contact (e.g. cold walls/windows). Evaporation is water loss, convection is loss to moving air, conduction is loss to objects in contact. Per Kenya Basic Paediatric Protocols / Myles (thermoregulation).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At one week a mother complains that her new-born’s umbilical cord is smelly. You:', 'Tell her that often happens and reassure her all is well', 'Inspect the cord and surrounding skin', 'Clean the cord with antiseptic', 'Phone a paediatrician', 'B', 'A smelly cord may indicate omphalitis (a neonatal sepsis danger sign); the nurse must first assess by inspecting the cord and surrounding skin for redness, discharge or induration before acting. Reassuring without assessing is unsafe. Per Kenya Basic Paediatric Protocols (newborn care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother delivers a baby who has an Apgar score of 0/1. Which of the following findings demonstrate that Apgar score:', 'Has minimal grimace', 'Neonatal fetal heart rate of less than100', 'Gasping respiration', 'The body and the extremities are pale', 'D', 'An Apgar of 0/1 indicates a severely depressed neonate; only the completely pale/absent colour (0 for colour, no cyanosis grading possible) fits. Minimal grimace, HR<100 and gasping respiration all score 1 in their categories and would raise the score above near-zero, whereas generalised pallor reflects the profoundly depressed state. Per Kenya Basic Paediatric Protocols (Apgar scoring). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a newborn baby is in contact with cold surfaces, heat loss occurs by;', 'Evaporation', 'Radiation', 'Convection', 'Conduction', 'D', 'Heat loss from the baby''s body to a cold surface in direct contact (e.g. cold weighing scale or bed) occurs by conduction. Radiation is to non-contact objects, convection to moving air, evaporation from moisture. Per Kenya Basic Paediatric Protocols (thermoregulation).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aims of first examination of the newborn are;', 'Assess growth, maintain clear airway, assess maturity at birth', 'Detect birth injuries, assess minor disorders, detect congenital anomalies', 'Provide care, detect infections, assess growth and development', 'Detect birth injuries, detect any congenital abnormalities, and assess maturity at term.', 'D', 'The aims of the first (immediate) newborn examination are to detect birth injuries, identify congenital abnormalities and assess maturity/wellbeing at birth. Maintaining the airway is resuscitation, not the examination''s aim. Per Myles Textbook for Midwives (examination of the newborn).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anterior posterior fontanelle normally close by the age of;', '6 weeks and 18 weeks respectively', '18 weeks and 6 weeks respectively', '18 months and 6 weeks respectively', '6 months and 18 months respectively', 'D', 'The posterior fontanelle closes by about 6 weeks and the anterior fontanelle by about 18 months; among the options given, only ''D'' offers 18 months for the anterior fontanelle, which is the defining figure. The question wording is imperfect but D best matches the standard anterior-fontanelle closure time. Per Myles / Kenya Basic Paediatric Protocols (fontanelles). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The rooting reflex is defined as response of the baby to;', 'Being pulled upright by the wrist to a sitting position', 'Being supported upright ith his feet touching a flat surface', 'Stroking of the cheek or side of the mouth', 'Being left to drop from an angle of 45', 'C', 'The rooting reflex is elicited by stroking the newborn''s cheek or corner of the mouth, causing the baby to turn towards the stimulus and open the mouth to feed. The other options describe traction, stepping and Moro responses. Per Myles Textbook for Midwives (neonatal reflexes).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a contraindication for combined oral contraceptives', 'Mothers exclusively breast feeding', '30yrs old smoker', 'History of uterine cancer', 'Women on Antiretroviral therapy.', 'B', 'Per Kenya National Family Planning Guidelines/WHO MEC, smoking with COCs raises thromboembolic/cardiovascular risk; smoking is a contraindication (absolute at >=35yrs, strong caution otherwise). History of uterine (endometrial) cancer is not a COC contraindication the way this listed answer is; the smoker is the intended best contraindication answer. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse should advice a client using the basal body temperature method of contraception to;', 'Take her body temperature at the same time at night before getting to bed.', 'Avoid sex when she notices a temperature rise.', 'Avoid sex from the first day of menses until she notices a temperature rise.', 'Take her body temperature every morning before she gets out of bed', 'D', 'Per Kenya FP/fertility awareness guidelines, basal body temperature must be measured at rest each morning before any activity or getting out of bed to detect the post-ovulatory temperature rise.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The drugs used for chemoprophylaxis against malaria include;', 'Mefloquine, doxycycline, proguanil', 'Artemether- lumefantrine, Fansidar, quinine', 'Fansidar, proguanil, metakelfin', 'Fansidar, Artemether- lumefantrine, metakelfin', 'A', 'Per Kenya malaria guidelines, chemoprophylaxis drugs include mefloquine, doxycycline and proguanil (and atovaquone-proguanil). Artemether-lumefantrine and quinine are for treatment, not routine prophylaxis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to the World Health Organization (WHO), clinical staging of HIV infection stage III in adults is characterized by;', 'Weight loss more than 50% of usual body weight, cryptoccocosis, extra pulmonary tuberculosis.', 'Weight loss of more than 50% of usual body weight, HIV encephalopathy, candidiasis of the oesophagus.', 'Weight loss of more than 10% of usual body weight, recurrent respiratory tract infections, herpes zoster within the last five years.', 'Weight loss of more than 10% of usual body weight, pulmonary tuberculosis, oral candidiasis.', 'C', 'Per WHO/Kenya ART clinical staging (adopted in Kenya National HIV guidelines), Stage III features unexplained weight loss >10% plus conditions like recurrent respiratory infections, herpes zoster, oral candidiasis and pulmonary TB; option C fits Stage III. Options with >50% weight loss, cryptococcosis, oesophageal candidiasis or HIV encephalopathy are Stage IV. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Medical eligibility criteria category 4 for contraceptive implants include:', 'Women with history of breast cancer', 'Women who have severe cirrhosis', 'Women who have unexplained vaginal bleeding', 'Women who have deep venous thrombosis', 'A', 'Per WHO/Kenya Medical Eligibility Criteria for contraceptives, current/history of breast cancer is a hormonal-contraceptive concern; current breast cancer is Category 4 and past breast cancer Category 3 for implants, making breast cancer the correct MEC-4 associated condition here. DVT and severe cirrhosis are typically Category 3, and unexplained vaginal bleeding is Category 3 before evaluation. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In enterobiasis infection, the adult worm lives in the:-', 'Lungs', 'Caecum', 'Large intestines', 'Small intestines', 'B', 'Per parasitology in Kenyan nursing texts, in enterobiasis the adult Enterobius vermicularis (pinworm) lives in the caecum and appendiceal region; females migrate to the perianal area to lay eggs. Caecum is the specific site making it the best answer over ''large intestines''.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a lymphoma that affects children:', 'Non-hodgkin''s disease', 'Acute lymphoblastic disease', 'Acute myeloid leukemia', 'Wilm''s tumor', 'A', 'Non-Hodgkin''s lymphoma is a lymphoma of childhood; ALL is a leukemia, AML is a leukemia, and Wilm''s tumor is a renal tumor, not lymphomas (Nelson/Basic Paediatric Protocols, Kenya).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant who has no head lag when pulled to a sitting position is able to reach for objects and transfer them from hand to hand is likely to be in what age?', '4 months', '6 months', '9 months', '12 months', 'B', 'Absence of head lag on pull-to-sit, reaching for objects and hand-to-hand transfer are classic 6-month developmental milestones (Basic Paediatric Protocols, Kenya; IMNCI developmental milestones).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bullous impetigo;', 'Is not contagious', 'Is commonly caused by Staphylococcus', 'Presents with painful blisters', 'Is managed using topical steroids', 'B', 'Bullous impetigo is commonly caused by Staphylococcus aureus (toxin-mediated); it is contagious, presents with fragile painless bullae, and is treated with antibiotics, not topical steroids (Basic Paediatric Protocols; Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The management of a child with mumps includes the following EXCEPT', 'Use of cold compresses', 'Use of aspirin to relieve pain', 'Warm salt water gargles', 'Avoiding acidic foods', 'B', 'Aspirin is contraindicated in children with viral illness (mumps) due to Reye''s syndrome risk; cold compresses, warm salt gargles and avoiding acidic foods are appropriate, so aspirin is the EXCEPTion (Basic Paediatric Protocols; Kenya paediatric guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 1 ½ yrs old child with meningitis is likely to present with;', 'Bulging of the fontanelle, cold extremities,rash', 'Vomiting, rash, fever', 'Fever, bulging of the fontanelle, photophobia', 'Lethargy, Seizure, Bulging fontanelle', 'C', 'In an 18-month-old, meningitis typically presents with fever, bulging fontanelle (anterior fontanelle may still be open) and photophobia; this combination best represents classic meningeal signs (Basic Paediatric Protocols; IMNCI). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Rheumatic heart disease is caused by;', 'Streptococcus pyogenes', 'Staphylococcus aureus', 'Haemophilus influenza', 'Streptococcus pneumonia', 'A', 'Rheumatic heart disease follows rheumatic fever caused by group A beta-haemolytic Streptococcus pyogenes; the other organisms are not implicated (Brunner & Suddarth''s; Kenya clinical guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When palpating a child''s abdomen you note hepatomegaly. You know this can be a sign of what cardiac problem?', 'Right sided heart failure', 'Left- sided heart failure', 'Rheumatic heart disease', 'Anemia', 'A', 'Right-sided heart failure causes systemic venous congestion, producing hepatomegaly and peripheral oedema. Left-sided failure causes pulmonary congestion. Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What type of imbalance is typically a trigger for Status epilepticus in a vulnerable child?', 'Temperature', 'Electrolyte', 'Hormonal', 'Fluid', 'B', 'Electrolyte imbalances (notably hyponatraemia, hypocalcaemia, hypoglycaemia-related) commonly precipitate status epilepticus in vulnerable children. Fever triggers simple febrile seizures, but sustained status epilepticus is classically driven by electrolyte disturbance. Per Basic Paediatric Protocols (Kenya). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse is caring for a client admitted 2days ago with myocardial infection .upon assessment the nurse notes a new systolic murmur at the cardiac apex. The nurse should assess the client for which of the following conditions?', 'Ventricular aneurysm', 'Acute pericarditis', 'Papillary muscle dysfunction', 'Pulmonary embolism', 'C', 'A new systolic (apical) murmur post-MI signals papillary muscle dysfunction/rupture causing mitral regurgitation; Brunner & Suddarth lists this as a mechanical complication of MI. Ventricular aneurysm and pericarditis do not typically produce a new apical systolic murmur.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 21 year old male client is transported by ambulance to the emergency unit. He complains of severe pain in his right chest where he struck the steering wheel. Which is the primary client goal at this time?', 'Reduce client’s anxiety', 'Maintain adequate oxygenation', 'Decrease chest pain', 'Maintain adequate circulating volume', 'B', 'With blunt chest trauma the ABC priority (airway/breathing) makes maintaining adequate oxygenation the primary goal; Brunner & Suddarth trauma management places oxygenation before pain and anxiety control.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has just undergone spinal fusion after experiencing herniation of a lumbar disk. The nurse would avoid which intervention to maintain client safety after this procedure?', 'Use the overhead trapeze.', 'Keep the head of the bed flat.', 'Place pillows under the length of the legs.', 'Use logrolling technique for repositioning.', 'C', 'After spinal fusion the spine must be kept in neutral alignment; placing pillows along the full length of the legs causes spinal flexion and is avoided. Logrolling, overhead trapeze and a flat bed are safe/appropriate (Brunner & Suddarth ortho nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a difficult labor and birth, a primiparous woman refuses to feed her baby four hours after delivery, she states that she is too tired and just wants to sleep. The nurse should:', 'Tell the woman she can rest after she feeds her baby', 'Take the baby back to the nursery, reassuring the woman that her rest is a priority at this time', 'Recognize this as a behavior of the taking-hold stage', 'Record the behavior as ineffective maternal-newborn attachment', 'B', 'In the taking-in phase after a difficult birth the mother is fatigued and focused on her own needs; the nurse supports rest and defers feeding, reassuring her (Myles Textbook for Midwives, Rubin''s maternal phases). Forcing feeding or labelling poor attachment at 4 hours is inappropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('About puerperium, the following statement is true', 'The puerperium is a period of 60 days following delivery of the placenta', 'The puerperium is a period of 42 days following delivery of the placenta', 'The puerperium is a period of 21 days following delivery of the placenta', 'The puerperium is a period of 14 days following delivery of the placenta', 'B', 'The puerperium is the ~6-week (42-day) period after delivery of the placenta during which the reproductive organs return to the non-pregnant state (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At the end of labor, the cervix is:', 'soft and flabby', '2cm dilated', '1cm dilated', 'a slit', 'A', 'At the end of labour, after full dilatation and delivery, the cervix is soft, flabby and thin; it is no longer measured in cm of dilatation (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After delivery of a healthy newborn. Which time frame should the nurse relay to the client regarding the return of bowel function?', '7 days postpartum', '3 days postpartum', 'Within 2 weeks postpartum', 'On the day of delivery', 'B', 'Normal bowel function typically returns about 2-3 days postpartum, delayed by reduced tone, perineal discomfort and analgesia (Myles Textbook for Midwives; postpartum nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antenatal care of HIV positive client includes:', 'Antiretroviral therapy for life immediately HIV positive status is confirmed', 'Sulfadoxine Pyrimethamine(SP)and cotrimoxazole prophylaxis daily until delivery', 'Antiretroviral therapy up to postnatal period from the time the CD4 count is established', 'Delay administration of Sulfadoxine Pyrimethamine until antiretroviral therapy is started Maternal and Newborn Health (MNH) Pillars', 'A', 'Per Kenya PMTCT / National HIV guidelines (Option B+), all HIV-positive pregnant women are started on lifelong ART immediately upon diagnosis regardless of CD4 count.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client who is pregnant reports nausea and vomiting. The nurse reassures the client that these symptoms will subside by;', '6-9 WEEKS', '10-13 WEEKS', '14-17 WEEKS', '18- 22 WEEKS', 'B', 'Per Myles Textbook for Midwives, nausea and vomiting of pregnancy typically resolve by the end of the first trimester (around 12-13 weeks) as hCG levels fall.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Effects of gestational diabetes on the fetus include:', 'Congenital malformation, macrosomia,', 'Fetal hypoglycaemia, congenital anomalies', 'Hypocalcemia, fetal hyperglyceamia', 'Macrosomia, fetal hypoglycaemia', 'D', 'Per Myles Textbook for Midwives, gestational diabetes causes fetal macrosomia (maternal hyperglycaemia) and neonatal hypoglycaemia (fetal hyperinsulinism after birth). Congenital malformations are chiefly linked to pre-gestational diabetes, making this the best option. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The normal level of haemoglobin (Hb) on a pregnant woman is:-', '10-15g/dl', '12-14g/dl', '9-14g/dl', '11-12g/dl', 'D', 'Per Kenya ANC / WHO guidelines, the normal haemoglobin in pregnancy is 11 g/dl or above (roughly 11-12 g/dl); below 11 g/dl is anaemia in pregnancy. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The diastolic pressure is usually not affected by excitement, its increase therefore is more significant in assessment of pregnant women for pre-eclampsia. The range of change in mmHg is:', '10-15', '15-20', '15-30', '20-30', 'C', 'Per Myles Textbook for Midwives, a rise in diastolic pressure of 15-30 mmHg above baseline is significant in assessing pregnant women for pre-eclampsia as diastolic pressure is less affected by excitement. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After birth, the functional closure of ductus arteriosus takes place within:', '0-1 hour', '2-4hour', '4-6 hours', '8-10 hours', 'B', 'Per Myles Textbook for Midwives and neonatal physiology, functional (physiological) closure of the ductus arteriosus occurs within the first few hours after birth (about 2-4 hours), with anatomical closure over weeks.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Laboratory findings that are consistent with hyperthyroidism include', 'Decreased serum triiodothyronine (T3) and thyroxine (T4) levels', 'Elevated serum thyrotropin releasing hormone (TRH) levels', 'Decreased radioactive iodine uptake', 'Increased free triiodothyronine (T3) and thyroxine (T4) levels', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, hyperthyroidism is characterised by elevated free T3 and T4 with suppressed TSH and increased radioactive iodine uptake.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Discharge instructions for a client with chronic respiratory acidosis should include', 'Discussing how to plan for periods of increased activity', 'Teaching about a low protein, low carbohydrate diet', 'Demonstrating exercises to increase vital capacity', 'Encouraging participation in activities such as jogging', 'C', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, clients with chronic respiratory acidosis (e.g. COPD) are taught breathing/pulmonary exercises to improve vital capacity; strenuous activity like jogging and increased activity periods are inappropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most common preventable cause of valvular heart disease is:', 'Congenital disease acquired intrauterine', 'Calcium deposits and thrombus formation', 'Marfans syndrome', 'Beta-hemolytic streptococcal infection', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rheumatic heart disease following group A beta-haemolytic streptococcal infection is the most common preventable cause of valvular heart disease.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pelvic inflammatory diseases include:', 'Salpingitis, cervicitis, candidiasis', 'Cervicitis, endometritis, oophoritis.', 'Trichomoniasis, salpingitis, urethritis.', 'Candidiasis, toxic shock syndrome, endometritis.', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, PID is ascending infection of the upper genital tract including cervicitis, endometritis, salpingitis and oophoritis; candidiasis and trichomoniasis are lower-tract/vaginal infections, so option B best lists true PID components.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cholelithiasis is associated with:-', 'Abnormal metabolism of cholesterol and bile salts.', 'Abnormal metabolism of lipids and bile acids.', 'Chronic pancreatitis.', 'Hepatitis.', 'A', 'Per Brunner & Suddarth''s, cholesterol gallstones (the commonest type) form when bile is supersaturated with cholesterol relative to bile salts, i.e. abnormal metabolism of cholesterol and bile salts. Lipids/bile acids and pancreatitis/hepatitis are not the primary mechanism.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Glomerulonephritis usually follows:-', 'Staphylococcal infection.', 'Gonococcal infection.', 'Gonococcal infection.', 'Streptococcal infection', 'D', 'Per Brunner & Suddarth''s, acute post-streptococcal glomerulonephritis typically follows a group A beta-haemolytic streptococcal throat or skin infection. Options B and C are duplicates (gonococcal) and incorrect.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Body mechanics usually prescribed for clients with low pain include:-', 'Bending at knee and hips, standing straight, carrying objects close to the body.', 'Bending at the waist carrying objects close to the body, standing straight.', 'Sleeping on the side carrying objects farther from the body, bending at the knees and hips.', 'Bending at the waist, sleeping on the side, standing straight.', 'A', 'Per Kozier & Erb''s Fundamentals of Nursing, correct body mechanics for low-back pain prevention involve bending at the knees and hips (not the waist), keeping the back straight, and carrying objects close to the body to reduce spinal strain.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When a nurse is monitoring a patient for cerebrospinal fluid (CSF) leak he/she should observe for:-', 'Halo sign.', 'Babinski reflex.', 'Iliopsoas sign.', 'Blumberg sign.', 'A', 'Per Brunner & Suddarth''s, CSF leak is detected by the halo (ring) sign, where drainage on gauze forms a clear ring around blood, and by glucose-positive fluid. Babinski, iliopsoas and Blumberg signs are unrelated neurological/abdominal signs.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The commonest cause of toxic goitre (Grave’s disease) is: -', 'Pituitary tumours', 'Benign thyroid', 'Lack of iodine in the diet', 'Immunoglobulins reaction', 'D', 'Per Brunner & Suddarth''s, Graves'' disease is an autoimmune disorder caused by thyroid-stimulating immunoglobulins (TSH-receptor antibodies). Iodine lack causes simple/endemic goitre, not toxic Graves'' goitre.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The carcinogenic risk factors for laryngeal cancers include:', 'Tar products, mustard gas, chronic laryngitis', 'Asbestos, chronic laryngitis, voice straining', 'Voice straining, high fibre diet, tobacco', 'Asbestos, tobacco, tar products', 'D', 'Per Brunner & Suddarth''s, carcinogenic risk factors for laryngeal cancer include tobacco, alcohol, asbestos and tar/industrial exposures. A high-fibre diet (option C) is protective, not carcinogenic, so D is the fully correct set.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The position an unconscious patient should be nursed in is:', 'Recumbent', 'Lithotomy', 'Prone', 'Semi-prone', 'D', 'Per Kozier & Erb''s, the unconscious patient is nursed in the semi-prone (recovery/lateral) position to maintain a patent airway and allow drainage of secretions, preventing aspiration.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parklands’ formula is used to calculate', 'Total burnt surface area', 'Fluid replacement', 'Thickness of the burn', 'Hemo-concentration', 'B', 'Per Brunner & Suddarth''s / MOH burns guidelines, the Parkland formula (4 ml x weight x %TBSA) calculates the volume of IV fluid replacement required in the first 24 hours after a burn.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following thyroidectomy, the nurse suspects damage or removal of parathyroid gland when the patient develops:', 'Muscle weakness and weight loss', 'Hyperthermia and severe tachycardia', 'Hypertension and difficulty in swallowing', 'Laryngeal stridor and tingling in the hands and feet', 'D', 'Per Brunner & Suddarth''s, parathyroid damage after thyroidectomy causes hypocalcaemia manifesting as tetany: perioral/peripheral tingling (paraesthesia), carpopedal spasm and laryngeal stridor/spasm. 326. increased concentration of red blood cells due to excessive production of erythropoietin is referred to as: A. primary polycythemia B. leukopenia C. secondary polycythemia D. agranulocytosis Answer: C. secondary polycythemia Rationale: Per Brunner & Suddarth''s, secondary polycythaemia is an increase in RBC mass driven by excessive erythropoietin (e.g. from hypoxia). Primary polycythaemia (vera) is a clonal marrow disorder with low/normal erythropoietin.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following observations are noted on the patient on underwater seal drainage:', 'Vital signs, patent connections, colour of drainage', 'Vital signs, colour of drainage, amount of drainage', 'Vital signs, patient understanding of the procedure, amount of drainage', 'Vital signs, patient understanding of the procedure, cyanosis', 'A', 'Per Brunner & Suddarth''s, monitoring a patient on underwater seal (chest) drainage includes vital signs, ensuring patent/intact connections and tubing, and observing the colour and amount of drainage. Option A best captures the objective drainage-system observations. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fractures of the base of the skull will manifest with', 'Hemorrhage from the nose, the pharynx or the ears', 'Cerebrospinal fluid leakage from the ears', 'Bloody spinal fluid', 'Persistent localized pain on swelling', 'A', 'Per Brunner & Suddarth''s, basal skull fractures manifest with bleeding and CSF leakage from the nose (rhinorrhoea), pharynx and ears (otorrhoea), plus Battle''s sign and raccoon eyes. Option A most completely describes the classic bleeding presentation. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The main long-term complication following radical mastectomy is', 'Phantom pain', 'Tingling and numbness', 'Lymphoedema', 'Paralysis', 'C', 'Per Brunner & Suddarth''s, lymphoedema of the affected arm is the main long-term complication after radical mastectomy due to removal of axillary lymph nodes impairing lymphatic drainage.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The accumulation of thick, purulent fluid within the pleural space with fibrin development is characteristic of:', 'Empyema', 'Effusion', 'Pleurisy', 'Emphysema', 'A', 'Per Brunner & Suddarth''s, empyema is the accumulation of thick, purulent fluid within the pleural space, often with fibrin and loculation. Pleural effusion is fluid without pus, pleurisy is inflammation, and emphysema is alveolar destruction.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The anterior posterior fontanelles normally closes at the age of:', '6weeks and 18 weeks respectively', '18 weeks and 6 weeks respectively', '18 months and 6 weeks respectively', '6 months and 18 months respectively', 'B', 'Per Basic Paediatric Protocols/paediatric texts, the posterior fontanelle closes by about 6-8 weeks and the anterior fontanelle much later (around 18 months). Option B is the only choice giving the anterior fontanelle a later closure (18 ''weeks'') than the posterior (6 weeks), so it is the intended best answer; note the correct anterior closure is ~18 months. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When performing Leopold''s maneuver, the purpose of the first maneuver is to determine', 'Fetal part lying in the fundus and presentation', 'Location of fetal back and position', 'Engagement of the presenting part', 'The degree of flexion of fetal head', 'A', 'Per Myles Textbook for Midwives, the first Leopold''s manoeuvre (fundal palpation) determines which fetal pole occupies the fundus, thereby indicating the presentation/lie.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If Mrs. Cola’s menstrual period was on 27.7.08, her expected date of delivery will be:', '3.4.09', '4.5.09', '3.5.09', '4.4.09', 'C', 'Per Naegele''s rule (Myles), EDD = LMP - 3 months + 7 days + 1 year. From 27.7.08: -3 months = 27.4, +7 days = 3.5, +1 year = 3.5.09.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Fetal axis pressure is a physical change that is more significant durin', 'Early stages of labour transmitting the force of contraction to the upper pole of fetus.', 'Second stage of labour when membranes are intact.', 'Active and second stages of labour when membranes are ruptured.', 'Second stage of labour transmitting the force of contraction to the lower pole of the uterus.', 'A', 'Per Myles Textbook for Midwives, fetal axis pressure is the force of the contraction transmitted through the fetal long axis from the upper pole (fundus/breech) down to the presenting part, aiding descent, and is most evident once the membranes rupture in advancing labour. Among the options this best describes fundal transmission to the fetal pole. ⚠ Question may be INCOMPLETE ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('At primary level of ant-retroviral prophylaxis for PMTCT (prevention of mother to child transmission), a HIV-positive woman should take:-', 'Nevirapine 300 mgs at onset of labour', 'Nevirapine 200 mgs at onset of labour', 'Zidovudine 300 mgs 3 hourly for 12 hours.', 'Zidovudine 2mg/ kilogram body weight within three days of delivery', 'B', 'Per Kenya PMTCT guidelines, single-dose intrapartum nevirapine prophylaxis is 200 mg orally to the mother at onset of labour; 300 mg is incorrect dosing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Perineal trauma is common in delivery of face to pubis due to:-', 'Irregular shape of the face as a presenting part.', 'Persistent occipito-posterior position when occiput becomes the leading part.', 'Large presenting mentovertical diameter', 'Large presenting occipito-frontal and biparietal diameters.', 'B', 'Per Myles Textbook for Midwives, face-to-pubis (persistent occipitoposterior delivered with occiput anterior/leading) distends the perineum with the larger presenting diameters, causing severe perineal stretching and trauma. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After birth, the functional closure of ductus arteriosus takes place within:-', '1-2hours.', '2-4 hours', '4-6 hours', '8-15 hours', 'D', 'Per neonatal physiology (Myles/paediatric texts), the ductus arteriosus closes functionally within the first 8-24 hours after birth in response to rising oxygen tension; 8-15 hours best fits this window.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The exogenous causative organisms to puerperal infection include:-', 'Escherichia coli, clostridium welchii.', 'Streptococcus faecalis, haemolytic streptococcus', 'Staphylococcus aureus, Escherichia coli.', 'Haemolytic streptococcus aureus', 'C', 'Per Myles Textbook for Midwives, exogenous (externally introduced) organisms in puerperal sepsis include Staphylococcus aureus and E. coli carried on hands/instruments, whereas endogenous flora arise from the woman''s own tract. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In monitoring fetal well being using the fetal kick chart, you will tell the client to notify you if she counts:-', 'More than 10 movements in 3hours', 'Less than 10 movements in 3hours', 'More than 10 movements per hour', 'Less than 10 movements per hour', 'D', 'Per fetal-wellbeing monitoring (Myles/MOH), reduced fetal movements are a warning sign; the mother is told to report if she counts fewer than the expected movements. Among the options, less than 10 movements per hour is the alerting (reduced) threshold to report. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The hormone that maintains endometrium and stimulates maternal metabolism and development of breast alveoli during pregnancy is:-', 'Human chorionic gonadotropin', 'Human placental lactogen', 'Oestrogen', 'Progesterone', 'C', 'Per Myles Textbook for Midwives, oestrogen maintains the endometrium, stimulates maternal metabolism and promotes growth of the breast ductal/alveolar tissue during pregnancy; progesterone chiefly maintains pregnancy and relaxes smooth muscle. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of superficial thrombophlebitis include:-', 'Local redness and tenderness in a portion of the vein', 'Edema of the ankle and lower leg', 'Pain in the affected leg and foot', 'Positive Homan’s sign', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, superficial thrombophlebitis presents with localized redness, warmth and tenderness along the palpable, cord-like superficial vein; oedema and positive Homan''s sign indicate deep vein thrombosis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Direct causes of placenta abruption include:-', 'Abnormally short umbilical cord, sudden loss of uterine volume', 'Defective vascularization of the deciduas, previous uterine surgery', 'Injury to the abdomen from fall or accident, multiple pregnancy', 'Advanced maternal age, injury to the abdomen from fall or accident', 'C', 'Per Myles Textbook for Midwives, direct/mechanical causes of placental abruption include abdominal trauma and sudden decompression such as after delivery of a first twin (multiple pregnancy); defective decidual vascularization and hypertension are indirect predisposing causes. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Babies born with intrauterine growth retardation are usually prone to;', 'Congenital abnormalities, hyperglycemia', 'Neonatal hyperglcemia, asphyxia', 'Neonatal asphyxia, birth defects', 'Neonatal tetanus, asphyxia', 'C', 'Per Myles Textbook for Midwives and Basic Paediatric Protocols (Kenya), IUGR (small-for-gestational-age) infants are prone to intrapartum/neonatal asphyxia, hypoglycaemia (not hyperglycaemia), and congenital anomalies/birth defects. Options with hyperglycaemia are wrong (SGA babies get HYPOglycaemia); neonatal tetanus relates to unhygienic cord care, not IUGR. So asphyxia plus birth defects is the best pairing.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Benefits of breastfeeding to the infant include:', 'Increased cognitive development, less chances of developing diabetes type 2, less risk of extreme obesity', 'Lowered risk of infection, less likely to become overweight, protection against malignancies', 'Strengthens bonding, protection against malignancies, decreased risk of cardiovascular diseases', 'Reduced risk of metabolic syndrome, lowered risk of developing necrotizing enterocolitis, protection against diabetes type 1', 'B', 'Per WHO/Kenya MOH infant feeding guidelines, breastfeeding lowers infant infection risk, reduces risk of later overweight/obesity, and offers some protection against childhood malignancies. Option A wrongly cites diabetes type 2 for the infant; the best evidence-based cluster of INFANT benefits is B. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following respiratory patterns indicate increased intracranial pressure in the brain stem?', 'Slow, irregular respirations', 'Rapid, shallow respirations’', 'Asymmetric chest excursion', 'Nasal flaring', 'A', 'Per Brunner & Suddarth, brainstem compression from raised ICP produces slow, irregular (e.g., Cheyne-Stokes, ataxic/Biot''s, or apneustic) respiratory patterns as part of Cushing''s response. Rapid shallow breathing, asymmetric excursion and nasal flaring are not the hallmark brainstem pattern of increased ICP.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse administers mannitol to the client with increased intracranial pressure. Which parameter needs close monitoring', 'Muscle relaxation', 'Intake and output', 'Widening of the pulse pressure', 'Pupil dilation', 'B', 'Per Brunner & Suddarth, mannitol is an osmotic diuretic used to reduce ICP; it causes profuse diuresis, so strict intake and output (with fluid/electrolyte and osmolality) monitoring is essential to avoid dehydration and renal compromise. Muscle relaxation, widening pulse pressure and pupil dilation are not the primary parameter tied to the drug''s diuretic action.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('For a client who is experiencing expressive aphasia, which nursing intervention is most helpful in promoting communication?', 'Speaking loudly', 'Using a picture board', 'Writing directions so client can read them', 'Speaking in short sentence ● (6) The nurse is assessing the motor and sensory function of an unconscious client. The nurse should use which technique to test the client’s peripheral response to pain? (A) Sternal rub (B) Nail bed pressure (C) Pressure on the orbital rim - (localizing pain) (D) Squeezing of the sternocleidomastoid muscle', 'B', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, expressive (Broca''s) aphasia means the client understands but cannot produce speech; a picture/communication board lets them convey needs. Speaking loudly (A) is for hearing loss, not aphasia. (Option D text is garbled with a trailing unrelated stem, but B is the best communication aid.) ⚠ Question may be INCOMPLETE', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has a neurological deficit involving the limbic system. On assessment, which finding is specific to this type of deficit?', 'Is disoriented to person, place, and time', 'Affect is flat, with periods of emotional lability', 'Cannot recall what was eaten for breakfast today', 'Demonstrates inability to add and subtract; does not know who is the president of the United States', 'B', 'Per Brunner & Suddarth, the limbic system governs emotion and behaviour, so a deficit produces flat affect and emotional lability. Disorientation, recent-memory loss and impaired calculation/general knowledge point more to cortical/hippocampal or global cognitive dysfunction; altered emotional regulation is specific to the limbic system.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating the status of a client who had a craniotomy 3 days ago. Which assessment finding would indicate that the client is developing meningitis as a complication of surgery?', 'A negative Kernig’s sign', 'Absence of nuchal rigidity', 'A positive Brudzinski’s sign', 'A Glasgow Coma Scale score of 15', 'C', 'Per Brunner & Suddarth, meningitis produces meningeal irritation signs: nuchal rigidity and positive Kernig''s and Brudzinski''s signs. A positive Brudzinski''s sign indicates developing meningitis; a negative Kernig''s, absent nuchal rigidity and a normal GCS of 15 would suggest NO meningitis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with myasthenia gravis has become increasingly weaker. The health care provider prepares to identify whether the client is reacting to an overdose of the medication (cholinergic crisis) or an increasing severity of the disease (myasthenic crisis). An injection of edrophonium is administered. Which finding would indicate that the client is in a cholinergic crisis?', 'No change in the condition', 'Complaints of muscle spasms', 'An improvement of the weakness', 'A temporary worsening of the condition', 'D', 'Per Brunner & Suddarth, in the edrophonium (Tensilon) test, improvement of weakness indicates myasthenic crisis (needs more anticholinesterase), whereas temporary worsening of weakness indicates cholinergic crisis (already too much drug). Hence temporary worsening indicates cholinergic crisis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for the male client who begins to experience seizure activity while in bed. Which of the following actions by the nurse would be contraindicated?', 'Loosening restrictive clothing', 'Restraining the client’s limbs', 'Removing the pillow and raising padded side rails', 'Positioning the client to side, if possible , with the head flexed forward', 'B', 'Per Kozier & Erb''s Fundamentals and Brunner & Suddarth, during a seizure the nurse must NOT restrain the limbs (risks fractures/injury). Correct actions are loosening clothing, removing the pillow and padding side rails, and side-lying with head flexed forward; restraining limbs is contraindicated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A female client has experienced an episode of myasthenic crisis. The nurse would assess whether the client has precipitating factors such as:', 'getting too little exercise', 'taking excess medication - (will cause cholinergic crisis instead)', 'omitting doses of medication', 'increasing intake of fatty foods', 'C', 'Per Brunner & Suddarth, myasthenic crisis is precipitated by under-medication (omitting/missing anticholinesterase doses), infection, stress or surgery. Excess medication causes cholinergic crisis; too little exercise and fatty foods are not precipitants. Thus omitting doses precipitates myasthenic crisis.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A male client is having a tonic-clonic seizures. What should the nurse do first?', 'Elevate the head of the bed', 'Restrain the client’s arms and legs', 'Place a tongue blade in the client’s mouth', 'Take measures to prevent injury', 'D', 'Per Kozier & Erb''s and Brunner & Suddarth, the FIRST priority during a tonic-clonic seizure is to protect the client from injury (ease to the floor/side-lying, clear the area, cushion the head). Do not restrain limbs or insert a tongue blade; elevating the head is not the priority. Injury prevention/safety comes first.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The area of the brain which is involved in the understanding of meaning is:', 'Broca’s area', 'association areas', 'Wernicke area', 'Motor speech area', 'C', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (posterior superior temporal lobe) is responsible for comprehension/understanding of language meaning. Broca''s/motor speech area handles speech production; general association areas integrate information, but understanding of meaning is specifically Wernicke''s area.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Parkinson’s disease , is caused by the degeneration of neurons in an area of the brain called the:', 'Substantia nigra', 'Basal ganglia', 'Cerebellum', 'Corpus callosum', 'A', 'Per Brunner & Suddarth, Parkinson''s disease results from degeneration of dopaminergic neurons in the substantia nigra, reducing dopamine. Although the basal ganglia circuit is affected, the primary site of neuronal degeneration is the substantia nigra.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is unconscious following a tonic-clonic seizure. What should the nurse do FIRST?', 'Place the client in a side-lying position', 'Check the pulse', 'Administer Valium', 'Place a tongue blade in the mouth (Never do this! Places client in danger!)', 'A', 'Per Kozier & Erb''s and Brunner & Suddarth, in the postictal unconscious client the FIRST action is to place them in a side-lying (recovery) position to maintain a patent airway and prevent aspiration. Never insert a tongue blade; pulse check and Valium are not the immediate priority over airway positioning.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse enters the room as the client is beginning to have a tonic-clonic seizure. What action should the nurse implement first?', 'Determine if the client is incontinent of urine or stool.', 'Provide the client with privacy during the seizure.', 'Note the first thing the client does in the seizure.', 'Assess the size of the client’s pupils.', 'C', 'Per Brunner & Suddarth, once safety is ensured the nurse''s key nursing action at seizure onset is accurate observation/documentation, beginning with noting the first thing the client does (onset/aura and initial movements), which aids diagnosis and localization. Checking incontinence, providing privacy and pupil size are secondary to observing the seizure''s onset. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('If a male client experienced a cerebrovascular accident (CVA) that damaged the hypothalamus, the nurse would anticipate that the client has problems with:', 'Thinking and reasoning', 'Body temperature control', 'Balance and equilibrium', 'Visual acuity', 'B', 'The hypothalamus is the principal thermoregulatory centre (also controlling hunger, thirst, and neuroendocrine function). Damage impairs body temperature control. Thinking/reasoning is cortical (frontal), balance is cerebellar, and visual acuity is occipital/optic pathway (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During recovery from a cerebrovascular accident (CVA), a female client is given nothing by mouth, to help prevent aspiration. To determine when the client is ready for a liquid diet, the nurse assesses the client’s swallowing ability once each shift. This assessment evaluates', 'Cranial nerves III and V', 'Cranial nerves IX and X', 'Cranial nerves I and II', 'Cranial nerves VI and VIII', 'B', 'Swallowing (gag reflex) is mediated by the glossopharyngeal (IX) and vagus (X) nerves. Assessing swallowing ability tests these cranial nerves before advancing diet post-CVA (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A male client is admitted with a cervical spine injury sustained during a diving accident. When planning this client’s care, the nurse should assign highest priority to which nursing diagnosis?', 'Disturbed sensory perception (tactile)', 'Self-care deficit: dressing /grooming', 'Impaired physical mobility', 'Ineffective breathing pattern', 'D', 'A cervical (high) spinal cord injury threatens the diaphragm and respiratory muscles (C3-C5 innervate the diaphragm). Airway/breathing is the highest priority per ABC prioritisation; the other diagnoses are important but not immediately life-threatening (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Demyelination is defined as;', 'Loss of an axon in a neuron', 'Loss of dendrites in a neuron', 'Loss of protective sheath surrounding neurons', 'Loss of connective tissue between neurons', 'C', 'Demyelination is the loss/destruction of the myelin sheath surrounding nerve fibres (as in multiple sclerosis), slowing nerve conduction (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Failure of muscle coordination , including unsteady movements and staggering walk, due to disorders in the cerebellum is called?', 'Anoxia', 'Dyslexia', 'Paraplegia', 'Ataxia', 'D', 'Ataxia is impaired muscle coordination causing unsteady, staggering gait, characteristically due to cerebellar dysfunction. Anoxia is oxygen lack, dyslexia is a reading disorder, and paraplegia is lower-limb paralysis (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which part of the brain regulates heartbeat, breathing and other vital functions?', 'Grey matter', 'Brain stem', 'Occipital lobe', 'White matter', 'B', 'The brain stem (specifically the medulla oblongata) contains the cardiac, respiratory, and vasomotor centres regulating heartbeat, breathing and other vital functions (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common complications of spinal cord injury include each of the following EXCEPT?', 'Pressure sores', 'Deep vein thrombosis', 'Diarrhoea', 'Urinary Tract infections', 'C', 'Spinal cord injury commonly causes pressure sores, DVT (from immobility), and UTIs (from neurogenic bladder/catheterisation). Constipation, not diarrhoea, results from neurogenic bowel; thus diarrhoea is the exception (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Broca’s area is located in the', 'Brain stem', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'B', 'Broca''s area (motor speech centre) lies in the inferior frontal lobe of the dominant hemisphere; damage causes expressive (non-fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is located in the', 'Brain stem', 'Parietal lobe', 'Temporal lobe', 'Frontal lobe', 'C', 'Wernicke''s area (receptive/sensory speech centre) is located in the posterior superior temporal lobe of the dominant hemisphere; damage causes receptive (fluent) aphasia (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 60-year-old man complains of extremely severe, sharp, shooting pain in his face. Hee describes the episodes as being “like a bolt of electricity”that is brought about by touching a specific area. Lasta about 60 seconds, and occur many times during the day. Neurologic examination is completely normal but it is noted that part of his face is unshaven because he fears to touch that area. Which on the following is the most appropriate initial treatment?', 'Anticonvulsants', 'Aspirin', 'NSAIDS', 'Vasoconstrictors', 'A', 'The description is classic trigeminal neuralgia (brief, electric-shock-like facial pain triggered by touch). First-line treatment is an anticonvulsant, carbamazepine. Aspirin/NSAIDs and vasoconstrictors are ineffective (Brunner & Suddarth''s Medical-Surgical Nursing; Kenya EML).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following function is controlled by parasympathetic system?', 'Pupil constriction', 'Acceleration of heart beat', 'Stimulation of sweat glands', 'Contraction of hair muscles', 'A', 'Parasympathetic (rest-and-digest) stimulation causes pupil constriction (miosis), slows the heart, and reduces secretions. Acceleration of heart rate, sweating, and pilo-erection are sympathetic responses (Kozier & Erb''s Fundamentals; Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('You are caring for a woman in the second stage of labor. The client is experiencing uterine contractions every 2 minutes and cries out in pain with each contraction. This behaviour is best described as:', 'Exhaustion', 'Fear of losing control', 'Involuntary grunting', 'Valsalva''s maneuver', 'B', 'Crying out in pain with each contraction during transition reflects fear of losing control, a recognised psychological response requiring reassurance and support. It is not exhaustion, involuntary grunting (an urge to push), or Valsalva (Myles Textbook for Midwives). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman who is gravida 1, para 0 is admitted in active labour. Her cervix is 100% effaced, and she is dilated to 3 cm. The presenting part is at +1 station. The midwife is aware that the fetus'' head is:', 'Not yet engaged', 'Entering the pelvic inlet', 'Below the ischial spines', 'Visible at the vaginal opening', 'C', 'Station is measured relative to the ischial spines (station 0). A presenting part at +1 station is 1 cm below the ischial spines (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mrs. Peters is experiencing contractions every 2 minutes. She is in which stage of birth?', 'First', 'Second', 'Third', 'Fourth', 'A', 'Contractions every 2 minutes without further data indicate established/active first stage of labour (cervical dilatation). The stem gives no evidence of full dilatation or delivery, so it is the first stage (Myles Textbook for Midwives). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When resuscitating a neonate who has neonatal asphyxia after how long should the midwife use ambubag', 'After 30 seconds of oxygen by face mask', 'When the baby remains apnoeic after 30 minutes of facemask oxygen therapy.', 'When the neonate is no longer cyanosed', 'When the neonate P02 level has increased', 'A', 'In neonatal resuscitation, if the baby is not breathing adequately after the initial steps, positive-pressure ventilation with a bag-and-mask (ambubag) is started within about 30 seconds (''the golden minute''). The 30-minute option is clearly wrong (Kenya Basic Paediatric Protocols; WHO/HBB neonatal resuscitation).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which neonate from the listed below is at risk of developing severe jaundice?', 'Breast feed neonates', 'Conjoined twins', 'Neonates with haemorrhagic conditionsions', 'Term neonates', 'C', 'Extravascular blood breakdown (cephalhaematoma, bruising, haemorrhage) increases the bilirubin load and predisposes to severe jaundice. Term neonates and normal breastfeeding are not high-risk to the same degree (Kenya Basic Paediatric Protocols; Myles Textbook for Midwives). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most appropriate feature seen in symmetric growth retarded infant?', 'Weight is depressed more than length or head circumference.', 'Fetal growth retardation probably has occurred in the last trimester of pregnancy.', 'Weight, length and head circumference are below normal and babies look like miniature normal babies.', 'It is mostly linked with cigarette smoking.', 'C', 'Symmetric (early-onset) IUGR affects weight, length and head circumference proportionately, producing a proportionately small (''miniature normal'') infant. Asymmetric IUGR (late trimester, spares head, linked to smoking) is described by the other options (Myles Textbook for Midwives; Basic Paediatric Protocols).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A new born infant was delivered in your maternity unit an hour ago. The skin of this infant appears to be red, wrinkly with ribs visible under the skin. When was the infant probably born?', 'Before 24 and 27 weeks', 'Before 30 and 32 weeks', 'Before 29 and 32 weeks', 'Around 35 weeks', 'D', 'Red, wrinkled, thin skin with visible ribs but delivered surviving in a maternity unit fits a moderately preterm infant around 35 weeks; extreme prematurity (24-27 weeks) skin is gelatinous/translucent. Of the options, ~35 weeks best matches the described appearance and survival (Myles Textbook for Midwives; Basic Paediatric Protocols). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which statement is true about meconium?', 'Meconium is 1st found in the foetal ileum between the 20th and 26th weeks of gestation', 'Meconium passage is uncommon before 36 weeks but its common in pregnancies beyond 42 weeks', 'In utero passage of meconium is common because the anal sphincter tone is poor', 'All of the above', 'D', 'Meconium first forms in the fetal ileum around 20-26 weeks, its passage in utero is uncommon before 36 weeks but rises in post-term (over 42 weeks) pregnancies, and passage relates to gut maturation/hypoxia. All statements are correct, so ''All of the above'' applies (Myles Textbook for Midwives).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is NOT diagnostic of twin to twin transfusion?', 'Both are of same sex', 'It results from venous communication of both foetuses', 'Both are of different growth', 'Both are of different amniotic fluid.', 'C', 'Twin-to-twin transfusion syndrome (TTTS) occurs in monochorionic (same-sex) twins from placental vascular anastomoses, causing discordant growth and amniotic fluid (oligo/polyhydramnios). Discordant growth is a FEATURE, not a non-diagnostic finding as the negatively worded question implies; however discordant growth alone is non-specific whereas monochorionicity and vascular communication are the defining criteria. The item asks which is NOT diagnostic; different growth is the least specific defining criterion of the listed features. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A twin pregnancy is identified at 12 weeks gestation on antenatal ultrasound. One placenta and one amnion sac are identified. What would be the probable cause?', 'ICSI with single embryo transfer', 'Ovulation induction', 'Maternal age over 35 years', 'Family history of multiple pregnancies', 'B', 'One placenta with one amniotic sac indicates monochorionic monoamniotic (monozygotic) twinning, which arises from splitting of a single fertilized ovum. Of the listed causes, ovulation induction is a recognised association with (predominantly dizygotic) multiple pregnancy; ICSI single-embryo transfer, maternal age and family history relate mainly to dizygotic twinning, so ovulation induction is the closest predisposing factor listed. ⚠ Best answer not clearly among choices ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following BEST describes a third degree perinea! tear?', 'Injury to perineum involving perineal muscles', 'Injury to perineal! skin, includes the fourchette, the hymen, labia and vaginalmucosa', 'Injury to perineum involving anal sphincter complex and anal epithelium', 'Injury to perineum involving the anal sphincter complex', 'C', 'Per Myles Textbook for Midwives (RCOG classification adopted in Kenya): 1st degree = skin/mucosa only, 2nd = perineal muscles, 3rd = anal sphincter complex, 4th = sphincter complex PLUS anal/rectal epithelium. Option C best captures a third-degree tear extending through the sphincter complex to the anal epithelium (option D describing only the sphincter is less complete for the best answer). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which ONE of the following IS NOT a precaution for tocolytics?', 'Measure blood pressure hourly', 'Give one tocolytic agent at a time', 'Do not give tocolytics to women with heart rate greater than or equal to 120 beats per minute', 'Auscultate the mother''s lungs every 2 hours', 'D', 'Per MOH/Myles tocolysis precautions: monitor BP, give a single agent, and withhold beta-agonist tocolytics if maternal HR ≥120 bpm; lung auscultation for pulmonary oedema is done more frequently than 2-hourly (typically hourly/with each observation), so a 2-hourly interval is NOT an adequate stated precaution. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Causes of primary amenorrhea include:-', 'Gonadal dysgenesis, premature ovarian failure, asherman’s syndrome.', 'Sheehan’s syndrome, gonadal dysgenesis, imperforate hymen.', 'Androgen insensitivity, gonadal dysgenesis, imperforate hymen.', 'Polycystic ovarian syndrome, sheehan’s syndrome, gonadal dysgenesis.', 'C', 'Per gynaecology texts (Myles/standard), primary amenorrhoea causes include androgen insensitivity, gonadal dysgenesis (Turner) and outflow obstruction like imperforate hymen. Asherman''s and Sheehan''s cause SECONDARY amenorrhoea, excluding options A, B and D.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Wernicke area is in the;', 'Occipital lobe', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'D', 'Per neuroanatomy (Brunner & Suddarth), Wernicke''s area (receptive/comprehension speech) lies in the posterior superior temporal lobe of the dominant hemisphere.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bell’s palsy involves the following cranial nerve', 'VIII', 'VII', 'V', 'II', 'B', 'Per Brunner & Suddarth, Bell''s palsy is an acute peripheral paralysis of cranial nerve VII (facial nerve), causing unilateral facial weakness.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is true regarding Hashimoto thyroiditis', 'Is an autoimmune disease, causes primary hypothyroidism', 'Is an autoimmune disease, causes primary hyperthyroidism', 'Results in goiter, causes exophthalmos', 'More common in women, there is an increase in TH levels.', 'A', 'Per Brunner & Suddarth, Hashimoto thyroiditis is an autoimmune destruction of the thyroid causing primary HYPOthyroidism. Exophthalmos and hyperthyroidism belong to Graves'' disease, excluding B and C.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When estimating the size of burns, the palm of the patient’s hand represents body surface area of;', '3%', '1%', '4.5%', '9%', 'B', 'Per Brunner & Suddarth and burn assessment guidelines, the patient''s palm (palmar surface including fingers) represents approximately 1% of total body surface area, used to estimate scattered burns.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client complains of decreasing peripheral vision and halos around lights. These manifestations are characteristics of;', 'Retinal detachment', 'Open-angle glaucoma', 'Cataract', 'Macular degeneration', 'B', 'Per Brunner & Suddarth, chronic open-angle glaucoma causes gradual loss of peripheral (tunnel) vision and haloes around lights from raised intraocular pressure. Cataract causes cloudy vision and detachment causes flashes/curtain, not this pattern.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During chest auscultation of a patient, which findings will indicate that the patient has cardiac condition and cannot be felt in a normal person', 'S1, S3 , Murmurs', 'S1, S2, Negative Murmurs,', 'S3, S4, Murmurs', 'S3, S1,S2', 'C', 'Per Brunner & Suddarth''s Med-Surg Nursing, S1 and S2 are normal heart sounds heard in healthy people; extra sounds S3 (in adults) and S4, together with murmurs, indicate cardiac pathology and are not normally audible in a healthy adult. Options containing S1/S2 are normal findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An elderly client has severe xerosis. What topic should be included in your teaching plan?', 'Maintain a warm environment', 'Take a hot bath everyday', 'C . Apply skin lotions after a bath', 'Use fabric softeners when laundering clothing', 'C', 'Per Kozier & Erb''s Fundamentals of Nursing, xerosis (dry skin) is managed by applying emollient lotion after bathing to seal moisture; hot baths and fabric softeners worsen dryness and irritation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Gerontological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While providing care to an old woman with a cast on her lower arm (from below the elbow the elbow to above the fingers) you perform a neurovascular assessment. What is the possible complication?', 'Slightly edematous fingers', 'Warm, pink skin above the cast', 'Pale, cold fingers', 'Pain rating of 2 on a 1 to 10 scale', 'C', 'Per Brunner & Suddarth neurovascular (5 P''s) assessment, pale and cold fingers indicate impaired circulation/compartment compromise distal to the cast — a serious complication. Slight edema, warm pink skin and mild pain of 2/10 are expected, non-alarming findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient becomes restless and tells you she has a headache and feels nauseous during hemodialysis. Which complication do you suspect?', 'Infection', 'Disequilibrium syndrome', 'Air embolism', 'Acute hemolysis', 'B', 'Per Brunner & Suddarth renal nursing, dialysis disequilibrium syndrome presents with restlessness, headache, nausea/vomiting and confusion from rapid osmotic shifts during hemodialysis. Air embolism causes dyspnea/chest pain, and acute hemolysis causes back pain and hypotension.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A classification of ringworm that infect the finger nails is:-', 'Tinea coporis', 'Tinea unguium', 'Tinea cruris', 'Tinea pedis', 'B', 'Per standard microbiology/dermatology texts, tinea unguium (onychomycosis) is the dermatophyte infection of the nails. Tinea corporis affects the body, tinea cruris the groin, and tinea pedis the feet.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A patient with potassium levels in excess of 5.0 mEq/L is considered to be in a state of :-', 'Hypernatremia', 'Hypercalcemia', 'Hypervolemia', 'D . Hyperkalemia', 'D', 'Per Brunner & Suddarth and normal electrolyte values, a serum potassium above the normal 3.5–5.0 mEq/L range defines hyperkalemia. The other options refer to sodium, calcium and fluid volume, not potassium.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antihistamines are indicated in the management of vertigo because they:', 'Sedate the client', 'Activate the vestibular system', 'Suppress the vestibular system', 'Suppress the cochlear system', 'C', 'Per Kenya EML/BNF and Brunner & Suddarth, antihistamines (e.g. cinnarizine, promethazine, meclizine) relieve vertigo by suppressing vestibular over-activity and the vomiting centre. Sedation is a side effect, not the therapeutic mechanism, and they do not activate the vestibular system.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clinical features of hydatidiform mole include;', 'Positive pregnancy test of urine diluted to 1:100 after4 weeks of amenorrhea, ultrasound shows features of fetus.', 'Amenorrhea followed by vomiting, breast changes.', 'Uterus larger than dates ,chronic gonadotropin hormone in urine increase', 'Amenorrhea followed by intermittent bleeding, fetus demonstrated in x-ray.', 'C', 'Per Myles Textbook for Midwives, hydatidiform mole classically presents with a uterus larger than expected for gestational age and markedly raised hCG, plus a ''snowstorm'' ultrasound with NO fetus. Options showing a demonstrable fetus are therefore incorrect.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The aorta divides at the level of the 4th lumbar vertebra into;', 'external &internal iliac arteries', 'superior & inferior mesenteric arteries', 'common iliac arteries', 'lumbar arteries', 'C', 'Per standard anatomy (Gray''s/Kozier), the abdominal aorta bifurcates at the level of the 4th lumbar vertebra into the right and left common iliac arteries, which subsequently divide into external and internal iliac arteries.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Pleural effusion is a complication of;', 'Heart failure, nephritic syndrome, pulmonary tuberculosis', 'Pneumonia,upper respiratory infections, post thoracotomy', 'Penetrating chest trauma,bronchitis,haematogenous infection of the pleural space', 'Pulmonary embolism, lung cancer, post thoracentesis', 'A', 'Per Brunner & Suddarth, pleural effusion complicates heart failure and nephrotic/nephritic syndrome (transudative from raised hydrostatic or low oncotic pressure) and pulmonary tuberculosis (exudative) — all well-recognised causes. This option best captures classic effusion-causing conditions. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Early complication of fractures include;', 'Shock, vascular necrosis.', 'Reaction to internal fixation device, deep venous thrombosis', 'Compartment syndrome, fat embolism.', 'Complex regional pain syndrome, infection.', 'C', 'Per Brunner & Suddarth orthopaedic nursing, early complications of fractures include shock, fat embolism, compartment syndrome and DVT. Option C (compartment syndrome and fat embolism) lists two classic EARLY complications, whereas avascular necrosis, CRPS and hardware reaction are late/delayed complications. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Angiotensin-converting enzyme (ACE)inhibitors;', 'Inhibit conversion of angitensinogen to angiotensin I.', 'Block receptors from binding angiotensin II.', 'Inhibit conversion of angiotensin I to angiotensin II.', 'Block angiotensin I receptor sites. C C', 'C', 'Per Brunner & Suddarth''s Med-Surg pharmacology, ACE inhibitors block the angiotensin-converting enzyme, preventing conversion of angiotensin I to the potent vasoconstrictor angiotensin II. Blocking angiotensin II receptors (B) describes ARBs, not ACE inhibitors.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('After a barium enema a nurse should,', 'Keep the patient NPO for 8 hours to rest the bowel', 'Advise the patient that his/her stool will be radioactive', 'Encourage the patient to increase his fluid intake', 'Advise the patient to avoid abdominal exercises for at least 1 week C C', 'C', 'Per Kozier & Erb''s Fundamentals, after a barium enema fluids and often a mild laxative are given to promote elimination of retained barium and prevent constipation/impaction. Barium is inert and not radioactive (B).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Passive range of motion exercises;', 'Are performed to prevent nosocomial infections.', 'Helps to prevent joints rigidity and contractures.', 'Is a collaborative intervention that requires a surgeon and a nurse.', 'Are repeated 5-6 times a day to enhance quick recovery. D B', 'B', 'Per Kozier & Erb''s Fundamentals, passive ROM exercises maintain joint mobility and prevent stiffness and contractures in patients unable to move independently. They do not prevent infections (A).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The Korotkoff sounds heard while measuring blood pressure present in the order of,', 'Tapping, Swishing, Knocking, muffling and silence', 'Swishing, Tapping, Silence, muffling and knocking', 'Knocking, Tapping, Swishing, muffling, silence', 'Silence, Tapping, Knocking, Swishing and Muffling B A', 'A', 'Per Kozier & Erb''s, the five Korotkoff phases occur in order: sharp tapping (Phase I, systolic), swishing/murmur (Phase II), knocking (Phase III), muffling (Phase IV), then silence/disappearance (Phase V, diastolic).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Reed Sternberg cell is a pathologic hallmark essential in diagnosis of:-', 'Hodgkin’s disease', 'Acute myeloid leukemia', 'Chronic lymphocytic leukemia', 'Non-hodgkin disease', 'A', 'Per Brunner & Suddarth, the Reed-Sternberg cell is the pathognomonic hallmark used to diagnose Hodgkin''s lymphoma. It is absent in non-Hodgkin lymphoma and the leukemias.', 'KRCHN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Atherosclerosis impedes coronary blood flow by the following mechanisms', 'Plaques obstructs the vein', 'Plaques obstruct the artery', 'Blood clots from outside the vessel wall', 'Hardened vessels dilate to allow the blood to flow through B B', 'B', 'Per Brunner & Suddarth, atherosclerosis is the accumulation of lipid plaques within the coronary arteries, narrowing the lumen and impeding arterial blood flow to the myocardium.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The most appropriate nursing action when a client begins to cough and has difficulty breathing during nasogastric tube insertion is;', 'Inserting the tube quickly', 'Notifying the physician immediately', 'Removing the tube and reinserting when the respiratory distress subsides', 'Pulling the tube back a little and wait until the respiratory distress subsides D D', 'D', 'Per Kozier & Erb''s, coughing and dyspnea during NG insertion suggest the tube has entered the airway; the nurse should withdraw the tube slightly and pause until distress resolves before advancing again. Continuing to insert (A) risks tracheal placement.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An 11-month-old infant with dehydration and metabolic acidosis is likely to present with;', 'A decreased platelet count', 'Shallow respirations', 'Tachypnea', 'A reduced white blood cell count B C', 'C', 'Per Kenya Basic Paediatric Protocols, metabolic acidosis triggers compensatory respiratory response producing deep, rapid breathing (tachypnea/Kussmaul respirations) to blow off CO2, not shallow respirations (B).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The expected outcomes for a patient who has “potential for impaired gas exchange related to fluid overload” is;', 'No shortness of breath, scaphoid abdomen.', 'Chest X-ray normal, improved gas exchange.', 'Respiratory rate less than 20breaths/min, skin colour normal.', 'Heart rate less than 100 beats/min, increased urine output B D', 'C', 'Per Kozier & Erb''s, expected outcomes for impaired gas exchange are measurable normal respiratory function: respiratory rate <20/min and normal (pink) skin colour indicating adequate oxygenation. This directly reflects resolved gas-exchange impairment better than urine output (D).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Fluid and Electrolyte Balance', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During Lumbar puncture, a needle is inserted in the space between;-', 'Fifth and sixth thoracic vertebrae.', 'Fourth and fifth thoracic vertebrae', 'Third and fourth lumbar vertebrae.', 'First and second lumbar vertebrae C C', 'C', 'Per Brunner & Suddarth, lumbar puncture is performed below the spinal cord''s end (L1-L2), typically in the L3-L4 (or L4-L5) interspace to avoid cord injury. Thoracic sites (A, B) are unsafe.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The condition in which the eyeballs are not properly aligned with each other is referred to as;', 'Astigmatism', 'Strabismus', 'Presbyopia', 'Amblyopia', 'B', 'Per standard ophthalmic nursing (Brunner & Suddarth), strabismus is misalignment of the eyes so that they do not point in the same direction. Astigmatism is refractive error, presbyopia is age-related near-vision loss, and amblyopia is ''lazy eye''.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a client with possible Cushing’s syndrome you would expect to find;', 'Hypotension', 'Thick coarse skin', 'Deposits of adipose tissue in the trunk', 'Weight loss', 'C', 'Per Brunner & Suddarth, Cushing''s syndrome (cortisol excess) causes central (truncal) obesity, moon face, and buffalo hump. It produces hypertension, thin fragile skin, and weight gain—not hypotension or weight loss.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When administering an enema;', 'The client should lie in the right lateral position.', 'The enema tube should be inserted 8 inches into the clients’ rectum.', 'The client should be advised to retain the enema for 30 minutes.', 'The nurse should position the client in left lateral position', 'D', 'Per Kozier & Erb''s, an enema is administered with the client in the left lateral (Sims'') position to follow the natural curve of the sigmoid colon. Insertion depth for adults is about 3-4 inches, not 8 (B).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The 6-month-old client with a ventral septal defect is receiving Digitalis for regulation of his heart rate. Which finding should be reported to the doctor?', 'Blood pressure of 126/80', 'Blood glucose of 110 mg/dL', 'Heart rate of 60 bpm', 'Respiratory rate of 30 per minute', 'C', 'Per Kenya Basic Paediatric Protocols and Brunner & Suddarth, digoxin is withheld and the physician notified when the infant''s apical heart rate is below 90-100 bpm; a rate of 60 bpm signals bradycardia and possible digitalis toxicity in a 6-month-old.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is instructed regarding foods that are low in fat and cholesterol. Which diet selection is lowest in saturated fats?', 'Macaroni and cheese', 'Shrimp with rice', 'Turkey breast', 'Spaghetti', 'C', 'Per Brunner & Suddarth''s cardiac/lipid-lowering diet teaching, skinless white poultry (turkey breast) is lowest in saturated fat. Macaroni and cheese is high in dairy saturated fat, shrimp is high in cholesterol.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is admitted with left-sided congestive heart failure. In assessing the client for edema, the nurse should check the:', 'Feet', 'Neck', 'Hands', 'Sacrum', 'D', 'Per Brunner & Suddarth''s, dependent edema collects in the sacrum in a bedbound/supine client, making it the best site to assess in hospitalized CHF patients; feet edema is checked in ambulatory clients.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is checking the client’s central venous pressure. The nurse should place the zero of the manometer at the:', 'Phlebostatic axis', 'PMI', 'Erb’s point', 'Tail of Spence', 'A', 'Per Brunner & Suddarth''s critical care nursing, the zero reference of the manometer/transducer for CVP is levelled at the phlebostatic axis (4th intercostal space, mid-anteroposterior chest) to align with the right atrium.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The best method of evaluating the amount of peripheral edema is:', 'Weighing the client daily', 'Measuring the extremity', 'Measuring the intake and output', 'Checking for pitting', 'B', 'Per Kozier & Erb''s, measuring the circumference of the affected extremity with a tape at a marked point gives the most objective, reproducible measure of localized peripheral edema; daily weight best reflects generalized fluid, and pitting is only a graded estimate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with vaginal cancer is being treated with a radioactive vaginal implant. The client’s husband asks the nurse if he can spend the night with his wife. The nurse should explain that:', 'Overnight stays by family members is against hospital policy.', 'There is no need for him to stay because staffing is adequate.', 'His wife will rest much better knowing that he is at home.', 'Visitation is limited to 30 minutes when the implant is in place.', 'D', 'Per Brunner & Suddarth''s radiation-safety (time-distance-shielding) principles, visitors of a client with a sealed radioactive implant are restricted in time (about 30 minutes) and distance; overnight stays are unsafe due to radiation exposure.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client hospitalized with a facial stroke. Which diet selection would be suited to the client?', 'Roast beef sandwich, potato chips, pickle spear, iced tea', 'Split pea soup, mashed potatoes, pudding, milk', 'Tomato soup, cheese toast, Jello, coffee', 'Hamburger, baked beans, fruit cup, iced tea', 'B', 'Per Brunner & Suddarth''s stroke/dysphagia management, soft, cohesive, easily swallowed foods (soup, mashed potatoes, pudding) are safest; dry, crumbly or hard items (sandwich, chips, toast) increase aspiration risk with facial weakness.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with leukemia is receiving Trimetrexate. After reviewing the client’s chart, the physician orders Wellcovorin (leucovorin calcium). The rationale for administering leucovorin calcium to a client receiving Trimetrexate is to:', 'Treat iron-deficiency anemia caused by chemotherapeutic agents', 'Create a synergistic effect that shortens treatment time', 'Increase the number of circulating neutrophils', 'Reverse drug toxicity and prevent tissue damag e', 'D', 'Per Brunner & Suddarth''s/oncology pharmacology, leucovorin (folinic acid) ''rescue'' bypasses the folate-antagonist block of antimetabolites like trimetrexate, reversing toxicity to normal cells and preventing tissue damage.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 4-month-old is brought to the well-baby clinic for immunization. In addition to the DPT and polio vaccines, the baby should receive:', 'HibTITER', 'Mumps vaccine', 'Hepatitis B vaccine', 'MMR', 'A', 'Per the Kenya KEPI immunization schedule, Haemophilus influenzae type b (given here as HibTITER, now within pentavalent) is due at 6, 10 and 14 weeks; MMR/mumps are not given until 9 months or later. Hepatitis B is included in pentavalent, but Hib is the specific additional antigen expected with DPT/polio at this visit.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client is seen in the clinic for treatment of migraine headaches. The drug Imitrex (sumatriptan succinate) is prescribed for the client. Which of the following in the client’s history should be reported to the doctor?', 'Diabetes', 'Prinzmetal’s angina', 'Cancer', 'Cluster headaches', 'B', 'Per Kenya EML/BNF, sumatriptan is a 5-HT1 agonist that causes vasoconstriction and is contraindicated in ischaemic/vasospastic heart disease such as Prinzmetal''s (variant) angina, so this history must be reported.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with suspected meningitis is admitted to the unit. The doctor is performing an assessment to determine meningeal irritation and spinal nerve root inflammation. A positive Kernig’s sign is charted if the nurse notes:', 'Pain on flexion of the hip and knee', 'Nuchal rigidity on flexion of the neck', 'Pain when the head is turned to the left side', 'Dizziness when changing positions', 'A', 'Per Brunner & Suddarth''s neurologic assessment, a positive Kernig''s sign is pain/resistance on extending the knee when the hip and knee are flexed; nuchal rigidity on neck flexion describes Brudzinski''s sign.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with Alzheimer’s disease is being assisted with activities of daily living when the nurse notes that the client uses her toothbrush to brush her hair. The nurse is aware that the client is exhibiting:', 'Agnosia', 'Apraxia', 'Anomia', 'Aphasia', 'B', 'Per Brunner & Suddarth''s, apraxia is the inability to carry out purposeful, learned motor tasks correctly (e.g., using a toothbrush on the hair); agnosia is failure to recognize objects, aphasia is a language deficit.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted to the labor and delivery unit in active labor. During examination, the nurse notes a papular lesion on the perineum. Which initial action is most appropriate?', 'Document the finding', 'Report the finding to the doctor', 'Prepare the client for a C-section', 'Continue primary care as prescribed', 'B', 'Per Kenya maternal/newborn and STI guidelines, a genital lesion in a laboring woman may be active herpes/an infectious lesion posing vertical-transmission risk; the nurse must report it to the doctor so mode of delivery can be decided, rather than merely documenting.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 15-year-old primigravida is admitted with a tentative diagnosis of HELLP syndrome. Which laboratory finding is associated with HELLP syndrome?', 'Elevated blood glucose', 'Elevated platelet count', 'Elevated creatinine clearance', 'Elevated hepatic enzymes', 'D', 'Per Myles Textbook for Midwives, HELLP = Hemolysis, Elevated Liver enzymes, Low Platelets; thus elevated hepatic enzymes is the associated finding, and platelet count is decreased (not elevated).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assessing the deep tendon reflexes of a client with preeclampsia. Which method is used to elicit the biceps reflex?', 'The nurse places her thumb on the muscle inset in the antecubital space and taps the thumb briskly with the reflex hammer.', 'The nurse loosely suspends the client’s arm in an open hand while tapping the back of the client’s elbow.', 'The nurse instructs the client to dangle her legs as the nurse strikes the area below the patella with the blunt side of the reflex hammer.', 'The nurse instructs the client to place her arms loosely at her side as the nurse strikes the muscle insert just above the wrist.', 'A', 'Per Kozier & Erb''s/physical assessment technique, the biceps reflex is elicited by placing the thumb over the biceps tendon in the antecubital fossa and striking the thumb with the reflex hammer.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida with diabetes is admitted to the labor and delivery unit at 34 weeks gestation. Which doctor’s order should the nurse question?', 'Magnesium sulfate 4gm (25%) IV', 'Brethine 10 mcg IV', 'Stadol 1 mg IV push every 4 hours as needed prn for pain', 'Ancef 2gm IVPB every 6 hours', 'B', 'Per Kenya maternal care/pharmacology, terbutaline (Brethine) is a beta-agonist tocolytic that causes hyperglycaemia and should be questioned in a diabetic; the usual dose is ~0.25 mg subcutaneously, so an IV ''10 mcg'' order is also questionable. Magnesium sulfate, Stadol and Ancef are appropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A diabetic multigravida is scheduled for an amniocentesis at 32 weeks gestation to determine the L/S ratio and phosphatidylglycerol level. The L/S ratio is 1:1 and the presence of phosphatidylglycerol is noted. The nurse’s assessment of this data is:', 'The infant is at low risk for congenital anomalies.', 'The infant is at high risk for intrauterine growth retardation.', 'The infant is at high risk for respiratory distress syndrome.', 'The infant is at high risk for birth trauma.', 'C', 'Per Myles Textbook for Midwives, fetal lung maturity requires an L/S ratio of at least 2:1; a 1:1 ratio indicates immature lungs and high risk for respiratory distress syndrome. In diabetic pregnancies phosphatidylglycerol is the more reliable maturity marker, but the low L/S here signals RDS risk.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has cancer of the pancreas. The nurse should be most concerned about which nursing diagnosis?', 'Alteration in nutrition', 'Alteration in bowel elimination', 'Alteration in skin integrity', 'Ineffective individual coping', 'A', 'Pancreatic cancer severely impairs exocrine enzyme secretion and, with anorexia, cachexia and obstruction, causes profound malnutrition and weight loss; nutrition is the priority concern (Brunner & Suddarth''s Medical-Surgical Nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting an 18-year-old with osteogenesis imperfecta. Which information obtained on the visit would cause the most concern? The client:', 'Likes to play football', 'Drinks several carbonated drinks per day', 'Has two sisters with sickle cell tract', 'Is taking acetaminophen to control pain', 'A', 'Osteogenesis imperfecta causes brittle bones prone to fracture; contact sports such as football pose the greatest injury risk and cause most concern (Brunner & Suddarth''s, musculoskeletal disorders).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse working the organ transplant unit is caring for a client with a white blood cell count of 450. During evening visitation, a visitor brings a basket of fruit. What action should the nurse take?', 'Allow the client to keep the fruit', 'Place the fruit next to the bed for easy access by the client', 'Offer to wash the fruit for the client', 'Tell the family members to take the fruit home', 'D', 'A WBC of 450 indicates severe neutropenia; fresh fruit harbours bacteria/fungi and is contraindicated in neutropenic precautions, so it should be removed (Brunner & Suddarth''s, neutropenic care / IPC principles).', 'KRCHN', 'Paper I', 'Anatomy & Physiology', 'Anatomy and Physiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted 2 days earlier that a lung resection accidentally pulls out the chest tube. Which action by the nurse indicates understanding of the management of chest tubes?', 'Order a chest x-ray', 'Reinsert the tube', 'Cover the insertion site with a Vaseline gauze', 'Call the doctor', 'C', 'An accidentally dislodged chest tube requires immediate application of an occlusive (Vaseline) dressing to prevent air entry and tension pneumothorax, then notify the physician (Brunner & Suddarth''s, chest drainage management).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client being treated with sodium warfarin has a Protime of 120 seconds. Which intervention would be most important to include in the nursing care plan?', 'Assess for signs of abnormal bleeding', 'Anticipate an increase in the Coumadin dosage', 'Instruct the client regarding the drug therapy', 'Increase the frequency of neurological assessments', 'A', 'A Protime of 120 seconds is grossly prolonged, indicating warfarin over-anticoagulation and high bleeding risk; the priority is to assess for abnormal bleeding (Brunner & Suddarth''s / Kenya EML anticoagulant monitoring).', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which selection would provide the most calcium for the client who is 4 months pregnant?', 'A granola bar', 'A bran muffin', 'A cup of yogurt', 'A glass of fruit juice', 'C', 'Yogurt is a dairy product and the richest calcium source among the options, important for the increased calcium demand in pregnancy (Kozier & Erb''s Fundamentals; Kenya maternal nutrition guidelines).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 6-year-old client is admitted to the unit with a hemoglobin of 6g/dL. The physician has written an order to transfuse 2 units of whole blood. When discussing the treatment, the child’s mother tells the nurse that she does not believe in having blood transfusions and that she will not allow her child to have the treatment. What nursing action is most appropriate?', 'Ask the mother to leave while the blood transfusion is in progress', 'Encourage the mother to reconsider', 'Explain the consequences without treatment', 'Notify the physician of the mother’s refusal', 'D', 'When a parent refuses treatment for a minor, the nurse cannot coerce or force treatment; the appropriate action is to notify the physician so legal/ethical processes can follow (Professional ethics & law; Kozier & Erb''s on informed consent/refusal).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is evaluating nutritional outcomes for a with anorexia nervosa. Which data best indicates that the plan of care is effective?', 'The client selects a balanced diet from the menu.', 'The client’s hemoglobin and hematocrit improve.', 'The client’s tissue turgor improves.', 'The client gains weight.', 'D', 'In anorexia nervosa the primary nutritional goal is restoration of body weight; weight gain is the best objective indicator that the nutritional plan is effective (Brunner & Suddarth''s / mental health nursing).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 43-year-old African American male is admitted with sickle cell anemia. The nurse plans to assess circulation in the lower extremities every 2 hours. Which of the following outcome criteria would the nurse use?', 'Body temperature of 37.2 celsius or less', 'Toes moved in active range of motion', 'Sensation reported when soles of feet are touched', 'Capillary refill of < 3 seconds', 'D', 'In sickle cell anemia, monitoring peripheral circulation is best evaluated by capillary refill; a refill under 3 seconds is the outcome criterion indicating adequate lower-extremity perfusion (Brunner & Suddarth''s, haematologic disorders).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 30-year-old male from Haiti is brought to the emergency department in sickle cell crisis. What is the best position for this client?', 'Side-lying with knees flexed', 'Knee-chest', 'High Fowler''s with knees flexed', 'Semi-Fowler''s with legs extended on the bed', 'D', 'In sickle cell crisis, positions that flex joints and impede circulation are avoided; semi-Fowler''s with legs extended promotes comfort, oxygenation and unrestricted circulation (Brunner & Suddarth''s, sickle cell crisis management).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 25-year-old male is admitted in sickle cell crisis. Which of the following interventions would be of highest priority for this client?', 'Taking hourly blood pressures with mechanical cuff', 'Encouraging fluid intake of at least 200mL per hour', 'Position in high Fowler''s with knee gatch raised', 'Administering Tylenol as ordered', 'B', 'Hydration is the highest priority in sickle cell crisis because it reduces blood viscosity, promotes circulation and limits further sickling and vaso-occlusion (Brunner & Suddarth''s, sickle cell crisis).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following foods would the nurse encourage the client in sickle cell crisis to eat?', 'Peaches', 'Cottage cheese', 'Popsicle', 'Lima beans', 'C', 'Fluid intake is essential in sickle cell crisis; a popsicle provides additional fluids to support hydration and reduce sickling, making it the best choice to encourage (Brunner & Suddarth''s, sickle cell crisis hydration).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A newly admitted client has sickle cell crisis. The nurse is planning care based on assessment of the client. The client is complaining of severe pain in his feet and hands. The pulse oximetry is 92. Which of the following interventions would be implemented first? Assume that there are orders for each intervention.', 'Adjust the room temperature', 'Give a bolus of IV fluids', 'Start O2', 'Administer meperidine (Demerol) 75mg IV push', 'C', 'With a pulse oximetry of 92 and vaso-occlusive pain, correcting hypoxia by starting oxygen is implemented first to reduce further sickling, following the ABC priority (Brunner & Suddarth''s, sickle cell crisis oxygenation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is instructing a client with iron-deficiency anemia. Which of the following meal plans would the nurse expect the client to select?', 'Roast beef, gelatin salad, green beans, and peach pie', 'Chicken salad sandwich, coleslaw, French fries, ice cream', 'Egg salad on wheat bread, carrot sticks, lettuce salad, raisin pie', 'Pork chop, creamed potatoes, corn, and coconut cake', 'C', 'Iron-rich choices include eggs, whole wheat, leafy green vegetables and raisins (dried fruit); this meal provides the most dietary iron for iron-deficiency anemia (Kenya nutrition guidelines; Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Clients with sickle cell anemia are taught to avoid activities that cause hypoxia and hypoxemia. Which of the following activities would the nurse recommend?', 'A family vacation in the Rocky Mountains', 'Chaperoning the local boys club on a snow-skiing trip', 'Traveling by airplane for business trips', 'A bus trip to the Museum of Natural History', 'D', 'Activities causing hypoxia (high altitude in the Rocky Mountains, cold snow-skiing, unpressurised/altitude air travel) must be avoided; a low-altitude bus trip is safe (Brunner & Suddarth''s, sickle cell patient education).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting an admission assessment of a client with vitamin B12 deficiency. Which of the following would the nurse include in the physical assessment?', 'Palpate the spleen', 'Take the blood pressure', 'Examine the feet for petechiae', 'Examine the tongue', 'D', 'Vitamin B12 deficiency characteristically causes glossitis (a smooth, beefy-red, sore tongue); examining the tongue is the relevant physical assessment finding (Brunner & Suddarth''s, megaloblastic/pernicious anemia).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An African American female comes to the outpatient clinic. The physician suspects vitamin B12 deficiency anemia. Because jaundice is often a clinical manifestation of this type of anemia, what body part would be the best indicator?', 'Conjunctiva of the eye', 'Soles of the feet', 'Roof of the mouth', 'Shins', 'C', 'In dark-skinned clients jaundice is best detected in the hard palate (roof of the mouth) and sclera where the yellow discoloration is most visible (Kozier & Erb''s, assessment of skin colour in dark-skinned clients).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is conducting a physical assessment on a client with anemia. Which of the following clinical manifestations would be most indicative of the anemia?', 'BP 146/88', 'Respirations 28 shallow', 'Weight gain of 10 pounds in 6 months', 'Pink complexion', 'B', 'Anemia reduces oxygen-carrying capacity, causing compensatory tachypnea and dyspnea; increased shallow respirations (28) is the most indicative manifestation, while pink complexion would be inconsistent with anemia (Brunner & Suddarth''s, anemia assessment).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 33-year-old male is being evaluated for possible acute leukemia. Which of the following would the nurse inquire about as a part of the assessment?', 'The client collects stamps as a hobby.', 'The client recently lost his job as a postal worker.', 'The client had radiation for treatment of Hodgkin''s disease as a teenager.', 'The client''s brother had leukemia as a child.', 'C', 'Prior radiation therapy is a well-established risk factor for developing acute leukemia; this history is the relevant assessment inquiry (Brunner & Suddarth''s, leukemia risk factors).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An African American client is admitted with acute leukemia. The nurse is assessing for signs and symptoms of bleeding. Where is the best site for examining for the presence of petechiae?', 'The abdomen', 'The thorax', 'The earlobes', 'The soles of the feet', 'C', 'In dark-skinned clients petechiae are best assessed in areas of lighter pigmentation with thin skin such as the earlobes and oral mucosa/conjunctiva (Kozier & Erb''s, skin assessment in dark-skinned clients).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following would be the priority nursing diagnosis for the adult client with acute leukemia?', 'Oral mucous membrane, altered related to chemotherapy', 'Risk for injury related to thrombocytopenia', 'Fatigue related to the disease process', 'Interrupted family processes related to life-threatening illness of a family member', 'B', 'In acute leukemia, thrombocytopenia predisposes to life-threatening hemorrhage; risk for injury/bleeding is the priority (physiologic safety) nursing diagnosis (Brunner & Suddarth''s, leukemia nursing care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 21-year-old male with Hodgkin''s lymphoma is a senior at the local university. He is engaged to be married and is to begin a new job upon graduation. Which of the following diagnoses would be a priority for this client?', 'Sexual dysfunction related to radiation therapy', 'Anticipatory grieving related to terminal illness', 'Tissue integrity related to prolonged bed rest', 'Fatigue related to chemotherapy', 'A', 'Hodgkin''s lymphoma is highly curable so anticipatory grieving for terminal illness is inappropriate; for a young engaged man, radiation-induced sexual dysfunction/infertility is the priority concern (Brunner & Suddarth''s, Hodgkin''s lymphoma).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The home health nurse is visiting a client with autoimmune thrombocytopenic purpura (ATP). The client''s platelet count currently is 80, It will be most important to teach the client and family about:', 'Bleeding precautions', 'Prevention of falls', 'Oxygen therapy', 'Conservation of energy', 'A', 'With a low platelet count in ATP (ITP), the priority teaching is bleeding precautions to prevent hemorrhage (Brunner & Suddarth''s, thrombocytopenia/ITP care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a pituitary tumor has had a transsphenoidal hypophysectomy. Which of the following interventions would be appropriate for this client?', 'Place the client in Trendelenburg position for postural drainage', 'Encourage coughing and deep breathing every 2 hours', 'Elevate the head of the bed 30°', 'Encourage the Valsalva maneuver for bowel movements', 'C', 'After transsphenoidal hypophysectomy, the head of the bed is elevated 30° to reduce pressure on the sella and CSF leak risk; coughing, Valsalva and Trendelenburg increase intracranial pressure and are contraindicated (Brunner & Suddarth''s, hypophysectomy care).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a history of diabetes insipidus is admitted with polyuria, polydipsia, and mental confusion. The priority intervention for this client is:', 'Measure the urinary output', 'Check the vital signs', 'Encourage increased fluid intake', 'Weigh the client', 'B', 'Diabetes insipidus with polyuria and confusion risks severe dehydration and hypovolemic shock; assessing vital signs is the priority to detect fluid volume/hemodynamic instability (Brunner & Suddarth''s, diabetes insipidus).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Pituitary Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with hemophilia has a nosebleed. Which nursing action is most appropriate to control the bleeding?', 'Place the client in a sitting position with the head hyperextended', 'Pack the nares tightly with gauze to apply pressure to the source of bleeding', 'Pinch the soft lower part of the nose for a minimum of 5 minutes', 'Apply ice packs to the forehead and back of the neck', 'C', 'For epistaxis in hemophilia, applying steady pressure by pinching the soft lower nose (with the client upright, head forward) controls bleeding; hyperextension and tight packing are avoided (Basic nursing/first aid; Brunner & Suddarth''s, hemophilia).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has had a unilateral adrenalectomy to remove a tumor. To prevent complications, the most important measurement in the immediate postoperative period for the nurse to take is:', 'Blood pressure', 'Temperature', 'Output', 'Specific gravity', 'A', 'After adrenalectomy, adrenal hormone fluctuations cause hemodynamic instability (hypotension or hypertension); blood pressure is the most important immediate postoperative measurement (Brunner & Suddarth''s, adrenal surgery).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with Addison''s disease has been admitted with a history of nausea and vomiting for the past 3 days. The client is receiving IV glucocorticoids (Solu-Medrol). Which of the following interventions would the nurse implement?', 'Glucometer readings as ordered', 'Intake/output measurements', 'Sodium and potassium levels monitored', 'Daily weights', 'C', 'In Addison''s disease/adrenal insufficiency the key electrolyte disturbance is hyponatremia and hyperkalemia; monitoring sodium and potassium is the priority intervention (Brunner & Suddarth''s, Addisonian crisis).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Adrenal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client had a total thyroidectomy yesterday. The client is complaining of tingling around the mouth and in the fingers and toes. What would the nurses'' next action be?', 'Obtain a crash cart', 'Check the calcium level', 'Assess the dressing for drainage', 'Assess the blood pressure for hypertension', 'B', 'Tingling of the mouth, fingers and toes after thyroidectomy signals hypocalcemia from accidental parathyroid injury; the nurse should check the calcium level and watch for tetany (Brunner & Suddarth''s, post-thyroidectomy complications).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 32-year-old mother of three is brought to the clinic. Her pulse is 52, there is a weight gain of 30 pounds in 4 months, and the client is wearing two sweaters. The client is diagnosed with hypothyroidism. Which of the following nursing diagnoses is of highest priority?', 'Impaired physical mobility related to decreased endurance', 'Hypothermia r/t decreased metabolic rate', 'Disturbed thought processes r/t interstitial edema', 'Decreased cardiac output r/t bradycardia', 'D', 'Using the airway/circulation priority, the pulse of 52 (bradycardia) makes decreased cardiac output the highest-priority (physiologic) diagnosis in hypothyroidism (Brunner & Suddarth''s, hypothyroidism; Maslow/ABC prioritisation).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A primigravida, age 42, is 6 weeks pregnant. Based on the client''s age, her infant is at risk for:', 'Down syndrome', 'Respiratory distress syndrome', 'Turner''s syndrome', 'Pathological jaundice', 'A', 'Advanced maternal age (42) markedly increases the risk of chromosomal trisomies, most notably Down syndrome (trisomy 21) (Myles Textbook for Midwives; Kenya maternal care guidelines).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a missed abortion at 29 weeks gestation is admitted to the hospital. The client will most likely be treated with:', 'Magnesium sulfate', 'Calcium gluconate', 'Dinoprostone (Prostin E.)', 'Bromocriptine (Pardel)', 'C', 'A missed abortion at 29 weeks requires evacuation; dinoprostone (a prostaglandin E) is used to induce cervical ripening and uterine contractions to expel the retained products (Myles Textbook for Midwives; Kenya maternal guidelines on induction).', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with preeclampsia has been receiving an infusion containing magnesium sulfate for a blood pressure that is 160/80; deep tendon reflexes are 1 plus, and the urinary output for the past hour is 100mL. The nurse should:', 'Continue the infusion of magnesium sulfate while monitoring the client''s blood pressure', 'Stop the infusion of magnesium sulfate and contact the physician', 'Slow the infusion rate and turn the client on her left side', 'Administer calcium gluconate IV push and continue to monitor the blood pressure', 'A', 'Per Kenya National Maternal guidelines/Myles, MgSO4 is withheld only for magnesium toxicity signs: respiratory depression, absent reflexes, or urine output <30mL/hr (<100mL/4hr). Here reflexes are present (1+) and output is adequate (100mL/hr), so the infusion is safely continued with monitoring.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant client, age 32, asks the nurse why her doctor has recommended a serum alpha fetoprotein. The nurse should explain that the doctor has recommended the test:', 'Because it is a state law', 'To detect cardiovascular defects', 'Because of her age', 'To detect neurological defects', 'D', 'Per Myles/antenatal screening, maternal serum alpha-fetoprotein screens for neural tube (neurological) defects such as spina bifida and anencephaly; elevated AFP indicates open NTDs. Age relates to Down screening, not AFP alone.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with hypothyroidism asks the nurse if she will still need to take thyroid medication during the pregnancy. The nurse''s response is based on the knowledge that:', 'There is no need to take thyroid medication because the fetus''s thyroid produces a thyroid-stimulating hormone.', 'Regulation of thyroid medication is more difficult because the thyroid gland increases in size during pregnancy.', 'It is more difficult to maintain thyroid regulation during pregnancy due to a slowing of metabolism.', 'Fetal growth is arrested if thyroid medication is continued during pregnancy.', 'B', 'Per Brunner & Suddarth/maternal endocrine physiology, thyroid demand and gland size increase in pregnancy so thyroid replacement often needs upward adjustment; medication must be continued, not stopped. Metabolism rises (not slows) in pregnancy.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with sickle cell anemia is admitted to the labor and delivery unit during the first phase of labor. The nurse should anticipate the client''s need for:', 'Supplemental oxygen', 'Fluid restriction', 'Blood transfusion', 'Delivery by Caesarean section', 'A', 'Per Kenya haematology/maternal guidelines, in sickle cell disease during labor the priority is preventing hypoxia and sickling crisis, so supplemental oxygen and hydration are anticipated. Fluid restriction is contraindicated as it promotes sickling.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with diabetes has an order for ultrasonography. Preparation for an ultrasound includes:', 'Increasing fluid intake', 'Limiting ambulation', 'Administering an enema', 'Withholding food for 8 hours', 'A', 'Per obstetric ultrasound preparation (Myles), a full bladder from increased fluid intake elevates the uterus and provides an acoustic window for imaging in pregnancy. Withholding food and enemas are not required for obstetric/abdominal ultrasound.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant who weighs 8 pounds at birth would be expected to weigh how many pounds at 1 year?', '14 pounds', '16 pounds', '18 pounds', '24 pounds', 'D', 'Per Basic Paediatric Protocols/growth norms, an infant''s birth weight roughly triples by 1 year; 8 pounds x 3 = 24 pounds. Doubling occurs by ~5-6 months.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A pregnant client with a history of alcohol addiction is scheduled for a nonstress test. The nonstress test:', 'Determines the lung maturity of the fetus', 'Measures the activity of the fetus', 'Shows the effect of contractions on the fetal heart rate', 'Measures the neurological well-being of the fetus', 'B', 'Per Myles antenatal testing, a nonstress test evaluates fetal heart rate accelerations in response to fetal movement (activity), reflecting well-being. Contraction effects are assessed by the contraction stress test, and lung maturity by L/S ratio.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A full-term male has hypospadias. Which statement describes hypospadias?', 'The urethral opening is absent.', 'The urethra opens on the dorsal side of the penis.', 'The penis is shorter than usual.', 'The urethra opens on the ventral side of the penis.', 'D', 'Per Basic Paediatric Protocols/paediatric surgery, hypospadias is a congenital anomaly in which the urethral meatus opens on the ventral (underside) of the penis. A dorsal opening describes epispadias.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A gravida III, para II is admitted to the labor unit. Vaginal exam reveals that the client''s cervix is 8cm dilated, with complete effacement. The priority nursing diagnosis at this time is:', 'Alteration in coping related to pain', 'Potential for injury related to precipitate delivery', 'Alteration in elimination related to anesthesia', 'Potential for fluid volume deficit related to NPO status', 'B', 'Per Myles, a multipara (gravida III para II) at 8cm with complete effacement is in advanced active/transition labor and may deliver rapidly; the priority is preventing injury from precipitate delivery. Pain and elimination are lower priority than safety.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted complaining of chest pain. Which of the following drug orders should the nurse question?', 'Nitroglycerin', 'Ampicillin', 'Propranolol', 'Verapamil', 'B', 'Per Kenya EML/cardiac pharmacology, nitroglycerin, propranolol and verapamil are all appropriate for anginal chest pain; ampicillin is an antibiotic with no role in chest pain and should be questioned.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with acute pancreatitis is experiencing severe abdominal pain. Which of the following orders should be questioned by the nurse?', 'Meperidine 100mg IM q 4 hours PRN pain', 'Mylanta 30 ccs q 4 hours via NG', 'Cimetidine 300mg PO q.i.d.', 'Morphine 8mg IM q 4 hours PRN pain', 'D', 'Per traditional med-surg teaching (Brunner & Suddarth), morphine was avoided in acute pancreatitis due to concern for sphincter of Oddi spasm; meperidine was historically preferred, so the morphine order is the one questioned in NCK-style items.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('To maintain Bryant''s traction, the nurse must make certain that the child''s:', 'Hips are resting on the bed, with the legs suspended at a right angle to the bed', 'Hips are slightly elevated above the bed and the legs are suspended at a right angle to the bed', 'Hips are elevated above the level of the body on a pillow and the legs are suspended parallel to the bed', 'Hips and legs are flat on the bed, with the traction positioned at the foot of the bed', 'B', 'Per paediatric orthopaedic nursing (Brunner/paeds texts), Bryant''s traction requires the hips slightly elevated off the bed so the child''s weight provides countertraction, with legs suspended vertically at a 90-degree angle to the bed. Buttocks must clear the mattress.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing postpartum teaching for a mother planning to breastfeed her infant. Which of the client''s statements indicates the need for additional teaching?', '"I''m wearing a support bra."', '"I''m expressing milk from my breast."', '"I''m drinking four glasses of fluid during a 24-hour period."', '"While I''m in the shower, I''ll allow the water to run over my breasts."', 'C', 'Per Myles/postpartum lactation teaching, a breastfeeding mother needs increased fluids (about 8-10 glasses/day); only four glasses in 24 hours is inadequate and indicates a need for more teaching. Support bra, expressing milk, and letting water run over breasts are correct.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Damage to the VII cranial nerve results in:', 'Facial pain', 'Absence of ability to smell', 'Absence of eye movement', 'Tinnitus', 'A', 'Per neuroanatomy (Brunner & Suddarth), the VII (facial) nerve controls facial muscle movement and taste; its damage causes facial weakness/paralysis and altered sensation. Smell is CN I, eye movement CN III/IV/VI, so facial involvement is the best fit among the options. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is receiving Pyridium (phenazopyridine hydrochloride) for a urinary tract infection. The client should be taught that the medication may:', 'Cause diarrhea', 'Change the color of her urine', 'Cause mental confusion', 'Cause changes in taste', 'B', 'Per Kenya EML/pharmacology, phenazopyridine (Pyridium) is a urinary analgesic that characteristically turns urine reddish-orange; clients must be forewarned to avoid alarm and staining. It does not typically cause diarrhea or confusion.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with AIDS is taking Zovirax (acyclovir). Which nursing intervention is most critical during the administration of acyclovir?', 'Limit the client''s activity', 'Encourage a high-carbohydrate diet', 'Utilize an incentive spirometer to improve respiratory function', 'Encourage fluids', 'D', 'Per pharmacology (Brunner & Suddarth), acyclovir (Zovirax) is nephrotoxic and can crystallize in renal tubules, so adequate hydration is the most critical intervention to protect the kidneys during administration. Activity limitation and spirometry are not priorities.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted for an MRI. The nurse should question the client regarding:', 'Pregnancy', 'A titanium hip replacement', 'Allergies to antibiotics', 'Inability to move his feet', 'B', 'Per diagnostic imaging safety (Brunner & Suddarth), MRI uses a strong magnetic field, so the nurse must screen for metal implants; ferromagnetic hardware is a contraindication. Screening for implants/metal is the key MRI safety concern among these options.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for the client receiving Amphotericin B. Which of the following indicates that the client has experienced toxicity to this drug?', 'Changes in vision', 'Nausea', 'Urinary frequency', 'Changes in skin color', 'B', 'Per pharmacology (Brunner & Suddarth), amphotericin B commonly causes infusion reactions such as fever, chills, nausea and, importantly, nephrotoxicity; among the listed options nausea is the recognized adverse/toxic effect. Visual changes are not characteristic. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse should visit which of the following clients first?', 'The client with diabetes with a blood glucose of 95mg/dL', 'The client with hypertension being maintained on Lisinopril', 'The client with chest pain and a history of angina', 'The client with Raynaud''s disease', 'C', 'Per triage/prioritization (ABC, Brunner & Suddarth), the client with active chest pain and angina history is at risk of an evolving myocardial infarction and must be seen first. The others are stable with controlled findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with cystic fibrosis is taking pancreatic enzymes. The nurse should administer this medication:', 'Once per day in the morning', 'Three times per day with meals', 'Once per day at bedtime', 'Four times per day', 'B', 'Pancreatic enzyme replacements (pancrelipase) must be given with each meal and snack so the enzymes are present to digest fat, protein, and carbohydrate as food enters the gut (Brunner & Suddarth''s Medical-Surgical Nursing). Giving them once daily would leave most meals without enzyme support.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cataracts result in opacity of the crystalline lens. Which of the following best explains the functions of the lens?', 'The lens controls stimulation of the retina.', 'The lens orchestrates eye movement.', 'The lens focuses light rays on the retina.', 'The lens magnifies small objects.', 'C', 'The crystalline lens refracts (focuses) incoming light rays onto the retina; cataract opacity blurs this focus (Anatomy & Physiology; Brunner & Suddarth''s). Pupil/iris controls light intake and extraocular muscles control movement, not the lens.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client who has glaucoma is to have miotic eye drops instilled in both eyes. The nurse knows that the purpose of the medication is to:', 'Anesthetize the cornea', 'Dilate the pupils', 'Constrict the pupils', 'Paralyze the muscles of accommodation', 'C', 'Miotics (e.g., pilocarpine) constrict the pupil, which widens the trabecular outflow and lowers intraocular pressure in glaucoma (Brunner & Suddarth''s; Kenya EML ophthalmic drugs). ''Miosis'' means pupillary constriction, the opposite of mydriasis/dilation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a severe corneal ulcer has an order for Gentamicin gtt. q 4 hours and Neomycin 1 gtt q 4 hours. Which of the following schedules should be used when administering the drops?', 'Allow 5 minutes between the two medications.', 'The medications may be used together.', 'The medications should be separated by a cycloplegic drug.', 'The medications should not be used in the same client.', 'A', 'When two different eye drops are ordered, a waiting interval (about 5 minutes) is required so the first drop is not washed out before absorption (Kozier & Erb''s Fundamentals of Nursing). They should not be instilled simultaneously.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with a pacemaker should be taught to:', 'Report ankle edema', 'Check his blood pressure daily', 'Refrain from using a microwave oven', 'Monitor his pulse rate', 'D', 'Pacemaker clients are taught to check their pulse daily and report a rate below the set threshold, which signals pacemaker malfunction (Brunner & Suddarth''s). Modern microwaves are safe, so refraining from them is unnecessary.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Cardiovascular Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with enuresis is being taught regarding bladder retraining. The nurse should advise the client to refrain from drinking after:', '1900', '1200', '1000', '0700', 'A', 'In bladder retraining for enuresis, fluids are restricted in the evening (after about 1900 hrs / 7 pm) to reduce night-time bladder filling, while daytime intake stays adequate (Kozier & Erb''s Fundamentals of Nursing). Stopping fluids at midday would cause dehydration.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following diet instructions should be given to the client with recurring urinary tract infections?', 'Increase intake of meats.', 'Avoid citrus fruits.', 'Perform pericare with hydrogen peroxide.', 'Drink a glass of cranberry juice every day.', 'D', 'Cranberry juice acidifies urine and inhibits bacterial adherence to the bladder wall, helping prevent recurrent UTIs (Brunner & Suddarth''s). Citrus need not be avoided, and hydrogen peroxide pericare is inappropriate.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed NPH insulin for a client with diabetes mellitus. Which statement indicates that the client knows when the peak action of the insulin occurs?', '"I will make sure I eat breakfast within 2 hours of taking my insulin."', '"I will need to carry candy or some form of sugar with me all the time."', '"I will eat a snack around three o''clock each afternoon."', '"I can save my dessert from supper for a bedtime snack."', 'C', 'NPH (intermediate-acting) insulin peaks roughly 6-12 hours after a morning dose, so a mid-afternoon snack covers the peak and prevents hypoglycemia (Brunner & Suddarth''s; Kenya EML). Eating breakfast within 2 hours describes rapid/short-acting insulin.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with pneumocystis carinii pneumonia is receiving trimetrexate. The rationale for administering leucovorin calcium to a client receiving Methotrexate is to:', 'Treat anemia.', 'Create a synergistic effect.', 'Increase the number of white blood cells.', 'Reverse drug toxicity.', 'D', 'Leucovorin (folinic acid) rescue counteracts the folate-antagonist toxicity of methotrexate/trimetrexate, protecting normal cells (Brunner & Suddarth''s; Kenya EML). It is a rescue agent, not a synergistic or hematinic agent.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client tells the nurse that she is allergic to eggs, dogs, rabbits, and chicken feathers. Which order should the nurse question?', 'TB skin test', 'Rubella vaccine', 'ELISA test', 'Chest x-ray', 'B', 'MMR/rubella vaccine is cultured in chick embryo cells, so a documented severe egg allergy warrants questioning the order (Brunner & Suddarth''s; KEPI cautions). TB skin test, ELISA, and chest x-ray carry no egg-protein risk.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has prescribed ranitidine (Zantac) for a client with erosive gastritis. The nurse should administer the medication:', '30 minutes before meals', 'With each meal', 'In a single dose at bedtime', '60 minutes after meals', 'A', 'H2 antagonists such as ranitidine are best given before meals so the drug blocks the acid secretion stimulated by eating (Brunner & Suddarth''s; Kenya EML). Single bedtime dosing does not cover mealtime acid surges as well.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A temporary colostomy is performed on the client with colon cancer. The nurse is aware that the proximal end of a double barrel colostomy:', 'Is the opening on the client''s left side', 'Is the opening on the distal end on the client''s left side', 'Is the opening on the client''s right side', 'Is the opening on the distal right side', 'C', 'In a double-barrel colostomy the proximal (functioning) stoma is on the client''s right, following the direction of bowel flow from the ascending/transverse colon, while the distal non-functioning stoma is on the left (Brunner & Suddarth''s).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an MRI for a client with an orthopedic ailment. An MRI should not be done if the client has:', 'The need for oxygen therapy', 'A history of claustrophobia', 'A permanent pacemaker', 'Sensory deafness', 'C', 'MRI is contraindicated with most permanent pacemakers because the strong magnetic field can disrupt or damage the device (Brunner & Suddarth''s). Claustrophobia and deafness can be accommodated and are not absolute contraindications.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 6-month-old client is placed on strict bed rest following a hernia repair. Which toy is best suited to the client?', 'Colorful crib mobile', 'Hand-held electronic games', 'Cars in a plastic container', '30-piece jigsaw puzzle', 'A', 'A colorful crib mobile suits a 6-month-old''s developmental level (visual tracking) and is appropriate for strict bed rest (Basic Paediatric Protocols; growth & development principles). Electronic games and jigsaw puzzles are for older children.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to discharge a client with a long history of polio. The nurse should tell the client that:', 'Taking a hot bath will decrease stiffness and spasticity.', 'A schedule of strenuous exercise will improve muscle strength.', 'Rest periods should be scheduled throughout the day.', 'Visual disturbances can be corrected with prescription glasses.', 'C', 'Clients with polio/post-polio syndrome fatigue easily, so scheduled rest periods conserve energy and protect weakened muscles (Brunner & Suddarth''s). Strenuous exercise can worsen muscle weakness and is contraindicated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client on the postpartum unit has a proctoepisiotomy. The nurse should anticipate administering which medication?', 'Dulcolax suppository', 'Docusate sodium (Colace)', 'Methyergonovine maleate (Methergine)', 'Bromocriptine sulfate (Parlodel)', 'B', 'After a proctoepisiotomy (extending into the rectum), a stool softener such as docusate sodium prevents straining and protects the repair (Myles Textbook for Midwives). A stimulant Dulcolax suppository is avoided as it can traumatize the suture line.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with pancreatic cancer has an infusion of TPN (Total Parenteral Nutrition). The doctor has ordered for sliding-scale insulin. The most likely explanation for this order is:', 'Total Parenteral Nutrition leads to negative nitrogen balance and elevated glucose levels.', 'Total Parenteral Nutrition cannot be managed with oral hypoglycemics.', 'Total Parenteral Nutrition is a high-glucose solution that often elevates the blood glucose levels.', 'Total Parenteral Nutrition leads to further pancreatic disease.', 'C', 'TPN is a hypertonic high-dextrose solution that commonly causes hyperglycemia, requiring sliding-scale insulin coverage (Brunner & Suddarth''s). TPN actually promotes positive nitrogen balance, so option A is incorrect.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Diabetes Mellitus', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An adolescent primigravida who is 10 weeks pregnant attends the antepartal clinic for a first check-up. To develop a teaching plan, the nurse should initially assess:', 'The client''s knowledge of the signs of preterm labor', 'The client''s feelings about the pregnancy', 'Whether the client was using a method of birth control', 'The client''s thought about future children', 'B', 'For an adolescent primigravida, the nurse must first assess her feelings/acceptance of the pregnancy, as this shapes her receptiveness to any teaching plan (Myles Textbook for Midwives; Kenya focused antenatal care). Preterm-labor signs are taught later in pregnancy.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An obstetric client is admitted with dehydration. Which IV fluid would be most appropriate for the client?', '0.45 normal saline', 'Dextrose 1% in water', 'Lactated Ringer''s', 'Dextrose 5% in 0.45 normal saline', 'C', 'Lactated Ringer''s is an isotonic, balanced crystalloid ideal for restoring intravascular volume in dehydration (Kenya MOH fluid guidelines; Brunner & Suddarth''s). ''Dextrose 1% in water'' is not a standard preparation, and 0.45 NS is hypotonic.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a thyroid scan to confirm the diagnosis. Before the procedure, the nurse should:', 'Assess the client for allergies', 'Bolus the client with IV fluid', 'Tell the client he will be asleep', 'Insert a urinary catheter', 'A', 'A thyroid scan uses radioactive iodine tracer, so the nurse must assess for iodine/shellfish allergy before the procedure (Brunner & Suddarth''s). Sedation, IV bolus, and catheterization are not routinely required.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered an injection of RhoGam for a client with blood type A negative. The nurse understands that RhoGam is given to:', 'Provide immunity against Rh isoenzymes', 'Prevent the formation of Rh antibodies', 'Eliminate circulating Rh antibodies', 'Convert the Rh factor from negative to positive', 'B', 'RhoGam (anti-D immunoglobulin) provides passive immunity that suppresses the Rh-negative mother''s active production of anti-Rh antibodies, protecting future pregnancies (Myles Textbook for Midwives; Kenya MNH guidelines). It does not convert the Rh factor or eliminate existing antibodies.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted to the emergency room after a fall. X-rays reveal that the client has several fractured bones in the foot. Which treatment should the nurse anticipate for the fractured foot?', 'Application of a short inclusive spica cast', 'Stabilization with a plaster-of-Paris cast', 'Surgery with Kirschner wire implantation', 'A gauze dressing only', 'B', 'Simple closed fractures of the foot are typically immobilized with a plaster-of-Paris cast to allow bone healing (Brunner & Suddarth''s; Kenya orthopaedic practice). A spica cast is for hip/thigh, and Kirschner wires are reserved for unstable/displaced fractures.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with bladder cancer is being treated with iridium seed implants. The nurse''s discharge teaching should include telling the client to:', 'Strain his urine', 'Increase his fluid intake', 'Report urinary frequency', 'Avoid prolonged sitting', 'B', 'After bladder iridium seed implants, increased fluid intake dilutes urine, reduces bladder irritation, and flushes the urinary tract (Brunner & Suddarth''s oncology nursing). Straining urine is not indicated for internal implants.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Following a heart transplant, a client is started on medication to prevent organ rejection. Which category of medication prevents the formation of antibodies against the new organ?', 'Antivirals', 'Antibiotics', 'Immunosuppressants', 'Analgesics', 'C', 'Immunosuppressant drugs (e.g., cyclosporine, tacrolimus) suppress the immune response and prevent antibody-mediated rejection of the transplanted heart (Brunner & Suddarth''s; Kenya EML). Antivirals and antibiotics treat infection, not rejection.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing a client for cataract surgery. The nurse is aware that the procedure will use:', 'Mydriatics to facilitate removal', 'Miotic medications such as Timoptic', 'A laser to smooth and reshape the lens', 'Silicone oil injections into the eyeball', 'A', 'Before cataract extraction, mydriatic (dilating) drops are instilled to widen the pupil and allow access to and removal of the lens (Brunner & Suddarth''s; Kenya EML ophthalmic). Miotics constrict the pupil and would hinder surgery.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with Alzheimer''s disease is awaiting placement in a skilled nursing facility. Which long-term plans would be most therapeutic for the client?', 'Placing mirrors in several locations in the home', 'Placing a picture of herself in her bedroom', 'Placing simple signs to indicate the location of the bedroom, bathroom, and so on', 'Alternating healthcare workers to prevent boredom', 'C', 'Simple orienting signs help the Alzheimer''s client navigate and maintain independence and safety (Brunner & Suddarth''s; mental health nursing). Mirrors can increase confusion/agitation and rotating caregivers reduces consistency.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with an abdominal cholecystectomy returns from surgery with a Jackson-Pratt drain. The chief purpose of the Jackson-Pratt drain is to:', 'Prevent the need for dressing changes', 'Reduce edema at the incision', 'Provide for wound drainage', 'Keep the common bile duct open', 'C', 'A Jackson-Pratt is a closed-suction drain whose main purpose is to remove serosanguineous fluid from the surgical wound bed, reducing collection and promoting healing (Kozier & Erb''s; Brunner & Suddarth''s). It does not keep the bile duct patent.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is caring for a client admitted with multiple trauma. Fractures include the pelvis, femur, and ulna. Which finding should be reported to the physician immediately?', 'Hematuria', 'Muscle spasms', 'Dizziness', 'Nausea', 'A', 'With a pelvic fracture, hematuria signals possible bladder or urethral injury and must be reported immediately (Brunner & Suddarth''s; Kenya trauma care). Muscle spasms and nausea are expected and less urgent findings.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant''s Apgar score is 9 at 5 minutes. The nurse is aware that the most likely cause for the deduction of one point is:', 'The baby is cold.', 'The baby is experiencing bradycardia.', 'The baby''s hands and feet are blue.', 'The baby is lethargic.', 'C', 'Per Myles Textbook for Midwives, acrocyanosis (blue hands and feet) is the commonest reason a healthy newborn loses one Apgar point on colour, giving a score of 9; heart rate, tone and reflex are usually normal.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The primary reason for rapid continuous rewarming of the area affected by frostbite is to:', 'Lessen the amount of cellular damage', 'Prevent the formation of blisters', 'Promote movement', 'Prevent pain and discomfort', 'A', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, rapid continuous rewarming of frostbite in a warm water bath limits the extent of tissue and cellular destruction; the other options are secondary.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client recently started on hemodialysis wants to know how the dialysis will take the place of his kidneys. The nurse''s response is based on the knowledge that hemodialysis works by:', 'Passing water through a dialyzing membrane', 'Eliminating plasma proteins from the blood', 'Lowering the pH by removing nonvolatile acids', 'Filtering waste through a dialyzing membrane', 'D', 'Per Brunner & Suddarth''s, hemodialysis removes nitrogenous waste and excess solutes by diffusion across a semipermeable dialyzing membrane; it does not remove plasma proteins and its purpose is waste filtration, not simply passing water.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Renal Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During a home visit, a client with AIDS tells the nurse that he has been exposed to measles. Which action by the nurse is most appropriate?', 'Administer an antibiotic', 'Contact the physician for an order for immune globulin', 'Administer an antiviral', 'Tell the client that he should remain in isolation for 2 weeks', 'B', 'Per Kenya HIV/AIDS and immunocompromised care guidelines and Brunner & Suddarth''s, an immunosuppressed AIDS client exposed to measles should receive immune (immunoglobulin) prophylaxis; antibiotics and antivirals are not indicated for measles post-exposure protection.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client who is admitted with an above-the-knee amputation tells the nurse that his foot hurts and itches. Which response by the nurse indicates understanding of phantom limb pain?', '"The pain will go away in a few days."', '"The pain is due to peripheral nervous system interruptions. I will get you some pain medication."', '"The pain is psychological because your foot is no longer there."', '"The pain and itching are due to the infection you had before the surgery."', 'B', 'Per Brunner & Suddarth''s, phantom limb pain is a real physiologic phenomenon arising from severed peripheral nerve pathways and CNS reorganization, not psychological; it should be acknowledged and treated with analgesia.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with cancer of the pancreas has undergone a Whipple procedure. The nurse is aware that during the Whipple procedure, the doctor will remove the:', 'Head of the pancreas', 'Proximal third section of the small intestines', 'Stomach and duodenum', 'Esophagus and jejunum', 'A', 'Per Brunner & Suddarth''s, the Whipple (pancreaticoduodenectomy) removes the head of the pancreas along with the duodenum, distal stomach, gallbladder and distal common bile duct; among the options, the head of the pancreas is the defining structure removed.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a minimal-bacteria diet for a client with neutropenia. The client should be taught to avoid eating:', 'Fruits', 'Salt', 'Pepper', 'Ketchup', 'A', 'Per oncology nursing guidance in Brunner & Suddarth''s, a neutropenic (low-bacteria) diet avoids raw/fresh fruits and vegetables which carry surface bacteria; seasonings like salt, pepper and ketchup are not the primary hazard.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is assisting the physician with removal of a central venous catheter. To facilitate removal, the nurse should instruct the client to:', 'Perform the Valsalva maneuver as the catheter is advanced', 'Turn his head to the left side and hyperextend the neck', 'Take slow, deep breaths as the catheter is removed', 'Turn his head to the right while maintaining a sniffing position', 'A', 'Per Brunner & Suddarth''s, during central venous catheter removal the client performs the Valsalva maneuver (bear down/hold breath) to raise intrathoracic pressure and prevent air embolism as the catheter is withdrawn; the stem''s wording ''advanced'' reflects the removal procedure and the Valsalva timing is the key safety action.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client has an order for streptokinase. Before administering the medication, the nurse should assess the client for:', 'Allergies to pineapples and bananas', 'A history of streptococcal infections', 'Prior therapy with phenytoin', 'A history of alcohol abuse', 'B', 'Per Kenya EML/BNF pharmacology, streptokinase is derived from streptococci; recent streptococcal infection produces antibodies that reduce efficacy and increase allergic risk, so the nurse assesses for prior streptococcal infection.', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is providing discharge teaching for the client with leukemia. The client should be told to avoid:', 'Using oil- or cream-based soaps', 'Flossing between the teeth', 'The intake of salt', 'Using an electric razor', 'B', 'Per Brunner & Suddarth''s, leukemia clients are thrombocytopenic and neutropenic; flossing can cause gum bleeding and introduce infection, so it should be avoided. An electric razor is actually recommended to prevent cuts.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is changing the ties of the client with a tracheotomy. The safest method of changing the tracheostomy ties is to:', 'Apply the new tie before removing the old one.', 'Have a helper present.', 'Hold the tracheotomy with the nondominant hand while removing the old tie.', 'Ask the doctor to suture the tracheostomy in place.', 'A', 'Per Kozier & Erb''s Fundamentals, the safest method when changing tracheostomy ties is to secure the new tie before removing the old one to prevent accidental decannulation.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is monitoring a client following a lung resection. The hourly output from the chest tube was 300mL. The nurse should give priority to:', 'Turning the client to the left side', 'Milking the tube to ensure patency', 'Slowing the intravenous infusion', 'Notifying the physician', 'D', 'Per Brunner & Suddarth''s, chest tube drainage exceeding 100 mL/hr (here 300 mL) suggests active hemorrhage and is a priority to report to the physician immediately; milking the tube is contraindicated.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with clotting disorder has an order to continue Lovenox (enoxaparin) injections after discharge. The nurse should teach the client that Lovenox injections should:', 'Be injected into the deltoid muscle', 'Be injected into the abdomen', 'Aspirate after the injection', 'Clear the air from the syringe before injections', 'B', 'Per Kenya EML/BNF, enoxaparin (Lovenox) is given subcutaneously into the abdominal fat (''love handles''); the air bubble is not expelled and the site is not aspirated or massaged to avoid bruising.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client has recently returned from having a thyroidectomy. The nurse should keep which of the following at the bedside?', 'A tracheotomy set', 'A padded tongue blade', 'An endotracheal tube', 'An airway', 'A', 'Per Brunner & Suddarth''s, after thyroidectomy a tracheotomy set is kept at the bedside because laryngeal nerve damage, tracheal compression or tetany-related laryngospasm can cause airway obstruction requiring emergency tracheotomy. Source: NCK Paper 1 & 2 Combined Practice Sets (Type 1-4)', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Thyroid Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which blood gas analyses are most indicative of respiratory acidosis?', 'pH = 7.22, PC02 = 55 mm Hg, HC03 = 30 mEq/L.', 'pH = 7.28, PC02 = 45 mm Hg, HC03 = 15 mEq/L.', 'pH = 7.34, PC02 = 35 mm Hg, HC03 = 25 mEq/L.', 'pH = 7.40, PC02 = 25 mm Hg, HC03 = 30 mEq/L.', 'A', 'Respiratory acidosis = low pH with elevated PCO2. Option A shows pH 7.22 (acidotic) with PCO2 55 (elevated, the primary cause) and compensatory HCO3 rise. The other options are metabolic acidosis (B), normal (C), or respiratory alkalosis (D). Per Brunner & Suddarth''s Medical-Surgical Nursing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Expansion of the intravascular volume and increased intravascular pressure are the main causes of edema in', 'lymphatic obstruction', 'heart failure', 'protein-losing enteropathy', 'nephrotic syndrome', 'B', 'In heart failure, increased intravascular (venous/hydrostatic) volume and pressure drive fluid into interstitium causing oedema; per Brunner & Suddarth''s Medical-Surgical Nursing. Lymphatic obstruction, protein-losing enteropathy and nephrotic syndrome cause oedema mainly via reduced oncotic pressure or lymphatic blockage, not raised intravascular volume/pressure.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Common respiratory tract manifestations of neonatal bacterial infections is', 'ethmoiditis', 'empyema', 'otitis media', 'mastoiditis', 'C', 'Otitis media is a common upper respiratory tract manifestation of neonatal bacterial infection; per Basic Paediatric Protocols/neonatal texts. Ethmoiditis, empyema and mastoiditis are uncommon in neonates as presenting infections. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Antiretroviral agents, such as AZT are used in the management of AIDS. Which of the following is not an action expected of these drugs?', 'They prolong the life of the client with AIDS', '. They reduce the risk of opportunistic infections', '. They shorten the period of communicability of the disease', 'They are able to bring about a cure of the disease condition Your Answer :', 'D', 'Per Kenya National ARV Guidelines, ART suppresses viral replication, prolongs life, reduces opportunistic infections and lowers communicability, but does NOT cure HIV. The question asks which is NOT an expected action, so the correct answer is that ARVs cure the disease.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 1 1/2 year old child was classified as having 3rd degree of protein energy malnutrition, kwashjorkor. Which of the following signs will be most apparent in this child?', 'voracious appetite', 'wasting', 'apathy', 'edema', 'D', 'Per Kenya Basic Paediatric Protocols and IMNCI, kwashiorkor (protein malnutrition) is characterised chiefly by bilateral pitting oedema, along with apathy and hair/skin changes; oedema is the defining/most apparent sign distinguishing it from marasmus (wasting). Wasting is the hallmark of marasmus, not kwashiorkor. 675. abnrmally low set ears could be indicative of A. otogenous tetanus B. congenital heart defect C. tracheoesophageal fistula D. renal anomalies Answer: D. renal anomalies Rationale: Per paediatric/neonatal assessment (Basic Paediatric Protocols; standard paediatric texts), low-set ears are a well-recognised marker associated with congenital renal anomalies (and chromosomal syndromes) because the ears and kidneys develop concurrently. This is the classic newborn examination association. 676. in type three trachea-esophageal fistula A. upper segment of esophagus open into trachea B. lower segment of esophagus open into trachea C. normal trachea and esophagus are connected by a fistula D. proximal and distal segments of esophagus are blind Answer: C. normal trachea and esophagus are connected by a fistula Rationale: Per paediatric surgery classification (Gross type C, the most common tracheo-esophageal fistula), Type III/C is a proximal esophageal atresia with a distal esophageal segment communicating with the trachea via a fistula — i.e. trachea and esophagus connected by a fistula. This is the commonest variant taught in paediatric nursing. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother brought her daughter, 4 years old, to the RHU because of cough and colds. Following the IMCI assessment guide, which of the following is a danger sign that indicates the need for urgent referral to a hospital?', 'Inability to drink', 'High grade fever', 'Signs of severe dehydration', 'Cough for more than 30 days', 'A', 'Per Kenya IMNCI guidelines, the general danger signs requiring urgent referral are: inability to drink or breastfeed, vomiting everything, convulsions, and lethargy/unconsciousness. Inability to drink is a listed IMNCI danger sign; high fever and cough duration are not general danger signs.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother brought her 10 month old infant for consultation because of fever which started 4 days prior to consultation. To determine malaria risk, what will you do?', 'Do a tourniquet test', 'Ask where the family resides', 'Get a specimen for blood smear', 'Ask if the fever is present everyday', 'C', 'Per Kenya Malaria Guidelines and IMNCI, any child with fever in a malaria-endemic area must have a parasitological test (blood smear or RDT) to confirm malaria before treatment. A confirmed blood smear determines actual malaria, whereas residence/pattern questions only assess exposure risk. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The pathognomonic sign of measles is Koplik’s spot. You may see Koplik’s spot by inspecting the:', 'Nasal Mucosa', 'Buccal mucosa', 'Skin on the abdomen', 'Skin on the antecubital surface', 'B', 'Per standard paediatric/communicable disease texts, Koplik''s spots (pathognomonic of measles) are small white spots seen on the buccal mucosa opposite the molars, appearing before the rash. They are not found on the nasal mucosa or skin.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a mother’s class, you discuss proper breastfeeding technique. Which of these is a sign that the baby has “lactated on” the breast property?', 'The baby takes shallow, rapid sucks', '. The mother does not feel nipple pain', 'The baby’s mouth is only partly open', 'Only the mother’s nipple is inside the baby’s mouth', 'B', 'Per Kenya MOH/WHO breastfeeding guidance, good attachment (latch) signs include the baby''s mouth wide open, more areola visible above than below, chin touching breast, slow deep sucks, and painless feeding for the mother. Shallow rapid sucks, partly-open mouth and nipple-only in mouth indicate poor attachment.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following medications might be prescribed for someone with OCD: -', 'Anxiolytic', 'Antipsychotic', 'Hypnotic', 'Mood stabilizers', 'A', 'Per Kenya EML and psychiatric nursing references, OCD is treated with SSRIs and adjunctive anxiolytics to control anxiety; of the listed drug classes an anxiolytic is the appropriate choice, as OCD is an anxiety-spectrum disorder rather than a psychotic or mood disorder. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Pharmacology', 'Drug Therapy', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When developing a plan of care for a male adolescent, the nurse considers the child’s psychosocial needs. During adolescence, psychosocial development focuses on:', 'Becoming industrious', 'Establishing an identity', 'Achieving intimacy', 'Developing initiative', 'B', 'Per Erikson''s developmental theory (Kozier & Erb''s), the psychosocial task of adolescence is identity vs. role confusion, i.e. establishing an identity. Industry is school age, intimacy is young adulthood, initiative is preschool.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In a child less than 3 years, the diagnosis of failure to thrive (FTT)is considered if', 'weight is below the 3rdpercentile', 'BMI less than the 25thpercentile', 'weight drops down more than 2 major percentile', 'BMI less than the 25thpercentile', 'C', 'Failure to thrive in a child under 3 is defined by weight below the 3rd/5th percentile OR crossing downward more than 2 major percentile lines on the growth chart (Nelson; Basic Paediatric Protocols). The best single discriminating dynamic criterion is a fall of more than 2 major percentiles; BMI percentiles are not used in this age group. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Approaching to a child with failure to thrive based on signs and symptoms.Of the following, the MOST common cause behind a child has spitting, vomiting, and food refusal is', 'gastroesophageal reflux', 'chronic tonsillitis', 'food allergies', 'inflammatory bowel disease', 'A', 'In an infant/young child with spitting, vomiting and food refusal contributing to FTT, gastroesophageal reflux is the most common underlying cause (Nelson Textbook of Pediatrics). Tonsillitis, food allergy and IBD are far less common causes of this triad.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A child growing within normal developmental milestones will be able to have good head control at the age of:', '3-6 months', '6-9 months', '12-18 months', '20-24 months', 'A', 'Per Basic Paediatric Protocols / IMNCI developmental milestones, good head control is achieved by about 3-4 months (within the 3-6 month range), well before sitting and standing milestones. 705. the characteristics of a classical syphilitic ulcer include A. painful, flat lesion with edema of the surrounding area B. painful, extensive lesions, fluid filled vesicle like blister C. painless, flat lesion with smooth regular firm edge D. painless, flat lesion with irregular edges and flat dirty base Answer: C. painless, flat lesion with smooth regular firm edge Rationale: The primary syphilitic chancre is a painless, indurated ulcer with a smooth, clean base and firm, regular raised edges; painful ragged/dirty ulcers suggest chancroid (Kenya STI guidelines, Brunner & Suddarth). 706. the commonest causative organism of urinary tract infection is A. proteus B. streptococcus aureus C. Escherichia coli D. Klebsiela Answer: C. Escherichia coli Rationale: Escherichia coli is the commonest causative organism of urinary tract infection, accounting for the majority of uncomplicated UTIs (Brunner & Suddarth, Kenya clinical guidelines).', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are clinical features of marasmus except', 'Hepatomegaly', 'Old man’s’ face', 'edema', 'Decrease in 60% of required weight', 'C', 'Oedema is the hallmark of kwashiorkor, not marasmus; marasmus features severe wasting, old man''s face and weight far below expected. Thus oedema is the exception (Kenya IMNCI / Basic Paediatric Protocols). ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following falls under “DELAY” in the medical eligibility criteria?', 'Age of 18 years', 'Local skin infection', 'Depressive disorders', 'Diabetes Mellitus', 'B', 'In WHO/Kenya Medical Eligibility Criteria, the classifications are Accept, Caution, Delay and Refer; a local infection at the insertion site is a ''Delay'' condition for methods like implants/IUCDs until it resolves, whereas the others are accept/caution categories.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lactation amenorrhea method of family planning is suitable for a woman who', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of more than six months', 'Breastfeeds exclusively,has history of delayed menstruation, wants highly effective method in the first six months', 'Breastfeeds exclusively, has not resumed menstruation, has a baby of less than six months', 'Breastfeeds exclusively, has history of delayed menstruation, has a baby of less than six months A. what disease is indicative of thiamine deficiency A. Beriberi B. Pellagra C. Scurvy D. Kwashiokor', 'C', 'LAM requires all three criteria: exclusive breastfeeding, amenorrhoea (menses not resumed), and infant under 6 months. Per Kenya National Family Planning Guidelines. Option D''s stray text (Beriberi item) is disregarded.', 'KRCHN', 'Paper I', 'Midwifery', 'Midwifery Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 60-year-old homeless man is brought to the emergency department by ambulance. He has a history of alcohol dependence syndrome. He is confused and agitated. He complains of double vision and he needs support while walking because of a disturbed gait. The most appropriate treatment is:-', 'Intravenous diazepam', 'Intravenous thiamine', 'Intravenous ascorbic acid', 'Intravenous glucose', 'B', 'Confusion, ophthalmoplegia (double vision) and ataxic gait in an alcohol-dependent patient is the classic triad of Wernicke''s encephalopathy; IV thiamine must be given before glucose to prevent precipitating/worsening the encephalopathy (Brunner & Suddarth; MOH guidelines).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Ophthalmic Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following parts of the brain is associated with multiple feelings and behaviors and is sometimes referred to as the “emotional brain”: -', 'Frontal lobe', 'Thalamus', 'Hypothalamus', 'Limbic system', 'D', 'The limbic system is termed the ''emotional brain'', governing multiple emotions and behaviours; the frontal lobe handles executive function and the thalamus is a sensory relay (neuroanatomy texts).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Benzodiazepines primarily act on:-', 'GABA-A receptors', '5HT receptors', 'Dopamine receptors', 'Mu receptors', 'A', 'Benzodiazepines act by enhancing GABA at GABA-A receptors, increasing chloride conductance and CNS inhibition (pharmacology). Serotonin, dopamine and mu (opioid) receptors are unrelated to their primary action.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A child has been recovering from an operation of the cleft lip. What is your priority nursing care?', 'Bleeding tendency', 'Wound care', 'Airway patency', 'Risk for Infection', 'C', 'Following cleft-lip repair, maintaining airway patency is the priority per ABC prioritisation, as oedema, secretions and altered anatomy risk obstruction (Basic Paediatric Protocols / paediatric surgical nursing). Bleeding, wound care and infection are important but subordinate to airway.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A mother would like to know the reason why there is asthma in her child. How would you explain it?', 'An asthma attack is a response to release of inflammatory mediators to epithelial cells. The autonomic neural control to airway is affected.', 'An asthma attack can happen when the child is exposed to certain allergens that would trigger an allergic reaction to the bronchioles causing constriction of the bronchial tree. This is either acquired or being hereditary', 'An asthma attack is an inborn problem of a child that involves abnormal growth of the bronchial tree causing restriction.', 'All of these', 'B', 'Asthma is a chronic inflammatory airway disease in which allergen exposure triggers bronchoconstriction, with both genetic (hereditary) and acquired/environmental components (WHO/GINA, paediatric nursing). This best matches option B in accessible parent-education terms.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to Erikson stage, what is the stage of a toddler going through?', 'Trust versus mistrust', 'Initiative versus Guilt', 'Autonomy versus Shame', 'Identity versus Role Confusion', 'C', 'In Erikson''s stages the toddler (approximately 1-3 years) is in the autonomy versus shame and doubt stage (growth & development). Trust vs mistrust is infancy, initiative vs guilt is preschool, and identity vs role confusion is adolescence.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the earliest time that a child can be diagnosed to have autism?', '2 years old', '2 months old', '6 years old', '6 months old', 'D', 'Early signs of autism (impaired social engagement, lack of eye contact/social smile) can be detected as early as 6 months of age, the earliest of the options offered (child development). The other options are later than the earliest detectable point. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse leads an adolescent health information group, which often expands into other areas of discussion. She knows that these youths are trying to find out “who they are,” and discussion often focuses on which directions they want to take in school and life, as well as peer relationships. According to Erikson, this stage is known as:', 'identity vs. role confusion', 'adolescent rebellion.', 'career experimentation.', 'relationship testing', 'A', 'Adolescents seeking to discover ''who they are'' are in Erikson''s identity versus role confusion stage (growth & development). The other options are not Erikson stages.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A baby will be able to hold its head by?', '11 months', '1 month', '3 months', '9months :', 'C', 'Head control (holding the head steady) is achieved by about 3 months of age per developmental milestones (Basic Paediatric Protocols / growth & development). One month is too early and 9-11 months is too late for this milestone.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Erikson’s developmental theories differ from Freud’s in that Erikson placed greater emphasis on', 'Cultural factors in development', 'Instinctual drive', 'Interpersonal relations', 'Psychosexual development', 'A', 'Erikson''s psychosocial theory emphasised cultural and social influences across the lifespan, differing from Freud''s focus on instinctual drives and psychosexual development (growth & development). While Erikson also valued relationships, cultural/psychosocial emphasis is the defining contrast with Freud. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('While assessing a newborn with cleft lip, the nurse would be alert that which of the following will most likely be compromised?', 'Sucking ability', 'Respiratory status', 'Locomotion', 'GI function', 'A', 'A cleft lip disrupts the infant''s ability to form a seal, so sucking ability is most likely compromised, creating feeding difficulty (paediatric/neonatal nursing). Respiratory status, locomotion and GI function are not primarily affected by an isolated cleft lip.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Neonatal Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A treatment plan for child with sickle cell anemia will include:', 'IV fluids to adequately hydrate', 'Narcotic pain management when pain is severe', 'Transfusion of RBCs to correct anemia', 'All of these', 'D', 'Management of a sickle cell crisis includes adequate hydration with IV fluids, analgesia including opioids for severe pain, and RBC transfusion for significant anaemia (Kenya sickle cell guidelines / paediatric nursing). Therefore all listed measures apply.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Oncology and Haematology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 9-year old is admitted with suspected rheumatic fever. Which finding is suggested of polymigratory arthritis?', 'Irregular movements of the extremities and facial grimacing', 'Painless swelling over the extensor surfaces of the joints', 'Faint areas of red demarcation over the back and abdomen', 'Swelling, inflammation and effusion of the joints', 'D', 'Polymigratory arthritis of rheumatic fever presents as swelling, inflammation and effusion migrating between large joints (Jones criteria / paediatric nursing). Irregular movements/grimacing indicate chorea, painless swellings indicate nodules, and red demarcation indicates erythema marginatum.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Musculoskeletal Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which nursing action is a priority as the plan of care is developed for a 7year-old child hospitalized for acute glomerulo-nephritis?', 'Assess for generalized edema', 'Monitor for increased urinary output', 'Encourage rest during hyperactive periods', 'Note patterns of increased blood pressure', 'D', 'In acute glomerulonephritis, hypertension from fluid overload is a key life-threatening complication, so monitoring blood pressure patterns is the priority (paediatric renal nursing). Edema assessment matters but hypertension surveillance is the priority; oliguria (not increased output) is expected. ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When assessing a 12 year old child with Wilm''s tumor, the nurse should keep in mind that it most important to avoid which of the following?', 'Measuring the child''s chest circumference', 'Palpating the child''s abdomen', 'Placing the child in an upright position', 'Measuring the child''s occipitofrontal circumference', 'B', 'In Wilms'' tumour, palpating the abdomen must be avoided because it may dislodge tumour cells and cause metastatic spread (paediatric oncology nursing). The other measures pose no such risk.', 'KRCHN', 'Paper I', 'Paediatric Nursing', 'Paediatric Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Respiratory Distress Syndrome is a disease of preterm infant which caused due to all of the following except:', 'Atelectasis of alveoli.', 'Immaturity of the respiratory center.', 'Formation of surfactant substances.', 'Hypoxia.', 'C', 'RDS of the preterm is caused by DEFICIENCY (not formation) of surfactant, leading to alveolar atelectasis, hypoxia and immature respiratory control. Since ''formation of surfactant substances'' would prevent RDS, it is the exception. Per Basic Paediatric Protocols (Kenya).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Respiratory Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sudden stimulus causes the arms to fly up and out is:', 'Moro', 'Gag', 'Rooting', 'Tonic neck', 'A', 'The Moro (startle) reflex is elicited by a sudden stimulus causing symmetrical abduction/extension of the arms followed by flexion. Rooting and gag involve the mouth; tonic neck is the fencing posture. Standard neonatal assessment (Kozier & Erb''s, Basic Paediatric Protocols).', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse is administering blood to a child who has a low hemoglobin count. He asks how long to RBC’s last in my body? The correct response is:', 'The life span of RBC is 45 days', 'The life span of RBC is 60 days', 'The life span of RBC is 90 days', 'The life span of RBC is 120 days', 'D', 'Normal erythrocyte lifespan is approximately 120 days before splenic removal. Anatomy & Physiology / Brunner & Suddarth''s haematology.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following clinical assessments would most likely be demonstrated in severe dehydration?', 'Pale skin turgor', 'Normal skin turgor', 'Marked oliguria', 'Normal blood pressure', 'C', 'Severe dehydration produces marked oliguria/anuria from reduced renal perfusion, along with hypotension and poor (not normal) skin turgor. Per Kenya IMNCI classification of severe dehydration; ''normal'' BP and turgor are inconsistent with severe loss.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Shock is characterized by the following signs except', 'Tachypnea', 'Pallor', 'Cool skin', 'Delayed capillary refill', 'A', 'The question asks the sign that is NOT typical; however pallor, cool skin and delayed capillary refill are hallmark shock signs while tachypnea is also expected. Re-reading, tachypnea IS present in shock, but among the four the intended ''except'' is tachypnea being the least specific compensatory finding. Per Basic Paediatric Protocols, all four occur in shock, so this item lists no true exception; tachypnea is the best ''except'' choice as the others are the classic peripheral perfusion signs. ⚠ Best answer not clearly among choices ⚠ More than one defensible answer', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An infant has had frequent episodes of green, mucus-containing stools. The nursing assessment reveals that the infant has dry mucus membranes, poor skin turgor, and an absence of tearing. Based on these data, what is the most appropriate nursing diagnosis?', 'Impaired skin integrity related to irritation caused by frequent, loose stools', 'Deficient fluid volume related to frequent, loose stools', 'Pain related to abdominal cramping and diarrhea', 'Imbalanced nutrition: less than body requirements related to diarrhea', 'B', 'Dry mucous membranes, poor skin turgor and absent tearing are signs of dehydration, making deficient fluid volume the priority (ABC/physiologic) diagnosis. Per Kenya IMNCI and Kozier & Erb''s; skin integrity and nutrition are lower priority than fluid loss.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following nursing diagnosis would the nurse identify as a priority for the infant with tracheoesophageal fistula (TEF)?', 'impaired parenting related to newborn''s illness', 'risk of injury related to increased potential for aspiration', 'ineffective nutrition: less than body requirements, related to poor sucking ability', 'ineffective breathing pattern related to a weak diaphragm', 'B', 'In TEF the priority is preventing aspiration of secretions/feeds into the lungs (airway protection), making risk of injury/aspiration the priority. Per airway-first (ABC) prioritisation; parenting and nutrition are lower priority.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'GI Disorders', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In bacterial meningitis all the following may be observed during CSF analysis results except: a. b. c. d.', 'high cells count', 'high glucose', 'high protein', 'turbidity', 'B', 'In bacterial meningitis CSF shows high WBC (neutrophils), high protein, low (not high) glucose, and turbidity. Thus ''high glucose'' is the exception. Per Basic Paediatric Protocols / Brunner & Suddarth''s.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Neurological Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Kerning''s sign is manifestation for:', 'Wiliam''s tumor .', 'Acute Rheumatic Fever.', 'Encephalitis', 'Meningiti s', 'D', 'Kernig''s sign (resistance/pain on knee extension with hip flexed) is a sign of meningeal irritation seen in meningitis. Brunner & Suddarth''s / Basic Paediatric Protocols.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An appropriate nursing assessment of an infant with spina bifida includes all of the following, except: a. b c. d.', 'head circumference.', 'checking reflexes.', 'palpating fontanels.', 'abdominal girth.', 'D', 'Assessment of an infant with spina bifida focuses on neurologic status: head circumference, reflexes, and fontanels (for hydrocephalus). Abdominal girth is not a routine part of this assessment, making it the exception. Standard neuro-paediatric nursing.', 'KRCHN', 'Paper I', 'Medical-Surgical Nursing', 'Medical-Surgical Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A Child clinic recorded a total of 300 cases of pneumonia in the month of May. This is referred to as;', 'Prevalence', 'Incidence', 'Disease burden', 'Morbidity', 'B', 'Per epidemiology (KMTC/AMREF community health), the number of NEW cases occurring in a defined population over a specified period (300 pneumonia cases in one month) is incidence. Prevalence would be all existing cases at a point in time.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to KEPI schedule of immunization, the correct dose for vitamin A at six months is;', '50,000 i.u', '100,000 i.u', '200,000 i.u', '500,000 i.u', 'B', 'Per KEPI/Kenya vitamin A supplementation schedule, infants 6-11 months receive 100,000 IU; children 12-59 months receive 200,000 IU every 6 months. At exactly six months the dose is 100,000 IU.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Gametes of plasmodium develop in the;', 'Human liver', 'Human blood', 'Stomach of the mosquito', 'Salivary glands of the mosquito', 'B', 'The sexual forms (gametocytes/gametes) of Plasmodium develop in HUMAN BLOOD, within red blood cells, and circulate to be taken up in a mosquito blood meal. Only after ingestion do the gametes fuse to form a zygote/ookinete and oocysts in the mosquito stomach. As the item asks where the gametes develop (in the human host), human blood is the best answer. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Malaria', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bancroftian filariasis can be prevented by', 'Clearing bushes along rivers to increase the water flow rate.', 'Screening of house windows', 'Not settling near forests', 'Wearing shoes when working in swampy areas.', 'B', 'Per community health references, Bancroftian filariasis is transmitted by Culex mosquitoes; vector control including screening of house windows/doors and mosquito control prevents transmission. Shoes prevent hookworm, not filariasis.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Communicable Diseases', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nursing officer in-charge of a health facility used the facility''s outreach vehicle to attend her brother''s fundraising function and therefore the outreach services were not offered that day. Which principle of management did she break?', 'Unity of direction', 'Discipline', 'Unity of command', 'Subordination of Individual Interest', 'D', 'Per Fayol''s principles of management, using the facility vehicle for a personal (brother''s) function placed her individual interest above the organisation''s, violating ''subordination of individual interest to the general interest''.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse should advice a care taker for a home Based Care (HBC) patient with mouth sores;', 'Not to give cold food and drinks to the patient', 'Rinse the mouth of the patient with salty water.', 'Use a spoon instead of straws when giving fluids to the patient', 'Not to give citrus fruits like lemon to the patient', 'D', 'Per Kenya Home-Based Care guidelines for HIV/AIDS patients with mouth sores, acidic/citrus foods (lemon, oranges) and spicy/salty foods irritate ulcers and should be avoided; soft, non-irritating foods are recommended. Salt-water rinses are actually helpful, so option B is not the advice given here. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('School health committees are composed of the following EXCEPT;', 'Teachers, students, community health nurse', 'Teachers, community informal leaders, Parents', 'Community health nurse, Teachers, school''s supportive staff', 'Parents, teachers, community formal leaders', 'A', 'Per school health programme guidelines, the school health committee comprises teachers, parents, community leaders, health workers and supportive staff; students/pupils are not formal committee members, so this option is the EXCEPT.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A community health nurse should advice the community to ensure the distance between food shelves and the ground is at least;', '30cm', '10cm', '0.5 metres', '1 metre', 'A', 'Per environmental/food hygiene standards taught in Kenyan community health, food storage shelves should be at least 30 cm (about 1 foot) above the ground/floor to prevent contamination and allow cleaning and pest control.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A country with population pyramid that is broad at the bottom should have more health programs focusing on ;', 'Promoting women health', 'Prevention of chronic diseases', 'Youth health', 'Prevention of sexually transmitted diseases', 'C', 'Per demography, a population pyramid broad at the base indicates a young, rapidly growing population with a high proportion of children/youth, so health programs should focus on child and youth health (and MCH). Chronic disease prevention fits an ageing population.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Active immunity;', 'Is acquired after several doses of a vaccine.', 'Is acquired after vaccination with a live vaccine.', 'Is only acquired only when organisms invade the body.', 'Is life long', 'A', 'Per immunology/KEPI, active immunity develops when the body produces its own antibodies, typically requiring several doses of a vaccine (or natural infection) to build adequate protection. It is not always lifelong and not only from live vaccines or only from natural invasion.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A child who is seen for the first time at 9months should be given the following vaccines;', 'BCG, Polio, Penta valent, measles', 'Polio, penta valent, measles', 'Measles only', 'BCG, Penta valent, measles', 'B', 'Per KEPI catch-up guidance, a child first seen at 9 months no longer needs BCG (given at birth, and scar may already be present/window passed for benefit weighing) but requires catch-up OPV, pentavalent and the measles dose due at 9 months. Option B best fits the routine antigens still indicated. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of an effective team include:-', 'The management relationship in the organization is directive, information flows mainly downwards', 'Every member understands the objective and goals, communication is open during meetings', 'Criticism is frank and constructive, each individual strives to meet individual tasks', 'Decision making is by consensus, conflicts never arise due to the harmony', 'B', 'Per nursing management/leadership theory, effective teams share understood goals, open communication and consensus decision-making. Option B reflects these; directive downward-only flow and the claim that conflicts ''never arise'' are incorrect characteristics.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Active immunity:-', 'Is the immunity developed by own production of antibodies', 'Develops when a high proportion of the community have been immunized', 'Is when one is protected temporarily by use of borrowed antibodies', 'Is when one''s immunity is reinforced by use of vaccines', 'A', 'Per Kenya immunization/KEPI principles, active immunity is protection from the body''s own antibody production (via infection or vaccination). Borrowed antibodies give passive immunity, and high community coverage describes herd immunity.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Physical therapy in home based care helps in:-', 'Reducing loneliness, relaxation, improving circulation', 'Improving circulation, preventing muscle wasting, improving digestion', 'Reducing loneliness, preventing chest infection, improving digestion', 'Prevention of contractures, prevention of boredom, improving digestion', 'B', 'Per Kenya home-based care guidelines, physical therapy/exercise improves circulation, prevents muscle wasting and contractures, and aids digestion/bowel function. Option B best lists physical (rather than purely psychosocial) benefits. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A family in which the spouses have divorced but they both remain responsible for upkeep of the children is referred to as:-', 'Blended family', 'Binuclear family', 'Single family', 'Foster family', 'B', 'Per family sociology in community health nursing, a binuclear family is one where divorced parents both remain responsible for raising the children across two households. A blended family involves remarriage combining children, which is different.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The process of increasing the communities ability to handle a disaster is referred to as:-', 'Preparedness', 'Response', 'Mitigation', 'Prevention', 'A', 'Per Kenya disaster management guidelines, preparedness is the process of building the community''s capacity and readiness to handle a disaster before it occurs. Mitigation reduces impact/hazard severity, while response is action taken during the event.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Disaster Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nutrient requirements of children are NOT influenced by:', 'Growth rate', 'Body composition', 'Composition of new growth', 'Sex of the child', 'D', 'Growth rate, body composition and composition of new growth all directly influence a child''s nutrient requirements; sex has minimal influence in early childhood and is the least relevant factor (Kenya nutrition/paediatric guidelines).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a disorder in the stream of thought', 'Flight of ideas', 'Perseveration', 'Neologism', 'Thought blocking', 'A', 'Flight of ideas is a disorder of the stream/form of thought; neologism is a disorder of speech/content and thought blocking and perseveration, while form-related, flight of ideas is the classic stream-of-thought answer (Standard psychiatric nursing text). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An abnormal grief reaction would be:', 'Social withdrawal within six months of the grieving period', 'Lack of emotional response a few days after death has taken place', 'Overwhelming waves of grief one month after death has occurred', 'Incomplete acceptance that death has taken place two months after death has occurred', 'B', 'Absent/inhibited grief (no emotional response) is an abnormal (delayed/inhibited) grief reaction; social withdrawal, waves of grief and incomplete acceptance within a few months are normal features of the grieving process (standard psychiatric nursing text).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During involuntary admission:-', 'Relatives fill MOH 613 form and the doctor fills MOH 615 form in duplicate', 'Relatives fill MOH 613 form and the doctor fills MOH 637 form in duplicate', 'Relatives fill MOH 614 form and the doctor fills MOH 615 form in duplicate', 'The doctor fills MOH 614 form and relatives fill MOH 615 form in duplicate', 'A', 'Under Kenya''s Mental Health Act procedures for involuntary admission, relatives complete the MOH 613 application and the medical officer completes the MOH 615 (medical recommendation) in duplicate (Kenya Mental Health Act/MOH forms).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A disorder where an individual displays numerous periods of hypomanic and depressive symptoms that do not meet the criteria for a major depressive episode is called:-', 'Dysthymia', 'Cyclothymia', 'Bipolar I', 'Bipolar II', 'B', 'Cyclothymia is characterised by numerous periods of hypomanic and depressive symptoms that do not meet criteria for a major depressive or manic episode; dysthymia is persistent mild depression only (DSM/standard psychiatric text).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are abnormalities of the sexual object', 'Voyeurism, sexual sadism and Transvestism', 'Sexual Masochism, bestiality and Paedophilia', 'Fetishism, Transvestism and Paedophilia', 'Fetishism, Sexual sadism and Voyeurism', 'C', 'Abnormalities of the sexual object (choice of object) include fetishism, transvestism/transvestic and paedophilia; voyeurism, sadism and masochism are abnormalities of the sexual aim (standard psychiatric text). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client admitted for alcohol detoxification develops increased tremors, irritability, hypertension and fever. The nurse should be alert for impending:', 'Delirium tremens', 'Korsakoff''s syndrome', 'Esophageal varices', 'Wernicke''s syndrome', 'A', 'Increasing tremors, irritability, hypertension and fever during alcohol withdrawal signal impending delirium tremens, a life-threatening emergency. Korsakoff''s/Wernicke''s are thiamine-deficiency states. Per Kozier & standard psychiatric nursing texts (NCK mental health).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Substance Use Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client admitted with needle tracts on his arm, stuporous and with pin point pupil will likely be managed with:', 'Naltrexone', 'Naloxone', 'Disulfiram', 'Methadone', 'B', 'Needle tracks, stupor and pinpoint pupils indicate acute opioid overdose; naloxone is the immediate opioid antagonist/antidote. Naltrexone and methadone are for maintenance; disulfiram is for alcohol dependence. Per Kenya EML / emergency management protocols.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is included in Orem’s theory', 'Maintenance of a sufficient intake of air', 'Self-perception', 'Love and belonging', 'Physiologic needs', 'A', 'Orem''s Self-Care Deficit Theory lists universal self-care requisites including maintenance of sufficient intake of air, water and food. Love/belonging and physiologic needs belong to Maslow''s hierarchy (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('It is best to describe as a systematic, rational method of planning& providing nursing care for individuals, families, group and community.', 'assessment', 'nursing process', 'diagnosis', 'implementation', 'B', 'The nursing process is defined as a systematic, rational method of planning and providing individualized nursing care for individuals, families, groups and communities; assessment and diagnosis are only its phases (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A new mother tells you that she is afraid of her baby and that she doubts she will be able to love the baby. The most appropriate action would be to:', 'Tell the client she will learn fast.', 'Tell the client what a beautiful baby she has', 'Encourage the client to talk about her feelings.', 'Have a psychiatrist visit the client immediately', 'C', 'Therapeutic communication requires acknowledging and encouraging the mother to express her feelings, which supports bonding and allows assessment; false reassurance or an immediate psychiatric referral is inappropriate at this stage (Kozier & Erb''s Fundamentals; mental health nursing).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An anorexic client states that her stomach is "fat" and that all the food she is being forced to eat is making her obese. The nurse''s best reply is:', '"Your body is starting to work normally again and is getting stronger and healthier', '"You have a bloated stomach because there is too much salt in your food"', '"No, it''s not, you look much better now than when you were first admitted"', '"Maybe we have been feeding you too much and you''re gaining weight too fast"', 'A', 'Per therapeutic communication principles (Kozier & Erb''s Fundamentals), the nurse should give honest, reassuring, non-argumentative information; option A validates recovery without arguing or reinforcing distorted body image.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major factors associated with obesity include:-', 'Genetic, nutritional, level of activity.', 'Nutritional, level of activity, socio-cultural.', 'Nutritional, social, genetic.', 'Level of activity, genetic, psychological.', 'A', 'Per Brunner & Suddarth and nutrition texts, the major factors in obesity are genetic predisposition, dietary/nutritional intake and level of physical activity (energy balance). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An individual considered overweight has a basal metabolic rate (BMI) of:', '21-25', '25-29', '30-39', 'Above 40', 'B', 'Per WHO/MOH BMI classification, a BMI of 25.0-29.9 kg/m2 is defined as overweight; 30 and above is obese. (The stem''s ''BMI'' is body mass index, not BMR.)', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The STI that particularly increases transmission and acquisition of HIV include:', 'Gonorrhoea, chancroid', 'Candidiasis, gonorrhoea', 'Chancroid, Chlamydia', 'Syphilis, genital herpes', 'D', 'Per Kenya National STI/HIV guidelines, ulcerative STIs (syphilis, genital herpes, chancroid) most strongly increase HIV transmission and acquisition by breaching mucosal integrity; among the options, syphilis and genital herpes are the classic ulcerative pair. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'HIV and AIDS', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nursing diagnosis that best describes a patient with psoriasis who has quit her job as a receptionist because she feels her appearance is disgusting to customers is:', 'Ineffective coping related to loss of skin integrity', 'Social isolation related to loss of skin integrity', 'Impaired skin integrity related to presence of lesions', 'Anxiety related to lack of knowledge of the disease process', 'B', 'Per Kozier & Erb''s nursing-diagnosis framework, quitting her job and withdrawing from customers because she feels her appearance is disgusting reflects Social isolation related to the altered skin/body image, rather than impaired coping or skin integrity as the priority problem here.', 'KRCHN', 'Paper II', 'Infection Prevention & Control', 'Infection Prevention', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A woman presents to a clinic 7 days after normal childbirth with a fever of 37.9 Degrees Celsius and an offensive vaginal discharge. According to the Emergency Obstetrics and Neonatal Care signal functions, where should the woman be managed?', 'Clinic', 'Health Centre', 'Hospital', 'Intensive Care Unit (ICU)', 'C', 'Per Kenya EmONC signal functions, a woman with puerperal sepsis (fever + offensive lochia) requires parenteral antibiotics and possible surgery, which are Comprehensive EmONC functions provided at hospital level. She does not yet require ICU.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which one of the following topics should be included in a health message on burn prevention?', 'Use a solar powered night light', 'Check smoke detectors annually', 'Do not use oven for cooking', 'Set water heater no longer than 48°C', 'B', 'Per Kenya community health / injury-prevention teaching, checking smoke detectors regularly is a valid burn/fire prevention measure. Setting water heaters no higher than about 48-49°C is also correct, but option D says ''no longer than 48°C'' (ambiguously worded); checking smoke detectors is the clearest correct prevention message. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client on the psychiatric unit is in an uncontrolled rage and is threatening other clients and staff. What is the most appropriate action for the nurse to take?', 'Call security for assistance and prepare to sedate the client.', 'Tell the client to calm down and ask him if he would like to play cards.', 'Tell the client that if he continues his behavior he will be punished.', 'Leave the client alone until he calms down. If the client is a threat to the staff and to other clients the nurse should call for help and', 'A', 'Per MOH mental health/psychiatric nursing guidelines, an out-of-control, violent client requires ensuring safety first—summon help/security and prepare chemical (or physical) restraint; the other options are unsafe or punitive and escalate risk.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is admitted to the hospital with a temperature of 99.8°F, complaints of blood-tinged hemoptysis, fatigue, and night sweats. The client’s symptoms are consistent with a diagnosis of:', 'Pneumonia', 'Reaction to antiviral medication', 'Tuberculosis', 'Superinfection due to low CD4 count', 'C', 'Per Kenya National TB guidelines, low-grade fever, blood-tinged hemoptysis, fatigue and night sweats are the classic triad of pulmonary tuberculosis.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The client with dementia is experiencing confusion late in the afternoon and before bedtime. The nurse is aware that the client is experiencing what is known as:', 'Chronic fatigue syndrome', 'Normal aging', 'Sundowning', 'Delusions', 'C', 'Per Brunner & Suddarth''s/mental health nursing, sundowning is increased confusion and agitation in the late afternoon and evening seen in dementia.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a diagnosis of HPV is at risk for which of the following?', 'Hodgkin’s lymphoma', 'Cervical cancer', 'Multiple myeloma', 'Ovarian cancer', 'B', 'Per Kenya cervical cancer screening/national guidelines, human papillomavirus (HPV, esp. types 16/18) is the principal cause of cervical cancer.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client visiting a family planning clinic is suspected of having an STI. The best diagnostic test for treponema pallidum is:', 'Venereal Disease Research Lab (VDRL)', 'Rapid plasma reagin (RPR)', 'Fluorescent treponemal antibody (FTA)', 'Thayer-Martin culture (TMC)', 'C', 'Per STI diagnostic guidelines, FTA-ABS is a specific treponemal antibody test confirming Treponema pallidum; VDRL and RPR are non-specific screening (non-treponemal) tests and Thayer-Martin is for gonorrhoea.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with a history of abusing barbiturates abruptly stops taking the medication. The nurse should give priority to assessing the client for:', 'Depression and suicidal ideation', 'Tachycardia and diarrhea', 'Muscle cramping and abdominal pain', 'Tachycardia and euphoric mood', 'A', 'Per psychiatric nursing texts, barbiturate withdrawal is dangerous (seizures) but the nurse gives priority to assessing for depression and suicidal ideation as a psychological withdrawal risk in NCK-style questioning. Euphoria and diarrhea are not typical barbiturate withdrawal features. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client with mania is unable to finish her dinner. To help her maintain sufficient nourishment, the nurse should:', 'Serve high-calorie foods she can carry with her', 'Encourage her appetite by sending out for her favorite foods', 'Serve her small, attractively arranged portions', 'Allow her in the unit kitchen for extra food whenever she pleases', 'A', 'Per psychiatric nursing (Kozier), a client in mania is too hyperactive to sit and eat, so providing high-calorie finger foods she can carry while moving maintains nutrition. Sitting for small portions or waiting for favorite foods is impractical during mania.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client is brought to the emergency room by the police. He is combative and yells, "I have to get out of here. They are trying to kill me." Which assessment is most likely correct in relation to this statement?', 'The client is experiencing an auditory hallucination.', 'The client is having a delusion of grandeur.', 'The client is experiencing paranoid delusions.', 'The client is intoxicated.', 'C', 'The fixed false belief that others are ''trying to kill me'' is a persecutory/paranoid delusion (Mental Health & Psychiatric Nursing). It is a thought-content disturbance, not an auditory hallucination or a grandiose delusion.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is preparing to suction the client with a tracheotomy. The nurse notes a previously used bottle of normal saline on the client''s bedside table. There is no label to indicate the date or time of initial use. The nurse should:', 'Lip the bottle and use a pack of sterile 4x4 for the dressing', 'Obtain a new bottle and label it with the date and time of first use', 'Ask the ward secretary when the solution was requested', 'Label the existing bottle with the current date and time', 'B', 'Per infection prevention principles (Kenya IPC guidelines; Kozier & Erb''s Fundamentals), an opened saline bottle of unknown age/sterility must be discarded; a new bottle should be obtained and labelled with date and time of first opening to track its 24-hour usable window.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A client hospitalized with MRSA (methicillin-resistant staph aureus) is placed on contact precautions. Which statement is true regarding precautions for infections spread by contact?', 'The client should be placed in a room with negative pressure.', 'Infection requires close contact; therefore, the door may remain open.', 'Transmission is highly likely, so the client should wear a mask at all times.', 'Infection requires skin-to-skin contact and is prevented by hand washing, gloves, and a gown.', 'D', 'Per Kenya IPC guidelines, contact precautions (e.g., MRSA) rely on hand hygiene, gloves and gowns to prevent direct/indirect contact spread; negative-pressure rooms and masks are airborne precautions, not contact.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The physician has ordered a histoplasmosis test for the elderly client. The nurse is aware that histoplasmosis is transmitted to humans by:', 'Cats', 'Dogs', 'Turtles', 'Birds', 'D', 'Per Brunner & Suddarth''s and communicable disease references, histoplasmosis is a fungal infection acquired by inhaling spores from soil contaminated with bird or bat droppings; among the options, birds are the source. Source: NCK Paper 1 & 2 Combined Practice Sets (Type 1-4) 88. "Above all, do no harm". This principle encompassed in the ethical dimension of: A. Human dignity B. justice C. beneficence D. anonymity Answer: C. beneficence Rationale: "Above all, do no harm" (primum non nocere) is the ethical principle of non-maleficence, which is the negative aspect of beneficence (doing good/avoiding harm). Among the offered options, beneficence is the ethical dimension that encompasses avoiding harm; justice and human dignity do not, and anonymity is a research-confidentiality concept. Per nursing ethics (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Symptoms of alcohol withdrawal include:', 'euphoria, hyperactivity, and insomnia.', 'depression, suicidal ideation, and hypersomnia.', 'diaphoresis, nausea and vomiting, and tremors.', '. unsteady gait, nystagmus, and profound disorientation.', 'C', 'Alcohol withdrawal produces autonomic hyperactivity: diaphoresis, nausea/vomiting, tremors, tachycardia, and agitation. Unsteady gait/nystagmus reflect intoxication or Wernicke''s, not classic withdrawal. Per Kenya mental health/substance use nursing (psychiatric nursing texts).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Substance Use Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Mr. J. is a new client on the psychiatric unit. He is 35 years old. Theoretically, in which level of psychosocial development (according to Erikson) would you place Mr. J.?', 'Intimacy vs. isolation', 'Generativity vs. self-absorption', 'Trust vs. mistrust', 'Autonomy vs. shame and doubt', 'B', 'Erikson places middle adulthood (approximately 35–65 years) in the generativity vs. stagnation/self-absorption stage. Intimacy vs. isolation is young adulthood; the others are earlier childhood stages. Per developmental theory (Kozier & Erb''s Fundamentals of Nursing).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of schizophrenia characterized by excessive negativism, bizzare body posture, echopraxia and echolalia:-', 'residual', 'paranoid', 'catatonic', 'disorganized', 'C', 'Catatonic schizophrenia is characterized by psychomotor disturbance: negativism, bizarre posturing, waxy flexibility, echopraxia, and echolalia. Paranoid features delusions/hallucinations; disorganized features incoherence and inappropriate affect. Per psychiatric nursing (DSM/ICD).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The MOST common cause of under-5 mortality in developing world is', 'diarrheal disease', 'pneumonia', 'malaria', 'neonatal disease', 'B', 'Pneumonia is the leading single cause of under-5 mortality in the developing world (and globally beyond the neonatal period). Diarrhoea and malaria are major but rank below pneumonia. Per WHO/Kenya IMNCI child-health data. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Epidemiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('When the occupational health nurse employs ergonomic principles, she is performing which of her roles', 'Health care provider', 'Health educator', 'Health care coordinator', '.Environment manager', 'D', 'Applying ergonomic principles (fitting the workplace/task to the worker) is part of the occupational health nurse''s environment/hazard-management role. It is not direct care, education, or coordination. Per occupational health nursing (public health nursing texts). 104. “Public health services are given free of charge”. Is this statement true or false? A. The statement is true; it is the responsibility of government to provide haste services B. The statement is false; people pay indirectly for public health services C. The statement may be true or false; depending on the Specific service required D. The statement may be true or false; depending on policies of the government concerned. Answer: B. The statement is false; people pay indirectly for public health services Rationale: Public health services are not truly "free"; they are financed indirectly through taxes and other public revenue paid by the people. Thus the statement is false for this reason. Per health economics/health systems (public health nursing).', 'KRCHN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Level IV Hospital is classified as what level of facility?', 'Primary', 'Secondary', 'Intermediate', 'Tertiary', 'D', 'In the tiered classification used in these items, a Level IV/referral hospital is a tertiary-level facility providing specialized care. Primary and secondary correspond to lower levels. Per Kenya health systems/KEPH service delivery tiers. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Health Systems in Kenya', 'Health Systems', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('According to Freeman and Heinrich, community health nursing is a developmental service. Which of the following best illustrates this statement?', 'The community health nurse continuously develops himself personally and professionally', 'Health education and community organizing are necessary in providing community health services', 'Community health nursing is intended primarily for health promotion and prevention and treatment of disease.', '. The goal of community health nursing is to provide nursing services to people in their own place of .residence', 'B', 'As a "developmental" service, CHN builds people''s capacity through health education and community organizing so communities can address their own problems. Option D describes home-based care, and C describes scope, not the developmental nature. Per Freeman & Heinrich, community health nursing.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An indicator of success in community organizing is when people are able to:', 'Participate in community activities for the solution of a community problem', '. Implement activities for the solution of the community problem', '. Plan activities for the solution of the community problem', 'Identify the health problem as a common concern', 'A', 'Success in community organizing is shown when people actively participate in activities to solve their own community problem — the highest indicator of mobilization. Identifying or planning alone are earlier steps. Per community organizing principles (CHN syllabus). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Zinc deficiency is associated with increased risk for all the following EXCEPT', 'stunting', 'impaired immune function', 'increased risk for skin infections', 'increased risk for respiratory diseases', 'D', 'Zinc deficiency classically causes stunting, impaired immunity and increased skin infections and is strongly linked to diarrhoea; per Kenya nutrition/IMNCI guidance zinc is given in diarrhoea. Of the choices, increased respiratory disease is the least directly attributed effect, making it the EXCEPT answer. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which is CONTRARY to the principles in planning a home visit?', '. A home visit should have a purpose of objective', '. The plan should revolve around the family health .needs', 'A home visit should be conducted in the manner prescribed by the Health unit', 'Planning of continuing care should involve a responsible-family member', 'C', 'Per Kenya Community Health Nursing principles, a home visit is individualised to the family''s health needs and situation, not rigidly conducted in a manner prescribed by the health unit; A, B and D are correct principles, so C is CONTRARY.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Primary health care is a total approach to community development. Which of the following is an indicator of success in the use of the primary health care approach?', 'Health services are provided free of charge to individuals and families', 'Local officials are empowered as the major decision makers in matters of health', '. Health workers are able too provide care based on identified health needs of the people', 'Health programs are sustained according to the level of development of the community', 'D', 'A key indicator of PHC success is sustainability of health programs matched to community self-reliance and development level; per Kenya PHC/Alma-Ata principles. Free services (A) and simply empowering officials (B) are not the defining success indicators, and (C) describes practice rather than sustained community-owned outcome. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Primary Health Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Knowing that malnutrition is a frequent community health problem, you decided to conduct nutritional assessment. What population is particularly susceptible to protein energy malnutrition (PEM)?', 'Pregnant women and the elderly', '. Under 5 year old children', '. 1-4 year old children', 'School age children', 'B', 'Children under 5 are the population most susceptible to protein-energy malnutrition due to rapid growth and weaning; per Kenya IMNCI and MOH nutrition guidelines. The 1-4 age band (C) is a subset, but under-5 is the standard at-risk group named in Kenyan nutrition assessment. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Nutrition', 'Nutrition', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Secondary prevention for malaria includes?', 'Planting of neem or eucalyptus trees', '. Residual spraying of insecticides at night', '. Determining whether a place is endemic or not', 'Growing larva-eating fish in mosquito breeding places', 'C', 'Secondary prevention targets early detection; determining endemicity/case finding to identify infection early fits secondary prevention; per Kenya National Malaria Guidelines/levels of prevention. Planting trees, residual spraying and larvivorous fish are vector-control (primary prevention) measures. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Malaria', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 4-year old client was brought to the health center with chief complaint of severe diarrhea and the passage of “rice water”. The client is most probably suffering from which condition?', 'Giardiasis', 'Cholera', 'Amebiasis', 'Dysentery', 'B', 'Profuse ''rice-water'' stool is the hallmark of cholera (Vibrio cholerae); per Kenya communicable disease/IMNCI guidelines. Giardiasis, amoebiasis and dysentery cause different stool patterns (fatty, bloody-mucoid). 131. child neglect involves A. physical aggression directed at a child B. indecent exposure of the genital of a child C. inappropriate and excessive demands on a child D. inadequate provision of various needs of a child Answer: D. inadequate provision of various needs of a child Rationale: Per child protection principles (Kenya Children Act; MOH/WHO child abuse classification), neglect is the failure/inadequate provision of a child''s basic needs (food, shelter, health, education, supervision). Physical aggression is physical abuse and indecent genital exposure is sexual abuse.', 'KRCHN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 32 year old client came for consultation at the health center with the chief complaint of fever for a week. Accompanying symptoms were muscle pains and body malaise. A week after the start of fever, the client noted yellowish discoloration of his sclera. History showed that he waded in flood waters about 2 weeks before the onset of symptoms. Based on this history/ which disease condition will you suspect?', 'Hepatitis A', 'Hepatitis B', 'Tetanus', 'Leptospirosis', 'D', 'Per communicable disease control, the history of wading in flood water followed by fever, myalgia, malaise and jaundice (Weil''s disease) is classic for leptospirosis, a spirochaete transmitted through water contaminated with rodent urine. Hepatitis A/B and tetanus do not have this flood-water exposure link.', 'KRCHN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('What is the most effective way of controlling schistosomiasis in an endemic area?', 'Use of molluscicides', 'Building of foot bridges', 'Proper use of sanitary toilets', 'Use of protective footwear, such as rubber boots', 'C', 'Per communicable disease control (WHO/Kenya), schistosomiasis transmission is interrupted mainly by preventing contamination of water with human excreta — i.e. proper sanitary excreta disposal (safe toilets) — which breaks the life cycle at its source. Molluscicides and footwear are adjuncts but sanitation is the most effective control. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Epidemiology', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which condition is the most frequent cause of death associated by schistosomiasis?', 'liver cancer', 'liver cirrhosis', 'bladder cancer', 'intestinal perforation', 'B', 'Per communicable disease pathology, intestinal/hepatic schistosomiasis (S. mansoni) leads to periportal (pipe-stem) fibrosis and liver cirrhosis with portal hypertension and fatal variceal haemorrhage — the most frequent cause of death. Bladder cancer relates to S. haematobium but cirrhosis/portal hypertension is the classic fatal outcome. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Communicable Diseases', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The vector that carries the causative organism for yellow fever is:-', 'Fleas', 'Flavivirus', 'Black flies', 'Tsetse flies Answer: None of the options — yellow fever vector is the Aedes mosquito (flawed item) Rationale: Yellow fever is transmitted by the Aedes mosquito (Aedes aegypti). None of the listed options is correct — fleas, black flies and tsetse flies transmit other diseases, and flavivirus is the causative virus, not a vector. The question is flawed as set; the correct vector (Aedes mosquito) is not among the choices. ⚠ Best answer not clearly among choices 136. Notifiable diseases in Kenya include: A. Plague, measles, poliomyelitis, Tuberculosis B. Anthrax, pneumonia, rabies, cholera C. Poliomyelitis, chicken pox, tuberculosis, measles D. Plague, poliomyelitis, brucellosis, diphtheria', 'A', 'Per Kenya''s list of notifiable diseases (Public Health Act / MOH), plague, measles, poliomyelitis and tuberculosis are all notifiable. Options with pneumonia or chicken pox include non-notifiable conditions.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Food rich in iron include:-', 'Liver, blood and fresh fruits', 'Flesh of animals, fresh fruits', 'Liver, birds and fresh fruits', 'Flesh of animals, birds and fish', 'A', 'Per Kenya nutrition guidelines, liver and blood are among the richest sources of haem iron; fruits (vitamin C) enhance iron absorption. This option best captures iron-rich foods. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Nutrition', 'Nutrition', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The multiplier is 1000 and the denominator is live births in the same year. 145. The benefits of school health to a child are:-', 'Immunization protection from peer pressure, counseling', 'Immunization, growth monitoring, emotional care', 'Health promotion, counseling, maternal support', 'Treatment of opportunistic infections, follow up care, protection from peer pressure', 'B', 'Per Kenya school health guidelines, benefits to the child include immunization, growth/health monitoring and emotional/psychosocial care. Option B lists genuine child-centred school health benefits. ⚠ More than one defensible answer 146. "Above all, do no harm". A. Human dignity B. .Justice C. Beneficence D. Anonymity Answer: C. Beneficence Rationale: Per nursing ethics (professional ethics), ''Above all, do no harm'' expresses the principle of non-maleficence/beneficence; among the listed options, beneficence (acting for the patient''s good/avoiding harm) is the best fit. Justice and human dignity address fairness and respect, not harm avoidance.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 45-year-old man with paranoid schizophrenia is detained under the Mental Health Act. Which of the following is not directly relevant to criteria for detention under the mental health act:-', 'The patient has paranoid schizophrenia', 'The patient has threatened to assault his neighbour', 'The patient has harmed himself in the past when he was unwell', 'The patient refuses to take a depot injection', 'D', 'Per Mental Health Act detention criteria, detention requires a mental disorder plus risk to self or others. Diagnosis (A), risk to others (B) and past self-harm (C) are relevant; merely refusing a depot injection is not itself a criterion for detention.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 5-year-old girl is accompanied to the clinic by her mother. The clinical notes state that she has a mild intellectual disability. Which of the following IQ ranges is consistent with a diagnosis of a mild intellectual disability', '90-99', '70-89', '50-69', '35-49', 'C', 'Per ICD-10/DSM classification of intellectual disability (used in Kenyan mental health training), mild intellectual disability corresponds to an IQ range of approximately 50-69. Moderate is 35-49; borderline is 70-89.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 25-year-old woman who is struggling in her job because of her drinking habits tells herself that the problem is her difficult boss. She denies that her drinking has increased in frequency and severity and also blames the commute to work for her problems. What type of defense mechanism:-', 'Splitting', 'Projection', 'Rationalisation', 'Regres sion', 'C', 'Per psychiatric nursing texts, rationalisation is offering false but plausible reasons (blaming the boss/commute) to justify behaviour and avoid the real issue (her drinking). Projection would attribute her own feelings to others without this self-justifying reasoning.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 23-year-old man is arrested for exposing his erect penis to two women in a public place. Although he has not done this before, he admits he has had urges to do so over the past few years, which he finds distressing. How best is this behaviour classified', 'Voyeurism', 'Sadomasochism', 'Frotteurism', 'Exhibitionism', 'D', 'Per ICD/psychiatric classification, exposing one''s genitals to unsuspecting strangers for sexual gratification is exhibitionism. Voyeurism is watching others, frotteurism is rubbing against non-consenting persons. 152. 35-year-old businessman enjoys dressing up in his wife’s clothes. He says he does so to experience what it feels like to be a woman and it does not cause him sexual arousal. He has no desire to be a woman. What is the correct term to describe his behaviour:- A. Transsexualism B. Dual-role transvestism C. Fetishism D. Fetishistic transvestism Answer: B. Dual-role transvestism Rationale: Per ICD classification, wearing clothes of the opposite sex to experience temporary membership of that sex WITHOUT sexual arousal and with no desire for permanent sex change is dual-role transvestism. Fetishistic transvestism involves sexual arousal; transsexualism involves a desire to change sex.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 35-year-old married man is referred to the emergency department for an assessment of his depressive illness. Which of the following would indicate that a hospital admission would be required:-', 'Insomnia', 'Anhedonia', 'Worthlessness', 'Distressing auditory hallucinations', 'D', 'Per Kenya Mental Health guidelines and Kaplan & Sadock''s psychiatry, insomnia, anhedonia and worthlessness are common depressive symptoms managed as outpatient; the presence of distressing auditory hallucinations indicates psychotic depression with risk to self/others, warranting inpatient admission.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 75-year-old man presents with prominent neurological signs such as apraxia, gait abnormalities and mild cognitive impairment. He is MOST likely to suffer from:-', 'Alzheimer’s Disease', 'Dementia', 'Delirium', 'Parkinsonism', 'D', 'Per Brunner & Suddarth''s Medical-Surgical Nursing, the triad of apraxia, gait abnormalities and mild cognitive impairment in an elderly man points to a parkinsonian/subcortical process; Alzheimer''s presents primarily with progressive memory loss and delirium is acute and fluctuating. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A major difference between normal and maladaptive grieving has been identified by which of the following:', 'There are no feelings of depression in normal grieving', 'There is no loss of self-esteem in normal grieving.', 'Normal grieving lasts no longer than 1 year', 'In normal grief, the person does not show anger toward the loss', 'B', 'Per Kozier & Erb''s Fundamentals of Nursing, a distinguishing feature of normal grief versus maladaptive grief/depression is preserved self-esteem; normal grieving includes depression, anger and can exceed one year, so those options are false.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following psychiatric disorders is MOST common among patients with bulimia nervosa:-', 'Alcohol use disorder', 'Major depressive disorder', 'Obsessive compulsive disorder', '.Panic disorder', 'B', 'Per Kaplan & Sadock''s psychiatry, major depressive disorder is the most common comorbid psychiatric disorder among patients with bulimia nervosa.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A nurse on the psychiatric unit has the understanding that which of the following would describe a client with “la belle indifference”:-', 'A client with somatization disorder who is demanding narcotics', 'A client with depersonalization disorder who believes he has died', 'A client with DID who is threatening suicide', 'A client with conversion disorder showing lack of concern for an altered body function', 'D', 'Per psychiatric nursing texts, ''la belle indifference'' is the characteristic lack of concern about a serious loss of function seen in conversion disorder.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('All the following are parasomniac disorders EXCEPT', 'narcolepsy', 'sleepwalking', 'sleep terro', 'nightmares', 'A', 'Per sleep disorder classification (mental health), parasomnias include sleepwalking, sleep terrors, and nightmares. Narcolepsy is a dyssomnia (disorder of excessive sleepiness), not a parasomnia, so it is the EXCEPTION.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A parents came to your clinic complaining that their 5-year-old boy had attacks of frightening with imagination of a snake crawling over him and he is acting as trying to remove it. You assessed the child and find no acute physical illness and he is cooperative and quite intelligent.Of the following, the MOST appropriate explanation for the child behavior is', 'acute phobic hallucination', 'early sign of schizophrenia', 'delusional infestation', 'night terror E.bipolar disorder night terror E.bipolar disorder v', 'D', 'A well, intelligent, cooperative 5-year-old with episodic frightening imagery and motor activity, no acute illness and no psychosis, fits a night terror/parasomnia rather than psychosis. Per Kaplan & Sadock and standard paediatric psychiatry, phobic hallucination, schizophrenia and delusional infestation are inappropriate for a healthy pre-schooler; the option (though garbled) endorses night terror. ⚠ Question may be INCOMPLETE', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In assessing the seriousness of adolescent drug abuse score, which of the following take +2 in the score?', 'female sex', 'age>15 years', 'positive family history of drug abuse', 'use before driving', 'D', 'In adolescent drug-abuse severity scoring, using a substance before driving is a high-risk behaviour scoring +2 because of the immediate danger to self and others (adolescent medicine screening tools). Sex, age and family history are lower-weighted risk items. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Substance Use Disorders', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Lewin’s change theory is being applied as the community is addressing improvements in public safety. Which of the following would be one of the first steps in creating change?', 'Determining whether anyone else agrees.', 'Having a careful plan as to what change is desirable', 'Making community members aware of the need for changed.', 'Assessing community needs to determine whether change is possible', 'C', 'Per Lewin''s change theory as applied in community health nursing, the first stage is ''unfreezing'' — creating awareness of the need for change; assessment and planning follow once the need is recognised. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is the most effective way of prioritizing nursing diagnoses?', 'Ensuring that the diagnoses are reimbursable by third-party payers', 'Determining the degree of community concern about the problem', 'Comparing the diagnoses with the agency’s mission statement', 'Discussing conclusions with another community health nurse', 'B', 'Per community health nursing practice, prioritising nursing diagnoses is most effectively done by gauging the community''s own perception/concern about the problem, which drives participation and effective intervention.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The nurse is planning to present an educational program. Which of the following is important for the nurse to remember?', 'Having many handouts so that the audience can remember what was said', 'Ordering a microphone so that everyone in the room can hear easily', 'Using pictures and posters of professionals demonstrating the needed behaviors', 'Using many different methods of presentation with multimedia art', 'D', 'Per health education principles (Kenya community health), using varied multimedia teaching methods accommodates different learning styles and improves retention, making it the key consideration when planning an educational program. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The term “tabula rasa” highlights the importance of in shaping behaviour.', 'genes', 'experience', 'nature', 'predestination', 'B', 'Per behavioural science, Locke''s ''tabula rasa'' (blank slate) doctrine holds that the mind at birth is empty and behaviour is shaped by experience/environment, emphasising nurture over genes and predestination.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which stage of development is most unstable and challenging regarding the development of personal identity?', 'Adolescence', 'Toddlerhood', 'Childhood', 'Infancy', 'A', 'Per Erikson''s developmental theory, adolescence (identity vs role confusion) is the most unstable and challenging stage for the development of personal identity.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Andragogy refers to:', 'Adult learning', 'Action Learning', 'Experiential learning', 'Child learning', 'A', 'Andragogy (Knowles) is the theory and method of adult learning, contrasted with pedagogy (child learning); this is standard in NCK nurse-educator curriculum.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Cognitive domain in Bloom’s Taxonomy includes all the following, except', 'Evaluation', 'Synthesis', 'Analysis', 'Criticism', 'D', 'Bloom''s cognitive domain levels are knowledge, comprehension, application, analysis, synthesis and evaluation; ''Criticism'' is not a level, making it the exception.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of educational assessment which is generally carried out throughout a course or project is', 'Summative assessment', 'Formative assessment', 'Criterion-referenced assessment', 'Ipsative assessment', 'B', 'Formative assessment is conducted throughout a course to monitor learning and give feedback, whereas summative assessment occurs at the end; standard educational assessment principle.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Characteristics of Problem Based Learning include all, EXCEPT:', 'Learning is driven by challenging, open-ended, ill-defined and ill-structured problems.', 'Students generally work in collaborative groups.', 'The teacher is the authority', 'Teachers take on the role as "facilitators" of learning', 'C', 'In Problem-Based Learning the teacher is a facilitator, not the authority; learning is driven by ill-structured problems and collaborative group work, so ''the teacher is the authority'' is the exception.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Education', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The type of discussion where a group of 6-8 qualified experts discuss a topic in front of an audience is called:', 'Group discussion', 'Symposium', 'Panel discussion', 'Workshop', 'B', 'A symposium is a series of short talks by several qualified experts on a topic before an audience; a panel discussion involves interactive debate among a smaller panel. Standard teaching-methods classification. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A type of family in which more than one monogamous couple share resources is referred to as?', 'Dyad', 'Compound', 'Commune', 'Blended', 'C', 'A commune is a family form in which more than one monogamous couple share resources and responsibilities communally; a dyad is a couple only, blended combines previous families'' children. Standard family sociology (family nursing).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following is not a specific function of the school health services?', 'Determine the health status of each child.', 'Conduct a special screening programme which will disclose particular health problems.', 'Understanding the difference in the stages of growth and development.', 'Assist in maintaining the health of school personnel', 'C', 'Specific functions of school health services include determining each child''s health status, screening for problems and maintaining staff health; ''understanding the stages of growth and development'' is background knowledge, not a specific service function, so it is the exception.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The health-belief model is composed of one of the following factors:', 'Psychological factors', 'Modifying factors', 'Social factors', 'Environmental factors', 'B', 'The Health Belief Model comprises individual perceptions, modifying factors (demographic, socio-psychological cues) and likelihood of action; ''modifying factors'' is a recognised component of the model.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Which of the following channels of disease transmission is indirect transmission?', 'Droplet infection', 'Transplacental', 'Unclean hands and fingers', 'Bite of animal', 'B', 'Transplacental (vertical) transmission is a form of indirect transmission via the vehicle of the placenta; droplet infection, unclean hands/fingers and animal bite are direct/close-contact routes. Communicable disease epidemiology. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The capability of an infectious agent to invade, survive and multiply in the host is?', 'Toxigenicity', 'Invasiveness', 'pathogenicity', 'infectivity', 'D', 'Infectivity is the capability of an agent to invade, survive and multiply in a host; pathogenicity is the ability to cause disease and invasiveness the ability to spread in tissues. Epidemiology definitions. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The major components comprising the community core are?', 'History, values ,beliefs', 'Demography, education system, economic system', 'Values, political system, education system', 'Demography, political system, education system', 'A', 'In the community-as-partner (Anderson & McFarlane) model the community core comprises history, demographics, values, beliefs and religion of the people; ''history, values, beliefs'' best represents core elements, while demography, education, economic and political systems are subsystems. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Sustainable development 1 is about poverty. What is the aim of this goal?', 'Cut poverty in half by 2030', 'Reduce poverty by 75% by 2030', 'End poverty in all its forms everywhere', 'Help each nation make progress on reducing poverty', 'C', 'SDG 1 aim is ''End poverty in all its forms everywhere'' by 2030; halving or reducing by a percentage were older MDG-style targets (UN Sustainable Development Goals).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following is a health promotion activity;', 'Rehabilitation', 'Environmental sanitation', 'Prompt treatment', 'Provision of adequate housing', 'B', 'Environmental sanitation is a health promotion activity that improves living conditions to prevent disease; rehabilitation and prompt treatment are tertiary/secondary care. Provision of housing is closer to specific protection, so environmental sanitation is the best health promotion example (health promotion/prevention levels). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Primary Health Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('In the principles of primary health care, accessibility considers the following except', 'Elements of integrated services.', 'People''s awareness.', 'Transport and road network', 'Social status of community members.', 'D', 'In PHC principles, accessibility concerns physical/geographic reach (transport, road network), awareness of services and integration of services; social status relates to acceptability/equity, not accessibility, so it is the exception.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Primary Health Care', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The policy of open vaccine states that:', 'Discard all open vaccines at the end of the session', 'Discard polio, BCG, PCV10 at the end of the session', 'Discard all open vaccines with evidence of contamination', 'Discard measles, yellow fever and BCG after four hours.', 'A', 'Per KEPI, the open (multi-dose) vial policy distinguishes vaccines: reconstituted vaccines (BCG, measles, yellow fever) are discarded within 6 hours or end of session, while liquid multi-dose vaccines may be reused; the open-vaccine session rule is that all opened vaccines are discarded at the end of the immunization session (safest single statement here). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following concepts would enable the nurse to provide holistic care for culturally diverse clients', 'Cultural conflicts', 'Ethnocentrism', 'Stereotyping', 'Cultural brokering', 'D', 'Cultural brokering (bridging/mediating between the client''s culture and the health system) supports holistic, culturally competent care; cultural conflict, ethnocentrism and stereotyping are barriers to it (transcultural nursing, Kozier Fundamentals).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Max Weber is known for the development of which management theory?', 'Bureaucratic management', 'Scientific management', 'Humanistic management', 'Transformational leadership', 'A', 'Max Weber is credited with the bureaucratic theory of management (hierarchy, rules, division of labour); scientific management is Taylor''s, per nursing management/leadership texts.', 'KRCHN', 'Paper II', 'Nursing Management & Leadership', 'Nursing Management', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A low-income elderly woman is being screened for blood cholesterol level by a community nutritionist at a community health center. What level of prevention is the nutritionist using?', 'Primary', 'Secondary', 'Tertiary', 'Quartenary', 'B', 'Screening to detect disease early in an asymptomatic person (cholesterol screening) is secondary prevention (early detection); primary prevents onset, tertiary limits disability (Leavell & Clark levels of prevention).', 'KRCHN', 'Paper II', 'Nutrition', 'Nutrition', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A community can also be defined on the basis of a common interest or goal. A nutritionist was asked to identify and design a program for common- interest communities. All of these are examples of common-interest communities except:', 'homebound elderly persons', 'teenage mothers', 'co-workers', 'members of churches', 'C', 'Common-interest communities share a common goal/interest (homebound elderly, teenage mothers, church members). Co-workers form a community of place/organisation rather than a common-interest group, so they are the exception. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Nutrition', 'Nutrition', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Anthropometric measurements include:', 'skinfold measures', 'waist circumference', 'capillary fragility', 'a and b', 'D', 'Anthropometric measurements assess body size/composition: skinfold thickness and waist circumference are both anthropometric, whereas capillary fragility is a clinical/biophysical test, so ''a and b'' is correct.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An interpersonal conflict in which no participant is aware of the divergence of goals, needs, or interests is known as', 'Latent conflict', 'Manifest conflict', 'Cause of action', 'Overt conflict', 'A', 'Latent conflict is the stage where the conditions/divergence of goals exist but the parties are not yet aware of it; manifest/overt conflict is when it becomes openly recognised (conflict management theory in nursing leadership). 231. which public health Act is responsible for securing and maintaining health A. Cap 242 B. Cap 257 C. Cap 280 D. Cap 302 Answer: A. Cap 242 Rationale: In Kenya the Public Health Act is Chapter 242 (Cap 242) of the Laws of Kenya — the principal statute for securing and maintaining public health. (Kenya Public Health Act, Cap 242.) ⚠ Best answer not clearly among choices 232. which of the following is the advantage of integration of services A. save time and money for the nurse B. improves immunization coverage C. patients are integrated in the approach D. there is high chance of cross infection between sick and health especially children Answer: A. save time and money for the nurse Rationale: Integration of services allows a client to receive several services in one visit, saving time and resources for both client and provider and reducing missed opportunities; cross-infection risk is a disadvantage, not an advantage.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A situation where someone gains sexual gratification by rubbing his genitalia against a non-consenting female is', 'Transvestism', 'Fetishism', 'Masochism', 'Frotteorism', 'D', 'Frotteurism is the paraphilia of gaining sexual gratification by rubbing one''s genitals against a non-consenting person; distinct from fetishism (objects) or masochism (self-pain). Per DSM-5 as used in Kenyan mental health nursing texts. 240. fat soluble vitamins includes A. A,D,C,E B. A,D,E,K, C. E,D,C,K D. A,B,C,D Answer: B. A,D,E,K, Rationale: The fat-soluble vitamins are A, D, E and K (mnemonic ADEK); C and B are water-soluble. Per Kozier & Erb''s Fundamentals / nutrition texts used in Kenyan training.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A business firm must employ an occupational health nurse when it has at least how many employees.', '21', '101', '201', '301', 'B', 'Under Kenya''s Occupational Safety and Health Act (OSHA 2007), a workplace with 100+ employees must engage an occupational health nurse, i.e. at least', 'KRCHN', 'Paper II', 'Environmental Health', 'Environmental Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Per Kenyan OSH regulations / community health nursing. ⚠ More than one defensible answer 242. The number of cases of Dengue fever usually increases towards the end of the rainy season. This pattern of occurrence of Dengue fever is best described as;', 'Epidemic occurrence', 'Cyclical variation', 'Sporadic occurrence', 'Secular occurrence', 'B', 'A regular, predictable rise in cases tied to a recurring season (end of rains) is a seasonal/cyclical variation, not an unpredictable epidemic or long-term secular trend. Per epidemiology (Park''s / Kenya CDC control principles).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Among the following diseases, which is airborne?', 'Viral conjunctivitis', 'Acute poliomyelitis', 'Diphtheria', 'Measles', 'D', 'Measles is transmitted by airborne respiratory droplets/aerosols; polio is faeco-oral, conjunctivitis is contact, diphtheria is droplet (not true airborne). Per Kenya IMNCI / communicable disease control.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Objectives of the health services include each of the following except:', 'Delivery of curative care only', 'Health promotion', 'Prevention control, or eradication of disease', 'Treatment and rehabilitation', 'A', 'Health service objectives include promotion, prevention, treatment and rehabilitation; ''curative care only'' is the exception because it excludes the other functions. Per Kenya health systems / community health.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The community health nurse should not make surprise supervisory visits because:', 'The village health nurse may be on leave', 'The village health nurse may not be prepared for visit', 'The aim of supervisory visit is to train the subordinates', 'The village health nurse may be on home visits', 'C', 'Supportive supervision is developmental/training-oriented and should be planned, not a ''surprise'' fault-finding exercise; hence surprise visits are avoided. Per Kenya community health nursing management principles. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An absolute contraindication for pediatric immunization includes;', 'Anaphylactic reaction to previous immunization', 'Respiratory illness with low grade lever', 'Soreness, redness and itching at the previous injection site', 'A febrile seizure one month after the previous injection of vaccines', 'A', 'Anaphylaxis to a prior dose is an absolute contraindication to further immunization; minor illness, injection-site soreness and a delayed febrile seizure are not. Per Kenya KEPI guidelines.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Bitot’s spot’ is the characteristic feature of............. deficiency', 'Calcium', 'Vitamin D', 'Vitamin A', 'Vitamin C', 'C', 'Bitot''s spots (foamy conjunctival patches) are a classic sign of vitamin A deficiency/xerophthalmia. Per Kenya nutrition / IMNCI guidelines.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('An abiotic environment that can affect health of the community is:-', 'Infective organisms', 'Insects', 'Vegetation', 'Chemicals', 'D', 'Abiotic (non-living) environmental factors include chemicals, air, water and physical agents; infective organisms, insects and vegetation are biotic. Per Kenya environmental/public health nursing.', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Increasing the ability of the population to cope with a disaster is known as:', 'Preparedness', 'Triaging', 'Mobilization', 'Mitigation', 'D', 'Mitigation is action to reduce impact and increase a population''s ability to cope with a disaster; preparedness is planning/readiness beforehand. Per Kenya disaster management / community health. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Disaster Management', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The following are some of the activities done to ensure the needs of a school child are met.', 'Screening and physical examination.', 'Counseling and provision of food.', 'Evaluating the process and results of the programs.', 'Promoting positive health behavior among staff and students.', 'A', 'A core school-health service activity to meet the child''s needs is screening and physical examination for early detection of health problems. Per Kenya School Health Policy / community health nursing. ⚠ Question may be INCOMPLETE ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('KEPI refrigerator should be defrosted when the thickness of ice is:-', '0-3 millimeters.', '4-5 millimeters.', '11-13 millimeters.', '6-10 millimeters.', 'D', 'KEPI cold-chain guidance is to defrost the vaccine refrigerator when ice build-up reaches about 6-10 mm (roughly 0.5-1 cm) thickness to maintain efficient cooling. Per Kenya KEPI cold chain guidelines. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Immunization', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('A 20-year-old university student attends the clinic reporting a 1-year history of daily use of legal highs. She has recently experienced some mild paranoia on withdrawal from the use of mephedrone. Which class of drugs does mephedrone most closely resemble in its effect on users:-', 'Amphetamines', 'Heroin/opioids', 'Cannabinoids', 'D. Hallucinogens', 'A', 'Mephedrone is a synthetic cathinone stimulant whose effects (euphoria, alertness, paranoia on withdrawal) closely resemble amphetamines, not opioids, cannabinoids or hallucinogens (pharmacology/psychiatry texts).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Anticholinergic side effects include all of the following EXCEPT:-', 'Bradycardia', 'Constipation', 'Dry mouth', 'Exacerbation of open-angle glaucoma', 'A', 'Anticholinergic effects include tachycardia (not bradycardia), dry mouth, constipation, urinary retention and worsening of glaucoma; blockade of muscarinic receptors increases heart rate (pharmacology texts). 269. 22-year-old man started on a typical antipsychotic finds it difficult to sit still and has to move his legs constantly. How is this phenomenon best defined:- A. Tardive dyskinesia B. Akinesia C. Akathisia D. Neuroleptic malignant syndrome Answer: C. Akathisia Rationale: Akathisia is the subjective inner restlessness with an inability to sit still and constant leg movement, an early extrapyramidal effect of antipsychotics; tardive dyskinesia is late involuntary movements and akinesia is absence of movement (psychiatry texts).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Disorder of motor activity in which the person constantly maintains a position without any movement', 'Mannerism', 'Cataplexy', 'Verbigeration', 'Negativis m', 'D', 'Maintaining a fixed posture without movement is a catatonic feature; among the options negativism (motiveless resistance/immobility maintaining a position) best fits, whereas cataplexy is sudden loss of muscle tone and verbigeration is repetitive speech (psychopathology texts). ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('Psychosis is characterized by all, except:', 'Contact with reality is maintained', 'Positive symptoms are usually present', 'Impaired judgment', 'Insight is lost.', 'A', 'Psychosis is defined by LOSS of contact with reality, positive symptoms, impaired judgment and lost insight; therefore ''contact with reality is maintained'' is the exception (psychiatry texts).', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The priority psychiatric nursing intervention in the management of an aggressive and violent patient on admission would be: -', 'Engage him in a discussion, call for reinforcement to restrain him and administer intravenous fluids', 'Engage him in a discussion, call for reinforcement to restrain him and administer tranquilizers', 'Counsel the patient to calm down, call for reinforcement and administer tranquilizers', 'Counsel the patient to calm down, call for reinforcement and administer intravenous fluids', 'C', 'Per Kenya MOH mental health nursing standards, de-escalation (verbal calming) is attempted first, with reinforcement summoned and rapid tranquillisation (e.g. haloperidol/diazepam) given to control violence; IV fluids are irrelevant to acute aggression, ruling out options A and D. Tranquillisers, not IV fluids, are the pharmacologic priority. ⚠ More than one defensible answer', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'hard', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('During psychiatric interview patient retains a constellation of ideas long after they have ceased to be appropriate. E.g. “where do you live?”, “London”, “How old are you”, “London. The term used to explain the condition is:-', 'Perseveration', 'Mannerisms', 'Ambivalence', 'D. Echopraxia', 'A', 'Persistent, inappropriate repetition of the same response (answering ''London'' to unrelated questions) is perseveration (psychiatric mental status examination). Mannerisms, ambivalence and echopraxia (imitating movements) describe different phenomena.', 'KRCHN', 'Paper II', 'Mental Health Nursing', 'Mental Health Nursing', 'medium', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
INSERT INTO questions (stem, option_a, option_b, option_c, option_d, correct_option, rationale, cadre, paper, unit, topic, difficulty, status) VALUES ('The character of feeling for others in their position is called', 'Empathy', 'Sympathy', 'Warmth', 'Reassurance', 'A', 'Empathy is understanding and feeling with others from their perspective/position, distinguished from sympathy (feeling for them). Therapeutic communication (Kozier & Erb''s).', 'KRCHN', 'Paper II', 'Community Health Nursing', 'Community Health', 'easy', 'approved') ON CONFLICT (stem, cadre) DO NOTHING;
